// Exercices : free-exercise-db (domaine public, github.com/yuhonas/free-exercise-db), traduits en français.
window.EXDB = [{"id":"3_4_Sit-Up","n":"Sit-up aux 3/4","ne":"3/4 Sit-Up","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allonge-toi au sol, pieds calés et genoux fléchis.","Place les mains derrière la tête ou sur les côtés, dos au sol : c'est la position de départ.","Fléchis les hanches et la colonne pour monter le buste vers les genoux.","En haut, le buste est perpendiculaire au sol. Redescends seulement aux 3/4 du trajet."],"k":2},{"id":"90_90_Hamstring","n":"Étirement ischios 90/90","ne":"90/90 Hamstring","e":"body only","c":"stretching","l":"beginner","m":["hamstrings"],"s":["calves"],"i":["Allonge-toi sur le dos, une jambe tendue au sol.","Plie l'autre hanche et le genou à 90° ; tu peux tenir la jambe avec les mains. C'est la position de départ.","Tends la jambe vers le plafond, marque une courte pause en haut, puis reviens.","Fais 10 à 20 répétitions, puis change de jambe."],"k":2},{"id":"Ab_Crunch_Machine","n":"Crunch à la machine","ne":"Ab Crunch Machine","e":"machine","c":"strength","l":"intermediate","m":["abdominals"],"s":[],"i":["Choisis une charge légère, assieds-toi sur la machine, pieds sous les boudins, mains sur les poignées du haut, triceps posés sur les appuis (bras à 90°).","Monte les jambes en enroulant le haut du buste, en expirant. Mouvement lent et contrôlé : ce sont les abdos qui travaillent, jambes et pieds relâchés.","Après une seconde de pause, reviens lentement en inspirant."],"k":2},{"id":"Ab_Roller","n":"Roue abdominale","ne":"Ab Roller","e":"other","c":"strength","l":"intermediate","m":["abdominals"],"s":["shoulders"],"i":["Tiens la roue à deux mains et mets-toi à genoux au sol.","Pose la roue devant toi, en appui sur les mains et les genoux : c'est la position de départ.","Fais rouler la roue lentement vers l'avant en allongeant le corps, aussi loin que possible sans toucher le sol. Inspire pendant la descente.","Après une pause en position étirée, reviens en expirant, abdos toujours serrés."],"k":2},{"id":"Adductor","n":"Étirement des adducteurs","ne":"Adductor","e":"foam roll","c":"stretching","l":"intermediate","m":["adductors"],"s":[],"i":["Allonge-toi sur le ventre, une jambe posée sur un rouleau de massage.","Tourne la jambe pour que le rouleau soit contre l'intérieur de la cuisse et mets-y autant de poids que tu le supportes.","En relâchant l'intérieur de la cuisse, roule entre la hanche et le genou ; reste 10 à 30 s sur les points sensibles. Change de jambe."],"k":2},{"id":"Adductor_Groin","n":"Étirement adducteurs / aine","ne":"Adductor/Groin","e":"other","c":"stretching","l":"intermediate","m":["adductors"],"s":[],"i":["Allonge-toi sur le dos, pieds levés vers le plafond.","Ton partenaire tient tes pieds ou tes chevilles ; écarte les jambes au maximum : c'est la position de départ.","Essaie de serrer les jambes pendant au moins 10 s pendant que ton partenaire t'en empêche.","Relâche ensuite les jambes pendant qu'il les écarte doucement, jusqu'à un étirement confortable. Préviens-le dès que c'est suffisant pour éviter la blessure."],"k":2},{"id":"Advanced_Kettlebell_Windmill","n":"Moulin kettlebell avancé","ne":"Advanced Kettlebell Windmill","e":"kettlebells","c":"strength","l":"intermediate","m":["abdominals"],"s":["glutes","hamstrings","shoulders"],"i":["Monte une kettlebell au-dessus de la tête à un bras (épaulé puis développé).","Bras toujours verrouillé, pousse les fesses du côté de la kettlebell, l'autre main dans le dos, pieds tournés à 45° à l'opposé du bras chargé.","Descends le plus bas possible.","Marque une pause d'une seconde puis remonte."],"k":2},{"id":"Air_Bike","n":"Vélo air bike","ne":"Air Bike","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allonge-toi sur le dos, bas du dos plaqué au sol, mains de chaque côté de la tête sans tirer sur la nuque. Décolle les épaules comme pour un crunch.","Monte les genoux à la verticale, tibias parallèles au sol : c'est la position de départ.","Pédale lentement : tends la jambe droite et ramène le genou gauche en amenant le coude droit vers lui, en expirant.","Reviens au centre en inspirant.","Fais de même de l'autre côté : coude gauche vers genou droit.","Continue en alternant les côtés."],"k":2},{"id":"All_Fours_Quad_Stretch","n":"Étirement quadriceps à quatre pattes","ne":"All Fours Quad Stretch","e":"body only","c":"stretching","l":"intermediate","m":["quadriceps"],"s":["quadriceps"],"i":["À quatre pattes, lève une jambe et attrape le pied avec la main.","Garde le genou bien plié pour étirer le quadriceps et le fléchisseur de hanche.","Pousse les hanches vers le sol. Tiens 10 à 20 s puis change de côté."],"k":2},{"id":"Alternate_Hammer_Curl","n":"Curl marteau alterné","ne":"Alternate Hammer Curl","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":["forearms"],"i":["Debout, buste droit, un haltère dans chaque main bras tendus, coudes près du corps.","Paumes tournées vers le corps : c'est la position de départ.","Bras immobile, monte l'haltère droit en contractant le biceps et en expirant, jusqu'à hauteur d'épaule. Tiens une seconde. Seul l'avant-bras bouge.","Redescends lentement en inspirant.","Fais de même avec la main gauche : cela fait une répétition.","Continue en alternant."],"k":2},{"id":"Alternate_Heel_Touchers","n":"Touches de talons alternées","ne":"Alternate Heel Touchers","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allonge-toi, genoux fléchis, pieds au sol écartés d'environ 50 cm, bras le long du corps.","Enroule le buste vers la droite pour toucher le talon droit, tiens une seconde en expirant.","Reviens lentement en inspirant.","Fais de même vers la gauche. Les deux talons touchés = une répétition.","Continue en alternant les côtés."],"k":2},{"id":"Alternate_Incline_Dumbbell_Curl","n":"Curl haltères incliné alterné","ne":"Alternate Incline Dumbbell Curl","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":["forearms"],"i":["Assieds-toi sur un banc incliné, un haltère dans chaque main bras tendus, coudes près du corps.","Bras immobile, monte l'haltère droit en tournant la paume vers le haut, en expirant, jusqu'à hauteur d'épaule. Tiens une seconde. Seul l'avant-bras bouge.","Redescends lentement en inspirant.","Fais de même à gauche : cela fait une répétition.","Continue en alternant."],"k":2},{"id":"Alternate_Leg_Diagonal_Bound","n":"Bonds diagonaux alternés","ne":"Alternate Leg Diagonal Bound","e":"other","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["abductors","adductors","calves","glutes","hamstrings"],"i":["Pieds légèrement décalés, un pied devant l'autre.","Pousse sur la jambe avant et projette le genou opposé vers l'avant et le plus haut possible avant de te réceptionner. Couvre un maximum de distance en diagonale à chaque bond.","Une ligne au sol peut aider à repérer la distance.","Recommence avec l'autre jambe."],"k":2},{"id":"Alternating_Cable_Shoulder_Press","n":"Développé épaules à la poulie alterné","ne":"Alternating Cable Shoulder Press","e":"cable","c":"strength","l":"beginner","m":["shoulders"],"s":["triceps"],"i":["Place les poulies en bas et choisis la charge.","Tiens les poignées à hauteur d'épaules, paumes vers l'avant : c'est la position de départ.","Tête et poitrine hautes, tends un bras pour pousser au-dessus de la tête.","Pause en haut, redescends et fais de même de l'autre côté."],"k":2},{"id":"Alternating_Deltoid_Raise","n":"Élévations deltoïdes alternées","ne":"Alternating Deltoid Raise","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Debout, un haltère dans chaque main le long du corps.","Coudes légèrement fléchis, monte les haltères devant toi jusqu'à hauteur d'épaules, sans élan.","Redescends.","À la répétition suivante, monte-les sur les côtés jusqu'à hauteur d'épaules.","Redescends et continue en alternant avant et côté."],"k":2},{"id":"Alternating_Floor_Press","n":"Développé au sol alterné","ne":"Alternating Floor Press","e":"kettlebells","c":"strength","l":"beginner","m":["chest"],"s":["abdominals","shoulders","triceps"],"i":["Allonge-toi au sol, deux kettlebells à côté des épaules.","Place-les l'une après l'autre sur la poitrine, poignées en main, paumes vers l'avant.","Tends les deux bras au-dessus de la poitrine. Descends une kettlebell vers la poitrine.","Remonte-la et fais de même de l'autre côté."],"k":2},{"id":"Alternating_Hang_Clean","n":"Épaulé suspendu alterné","ne":"Alternating Hang Clean","e":"kettlebells","c":"strength","l":"intermediate","m":["hamstrings"],"s":["biceps","calves","forearms","glutes","lower back","traps"],"i":["Place deux kettlebells entre tes pieds, fesses en arrière, regard droit devant.","Monte une kettlebell à l'épaule en poussant avec les jambes et les hanches, en tournant le poignet ; l'autre reste suspendue.","Redescends-la et monte l'autre. Continue en alternant."],"k":2},{"id":"Alternating_Kettlebell_Press","n":"Développé kettlebell alterné","ne":"Alternating Kettlebell Press","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["triceps"],"i":["Monte deux kettlebells aux épaules en poussant avec les jambes et les hanches, en tournant les poignets.","Pousse-en une au-dessus de la tête, paume vers l'avant, l'autre reste immobile.","Redescends-la et pousse aussitôt avec l'autre bras."],"k":2},{"id":"Alternating_Kettlebell_Row","n":"Rowing kettlebell alterné","ne":"Alternating Kettlebell Row","e":"kettlebells","c":"strength","l":"intermediate","m":["middle back"],"s":["biceps","lats"],"i":["Place deux kettlebells devant tes pieds. Genoux légèrement fléchis, fesses bien en arrière, penche-toi et attrape les deux poignées.","Tire une kettlebell vers le ventre en serrant l'omoplate, coude près du corps ; l'autre reste au sol.","Redescends-la et fais de même avec l'autre bras."],"k":2},{"id":"Alternating_Renegade_Row","n":"Rowing renegade alterné","ne":"Alternating Renegade Row","e":"kettlebells","c":"strength","l":"expert","m":["middle back"],"s":["abdominals","biceps","chest","lats","triceps"],"i":["Place deux kettlebells au sol, écartées de la largeur des épaules. Mets-toi en position de pompe, mains sur les poignées, corps gainé ; écarte les pieds pour la stabilité.","Appuie sur une kettlebell et tire l'autre vers ta hanche en serrant l'omoplate.","Repose-la et fais de même de l'autre côté."],"k":2},{"id":"Ankle_Circles","n":"Cercles de chevilles","ne":"Ankle Circles","e":"other","c":"stretching","l":"beginner","m":["calves"],"s":[],"i":["Tiens-toi à un appui stable.","Lève la jambe droite à quelques centimètres du sol et dessine de grands cercles avec le gros orteil. Respire normalement.","Fais de même avec la jambe gauche."],"k":2},{"id":"Ankle_On_The_Knee","n":"Cheville sur le genou (étirement)","ne":"Ankle On The Knee","e":"other","c":"stretching","l":"beginner","m":["glutes"],"s":[],"i":["Allongé sur le dos, genoux pliés, pieds au sol.","Pose la cheville d'un pied sur le genou opposé.","Attrape la cuisse de la jambe du bas et ramène les deux jambes vers la poitrine, nuque et épaules relâchées. Tiens 10 à 20 s puis change de côté."],"k":2},{"id":"Anterior_Tibialis-SMR","n":"Auto-massage tibial antérieur","ne":"Anterior Tibialis-SMR","e":"other","c":"stretching","l":"intermediate","m":["calves"],"s":[],"i":["Assieds-toi au sol, jambes fléchies, pieds au sol.","Avec un rouleau de massage, appuie sur le muscle à l'extérieur du tibia, du genou à la cheville, en restant 10 à 30 s sur les points sensibles. Change de jambe."],"k":2},{"id":"Anti-Gravity_Press","n":"Développé anti-gravité","ne":"Anti-Gravity Press","e":"barbell","c":"strength","l":"beginner","m":["shoulders"],"s":["middle back","traps","triceps"],"i":["Pose une barre au sol au bout d'un banc incliné, côté tête.","Allonge-toi à plat ventre sur le banc, attrape la barre en pronation et ramène-la vers la poitrine (curl inversé) : c'est la position de départ.","Pousse la barre devant ta tête en tendant les coudes, bras parallèles au sol.","Reviens à la position de départ et recommence."],"k":2},{"id":"Arm_Circles","n":"Cercles de bras","ne":"Arm Circles","e":"other","c":"stretching","l":"beginner","m":["shoulders"],"s":["traps"],"i":["Debout, bras tendus sur les côtés, parallèles au sol.","Fais lentement de petits cercles d'environ 30 cm avec les bras, en respirant normalement.","Continue une dizaine de secondes, puis change de sens."],"k":2},{"id":"Arnold_Dumbbell_Press","n":"Développé Arnold haltères","ne":"Arnold Dumbbell Press","e":"dumbbell","c":"strength","l":"intermediate","m":["shoulders"],"s":["triceps"],"i":["Assieds-toi sur un banc avec dossier, deux haltères devant le haut de la poitrine, paumes vers toi, coudes fléchis (comme en haut d'un curl).","Monte les haltères en tournant les paumes vers l'avant.","Continue jusqu'à avoir les bras tendus au-dessus de la tête, en expirant.","Après une seconde de pause, redescends en tournant les paumes vers toi, en inspirant."],"k":2},{"id":"Around_The_Worlds","n":"Tour du monde","ne":"Around The Worlds","e":"dumbbell","c":"strength","l":"intermediate","m":["chest"],"s":["shoulders"],"i":["Allongé sur un banc plat, un haltère dans chaque main contre les cuisses, paumes vers le plafond, coudes légèrement fléchis.","Fais décrire aux haltères un demi-cercle jusqu'au-dessus de la tête, bras toujours parallèles au sol, en inspirant.","Fais le chemin inverse en expirant."],"k":2},{"id":"Atlas_Stone_Trainer","n":"Entraînement pierre d'Atlas","ne":"Atlas Stone Trainer","e":"other","c":"strongman","l":"intermediate","m":["lower back"],"s":["biceps","forearms","glutes","hamstrings","quadriceps"],"i":["Cet outil (souvent fait de tubes lestés) remplace les pierres d'Atlas.","Charge le poids voulu. Place-toi au-dessus, entoure la charge de tes bras en te penchant depuis les hanches.","Monte la charge au-dessus des genoux en poussant les hanches, pose-la sur les cuisses en t'asseyant légèrement et serre-la contre ta poitrine.","Termine en tendant hanches et genoux pour monter la charge le plus haut possible."],"k":2},{"id":"Atlas_Stones","n":"Pierres d'Atlas","ne":"Atlas Stones","e":"other","c":"strongman","l":"expert","m":["lower back"],"s":["abdominals","adductors","biceps","calves","forearms","glutes","hamstrings","middle back","quadriceps","traps"],"i":["La pierre entre les pieds, penche-toi et entoure-la de tes bras, doigts sous la pierre si possible.","Serre-la contre toi et pousse sur les talons pour la décoller du sol.","Une fois les genoux passés, pose-la sur les cuisses en t'asseyant en arrière.","Reste bas, remonte la pierre sur la poitrine en changeant de prise, puis lève-toi en poussant les hanches et dépose-la sur la plateforme."],"k":2},{"id":"Axle_Deadlift","n":"Soulevé de terre à l'essieu","ne":"Axle Deadlift","e":"other","c":"strongman","l":"intermediate","m":["lower back"],"s":["forearms","glutes","hamstrings","middle back","quadriceps","traps"],"i":["Place la barre au-dessus du milieu des pieds, pieds largeur de hanches. Penche-toi et attrape la barre à largeur d'épaules (souvent en prise mixte).","Inspire fort, descends les hanches jusqu'à ce que les tibias touchent la barre. Regard devant, poitrine haute, dos cambré, pousse sur les talons.","Une fois les genoux passés, tire la barre vers toi en serrant les omoplates et en avançant les hanches.","Redescends en pliant les hanches et en guidant la barre jusqu'au sol."],"k":2},{"id":"Back_Flyes_-_With_Bands","n":"Oiseau aux élastiques","ne":"Back Flyes - With Bands","e":"bands","c":"strength","l":"beginner","m":["shoulders"],"s":["middle back","triceps"],"i":["Accroche un élastique à un poteau fixe.","Prends les poignées et recule pour mettre l'élastique en tension.","Bras tendus devant toi, parallèles au sol, pieds écartés largeur d'épaules : c'est la position de départ.","En expirant, écarte les bras sur les côtés jusqu'à ce qu'ils soient alignés avec les épaules.","Après une pause, reviens en inspirant."],"k":2},{"id":"Backward_Drag","n":"Traîneau tiré en reculant","ne":"Backward Drag","e":"other","c":"strongman","l":"beginner","m":["quadriceps"],"s":["calves","forearms","glutes","hamstrings","lower back"],"i":["Charge un traîneau et attache-y une corde ou des sangles.","Recule sur la distance voulue, buste penché en arrière, à petits pas rapides en poussant sur les jambes."],"k":2},{"id":"Backward_Medicine_Ball_Throw","n":"Lancer de médecine-ball arrière","ne":"Backward Medicine Ball Throw","e":"medicine ball","c":"plyometrics","l":"beginner","m":["shoulders"],"s":[],"i":["À faire idéalement avec un partenaire (sinon contre un mur).","Place-toi quelques mètres devant ton partenaire, dos à lui, ballon tenu entre les jambes.","Descends en squat puis remonte explosivement en lançant le ballon par-dessus ta tête vers lui.","Il te renvoie le ballon en le faisant rouler."],"k":2},{"id":"Balance_Board","n":"Planche d'équilibre","ne":"Balance Board","e":"other","c":"strength","l":"beginner","m":["calves"],"s":["hamstrings","quadriceps"],"i":["Place une planche d'équilibre devant toi.","Monte dessus et essaie de garder l'équilibre.","Tiens aussi longtemps que souhaité."],"k":2},{"id":"Ball_Leg_Curl","n":"Leg curl sur ballon","ne":"Ball Leg Curl","e":"exercise ball","c":"strength","l":"beginner","m":["hamstrings"],"s":["calves","glutes"],"i":["Allongé sur le dos, pieds posés sur un swiss ball.","Chevilles sur le ballon, jambes tendues : c'est la position de départ.","Décolle les hanches du sol, appui sur les omoplates et les pieds.","Plie les genoux pour ramener le ballon vers toi en contractant les ischios.","Après une courte pause, reviens."],"k":2},{"id":"Band_Assisted_Pull-Up","n":"Traction assistée à l'élastique","ne":"Band Assisted Pull-Up","e":"other","c":"strength","l":"beginner","m":["lats"],"s":["abdominals","forearms","middle back"],"i":["Accroche un élastique au centre de la barre de traction (plus il est épais, plus il aide).","Tire l'élastique vers le bas et place un genou plié dans la boucle. Prends la barre en prise moyenne à large : c'est la position de départ.","Tire-toi vers le haut en ramenant les coudes vers les côtés jusqu'à passer le menton au-dessus de la barre, sans balancer.","Après une courte pause, redescends."],"k":2},{"id":"Band_Good_Morning","n":"Good morning à l'élastique","ne":"Band Good Morning","e":"bands","c":"powerlifting","l":"beginner","m":["hamstrings"],"s":["glutes","lower back"],"i":["Debout sur une extrémité d'un élastique, pieds légèrement écartés. Penche-toi pour passer l'autre extrémité derrière la nuque : c'est la position de départ.","Jambes tendues, redresse-toi en poussant les hanches jusqu'à être presque vertical.","Redescends sans jamais arrondir le dos."],"k":2},{"id":"Band_Good_Morning_Pull_Through","n":"Good morning à l'élastique (tirage entre les jambes)","ne":"Band Good Morning (Pull Through)","e":"bands","c":"powerlifting","l":"beginner","m":["hamstrings"],"s":["glutes","lower back"],"i":["Accroche un élastique à un poteau, éloigne-toi un peu et passe l'autre extrémité derrière la nuque, en la tenant avec les mains.","Penche-toi depuis les hanches en reculant les fesses, dos plat, jusqu'à environ 90°, genoux à peine fléchis.","Redresse-toi en poussant les hanches vers l'avant."],"k":2},{"id":"Band_Hip_Adductions","n":"Adductions de hanche à l'élastique","ne":"Band Hip Adductions","e":"bands","c":"strength","l":"beginner","m":["adductors"],"s":[],"i":["Accroche un élastique à un poteau solide.","Côté gauche vers le poteau, passe la cheville droite dans l'élastique.","Tiens-toi droit, en t'aidant du poteau si besoin : c'est la position de départ.","Genou tendu, écarte la jambe droite sur le côté au maximum.","Reviens et répète.","Change de côté."],"k":2},{"id":"Band_Pull_Apart","n":"Écarté d'élastique (pull apart)","ne":"Band Pull Apart","e":"bands","c":"strength","l":"beginner","m":["shoulders"],"s":["middle back","traps"],"i":["Bras tendus devant toi, un élastique tenu à deux mains.","Écarte les mains sur les côtés comme un oiseau.","Coudes tendus, amène l'élastique contre la poitrine, épaules en arrière.","Marque une pause puis reviens en contrôlant."],"k":2},{"id":"Band_Skull_Crusher","n":"Barre au front à l'élastique","ne":"Band Skull Crusher","e":"bands","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Fixe un élastique au pied d'un rack ou du banc et allonge-toi, tête alignée avec l'élastique.","Attrape l'élastique, bras vers le haut perpendiculaires au sol, coudes fléchis, mains au-dessus de la tête : c'est la position de départ.","Tends les coudes sans bouger le haut des bras. Pause en haut, puis reviens."],"k":2},{"id":"Barbell_Ab_Rollout","n":"Roue abdominale à la barre","ne":"Barbell Ab Rollout","e":"barbell","c":"strength","l":"intermediate","m":["abdominals"],"s":["lower back","shoulders"],"i":["Mets-toi en position de pompe, mains sur une barre olympique légèrement chargée (2 à 5 kg de chaque côté).","Dos légèrement cambré, monte les hanches et fais rouler la barre vers tes pieds en expirant. Les fessiers montent, abdos serrés, bras perpendiculaires au sol (sinon ce sont surtout les épaules qui travaillent).","Après une seconde de contraction, ramène lentement la barre en inspirant."],"k":2},{"id":"Barbell_Ab_Rollout_-_On_Knees","n":"Roue abdominale à la barre à genoux","ne":"Barbell Ab Rollout - On Knees","e":"barbell","c":"strength","l":"expert","m":["abdominals"],"s":["lower back","shoulders"],"i":["À genoux au sol, tiens une barre olympique légèrement chargée (2 à 5 kg de chaque côté).","Pose la barre devant toi, en appui sur les mains et les genoux : c'est la position de départ.","Fais rouler la barre lentement vers l'avant en allongeant le corps, le plus loin possible sans toucher le sol, en inspirant.","Après une pause, reviens en expirant, lentement, abdos toujours serrés."],"k":2},{"id":"Barbell_Bench_Press_-_Medium_Grip","n":"Développé couché barre prise moyenne","ne":"Barbell Bench Press - Medium Grip","e":"barbell","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Allonge-toi sur un banc plat. Prise moyenne (avant-bras et bras à 90° à mi-mouvement), sors la barre du support et tiens-la bras tendus au-dessus de toi.","Inspire et descends lentement jusqu'à toucher le milieu de la poitrine.","Après une courte pause, pousse la barre en expirant avec les pectoraux. Bras tendus en haut, serre les pectoraux une seconde puis redescends. La descente doit durer environ deux fois plus longtemps que la montée.","À la fin, repose la barre sur le support."],"k":2},{"id":"Barbell_Curl","n":"Curl barre","ne":"Barbell Curl","e":"barbell","c":"strength","l":"beginner","m":["biceps"],"s":["forearms"],"i":["Debout, buste droit, barre en main à largeur d'épaules, paumes vers l'avant, coudes près du corps.","Bras immobiles, monte la barre en contractant les biceps et en expirant. Seuls les avant-bras bougent.","Continue jusqu'à hauteur d'épaules et serre fort les biceps une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Barbell_Curls_Lying_Against_An_Incline","n":"Curl barre allongé sur banc incliné","ne":"Barbell Curls Lying Against An Incline","e":"barbell","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Allonge-toi contre un banc incliné, barre en main, bras pendants.","Bras immobiles, monte la barre le plus haut possible en serrant les biceps et en expirant, sans balancer.","Après une seconde, redescends lentement jusqu'en bas en inspirant."],"k":2},{"id":"Barbell_Deadlift","n":"Soulevé de terre barre","ne":"Barbell Deadlift","e":"barbell","c":"strength","l":"intermediate","m":["lower back"],"s":["calves","forearms","glutes","hamstrings","lats","middle back","quadriceps","traps"],"i":["Place-toi devant une barre chargée.","Dos le plus droit possible, plie les genoux, penche-toi et attrape la barre en pronation à largeur d'épaules (prise mixte ou sangles si besoin).","Pousse avec les jambes tout en redressant le buste, en expirant. En haut, poitrine sortie, omoplates serrées.","Redescends en pliant les genoux et en penchant le buste, dos toujours droit, jusqu'à poser les disques au sol."],"k":2},{"id":"Barbell_Full_Squat","n":"Squat complet barre","ne":"Barbell Full Squat","e":"barbell","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings","lower back"],"i":["Idéalement dans une cage à squat. Règle la barre juste au-dessus des épaules, passe dessous et pose-la sur le haut du dos (sous la nuque).","Tiens la barre des deux mains et décroche-la en poussant avec les jambes.","Recule, pieds largeur d'épaules, pointes légèrement ouvertes, tête haute, dos droit : c'est la position de départ.","Descends lentement en pliant les genoux et en reculant les hanches, jusqu'à ce que l'arrière des cuisses touche les mollets. Inspire en descendant.","Remonte en expirant en poussant sur les talons ou le milieu du pied."],"k":2},{"id":"Barbell_Glute_Bridge","n":"Pont fessier barre","ne":"Barbell Glute Bridge","e":"barbell","c":"powerlifting","l":"intermediate","m":["glutes"],"s":["calves","hamstrings"],"i":["Assieds-toi au sol, barre chargée sur les jambes (une mousse sur la barre est plus confortable). Fais-la rouler au-dessus des hanches et allonge-toi.","Pousse sur les talons pour monter les hanches à la verticale. Le poids repose sur le haut du dos et les talons.","Monte au maximum puis redescends."],"k":2},{"id":"Barbell_Guillotine_Bench_Press","n":"Développé couché guillotine","ne":"Barbell Guillotine Bench Press","e":"barbell","c":"strength","l":"intermediate","m":["chest"],"s":["shoulders","triceps"],"i":["Prise moyenne, sors la barre du support et tiens-la bras tendus au-dessus du cou.","En inspirant, descends lentement jusqu'à environ 2 cm du cou.","Après une seconde, remonte en expirant avec les pectoraux. Serre en haut une seconde. La descente doit durer deux fois plus longtemps que la montée.","À la fin, repose la barre sur le support."],"k":2},{"id":"Barbell_Hack_Squat","n":"Hack squat barre","ne":"Barbell Hack Squat","e":"barbell","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","forearms","hamstrings"],"i":["Debout, barre tenue derrière toi bras tendus, prise largeur d'épaules paumes vers l'arrière, pieds largeur d'épaules.","Tête haute, dos droit, descends jusqu'à avoir les cuisses parallèles au sol en inspirant.","Remonte en poussant surtout sur les talons, en expirant."],"k":2},{"id":"Barbell_Hip_Thrust","n":"Hip thrust barre","ne":"Barbell Hip Thrust","e":"barbell","c":"powerlifting","l":"intermediate","m":["glutes"],"s":["calves","hamstrings"],"i":["Assieds-toi au sol, un banc juste derrière toi, barre chargée sur les jambes (mousse conseillée).","Fais rouler la barre au-dessus des hanches et appuie le haut du dos (omoplates) contre le bord du banc.","Pousse sur les pieds pour monter les hanches à la verticale. Le poids repose sur les omoplates et les pieds. Monte au maximum puis redescends."],"k":2},{"id":"Barbell_Incline_Bench_Press_-_Medium_Grip","n":"Développé incliné barre prise moyenne","ne":"Barbell Incline Bench Press - Medium Grip","e":"barbell","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Allonge-toi sur un banc incliné. Prise moyenne, sors la barre et tiens-la bras tendus au-dessus de toi.","En inspirant, descends lentement jusqu'au haut de la poitrine.","Après une seconde, pousse en expirant avec les pectoraux et serre en haut. La descente doit durer deux fois plus longtemps que la montée.","À la fin, repose la barre."],"k":2},{"id":"Barbell_Incline_Shoulder_Raise","n":"Élévation d'épaules barre sur banc incliné","ne":"Barbell Incline Shoulder Raise","e":"barbell","c":"strength","l":"beginner","m":["shoulders"],"s":["chest"],"i":["Allongé sur un banc incliné, prise un peu plus large que les épaules, barre tenue bras tendus.","Bras toujours tendus, monte la barre en avançant les omoplates (les épaules décollent du banc), en expirant.","Redescends en inspirant."],"k":2},{"id":"Barbell_Lunge","n":"Fentes barre","ne":"Barbell Lunge","e":"barbell","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Idéalement dans une cage à squat. Pose la barre sur le haut du dos (sous la nuque).","Décroche-la en poussant avec les jambes.","Recule, fais un pas en avant avec la jambe droite et descends, buste droit, en inspirant. Le genou ne doit pas dépasser les orteils.","Remonte en poussant sur le talon, en expirant.","Fais toutes les répétitions puis change de jambe."],"k":2},{"id":"Barbell_Rear_Delt_Row","n":"Rowing barre arrière d'épaules","ne":"Barbell Rear Delt Row","e":"barbell","c":"strength","l":"beginner","m":["shoulders"],"s":["biceps","lats","middle back"],"i":["Debout, barre en main en prise large, paumes vers toi.","Genoux légèrement fléchis, penche-toi dos droit jusqu'à ce que le buste soit parallèle au sol. Écarte les coudes du corps : buste et bras forment un « T ».","Bras perpendiculaires au buste, tire la barre vers le haut de la poitrine en serrant l'arrière des épaules, en expirant. Les bras ne sont que des crochets, pas de biceps.","Redescends lentement en inspirant."],"k":2},{"id":"Barbell_Rollout_from_Bench","n":"Roue à la barre depuis un banc","ne":"Barbell Rollout from Bench","e":"barbell","c":"strength","l":"intermediate","m":["abdominals"],"s":["glutes","hamstrings","lats","shoulders"],"i":["Pose une barre chargée au sol près du bout d'un banc. À genoux sur le banc, prise moyenne à serrée : c'est la position de départ.","Fais rouler la barre vers l'avant en ouvrant les hanches et en montant les bras au-dessus de la tête, bras toujours tendus.","Une fois au plus loin, reviens."],"k":2},{"id":"Barbell_Seated_Calf_Raise","n":"Mollets assis barre","ne":"Barbell Seated Calf Raise","e":"barbell","c":"strength","l":"beginner","m":["calves"],"s":[],"i":["Place une cale à environ 30 cm devant un banc plat.","Assieds-toi, avant des pieds sur la cale.","Fais placer une barre sur le haut des cuisses, à quelques centimètres des genoux : c'est la position de départ.","Monte sur la pointe des pieds le plus haut possible en serrant les mollets, en expirant.","Après une seconde, redescends lentement en étirant bien les mollets."],"k":2},{"id":"Barbell_Shoulder_Press","n":"Développé militaire barre","ne":"Barbell Shoulder Press","e":"barbell","c":"strength","l":"intermediate","m":["shoulders"],"s":["chest","triceps"],"i":["Assieds-toi sur un banc à dossier dans une cage, barre réglée juste au-dessus de la tête. Prends-la en pronation.","Monte la barre bras tendus au-dessus de la tête, légèrement devant : c'est la position de départ.","Descends lentement la barre jusqu'aux épaules en inspirant.","Remonte en expirant."],"k":2},{"id":"Barbell_Shrug","n":"Shrug barre","ne":"Barbell Shrug","e":"barbell","c":"strength","l":"beginner","m":["traps"],"s":[],"i":["Debout, pieds largeur d'épaules, barre tenue devant toi en pronation, mains un peu plus larges que les épaules.","Monte les épaules le plus haut possible en expirant et tiens une seconde, sans plier les bras.","Redescends lentement en inspirant."],"k":2},{"id":"Barbell_Shrug_Behind_The_Back","n":"Shrug barre derrière le dos","ne":"Barbell Shrug Behind The Back","e":"barbell","c":"strength","l":"beginner","m":["traps"],"s":["forearms","middle back"],"i":["Debout, pieds largeur d'épaules, barre tenue derrière le dos en pronation, mains un peu plus larges que les épaules.","Monte les épaules le plus haut possible en expirant et tiens une seconde, bras toujours tendus.","Redescends lentement en inspirant."],"k":2},{"id":"Barbell_Side_Bend","n":"Flexion latérale barre","ne":"Barbell Side Bend","e":"barbell","c":"strength","l":"beginner","m":["abdominals"],"s":["lower back"],"i":["Debout, barre sur le haut du dos, pieds largeur d'épaules.","Dos droit, tête haute, penche-toi uniquement à la taille vers la droite en inspirant. Tiens une seconde puis remonte en expirant. Le reste du corps ne bouge pas.","Fais de même vers la gauche."],"k":2},{"id":"Barbell_Side_Split_Squat","n":"Squat fendu latéral barre","ne":"Barbell Side Split Squat","e":"barbell","c":"strength","l":"beginner","m":["quadriceps"],"s":["calves","hamstrings","lower back"],"i":["Debout, barre sur le haut du dos, pieds très écartés, pied avant tourné vers l'extérieur.","Descends vers le côté du pied tourné en pliant la hanche et le genou de cette jambe, l'autre jambe presque tendue, en inspirant.","Remonte en poussant sur cette jambe, en expirant.","Fais toutes les répétitions puis change de côté."],"k":2},{"id":"Barbell_Squat","n":"Squat barre","ne":"Barbell Squat","e":"barbell","c":"strength","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings","lower back"],"i":["Idéalement dans une cage à squat. Règle la barre juste sous les épaules, passe dessous et pose-la sur le haut du dos (sous la nuque).","Décroche la barre en poussant avec les jambes.","Recule, pieds largeur d'épaules, pointes légèrement ouvertes, tête haute, dos droit : c'est la position de départ.","Descends lentement en pliant genoux et hanches jusqu'à un angle un peu inférieur à 90° aux genoux, en inspirant. Les genoux restent dans l'axe des pieds.","Remonte en poussant sur les talons, en expirant."],"k":2},{"id":"Barbell_Squat_To_A_Bench","n":"Squat barre jusqu'au banc","ne":"Barbell Squat To A Bench","e":"barbell","c":"strength","l":"expert","m":["quadriceps"],"s":["calves","glutes","hamstrings","lower back"],"i":["Idéalement dans une cage. Place un banc ou un box derrière toi : il t'apprend à reculer les hanches et à descendre assez bas.","Pose la barre sur le haut du dos.","Décroche-la en poussant avec les jambes.","Recule, pieds largeur d'épaules, tête haute, dos droit.","Descends en reculant les hanches jusqu'à effleurer le banc, en inspirant. Genoux dans l'axe des pieds.","Remonte en poussant sur les talons, en expirant."],"k":2},{"id":"Barbell_Step_Ups","n":"Montées sur banc barre","ne":"Barbell Step Ups","e":"barbell","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings","quadriceps"],"i":["Debout derrière une marche ou un banc, barre sur le haut du dos.","Pose le pied droit sur la marche et monte en poussant sur le talon, puis pose le pied gauche à côté, en expirant.","Redescends avec la jambe gauche puis la droite, en inspirant.","Fais toutes les répétitions puis change de jambe d'attaque."],"k":2},{"id":"Barbell_Walking_Lunge","n":"Fentes marchées barre","ne":"Barbell Walking Lunge","e":"barbell","c":"strength","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Debout, pieds largeur d'épaules, barre sur le haut du dos.","Fais un pas en avant et descends jusqu'à ce que le genou arrière frôle le sol, buste droit, genou avant au-dessus du pied.","Pousse sur le talon avant pour remonter.","Avance le pied arrière et enchaîne de l'autre côté."],"k":2},{"id":"Battling_Ropes","n":"Cordes ondulatoires","ne":"Battling Ropes","e":"other","c":"strength","l":"beginner","m":["shoulders"],"s":["chest","forearms"],"i":["Il faut une corde lourde fixée en son milieu à 5 ou 6 m. Une extrémité dans chaque main, bras le long du corps : c'est la position de départ.","Monte un bras le plus vite possible jusqu'à hauteur d'épaule.","En le laissant retomber, monte l'autre.","Continue en alternant le plus vite possible pour faire onduler les cordes."],"k":2},{"id":"Bear_Crawl_Sled_Drags","n":"Marche de l'ours avec traîneau","ne":"Bear Crawl Sled Drags","e":"other","c":"strongman","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Avec un harnais ou une ceinture, attache le traîneau derrière toi. Penche-toi, mains au sol, dos plat, genoux fléchis.","Avance à quatre pattes en poussant fort sur les jambes, en alternant, les mains servant à l'équilibre. Garde le dos plat sur toute la distance."],"k":2},{"id":"Behind_Head_Chest_Stretch","n":"Étirement pectoraux mains derrière la tête","ne":"Behind Head Chest Stretch","e":"other","c":"stretching","l":"expert","m":["chest"],"s":["shoulders"],"i":["Assieds-toi droit au sol, ton partenaire derrière toi.","Mains derrière la tête, recule les coudes au maximum ; ton partenaire les tient.","Essaie de ramener les coudes vers l'avant pendant au moins 10 s pendant qu'il t'en empêche.","Relâche ensuite et laisse-le tirer doucement tes coudes vers l'arrière, jusqu'à un étirement confortable."],"k":2},{"id":"Bench_Dips","n":"Dips sur banc","ne":"Bench Dips","e":"body only","c":"strength","l":"beginner","m":["triceps"],"s":["chest","shoulders"],"i":["Place un banc derrière toi. Mains sur le bord, bras tendus, écartées largeur d'épaules, jambes tendues devant toi : c'est la position de départ.","Descends lentement en pliant les coudes jusqu'à un angle un peu inférieur à 90°, en inspirant. Coudes serrés, avant-bras vers le bas.","Remonte avec les triceps jusqu'à la position de départ."],"k":2},{"id":"Bench_Jump","n":"Sauts sur banc","ne":"Bench Jump","e":"body only","c":"plyometrics","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Place un banc ou un box à 30-60 cm devant toi, pieds largeur d'épaules.","Fais une petite flexion en balançant les bras vers l'arrière.","Saute le plus haut possible en tendant hanches, genoux et chevilles, bras vers l'avant et le haut.","Passe par-dessus le banc et réceptionne-toi genoux fléchis.","Retourne-toi et saute à nouveau par-dessus."],"k":2},{"id":"Bench_Press_-_Powerlifting","n":"Développé couché force athlétique","ne":"Bench Press - Powerlifting","e":"barbell","c":"powerlifting","l":"intermediate","m":["triceps"],"s":["chest","forearms","lats","shoulders"],"i":["Allonge-toi sur le banc, pieds ramenés sous toi, dos cambré. Serre les omoplates et plaque-les dans le banc. Garde ce gainage tout au long du mouvement.","Prise couvrant les bagues de la barre. Sors la barre sans avancer les épaules, en la serrant fort.","Descends-la vers le bas de la poitrine, barre, poignets et coudes alignés.","Marque une pause au contact, puis pousse le plus fort possible, coudes rentrés jusqu'en haut."],"k":2},{"id":"Bench_Press_-_With_Bands","n":"Développé couché aux élastiques","ne":"Bench Press - With Bands","e":"bands","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Fixe un élastique sous le pied du banc, côté tête.","Prends les deux poignées et allonge-toi sur le banc.","Tends les bras, poignées devant toi à largeur d'épaules, paumes vers l'avant : c'est la position de départ.","Descends lentement jusqu'à ce que les coudes forment 90°.","Pousse en expirant avec les pectoraux et serre une seconde en haut. La descente doit durer deux fois plus longtemps que la montée."],"k":2},{"id":"Bench_Press_with_Chains","n":"Développé couché avec chaînes","ne":"Bench Press with Chains","e":"barbell","c":"powerlifting","l":"expert","m":["triceps"],"s":["chest","lats","shoulders"],"i":["Règle la longueur des chaînes et accroche-les aux extrémités de la barre.","Allongé sur le banc, pieds ramenés sous toi, dos cambré, omoplates serrées et plaquées. Prise couvrant les bagues.","Sors la barre sans avancer les épaules et descends-la vers le bas de la poitrine, barre, poignets et coudes alignés.","Pause au contact, puis pousse fort, coudes rentrés jusqu'en haut."],"k":2},{"id":"Bench_Sprint","n":"Sprint sur banc","ne":"Bench Sprint","e":"other","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Debout, un pied posé sur un banc ou un box, talon près du bord.","Pousse sur le pied du haut en tendant hanche et genou.","Réceptionne-toi avec l'autre pied sur le box en ramenant le premier au sol.","Continue en alternant rapidement."],"k":2},{"id":"Bent-Arm_Barbell_Pullover","n":"Pull-over barre bras fléchis","ne":"Bent-Arm Barbell Pullover","e":"barbell","c":"strength","l":"intermediate","m":["lats"],"s":["chest","lats","shoulders","triceps"],"i":["Allongé sur un banc plat, barre en main à largeur d'épaules.","Tiens-la au-dessus de la poitrine, bras légèrement fléchis : c'est la position de départ.","Bras toujours fléchis, descends la barre en arc de cercle derrière la tête en inspirant, jusqu'à sentir l'étirement des pectoraux.","Ramène-la par le même arc en expirant.","Tiens une seconde en haut avant de recommencer."],"k":2},{"id":"Bent-Arm_Dumbbell_Pullover","n":"Pull-over haltère bras fléchis","ne":"Bent-Arm Dumbbell Pullover","e":"dumbbell","c":"strength","l":"intermediate","m":["chest"],"s":["lats","shoulders","triceps"],"i":["Pose un haltère debout sur un banc plat.","Allonge-toi en travers du banc, seules les épaules posées, hanches plus basses que le banc, pieds au sol, tête dans le vide.","Tiens l'haltère à deux mains au-dessus de la poitrine, bras légèrement fléchis, paumes contre un des disques. Vérifie que l'haltère est bien serré.","Bras fixes, descends l'haltère en arc derrière la tête en inspirant, jusqu'à l'étirement des pectoraux.","Ramène-le par le même arc en expirant.","Tiens une seconde en haut puis recommence."],"k":2},{"id":"Bent-Knee_Hip_Raise","n":"Relevé de bassin genoux fléchis","ne":"Bent-Knee Hip Raise","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé au sol, bras le long du corps.","Plie les genoux à environ 75° et décolle les pieds de quelques centimètres.","Avec le bas des abdos, ramène les genoux vers toi jusqu'à décoller les hanches en enroulant le bassin, en expirant. En fin de mouvement, les genoux sont au-dessus de la poitrine.","Serre les abdos une seconde puis redescends lentement en inspirant."],"k":2},{"id":"Bent_Over_Barbell_Row","n":"Rowing barre penché","ne":"Bent Over Barbell Row","e":"barbell","c":"strength","l":"beginner","m":["middle back"],"s":["biceps","lats","shoulders"],"i":["Barre en pronation, genoux légèrement fléchis, penche le buste dos droit jusqu'à être presque parallèle au sol, tête haute. La barre pend devant toi, bras tendus : c'est la position de départ.","Buste immobile, tire la barre vers toi en expirant, coudes près du corps. En haut, serre les muscles du dos une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench","n":"Oiseau haltères tête sur banc","ne":"Bent Over Dumbbell Rear Delt Raise With Head On Bench","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Debout, un haltère dans chaque main, un banc incliné devant toi.","Dos droit, penche-toi jusqu'à poser le front sur le banc. Bras pendants, paumes face à face, buste parallèle au sol : c'est la position de départ.","Buste immobile, coudes légèrement fléchis, monte les haltères sur les côtés jusqu'à l'horizontale en expirant. Évite tout élan.","Après une seconde en haut, redescends lentement."],"k":2},{"id":"Bent_Over_Low-Pulley_Side_Lateral","n":"Oiseau à la poulie basse","ne":"Bent Over Low-Pulley Side Lateral","e":"cable","c":"strength","l":"beginner","m":["shoulders"],"s":["lower back","middle back","traps"],"i":["Choisis la charge et prends la poignée de la poulie basse dans la main droite.","Penche-toi jusqu'à avoir le buste presque parallèle au sol, jambes légèrement fléchies, main gauche sur la cuisse gauche, bras droit pendant, coude légèrement fléchi.","Monte le bras droit sur le côté jusqu'à l'horizontale, en expirant.","Redescends lentement en inspirant.","Fais toutes les répétitions puis change de bras."],"k":2},{"id":"Bent_Over_One-Arm_Long_Bar_Row","n":"Rowing T-bar à un bras","ne":"Bent Over One-Arm Long Bar Row","e":"barbell","c":"strength","l":"beginner","m":["middle back"],"s":["biceps","lats","lower back","traps"],"i":["Charge une seule extrémité d'une barre olympique ; cale l'autre bout dans un coin ou sous un objet lourd.","Penche-toi jusqu'à avoir le buste presque parallèle au sol, genoux légèrement fléchis.","Attrape la barre d'une main juste derrière les disques, l'autre main sur le genou.","Tire la barre vers le haut, coude près du corps, jusqu'à ce que les disques touchent le bas de la poitrine. Serre le dos une seconde, en expirant. Seul le bras bouge.","Redescends lentement en étirant bien le dos, sans poser les disques.","Fais toutes les répétitions puis change de bras."],"k":2},{"id":"Bent_Over_Two-Arm_Long_Bar_Row","n":"Rowing T-bar à deux bras","ne":"Bent Over Two-Arm Long Bar Row","e":"barbell","c":"strength","l":"intermediate","m":["middle back"],"s":["biceps","lats"],"i":["Charge une seule extrémité d'une barre olympique ; cale l'autre bout dans un coin ou sous un objet lourd.","Penche-toi jusqu'à avoir le buste presque parallèle au sol, genoux légèrement fléchis.","Attrape la barre à deux mains juste derrière les disques (une poignée en V aide beaucoup).","Tire la barre vers le haut, coudes près du corps, jusqu'à ce que les disques touchent le bas de la poitrine. Serre le dos une seconde, en expirant.","Redescends lentement sans poser les disques."],"k":2},{"id":"Bent_Over_Two-Dumbbell_Row","n":"Rowing deux haltères penché","ne":"Bent Over Two-Dumbbell Row","e":"dumbbell","c":"strength","l":"beginner","m":["middle back"],"s":["biceps","lats","shoulders"],"i":["Un haltère dans chaque main, paumes vers toi, genoux légèrement fléchis, penche le buste dos droit jusqu'à être presque parallèle au sol, tête haute. Haltères pendants : c'est la position de départ.","Buste immobile, monte les haltères le long du corps en expirant, coudes près du corps. En haut, serre le dos une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Bent_Over_Two-Dumbbell_Row_With_Palms_In","n":"Rowing deux haltères penché paumes face à face","ne":"Bent Over Two-Dumbbell Row With Palms In","e":"dumbbell","c":"strength","l":"beginner","m":["middle back"],"s":["biceps","lats"],"i":["Un haltère dans chaque main, paumes face à face, genoux légèrement fléchis, penche le buste dos droit jusqu'à être presque parallèle au sol, tête haute : c'est la position de départ.","Buste immobile, monte les haltères le long du corps en expirant, en serrant les omoplates. Tiens une seconde en haut.","Redescends lentement en inspirant."],"k":2},{"id":"Bent_Press","n":"Développé penché (bent press)","ne":"Bent Press","e":"kettlebells","c":"strength","l":"expert","m":["abdominals"],"s":["glutes","hamstrings","lower back","quadriceps","shoulders","triceps"],"i":["Monte une kettlebell à l'épaule en poussant avec les jambes et les hanches, en tournant le poignet : c'est la position de départ.","Penche-toi du côté opposé jusqu'à toucher le sol avec la main libre, regard sur la kettlebell, tout en tendant le bras chargé à la verticale.","Redresse-toi, kettlebell au-dessus de la tête, puis ramène-la à l'épaule."],"k":2},{"id":"Bicycling","n":"Pédalage","ne":"Bicycling","e":"other","c":"cardio","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Installe-toi sur le vélo et règle la selle à ta hauteur, puis pédale."],"k":2},{"id":"Bicycling_Stationary","n":"Vélo d'appartement","ne":"Bicycling, Stationary","e":"machine","c":"cardio","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Installe-toi sur le vélo et règle la selle à ta hauteur.","Choisis un programme ou le mode manuel (pédaler allume souvent l'écran). Tu peux entrer âge et poids pour estimer les calories, changer la résistance pendant la séance et utiliser les poignées pour suivre ton rythme cardiaque."],"k":2},{"id":"Board_Press","n":"Développé sur planches","ne":"Board Press","e":"barbell","c":"powerlifting","l":"intermediate","m":["triceps"],"s":["chest","forearms","lats","shoulders"],"i":["Allonge-toi sur le banc. Une à cinq planches vissées ensemble sont posées sur ta poitrine (tenues par un partenaire, des élastiques ou glissées sous le t-shirt).","Pieds ramenés sous toi, dos cambré, omoplates serrées et plaquées dans le banc. Garde ce gainage.","Prise classique ou largeur d'épaules pour cibler les triceps. Sors la barre sans avancer les épaules ; barre, poignets et coudes alignés.","Descends la barre jusqu'aux planches puis pousse le plus fort possible, coudes rentrés."],"k":2},{"id":"Body-Up","n":"Body-up","ne":"Body-Up","e":"body only","c":"strength","l":"intermediate","m":["triceps"],"s":["abdominals","forearms"],"i":["Mets-toi en planche sur les avant-bras et les orteils, buste droit, avant-bras largeur d'épaules.","Appuie fort les paumes au sol et tends les coudes pour monter le corps, buste gainé.","Redescends lentement sur les avant-bras."],"k":2},{"id":"Body_Tricep_Press","n":"Extension triceps au poids du corps","ne":"Body Tricep Press","e":"body only","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Place une barre dans un rack à hauteur de poitrine.","Prends-la à largeur d'épaules et recule d'un ou deux pas, pieds joints, bras tendus, en appui sur la barre.","Plie les coudes pour descendre vers la barre.","Pause, puis tends les coudes pour remonter.","Pour progresser, ajoute des chaînes sur les épaules."],"k":2},{"id":"Bodyweight_Flyes","n":"Écarté au poids du corps","ne":"Bodyweight Flyes","e":"e-z curl bar","c":"strength","l":"intermediate","m":["chest"],"s":["abdominals","shoulders","triceps"],"i":["Pose deux barres EZ chargées pareil côte à côte au sol ; elles doivent pouvoir rouler.","Mets-toi en position de pompe au-dessus, bras tendus, corps droit.","Mains sur les barres : c'est la position de départ.","Lentement, écarte les mains en faisant rouler les barres, en inspirant.","Une fois au plus large, ramène-les en expirant."],"k":2},{"id":"Bodyweight_Mid_Row","n":"Rowing au poids du corps","ne":"Bodyweight Mid Row","e":"other","c":"strength","l":"intermediate","m":["middle back"],"s":["biceps","lats"],"i":["Prends une barre de traction en prise moyenne à large, paumes vers l'avant. Depuis la suspension, ramène les genoux et passe les jambes par-dessus la barre.","Bras tendus au départ, plie les coudes et serre les omoplates pour monter jusqu'à ce que les jambes touchent la barre.","Après une courte pause, redescends."],"k":2},{"id":"Bodyweight_Squat","n":"Squat au poids du corps","ne":"Bodyweight Squat","e":"body only","c":"strength","l":"beginner","m":["quadriceps"],"s":["glutes","hamstrings"],"i":["Debout, pieds largeur d'épaules, mains derrière la tête si tu veux : c'est la position de départ.","Plie genoux et hanches en reculant les fesses.","Descends aussi bas que possible puis remonte rapidement. Garde la tête et la poitrine hautes et pousse les genoux vers l'extérieur."],"k":2},{"id":"Bodyweight_Walking_Lunge","n":"Fentes marchées au poids du corps","ne":"Bodyweight Walking Lunge","e":"other","c":"strength","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Debout, pieds largeur d'épaules, mains sur les hanches.","Fais un pas en avant et descends jusqu'à ce que le genou arrière frôle le sol, buste droit, genou avant au-dessus du pied.","Pousse sur le talon avant pour remonter.","Avance le pied arrière et enchaîne avec l'autre jambe."],"k":2},{"id":"Bosu_Ball_Cable_Crunch_With_Side_Bends","n":"Crunch poulie sur Bosu avec flexions latérales","ne":"Bosu Ball Cable Crunch With Side Bends","e":"cable","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Fixe une poignée à chaque poulie, en position basse.","Place un Bosu devant la machine, au centre.","Allonge-toi dessus, bas du dos arrondi sur le ballon, fesses proches du sol sans le toucher.","Attrape une poignée dans chaque main derrière toi.","Pieds écartés, tends les bras devant toi entre les genoux, mains à hauteur des genoux.","Bras tendus dans l'axe des câbles, monte le buste en crunch sans plier les bras.","Redescends lentement, dos arrondi sur le Bosu, abdos étirés.","Continue jusqu'à l'échec.","Puis, abdos serrés, monte le buste en planche au-dessus du Bosu.","Bras tendus le long du corps, fais des flexions latérales alternées en allant chercher tes talons pour finir les obliques."],"k":2},{"id":"Bottoms-Up_Clean_From_The_Hang_Position","n":"Épaulé kettlebell à l'envers depuis la suspension","ne":"Bottoms-Up Clean From The Hang Position","e":"kettlebells","c":"strength","l":"intermediate","m":["forearms"],"s":["biceps","shoulders"],"i":["Debout, une kettlebell dans une main.","Balance-la fort vers l'arrière puis vers l'avant, serre la poignée au maximum et monte la kettlebell à l'épaule, cul vers le haut."],"k":2},{"id":"Bottoms_Up","n":"Relevé de bassin (bottoms up)","ne":"Bottoms Up","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allonge-toi sur le dos, jambes tendues, bras le long du corps.","Ramène les genoux vers la poitrine, puis tends les jambes vers le plafond et décolle les fesses du sol en enroulant le bassin.","Après une courte pause, reviens."],"k":2},{"id":"Box_Jump_Multiple_Response","n":"Sauts sur box enchaînés","ne":"Box Jump (Multiple Response)","e":"other","c":"plyometrics","l":"beginner","m":["hamstrings"],"s":["abductors","adductors","calves","glutes","quadriceps"],"i":["Debout, détendu, face à un box à environ une longueur de bras, bras le long du corps, jambes légèrement fléchies.","Aide-toi des bras et saute vers le haut et l'avant pour atterrir les deux pieds sur le box.","Redescends aussitôt en sautant et enchaîne."],"k":2},{"id":"Box_Skip","n":"Sauts sautillés sur box","ne":"Box Skip","e":"other","c":"plyometrics","l":"beginner","m":["hamstrings"],"s":["abductors","adductors","calves","glutes","quadriceps"],"i":["Aligne plusieurs box espacés d'environ 2,5 m.","Face au premier, une jambe légèrement en arrière.","Pousse sur la jambe arrière pour monter les hanches le plus haut possible.","Dès que tu touches le box, projette l'autre jambe vers l'avant et le haut pour bondir et atterris entre les deux box sur la même jambe.","Avance jusqu'au box suivant et recommence."],"k":2},{"id":"Box_Squat","n":"Box squat","ne":"Box Squat","e":"barbell","c":"powerlifting","l":"intermediate","m":["quadriceps"],"s":["adductors","calves","glutes","hamstrings","lower back"],"i":["Le box squat permet de contrôler la profondeur et de développer l'explosivité. Dans une cage, place un box derrière toi, généralement à hauteur de squat parallèle.","Pose la barre sur le haut du dos, serre les omoplates, décroche la barre en cambrant le bas du dos et recule. Pieds plus écartés pour le dos, les fessiers et les ischios, plus serrés pour les quadriceps. Regard devant.","Dos et abdos gainés, pousse genoux et fesses vers l'extérieur et descends en reculant les hanches jusqu'à t'asseoir sur le box, tibias verticaux. Marque une pause, sans rebondir.","Poids sur les talons, pousse pour te relever en menant le mouvement avec la tête, gainé de la tête aux pieds."],"k":2},{"id":"Box_Squat_with_Bands","n":"Box squat aux élastiques","ne":"Box Squat with Bands","e":"barbell","c":"powerlifting","l":"expert","m":["quadriceps"],"s":["abductors","adductors","calves","glutes","hamstrings","lower back"],"i":["Dans une cage, box derrière toi. Fixe des élastiques aux extrémités de la barre et au sol (crochets, rack ou haltères lourds bien calés) pour obtenir la tension voulue.","Pose la barre sur le haut du dos, serre les omoplates, décroche-la en cambrant le bas du dos et recule. Écartement des pieds selon les muscles visés, regard devant.","Gainé, pousse genoux et fesses vers l'extérieur et descends jusqu'à t'asseoir sur le box, tibias verticaux. Pause, sans rebondir.","Poids sur les talons, relève-toi en menant avec la tête. Repose la barre avec précaution."],"k":2},{"id":"Box_Squat_with_Chains","n":"Box squat avec chaînes","ne":"Box Squat with Chains","e":"barbell","c":"strength","l":"expert","m":["quadriceps"],"s":["abductors","adductors","calves","glutes","hamstrings","lower back"],"i":["Dans une cage, box derrière toi à hauteur de squat parallèle.","Accroche les chaînes aux extrémités de la barre ; quelques maillons doivent rester au sol en haut du mouvement.","Pose la barre sur le haut du dos, serre les omoplates, décroche-la en cambrant le bas du dos et recule. Regard devant.","Gainé, pousse genoux et fesses vers l'extérieur et descends jusqu'à t'asseoir sur le box. Pause, sans rebondir.","Poids sur les talons, relève-toi en menant avec la tête."],"k":2},{"id":"Brachialis-SMR","n":"Auto-massage brachial","ne":"Brachialis-SMR","e":"foam roll","c":"stretching","l":"intermediate","m":["biceps"],"s":[],"i":["Allonge-toi sur le côté, le bras contre un rouleau de massage, l'extérieur du biceps appuyé dessus.","Décolle les hanches, appui sur le bras et les pieds. Tiens 10 à 30 s puis change de côté."],"k":2},{"id":"Bradford_Rocky_Presses","n":"Développé Bradford / Rocky","ne":"Bradford/Rocky Presses","e":"barbell","c":"strength","l":"beginner","m":["shoulders"],"s":["triceps"],"i":["Assieds-toi sur un banc de développé militaire, barre à hauteur d'épaules en pronation, prise plus large que les épaules.","Monte la barre au-dessus de la tête bras tendus.","Descends-la lentement derrière la tête en inspirant.","Remonte en expirant.","Descends-la devant, en inspirant : cela fait une répétition.","Continue en alternant devant / derrière."],"k":2},{"id":"Butt-Ups","n":"Relevés de fessiers (butt-ups)","ne":"Butt-Ups","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["En position de pompe mais sur les avant-bras, bras à 90°.","Laisse le dos légèrement arrondi plutôt que parfaitement droit.","Monte les fesses vers le plafond en serrant les abdos, jusqu'à une position de pont haute, en expirant.","Redescends lentement en inspirant sans laisser le dos s'affaisser."],"k":2},{"id":"Butt_Lift_Bridge","n":"Pont fessier","ne":"Butt Lift (Bridge)","e":"body only","c":"strength","l":"beginner","m":["glutes"],"s":["hamstrings"],"i":["Allongé sur le dos, mains le long du corps, genoux fléchis, pieds écartés largeur d'épaules.","En poussant surtout sur les talons, décolle les hanches du sol, dos droit, en expirant. Tiens une seconde en haut.","Redescends lentement en inspirant."],"k":2},{"id":"Butterfly","n":"Butterfly (pec deck)","ne":"Butterfly","e":"machine","c":"strength","l":"beginner","m":["chest"],"s":[],"i":["Assieds-toi sur la machine, dos bien plaqué.","Prends les poignées, bras parallèles au sol (règle la machine en conséquence).","Rapproche lentement les poignées en serrant les pectoraux, en expirant, et tiens une seconde.","Reviens lentement en inspirant jusqu'à bien étirer les pectoraux."],"k":2},{"id":"Cable_Chest_Press","n":"Développé pectoraux à la poulie","ne":"Cable Chest Press","e":"cable","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Choisis la charge et assieds-toi, poignées en main, bras à environ 45° du corps, coudes à 90°, tête et poitrine hautes.","Tends les bras pour pousser les poignées droit devant toi, omoplates serrées.","Après une pause bras tendus, reviens en gardant la tension.","Variante : dos décollé, incliné, décliné ou un bras à la fois."],"k":2},{"id":"Cable_Crossover","n":"Écarté poulie vis-à-vis","ne":"Cable Crossover","e":"cable","c":"strength","l":"beginner","m":["chest"],"s":["shoulders"],"i":["Place les poulies en haut, choisis la charge et prends une poignée dans chaque main.","Avance d'un pas en ramenant les mains devant toi, buste légèrement penché : c'est la position de départ.","Coudes légèrement fléchis, ouvre les bras sur les côtés en grand arc jusqu'à sentir l'étirement des pectoraux, en inspirant. Seules les épaules bougent.","Ramène les bras par le même arc en expirant.","Tiens une seconde puis recommence."],"k":2},{"id":"Cable_Crunch","n":"Crunch à la poulie","ne":"Cable Crunch","e":"cable","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["À genoux sous une poulie haute équipée d'une corde.","Attrape la corde et descends-la jusqu'à ce que les mains soient près du visage.","Hanches légèrement fléchies : c'est la position de départ.","Hanches fixes, enroule le buste en contractant les abdos pour amener les coudes vers le milieu des cuisses, en expirant. Tiens une seconde.","Remonte lentement en inspirant, en gardant la tension sur les abdos. Évite une charge trop lourde qui ferait travailler le bas du dos."],"k":2},{"id":"Cable_Deadlifts","n":"Soulevé de terre à la poulie","ne":"Cable Deadlifts","e":"cable","c":"strength","l":"beginner","m":["quadriceps"],"s":["forearms","glutes","hamstrings","lower back"],"i":["Place les poulies en bas, choisis la charge et mets-toi entre les deux montants.","Descends en pliant hanches et genoux pour attraper les poignées.","Pousse sur les talons pour te redresser, mains le long du corps, tête et poitrine hautes.","Une fois debout, redescends et recommence."],"k":2},{"id":"Cable_Hammer_Curls_-_Rope_Attachment","n":"Curl marteau à la corde","ne":"Cable Hammer Curls - Rope Attachment","e":"cable","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Fixe une corde à la poulie basse et place-toi face à la machine à environ 30 cm.","Prends la corde paumes face à face, debout, dos droit et immobile.","Coudes collés au corps et fixes : seuls les avant-bras bougent.","Monte la corde en contractant les biceps, en expirant.","Après une seconde de contraction, redescends lentement."],"k":2},{"id":"Cable_Hip_Adduction","n":"Adduction de hanche à la poulie","ne":"Cable Hip Adduction","e":"cable","c":"strength","l":"beginner","m":["quadriceps"],"s":[],"i":["Debout face à une poulie basse, une jambe du côté de la poulie.","Attache la sangle de cheville à cette jambe.","Écarte-toi de la machine, pieds écartés, en tenant la barre de la machine.","Appui sur le pied éloigné, laisse la jambe attachée être tirée vers la poulie : c'est la position de départ.","Ramène la jambe attachée devant l'autre en serrant l'intérieur de la cuisse, en expirant.","Reviens lentement en inspirant.","Fais toutes les répétitions puis change de jambe."],"k":2},{"id":"Cable_Incline_Pushdown","n":"Extension triceps poulie sur banc incliné","ne":"Cable Incline Pushdown","e":"cable","c":"strength","l":"beginner","m":["lats"],"s":[],"i":["Allongé sur un banc incliné, dos à une poulie haute munie d'une barre droite.","Attrape la barre au-dessus de toi en pronation, largeur d'épaules, et tends les bras devant toi, barre à quelques centimètres des cuisses : c'est la position de départ.","Bras tendus, ramène la barre en demi-cercle au-dessus de la tête en inspirant.","Ramène-la lentement avec le grand dorsal et serre en fin de mouvement, en expirant."],"k":2},{"id":"Cable_Incline_Triceps_Extension","n":"Extension triceps poulie inclinée","ne":"Cable Incline Triceps Extension","e":"cable","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Allongé sur un banc incliné, dos à une poulie haute munie d'une barre droite.","Attrape la barre en pronation, prise serrée, coudes serrés contre le corps, bras à environ 25° du sol.","Bras fixes, tends les avant-bras en contractant les triceps, en expirant. Tiens une seconde.","Reviens lentement."],"k":2},{"id":"Cable_Internal_Rotation","n":"Rotation interne à la poulie","ne":"Cable Internal Rotation","e":"cable","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Assis de profil à côté d'une poulie basse, prends la poignée avec le bras le plus proche (ou assis sur un banc si la poulie est réglable).","Coude contre le corps, plié à 90°, avant-bras pointé vers la poulie : c'est la position de départ.","Tire la poignée vers ton ventre en faisant tourner l'épaule vers l'intérieur, avant-bras toujours perpendiculaire au buste.","Reviens lentement.","Fais toutes les répétitions puis change de bras."],"k":2},{"id":"Cable_Iron_Cross","n":"Croix de fer à la poulie","ne":"Cable Iron Cross","e":"cable","c":"strength","l":"beginner","m":["chest"],"s":[],"i":["Place les poulies en haut, choisis la charge et prends une poignée dans chaque main.","Debout entre les poulies, bras écartés en « T », tête et poitrine hautes : c'est la position de départ.","Coudes tendus, tire les bras vers le bas le long du corps.","Après une pause, remonte les bras."],"k":2},{"id":"Cable_Judo_Flip","n":"Judo flip à la poulie","ne":"Cable Judo Flip","e":"cable","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Fixe une corde à la poulie la plus basse. De profil, pieds écartés, attrape la corde à deux mains.","Tourne-toi à l'opposé de la poulie en passant la corde par-dessus l'épaule, comme une prise de judo.","Transfère le poids d'un pied à l'autre en tournant et en enroulant le buste vers le bas.","Reviens et continue jusqu'à l'échec.","Puis fais de même de l'autre côté."],"k":2},{"id":"Cable_Lying_Triceps_Extension","n":"Extension triceps allongé à la poulie","ne":"Cable Lying Triceps Extension","e":"cable","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Allongé sur un banc plat, prends la barre droite d'une poulie basse en pronation, prise serrée (demande-la à quelqu'un si besoin).","Bras tendus, barre au-dessus du buste, bras à 90° du corps : c'est la position de départ.","Plie les coudes, bras fixes et serrés, jusqu'à effleurer le front, en inspirant.","Tends les bras en contractant les triceps, en expirant.","Tiens une seconde puis recommence."],"k":2},{"id":"Cable_One_Arm_Tricep_Extension","n":"Extension triceps un bras à la poulie","ne":"Cable One Arm Tricep Extension","e":"cable","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Main droite sur une poignée de poulie haute en supination, face à la machine.","Tire la poignée vers le bas, bras et coude collés au corps, angle du coude inférieur à 90°. Un pied devant l'autre pour l'équilibre.","Tends le bras vers le bas en contractant le triceps, en expirant. Seul l'avant-bras bouge.","Serre le triceps une seconde.","Remonte lentement.","Fais toutes les répétitions puis change de bras."],"k":2},{"id":"Cable_Preacher_Curl","n":"Curl pupitre à la poulie","ne":"Cable Preacher Curl","e":"cable","c":"strength","l":"beginner","m":["biceps"],"s":["forearms"],"i":["Place un pupitre à environ 60 cm d'une poulie.","Fixe une barre droite à la poulie basse.","Assieds-toi au pupitre, bras bien posés sur l'appui, et fais-toi passer la barre.","Bras tendus sur le pupitre : c'est la position de départ.","Monte la barre vers les épaules en serrant fort les biceps, en expirant. Tiens une seconde.","Redescends lentement."],"k":2},{"id":"Cable_Rear_Delt_Fly","n":"Oiseau à la poulie","ne":"Cable Rear Delt Fly","e":"cable","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Règle les poulies au-dessus de la tête et choisis la charge.","Prends la poulie gauche avec la main droite et la droite avec la main gauche, bras croisés devant toi.","Écarte les bras vers l'arrière et l'extérieur, bras tendus.","Pause en fin de mouvement, puis reviens."],"k":2},{"id":"Cable_Reverse_Crunch","n":"Crunch inversé à la poulie","ne":"Cable Reverse Crunch","e":"cable","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Fixe une sangle de cheville à une poulie basse et pose un tapis devant.","Assieds-toi pieds vers la poulie et attache le câble aux chevilles.","Allonge-toi, jambes levées, genoux à 90°, alignées avec le câble.","Mains derrière la tête, ramène les genoux vers le buste en décollant les hanches du sol.","Pause, puis redescends lentement en gardant la tension sur les abdos.","Continue jusqu'à l'échec."],"k":2},{"id":"Cable_Rope_Overhead_Triceps_Extension","n":"Extension triceps nuque à la corde","ne":"Cable Rope Overhead Triceps Extension","e":"cable","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Fixe une corde à la poulie basse.","Tiens la corde à deux mains au-dessus de la tête, paumes face à face, coudes près de la tête, bras verticaux : c'est la position de départ.","Bras fixes, descends lentement la corde derrière la tête en inspirant, jusqu'à bien étirer les triceps.","Remonte en contractant les triceps, en expirant."],"k":2},{"id":"Cable_Rope_Rear-Delt_Rows","n":"Rowing arrière d'épaules à la corde","ne":"Cable Rope Rear-Delt Rows","e":"cable","c":"strength","l":"beginner","m":["shoulders"],"s":["biceps","middle back"],"i":["Assieds-toi au poste de tirage horizontal.","Fixe une corde et prends-la en pronation, bras tendus parallèles au sol, coudes écartés.","Bas du dos droit, genoux légèrement fléchis : c'est la position de départ.","Tire la corde vers le haut de la poitrine, juste sous le cou, coudes hauts et écartés, jusqu'à ce qu'ils passent légèrement derrière le dos, en expirant.","Reviens bras tendus en inspirant."],"k":2},{"id":"Cable_Russian_Twists","n":"Rotations russes à la poulie","ne":"Cable Russian Twists","e":"cable","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Fixe une poignée à une poulie à mi-hauteur.","Allonge-toi sur un swiss ball, perpendiculaire au câble, à environ une longueur de bras de la poulie, câble en tension.","Prends la poignée à deux mains, bras tendus au-dessus de la poitrine, alignés avec la poulie.","Hanches hautes, abdos serrés, tourne le buste d'un quart de tour à l'opposé de la poulie, corps droit de la tête aux genoux.","Pause puis reviens lentement en gardant la tension.","Continue jusqu'à l'échec.","Puis fais de même de l'autre côté."],"k":2},{"id":"Cable_Seated_Crunch","n":"Crunch assis à la poulie","ne":"Cable Seated Crunch","e":"cable","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Assieds-toi sur un banc plat, dos à une poulie haute.","Prends la corde à deux mains, paumes face à face, mains posées sur les épaules : c'est la position de départ.","Hanches fixes, enroule le buste pour amener les coudes vers les hanches, en expirant.","Reviens lentement en inspirant."],"k":2},{"id":"Cable_Seated_Lateral_Raise","n":"Élévations latérales assis à la poulie","ne":"Cable Seated Lateral Raise","e":"cable","c":"strength","l":"beginner","m":["shoulders"],"s":["middle back","traps"],"i":["Place-toi entre deux poulies basses, un banc plat derrière toi, et choisis la charge.","Assieds-toi au bout du banc, pieds devant les genoux.","Penche-toi, dos plat, buste posé sur les cuisses.","Prends la poulie gauche avec la main droite et la droite avec la gauche ; les câbles passent sous les genoux, bras tendus, paumes face à face, coudes légèrement fléchis.","Monte les bras sur les côtés jusqu'à hauteur d'épaules, en expirant. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Cable_Shoulder_Press","n":"Développé épaules à la poulie","ne":"Cable Shoulder Press","e":"cable","c":"strength","l":"beginner","m":["shoulders"],"s":["triceps"],"i":["Place les poulies en bas et choisis la charge.","Debout entre les montants, poignées à hauteur d'épaules, paumes vers l'avant : c'est la position de départ.","Tête et poitrine hautes, pousse les poignées au-dessus de la tête.","Pause en haut puis redescends."],"k":2},{"id":"Cable_Shrugs","n":"Shrug à la poulie","ne":"Cable Shrugs","e":"cable","c":"strength","l":"beginner","m":["traps"],"s":[],"i":["Prends la barre d'une poulie basse en pronation, largeur d'épaules ou un peu plus.","Debout près de la poulie, bras tendus devant toi : c'est la position de départ.","Monte les épaules le plus haut possible en expirant et tiens une seconde. Bras toujours tendus, seules les épaules bougent.","Redescends."],"k":2},{"id":"Cable_Wrist_Curl","n":"Curl poignets à la poulie","ne":"Cable Wrist Curl","e":"cable","c":"strength","l":"beginner","m":["forearms"],"s":[],"i":["Place un banc plat devant une poulie basse équipée d'une barre droite.","Prends la barre en supination, avant-bras posés sur les cuisses, poignets dans le vide au-delà des genoux.","Monte les poignets en expirant et tiens une seconde.","Redescends lentement en inspirant. Seuls les poignets bougent."],"k":2},{"id":"Calf-Machine_Shoulder_Shrug","n":"Shrug à la machine à mollets","ne":"Calf-Machine Shoulder Shrug","e":"machine","c":"strength","l":"beginner","m":["traps"],"s":[],"i":["Place-toi sous les appuis d'une machine à mollets, appuis sur les épaules, buste droit, bras le long du corps.","Monte les épaules vers les oreilles en expirant et tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Calf_Press","n":"Presse à mollets","ne":"Calf Press","e":"machine","c":"strength","l":"beginner","m":["calves"],"s":[],"i":["Règle le siège pour avoir les jambes à peine fléchies au départ, avant des pieds bien posé sur la plateforme.","Choisis la charge et prends les poignées.","Tends les jambes pour décoller la charge, chevilles fléchies, orteils vers le haut. Pousse avec l'avant des pieds le plus loin possible.","Après une courte pause, reviens."],"k":2},{"id":"Calf_Press_On_The_Leg_Press_Machine","n":"Mollets à la presse à cuisses","ne":"Calf Press On The Leg Press Machine","e":"machine","c":"strength","l":"beginner","m":["calves"],"s":[],"i":["Assieds-toi sur la presse, pieds largeur d'épaules sur la plateforme.","Déverrouille les sécurités et pousse jusqu'à jambes tendues sans verrouiller les genoux. Place ensuite l'avant des pieds sur le bas de la plateforme, talons dans le vide : c'est la position de départ.","Pousse en montant les talons le plus haut possible, en expirant ; les genoux ne bougent pas. Tiens une seconde.","Reviens lentement en inspirant jusqu'à bien étirer les mollets."],"k":2},{"id":"Calf_Raise_On_A_Dumbbell","n":"Mollets sur un haltère","ne":"Calf Raise On A Dumbbell","e":"dumbbell","c":"strength","l":"intermediate","m":["calves"],"s":[],"i":["Tiens-toi à un appui et monte avec l'avant des pieds sur la barre d'un haltère (avec disques ronds, il roule : c'est plus dur à stabiliser donc plus efficace).","Laisse le pied rouler un peu vers l'avant pour étirer le mollet : c'est la position de départ.","Monte sur la pointe en faisant rouler le pied sur la barre, en expirant. Serre fort une seconde.","Redescends en inspirant en laissant rouler l'haltère vers l'avant pour mieux étirer."],"k":2},{"id":"Calf_Raises_-_With_Bands","n":"Mollets aux élastiques","ne":"Calf Raises - With Bands","e":"bands","c":"strength","l":"beginner","m":["calves"],"s":[],"i":["Debout avec l'avant des pieds sur un élastique, même longueur de chaque côté.","Tiens les poignées à hauteur d'épaules, paumes vers l'avant, coudes sur les côtés, élastique tendu : c'est la position de départ.","Mains aux épaules, monte sur la pointe des pieds en expirant et serre fort les mollets en haut.","Après une seconde, redescends lentement."],"k":2},{"id":"Calf_Stretch_Elbows_Against_Wall","n":"Étirement mollets coudes au mur","ne":"Calf Stretch Elbows Against Wall","e":"other","c":"stretching","l":"beginner","m":["calves"],"s":[],"i":["Debout face à un mur, à environ 60 cm.","Penche-toi et appuie-toi sur les avant-bras contre le mur.","Garde les talons au sol et tiens 10 à 20 s. Éloigne-toi du mur pour accentuer, rapproche-toi pour diminuer."],"k":2},{"id":"Calf_Stretch_Hands_Against_Wall","n":"Étirement mollets mains au mur","ne":"Calf Stretch Hands Against Wall","e":"other","c":"stretching","l":"beginner","m":["calves"],"s":[],"i":["Debout face à un mur, à 1 m environ, un pied devant l'autre.","Penche-toi, mains contre le mur, talon arrière, hanche et tête alignés.","Garde le talon au sol, tiens 10 à 20 s puis change de côté."],"k":2},{"id":"Calves-SMR","n":"Auto-massage des mollets","ne":"Calves-SMR","e":"foam roll","c":"stretching","l":"intermediate","m":["calves"],"s":[],"i":["Assieds-toi au sol, un rouleau de massage sous le mollet ; l'autre jambe croisée dessus ou au sol pour soulager.","Mains au sol à côté ou derrière toi, décolle les hanches et roule du genou à la cheville, en restant 10 à 30 s sur les points sensibles. Change de jambe."],"k":2},{"id":"Car_Deadlift","n":"Soulevé de terre de voiture","ne":"Car Deadlift","e":"other","c":"strongman","l":"intermediate","m":["quadriceps"],"s":["forearms","glutes","hamstrings","lower back","traps"],"i":["Épreuve de strongman : l'appareil (souvent à poignées neutres) est chargé d'une voiture ou d'objets lourds.","Place-toi au centre des poignées, pieds largeur de hanches. Penche-toi pour les saisir, inspire fort, descends les hanches et plie les genoux.","Regard devant, poitrine haute, dos cambré, pousse sur les talons. En montant, serre les omoplates et avance les hanches.","Redescends en pliant les hanches jusqu'au sol."],"k":2},{"id":"Car_Drivers","n":"Volant (car drivers)","ne":"Car Drivers","e":"barbell","c":"strength","l":"beginner","m":["shoulders"],"s":["forearms"],"i":["Debout, tiens un disque à deux mains comme un volant (mains à 3 h et 9 h), bras tendus devant toi.","Tourne le disque au maximum d'un côté, comme un volant.","Puis tourne-le complètement de l'autre côté."],"k":2},{"id":"Carioca_Quick_Step","n":"Pas croisés carioca","ne":"Carioca Quick Step","e":"other","c":"plyometrics","l":"beginner","m":["adductors"],"s":["abdominals","abductors","calves","glutes","hamstrings","quadriceps"],"i":["Pieds légèrement écartés, bras gauche levé, en position athlétique détendue.","Passe vivement le pied droit derrière en montant le genou.","Lance les bras en même temps ; le genou monte et descend bien verticalement. Pieds orientés vers l'avant, regard devant pendant que tu te déplaces sur le côté."],"k":2},{"id":"Cat_Stretch","n":"Étirement du chat","ne":"Cat Stretch","e":"other","c":"stretching","l":"beginner","m":["lower back"],"s":["middle back","traps"],"i":["À quatre pattes au sol.","Rentre le ventre et arrondis la colonne, le bas du dos, les épaules et la nuque, tête relâchée.","Tiens 15 s."],"k":2},{"id":"Catch_and_Overhead_Throw","n":"Réception et lancer au-dessus de la tête","ne":"Catch and Overhead Throw","e":"medicine ball","c":"plyometrics","l":"beginner","m":["lats"],"s":["abdominals","chest","shoulders"],"i":["Debout face à un mur ou à un partenaire.","Ballon à deux mains derrière la tête, bras bien étirés, lance-le vers l'avant avec force.","Accompagne le geste et prépare-toi à recevoir le rebond. Contre un mur, reste assez près et vise un peu plus haut."],"k":2},{"id":"Chain_Handle_Extension","n":"Extension à la poignée de chaîne","ne":"Chain Handle Extension","e":"other","c":"powerlifting","l":"intermediate","m":["triceps"],"s":[],"i":["Il faut deux poignées de poulie, des chaînes et un banc plat. Accroche le milieu des chaînes aux poignées et allonge-toi, coudes pointés vers le plafond.","Tends les coudes, bras fixes, poignets en pronation.","Pause bras tendus, puis reviens."],"k":2},{"id":"Chain_Press","n":"Développé avec chaînes","ne":"Chain Press","e":"other","c":"powerlifting","l":"intermediate","m":["chest"],"s":["shoulders","triceps"],"i":["Accroche les chaînes aux poignées et allonge-toi sur un banc plat comme pour un développé haltères, poignets en pronation, bras verticaux.","Descends en pliant les coudes ; une partie de la chaîne se pose au sol.","Continue jusqu'à 90° aux coudes, puis pousse jusqu'à bras tendus."],"k":2},{"id":"Chair_Leg_Extended_Stretch","n":"Étirement jambe tendue sur chaise","ne":"Chair Leg Extended Stretch","e":"other","c":"stretching","l":"beginner","m":["hamstrings"],"s":["adductors"],"i":["Assis droit sur une chaise, mains de chaque côté de l'assise.","Lève une jambe en tendant le genou, cheville fléchie.","Écarte lentement la jambe au maximum, puis ramène-la au centre et repose-la.","Fais de même avec l'autre jambe."],"k":2},{"id":"Chair_Lower_Back_Stretch","n":"Étirement du bas du dos sur chaise","ne":"Chair Lower Back Stretch","e":"other","c":"stretching","l":"beginner","m":["lats"],"s":["lower back"],"i":["Assis droit sur une chaise.","Penche-toi sur le côté, bras au-dessus de la tête ; l'autre main peut tenir la chaise.","Tiens 10 s puis change de côté."],"k":2},{"id":"Chair_Squat","n":"Squat sur chaise","ne":"Chair Squat","e":"machine","c":"strength","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Règle la barre à ta hauteur, passe dessous et pose-la sur le haut du dos.","Prends la barre paumes vers l'avant et décroche-la en tendant les jambes.","Avance les pieds d'environ 45 cm devant la barre, largeur d'épaules, pointes légèrement ouvertes, regard devant, dos neutre.","Descends lentement en pliant les genoux, tête haute, jusqu'à passer sous 90°.","Remonte en expirant en poussant sur les talons."],"k":2},{"id":"Chair_Upper_Body_Stretch","n":"Étirement du haut du corps sur chaise","ne":"Chair Upper Body Stretch","e":"other","c":"stretching","l":"beginner","m":["shoulders"],"s":["biceps","chest"],"i":["Assis au bord d'une chaise, tiens le dossier derrière toi.","Bras tendus, dos droit, tire le buste vers l'avant jusqu'à sentir l'étirement. Tiens 20 à 30 s."],"k":2},{"id":"Chest_And_Front_Of_Shoulder_Stretch","n":"Étirement pectoraux et avant des épaules","ne":"Chest And Front Of Shoulder Stretch","e":"other","c":"stretching","l":"beginner","m":["chest"],"s":["shoulders"],"i":["Debout, jambes serrées, tiens un bâton ou une barre légère.","Prise un peu plus large que les épaules, paumes vers le bas, bâton devant toi.","Monte prudemment le bâton au-dessus puis derrière la tête."],"k":2},{"id":"Chest_Push_from_3_point_stance","n":"Poussée de poitrine en appui 3 points","ne":"Chest Push from 3 point stance","e":"medicine ball","c":"plyometrics","l":"beginner","m":["chest"],"s":["abdominals","shoulders","triceps"],"i":["En appui sur trois points, accroupi dos plat, une main au sol, médecine-ball devant toi.","Au premier pas, ramène le ballon contre la poitrine, mains prêtes à lancer.","Au deuxième pas, lance le ballon devant toi le plus fort possible."],"k":2},{"id":"Chest_Push_multiple_response","n":"Poussée de poitrine enchaînée","ne":"Chest Push (multiple response)","e":"medicine ball","c":"plyometrics","l":"beginner","m":["chest"],"s":["abdominals","shoulders","triceps"],"i":["À genoux face à un mur ou à un partenaire, ballon serré contre la poitrine.","Projette-toi vers l'avant avec les hanches en poussant le ballon le plus fort possible.","Laisse-toi tomber vers l'avant et réceptionne-toi sur les mains.","Redresse-toi aussitôt et enchaîne."],"k":2},{"id":"Chest_Push_single_response","n":"Poussée de poitrine unique","ne":"Chest Push (single response)","e":"medicine ball","c":"plyometrics","l":"beginner","m":["chest"],"s":["abdominals","shoulders","triceps"],"i":["À genoux, médecine-ball serré contre la poitrine.","Projette-toi vers l'avant avec les hanches en poussant le ballon le plus loin possible.","Laisse-toi tomber vers l'avant et réceptionne-toi sur les mains."],"k":2},{"id":"Chest_Push_with_Run_Release","n":"Poussée de poitrine avec départ en course","ne":"Chest Push with Run Release","e":"medicine ball","c":"plyometrics","l":"beginner","m":["chest"],"s":["abdominals","shoulders","triceps"],"i":["Position athlétique : genoux fléchis, hanches en arrière, dos plat, ballon près des jambes.","Au premier pas, ramène le ballon contre la poitrine.","Au deuxième pas, pousse le ballon explosivement vers l'avant puis sprinte une dizaine de mètres."],"k":2},{"id":"Chest_Stretch_on_Stability_Ball","n":"Étirement pectoraux sur swiss ball","ne":"Chest Stretch on Stability Ball","e":"exercise ball","c":"stretching","l":"beginner","m":["chest"],"s":[],"i":["À quatre pattes à côté d'un swiss ball.","Pose le coude sur le ballon, bras sur le côté : c'est la position de départ.","Descends le buste vers le sol, coude toujours sur le ballon. Tiens 20 à 30 s puis change de bras."],"k":2},{"id":"Childs_Pose","n":"Posture de l'enfant","ne":"Child's Pose","e":"other","c":"stretching","l":"beginner","m":["lower back"],"s":["glutes","middle back"],"i":["À quatre pattes, avance les mains devant toi.","Descends les fesses sur les talons en laissant les bras glisser au sol pour étirer toute la colonne.","Une fois assis sur les talons, ramène les mains près des pieds, front au sol, et respire profondément dans le dos. Évite cette posture en cas de problème de genou."],"k":2},{"id":"Chin-Up","n":"Traction supination (chin-up)","ne":"Chin-Up","e":"body only","c":"strength","l":"beginner","m":["lats"],"s":["biceps","forearms","middle back"],"i":["Attrape la barre paumes vers toi, prise plus serrée que les épaules.","Bras tendus, buste le plus droit possible, poitrine sortie, bas du dos légèrement cambré : c'est la position de départ.","En expirant, monte jusqu'à ce que la tête arrive au niveau de la barre, en te concentrant sur les biceps, coudes près du corps.","Après une seconde de contraction, redescends lentement bras tendus en inspirant."],"k":2},{"id":"Chin_To_Chest_Stretch","n":"Étirement menton vers la poitrine","ne":"Chin To Chest Stretch","e":"other","c":"stretching","l":"beginner","m":["neck"],"s":["traps"],"i":["Assieds-toi au sol.","Mains croisées derrière la tête, pouces vers le bas, coudes vers l'avant. Tire doucement la tête vers la poitrine et tiens 20 à 30 s."],"k":2},{"id":"Circus_Bell","n":"Haltère de cirque","ne":"Circus Bell","e":"other","c":"strongman","l":"expert","m":["shoulders"],"s":["forearms","glutes","hamstrings","lower back","traps","triceps"],"i":["L'haltère de cirque est un haltère géant à poignée épaisse. Commence avec l'haltère entre les pieds, poignée à deux mains.","Monte-le à l'épaule en poussant hanches et genoux, puis lâche la main libre.","Garde une tête de l'haltère derrière l'épaule pour l'équilibre. Fléchis les genoux puis pousse pour l'envoyer au-dessus de la tête en te penchant légèrement à l'opposé.","Redescends-le au sol en le contrôlant, idéalement sur un épais tapis."],"k":2},{"id":"Clean","n":"Épaulé","ne":"Clean","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["hamstrings"],"s":["calves","forearms","glutes","lower back","quadriceps","shoulders","traps"],"i":["Barre au sol contre les tibias, prise en pronation (ou crochet) juste à l'extérieur des jambes. Hanches basses, poids sur les talons, dos droit, regard devant, poitrine haute, épaules juste devant la barre.","Premier tirage : pousse sur les talons en tendant les genoux, angle du dos constant, bras tendus, jusqu'au-dessus des genoux.","Deuxième tirage : à mi-cuisse, tends explosivement hanches, genoux et chevilles comme pour sauter. Les bras ne tirent pas encore.","Troisième tirage : haussement d'épaules, coudes hauts, puis tire-toi sous la barre en tournant les coudes. Réceptionne en squat avant, barre sur les épaules, mains détendues.","Relève-toi aussitôt en poussant sur les talons, buste droit, coudes hauts."],"k":2},{"id":"Clean_Deadlift","n":"Soulevé de terre d'épaulé","ne":"Clean Deadlift","e":"barbell","c":"olympic weightlifting","l":"beginner","m":["hamstrings"],"s":["forearms","glutes","lower back","middle back","quadriceps","traps"],"i":["Debout, barre contre les tibias, pieds sous les hanches légèrement ouverts. Prise en pronation ou crochet, largeur d'épaules. Descends vers la barre, dos bien droit, épaules devant la barre.","Pousse sur les talons ; garde le même angle du dos pendant la montée et écarte les genoux pour libérer le passage de la barre.","Une fois les genoux passés, pousse les hanches vers la barre jusqu'à être debout."],"k":2},{"id":"Clean_Pull","n":"Tirage d'épaulé","ne":"Clean Pull","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["quadriceps"],"s":["forearms","glutes","hamstrings","lower back","traps"],"i":["Barre au sol contre les tibias, prise en pronation ou crochet juste à l'extérieur des jambes. Hanches basses, dos droit, regard devant, épaules juste devant la barre.","Premier tirage : pousse sur les talons, angle du dos constant, bras tendus, jusqu'au-dessus des genoux.","Deuxième tirage : à mi-cuisse, tends explosivement hanches, genoux et chevilles. Le corps finit en extension complète, légèrement en arrière, bras toujours tendus, sans prolonger l'extension."],"k":2},{"id":"Clean_Shrug","n":"Shrug d'épaulé","ne":"Clean Shrug","e":"barbell","c":"olympic weightlifting","l":"beginner","m":["traps"],"s":["forearms","shoulders"],"i":["Prise largeur d'épaules en pronation ou crochet, barre suspendue à mi-cuisse, dos droit légèrement incliné vers l'avant.","Monte les épaules vers les oreilles. On peut charger plus lourd qu'à l'épaulé, mais pas au point de ralentir le mouvement."],"k":2},{"id":"Clean_and_Jerk","n":"Épaulé-jeté","ne":"Clean and Jerk","e":"barbell","c":"olympic weightlifting","l":"expert","m":["shoulders"],"s":["abdominals","glutes","hamstrings","lower back","quadriceps","traps","triceps"],"i":["Barre au sol contre les tibias, prise en pronation ou crochet juste à l'extérieur des jambes. Hanches basses, dos droit, regard devant, épaules juste devant la barre.","Premier tirage : pousse sur les talons, angle du dos constant, bras tendus, jusqu'au-dessus des genoux.","Deuxième tirage : à mi-cuisse, tends explosivement hanches, genoux et chevilles comme pour sauter, bras tendus.","Troisième tirage : haussement d'épaules, coudes hauts, puis tire-toi sous la barre en tournant les coudes. Réceptionne en squat avant, barre posée sur les épaules.","Relève-toi en poussant sur les talons, buste droit, coudes hauts.","Le jeté : barre sur les épaules, pieds sous les hanches, fléchis légèrement les genoux sans reculer les hanches, puis inverse le plus puissamment possible.","Pousse fort sur les talons et écarte la tête du trajet de la barre.","Place vite les pieds en fente (un devant, un derrière) et réceptionne la barre bras verrouillés au-dessus de la tête. Reviens debout."],"k":2},{"id":"Clean_and_Press","n":"Épaulé et développé","ne":"Clean and Press","e":"barbell","c":"strength","l":"intermediate","m":["shoulders"],"s":["abdominals","calves","glutes","hamstrings","lower back","middle back","quadriceps","shoulders","traps","triceps"],"i":["Pieds largeur d'épaules, genoux entre les bras. Dos plat, plie genoux et hanches pour saisir la barre en pronation un peu plus large que les épaules, bras tendus, coudes vers l'extérieur, barre contre les tibias, épaules au-dessus ou un peu devant la barre.","Tire la barre en tendant les genoux ; hanches et épaules montent ensemble, angle du dos constant, barre près du corps.","Une fois les genoux passés, tends explosivement chevilles, genoux et hanches comme pour sauter, en haussant les épaules pour monter la barre le plus haut possible, coudes vers l'extérieur.","Au point haut, glisse-toi sous la barre en descendant en squat.","Tourne les coudes sous la barre et pose-la sur l'avant des épaules, buste droit, en amortissant avec les jambes.","Relève-toi, barre sur les épaules.","Sans bouger les pieds, pousse la barre au-dessus de la tête en expirant, puis redescends-la en contrôlant."],"k":2},{"id":"Clean_from_Blocks","n":"Épaulé depuis des blocs","ne":"Clean from Blocks","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings","shoulders","traps"],"i":["Barre posée sur des blocs à la hauteur voulue, prise en pronation ou crochet juste à l'extérieur des jambes. Hanches basses, dos droit, regard devant, épaules juste devant la barre.","Pousse sur les talons en tendant les genoux, angle du dos constant, bras tendus, coudes vers l'extérieur.","À l'extension complète, haussement d'épaules et coudes hauts, puis tire-toi sous la barre en tournant les coudes. Réceptionne en squat avant.","Relève-toi en poussant sur les talons, buste droit. Repose la barre sur les blocs."],"k":2},{"id":"Clock_Push-Up","n":"Pompes en horloge","ne":"Clock Push-Up","e":"body only","c":"strength","l":"intermediate","m":["chest"],"s":["shoulders","triceps"],"i":["En position de pompe, mains largeur d'épaules, bras tendus, corps droit.","Descends en pliant les coudes.","En bas, pousse le plus vite possible pour décoller du sol et « sauter » d'environ 40 cm sur le côté.","En montant, déplace aussi les pieds pour tourner le corps d'environ 30°.","Recommence jusqu'à faire le tour complet."],"k":2},{"id":"Close-Grip_Barbell_Bench_Press","n":"Développé couché prise serrée","ne":"Close-Grip Barbell Bench Press","e":"barbell","c":"strength","l":"beginner","m":["triceps"],"s":["chest","shoulders"],"i":["Allongé sur un banc plat, prise serrée (environ largeur d'épaules), barre tenue bras tendus.","En inspirant, descends lentement jusqu'au milieu de la poitrine, coudes près du corps pour cibler les triceps.","Après une seconde, pousse avec les triceps en expirant. La descente doit durer deux fois plus longtemps que la montée.","À la fin, repose la barre."],"k":2},{"id":"Close-Grip_Dumbbell_Press","n":"Développé haltères prise serrée","ne":"Close-Grip Dumbbell Press","e":"dumbbell","c":"strength","l":"beginner","m":["triceps"],"s":["chest","shoulders"],"i":["Pose un haltère debout sur un banc plat.","Allonge-toi en travers du banc, seules les épaules posées, hanches plus basses, pieds au sol.","Tiens l'haltère à deux mains au-dessus de la poitrine, bras tendus, paumes contre un disque : c'est la position de départ.","Descends l'haltère jusqu'à la poitrine.","Remonte en tendant les coudes."],"k":2},{"id":"Close-Grip_EZ-Bar_Curl_with_Band","n":"Curl barre EZ prise serrée avec élastique","ne":"Close-Grip EZ-Bar Curl with Band","e":"e-z curl bar","c":"strength","l":"beginner","m":["biceps"],"s":["forearms"],"i":["Fixe un élastique à chaque extrémité de la barre EZ et pose un pied au milieu. Debout, prise serrée en supination, coudes près du corps.","Bras fixes, plie les coudes pour faire le curl en expirant.","Continue jusqu'à hauteur d'épaules et serre fort les biceps une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Close-Grip_EZ-Bar_Press","n":"Développé barre EZ prise serrée","ne":"Close-Grip EZ-Bar Press","e":"e-z curl bar","c":"strength","l":"beginner","m":["triceps"],"s":["chest","shoulders"],"i":["Allongé sur un banc plat avec une barre EZ chargée.","Prise serrée, barre au-dessus du buste, coudes rentrés, bras verticaux : c'est la position de départ.","Descends la barre vers le bas de la poitrine en inspirant, coudes rentrés.","Pousse avec les triceps pour revenir, en expirant."],"k":2},{"id":"Close-Grip_EZ_Bar_Curl","n":"Curl barre EZ prise serrée","ne":"Close-Grip EZ Bar Curl","e":"barbell","c":"strength","l":"beginner","m":["biceps"],"s":["forearms"],"i":["Debout, buste droit, barre EZ tenue par les poignées intérieures, paumes vers l'avant, coudes près du corps.","Bras fixes, monte la barre en contractant les biceps, en expirant. Seuls les avant-bras bougent.","Continue jusqu'à hauteur d'épaules et serre fort une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Close-Grip_Front_Lat_Pulldown","n":"Tirage vertical prise serrée","ne":"Close-Grip Front Lat Pulldown","e":"cable","c":"strength","l":"beginner","m":["lats"],"s":["biceps","middle back","shoulders"],"i":["Assieds-toi au poste de tirage, cale les genoux sous les boudins.","Prends la barre paumes vers l'avant, mains plus serrées que les épaules.","Bras tendus, recule le buste d'environ 30°, poitrine sortie, bas du dos cambré : c'est la position de départ.","En expirant, tire la barre jusqu'au haut de la poitrine en abaissant épaules et coudes. Serre le dos ; le buste ne bouge pas, les avant-bras ne font que tenir.","Après une seconde, remonte lentement jusqu'à bras tendus en inspirant."],"k":2},{"id":"Close-Grip_Push-Up_off_of_a_Dumbbell","n":"Pompes prise serrée sur un haltère","ne":"Close-Grip Push-Up off of a Dumbbell","e":"body only","c":"strength","l":"intermediate","m":["triceps"],"s":["abdominals","chest","shoulders"],"i":["Mains posées sur un haltère debout au sol, en appui sur les orteils, corps gainé, coudes serrés, bras tendus.","Descends en pliant les coudes en inspirant, corps bien droit.","Remonte en tendant les coudes, en expirant.","Marque une pause en haut puis recommence."],"k":2},{"id":"Close-Grip_Standing_Barbell_Curl","n":"Curl barre debout prise serrée","ne":"Close-Grip Standing Barbell Curl","e":"barbell","c":"strength","l":"beginner","m":["biceps"],"s":["forearms"],"i":["Barre en main, paumes vers le haut, mains à quelques centimètres l'une de l'autre.","Debout, buste droit, tête haute, pieds largeur d'épaules, coudes près du corps et fixes.","Monte la barre en arc de cercle jusqu'à ce que les avant-bras touchent les biceps, en expirant. Serre fort une seconde, sans balancer.","Redescends lentement en inspirant."],"k":2},{"id":"Cocoons","n":"Cocons (crunch complet)","ne":"Cocoons","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur le dos, jambes tendues, bras tendus derrière la tête.","Ramène les genoux vers la poitrine en décollant les fesses, tout en enroulant le buste et en ramenant les bras par-dessus la tête (crunch simultané).","Après une courte pause, reviens."],"k":2},{"id":"Conans_Wheel","n":"Roue de Conan","ne":"Conan's Wheel","e":"other","c":"strongman","l":"intermediate","m":["quadriceps"],"s":["abdominals","biceps","calves","forearms","lower back","shoulders","traps"],"i":["Charge l'appareil et prends l'extrémité du bras en position Zercher : barre au creux des coudes, mains qui se tiennent les poignets.","Soulève la charge, reste droit et gainé, et marche à petits pas rapides en tournant en cercle, regard au loin, sans bloquer ta respiration. Fais un ou plusieurs tours."],"k":2},{"id":"Concentration_Curls","n":"Curl concentration","ne":"Concentration Curls","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":["forearms"],"i":["Assis au bout d'un banc plat, jambes écartées, un haltère au sol entre les pieds.","Prends l'haltère main droite, arrière du bras contre l'intérieur de la cuisse droite, paume vers l'avant, bras tendu : c'est la position de départ.","Bras fixe, monte l'haltère en contractant le biceps, en expirant, jusqu'à hauteur d'épaule. En haut, le petit doigt plus haut que le pouce. Tiens une seconde.","Redescends lentement en inspirant, sans balancer.","Fais toutes les répétitions puis change de bras."],"k":2},{"id":"Cross-Body_Crunch","n":"Crunch croisé","ne":"Cross-Body Crunch","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur le dos, genoux fléchis à environ 60°.","Pieds à plat, mains posées derrière la tête : c'est la position de départ.","Enroule-toi en amenant le coude et l'épaule droits vers le genou gauche, qui se rapproche en même temps, en expirant. Ce sont les abdos qui travaillent, pas seulement le coude.","Reviens en inspirant et fais de même avec le coude gauche et le genou droit.","Continue en alternant."],"k":2},{"id":"Cross_Body_Hammer_Curl","n":"Curl marteau croisé","ne":"Cross Body Hammer Curl","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":["forearms"],"i":["Debout, un haltère dans chaque main le long du corps, paumes vers l'intérieur.","Sans tourner le poignet, monte l'haltère droit vers l'épaule gauche en expirant. Touche l'épaule et tiens une seconde.","Redescends par le même chemin en inspirant puis fais de même avec le bras gauche.","Continue en alternant."],"k":2},{"id":"Cross_Over_-_With_Bands","n":"Écarté croisé aux élastiques","ne":"Cross Over - With Bands","e":"bands","c":"strength","l":"beginner","m":["chest"],"s":["biceps","shoulders"],"i":["Accroche un élastique à un poteau fixe.","Dos au poteau, prends les poignées et avance pour tendre l'élastique.","Bras écartés en « T », parallèles au sol, paumes vers l'avant, coudes légèrement fléchis : c'est la position de départ.","Bras tendus, ramène les mains devant la poitrine en arc de cercle en contractant les pectoraux, en expirant. Tiens une seconde.","Reviens lentement en inspirant."],"k":2},{"id":"Crossover_Reverse_Lunge","n":"Fente arrière croisée","ne":"Crossover Reverse Lunge","e":"other","c":"stretching","l":"intermediate","m":["lower back"],"s":["abdominals","abductors","glutes","hamstrings","quadriceps"],"i":["Debout, pieds largeur d'épaules.","Fais une fente arrière en reculant un pied, en tournant le buste vers la jambe avant.","Après une courte pause, reviens et fais de même de l'autre côté, en alternant."],"k":2},{"id":"Crucifix","n":"Crucifix","ne":"Crucifix","e":"other","c":"strongman","l":"beginner","m":["shoulders"],"s":["forearms"],"i":["Il s'agit de tenir des charges bras tendus sur les côtés le plus longtemps possible (haltères, haches ou marteaux de compétition).","Debout, monte les bras sur les côtés jusqu'à l'horizontale et tiens le plus longtemps possible. La charge doit faire céder en 30 à 60 s."],"k":2},{"id":"Crunch_-_Hands_Overhead","n":"Crunch mains au-dessus de la tête","ne":"Crunch - Hands Overhead","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur le dos, genoux fléchis à environ 60°.","Pieds à plat, bras tendus au-dessus de la tête, mains croisées : c'est la position de départ.","Enroule le haut du corps juste assez pour décoller les omoplates, bras toujours alignés avec la tête, en expirant. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Crunch_-_Legs_On_Exercise_Ball","n":"Crunch jambes sur swiss ball","ne":"Crunch - Legs On Exercise Ball","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur le dos, pieds posés sur un swiss ball, genoux à 90°.","Pieds écartés de 8 à 10 cm, orteils tournés vers l'intérieur.","Mains posées de chaque côté de la tête, coudes rentrés, sans croiser les doigts.","Plaque le bas du dos au sol : c'est la position de départ.","Décolle les épaules d'une dizaine de centimètres en gardant le bas du dos au sol, en expirant. Serre fort une seconde, sans élan.","Redescends lentement en inspirant."],"k":2},{"id":"Crunches","n":"Crunchs","ne":"Crunches","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur le dos, pieds à plat au sol (ou sur un banc, genoux à 90°).","Mains posées de chaque côté de la tête, coudes rentrés, sans croiser les doigts.","En plaquant le bas du dos au sol, décolle les épaules.","Monte d'une dizaine de centimètres en contractant les abdos et en expirant, bas du dos au sol. Serre fort une seconde, sans élan.","Redescends lentement en inspirant."],"k":2},{"id":"Cuban_Press","n":"Développé cubain","ne":"Cuban Press","e":"dumbbell","c":"strength","l":"intermediate","m":["shoulders"],"s":["traps"],"i":["Debout, un haltère dans chaque main en pronation. Monte les bras à l'horizontale, avant-bras pendants (position de l'épouvantail).","Fais tourner les épaules vers l'extérieur jusqu'à ce que les poignets soient au-dessus des coudes, avant-bras verticaux, bras immobiles.","Pousse ensuite les haltères au-dessus de la tête.","Reviens en inspirant en refaisant les étapes à l'envers."],"k":2},{"id":"Dancers_Stretch","n":"Étirement du danseur","ne":"Dancer's Stretch","e":"other","c":"stretching","l":"beginner","m":["lower back"],"s":["abductors","glutes"],"i":["Assis au sol.","Croise la jambe droite par-dessus la gauche, genou plié ; la jambe gauche reste tendue au sol.","Pose le bras gauche sur la jambe droite et la main droite au sol.","Tourne le haut du corps vers la droite et tiens 10 à 20 s. Change de côté."],"k":2},{"id":"Dead_Bug","n":"Dead bug","ne":"Dead Bug","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur le dos, bras tendus vers le plafond.","Monte pieds, genoux et hanches à 90°.","Expire fort pour abaisser les côtes et plaquer le dos au sol, bassin enroulé, fessiers serrés. Garde cette position tout au long : c'est la position de départ.","Tends une jambe jusqu'à ce qu'elle frôle le sol.","Le bas du dos va vouloir se cambrer : garde-le plaqué.","Reste gainé et ramène la jambe.","Fais de même de l'autre côté, en alternant."],"k":2},{"id":"Deadlift_with_Bands","n":"Soulevé de terre aux élastiques","ne":"Deadlift with Bands","e":"barbell","c":"powerlifting","l":"expert","m":["lower back"],"s":["forearms","glutes","hamstrings","middle back","quadriceps","traps"],"i":["Avec des élastiques courts, passe-les sur la barre et glisse les pieds dedans. Les élastiques longs doivent être fixés à une base solide (haltères lourds ou rack).","Inspire fort, descends les hanches jusqu'à ce que les tibias touchent la barre, regard devant, poitrine haute, dos cambré, puis pousse sur les talons. Une fois les genoux passés, tire la barre vers toi en serrant les omoplates et en avançant les hanches.","Redescends en pliant les hanches et en guidant la barre jusqu'au sol."],"k":2},{"id":"Deadlift_with_Chains","n":"Soulevé de terre avec chaînes","ne":"Deadlift with Chains","e":"barbell","c":"powerlifting","l":"expert","m":["lower back"],"s":["forearms","glutes","hamstrings","middle back","quadriceps","traps"],"i":["Accroche les chaînes aux extrémités de la barre, ou pose-les à cheval sur la barre.","Barre au-dessus du milieu des pieds, pieds largeur de hanches. Penche-toi et prends la barre à largeur d'épaules (pronation ou prise mixte). Inspire fort et descends jusqu'à ce que les tibias touchent la barre.","Regard devant, poitrine haute, dos cambré, pousse sur les talons. Une fois les genoux passés, tire la barre vers toi en avançant les hanches.","Redescends en pliant les hanches et en guidant la barre jusqu'au sol."],"k":2},{"id":"Decline_Barbell_Bench_Press","n":"Développé décliné barre","ne":"Decline Barbell Bench Press","e":"barbell","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Cale tes jambes au bout du banc décliné et allonge-toi lentement.","Prise moyenne, sors la barre (idéalement avec un partenaire) et tiens-la bras tendus, verticaux.","En inspirant, descends lentement jusqu'au bas de la poitrine.","Après une seconde, pousse avec les pectoraux en expirant et serre en haut. La descente doit durer deux fois plus longtemps que la montée.","À la fin, repose la barre."],"k":2},{"id":"Decline_Close-Grip_Bench_To_Skull_Crusher","n":"Développé décliné prise serrée vers barre au front","ne":"Decline Close-Grip Bench To Skull Crusher","e":"barbell","c":"strength","l":"intermediate","m":["triceps"],"s":["chest","shoulders"],"i":["Cale tes jambes au bout du banc décliné et allonge-toi lentement.","Prise serrée, sors la barre (idéalement avec un partenaire) et tiens-la bras tendus, coudes rentrés.","Descends la barre vers le bas de la poitrine en inspirant, coudes rentrés.","Pousse avec les triceps pour revenir, en expirant.","Puis, bras fixes, plie les coudes pour descendre la barre en arc jusqu'à effleurer le front, en inspirant.","Remonte en contractant les triceps, en expirant. Enchaîne ces deux mouvements."],"k":2},{"id":"Decline_Crunch","n":"Crunch décliné","ne":"Decline Crunch","e":"body only","c":"strength","l":"intermediate","m":["abdominals"],"s":[],"i":["Cale tes jambes au bout du banc décliné et allonge-toi.","Mains posées de chaque côté de la tête, coudes rentrés, sans croiser les doigts.","En plaquant le bas du dos sur le banc, décolle les épaules.","Monte d'une dizaine de centimètres en contractant les abdos et en expirant, bas du dos sur le banc. Serre une seconde, sans élan.","Redescends lentement en inspirant."],"k":2},{"id":"Decline_Dumbbell_Bench_Press","n":"Développé décliné haltères","ne":"Decline Dumbbell Bench Press","e":"dumbbell","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Cale tes jambes au bout du banc décliné et allonge-toi, un haltère dans chaque main posé sur les cuisses, paumes face à face.","Une fois allongé, place les haltères devant toi à largeur d'épaules.","Tourne les poignets pour avoir les paumes vers l'avant : c'est la position de départ.","Descends lentement les haltères sur les côtés, avant-bras toujours verticaux.","Pousse avec les pectoraux en expirant, serre une seconde en haut. La descente doit durer deux fois plus longtemps que la montée."],"k":2},{"id":"Decline_Dumbbell_Flyes","n":"Écarté décliné haltères","ne":"Decline Dumbbell Flyes","e":"dumbbell","c":"strength","l":"beginner","m":["chest"],"s":[],"i":["Cale tes jambes au bout du banc décliné et allonge-toi, un haltère dans chaque main sur les cuisses.","Place les haltères au-dessus de toi, bras tendus et verticaux, paumes face à face : c'est la position de départ.","Coudes légèrement fléchis, ouvre les bras sur les côtés en grand arc jusqu'à sentir l'étirement des pectoraux, en inspirant. Seules les épaules bougent.","Remonte par le même arc en serrant les pectoraux, en expirant.","Tiens une seconde puis recommence."],"k":2},{"id":"Decline_Dumbbell_Triceps_Extension","n":"Extension triceps décliné haltères","ne":"Decline Dumbbell Triceps Extension","e":"dumbbell","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Cale tes jambes au bout du banc décliné et allonge-toi, un haltère dans chaque main sur les cuisses.","Place les haltères au-dessus de toi, bras tendus et verticaux, paumes face à face : c'est la position de départ.","Bras fixes et coudes rentrés, plie les coudes pour descendre les haltères en arc jusqu'à ce que les pouces soient près des oreilles, en inspirant.","Remonte en contractant les triceps, en expirant."],"k":2},{"id":"Decline_EZ_Bar_Triceps_Extension","n":"Extension triceps décliné barre EZ","ne":"Decline EZ Bar Triceps Extension","e":"barbell","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Cale tes jambes au bout du banc décliné et allonge-toi lentement.","Prise serrée, sors la barre EZ (idéalement avec un partenaire) et tiens-la bras tendus, coudes rentrés, bras verticaux.","Bras fixes, plie les coudes pour descendre la barre en arc jusqu'à effleurer le front, en inspirant.","Remonte en contractant les triceps, en expirant."],"k":2},{"id":"Decline_Oblique_Crunch","n":"Crunch oblique décliné","ne":"Decline Oblique Crunch","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Cale tes jambes au bout du banc décliné et allonge-toi lentement.","Décolle le buste jusqu'à environ 35-45° par rapport au sol.","Une main à côté de la tête, l'autre sur la cuisse : c'est la position de départ.","Monte lentement en tournant le buste vers la gauche, jusqu'à ce que le coude droit touche le genou gauche, en expirant. Tiens une seconde.","Redescends lentement en inspirant.","Fais toute la série d'un côté puis change."],"k":2},{"id":"Decline_Push-Up","n":"Pompes déclinées","ne":"Decline Push-Up","e":"other","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Face au sol, mains écartées d'environ 90 cm, bras tendus. Pose les pieds sur un box ou un banc : c'est la position de départ.","Descends jusqu'à ce que la poitrine frôle le sol, en inspirant.","Remonte en expirant en serrant les pectoraux.","Après une courte pause, recommence."],"k":2},{"id":"Decline_Reverse_Crunch","n":"Crunch inversé décliné","ne":"Decline Reverse Crunch","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur le dos sur un banc décliné, tiens le haut du banc à deux mains.","Jambes tendues parallèles au sol, genoux et pieds serrés, tenues par les abdos : c'est la position de départ.","En expirant, ramène les jambes vers le buste en enroulant le bassin pour décoller les hanches, jusqu'à ce que les genoux touchent la poitrine.","Tiens une seconde puis reviens en inspirant."],"k":2},{"id":"Decline_Smith_Press","n":"Développé décliné à la Smith","ne":"Decline Smith Press","e":"machine","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Place un banc décliné sous la Smith machine, barre réglée pour être atteinte bras presque tendus. Prise en pronation plus large que les épaules, déverrouille la barre et tiens-la bras tendus.","En inspirant, descends la barre en contrôlant jusqu'à effleurer le buste.","Après une courte pause, pousse en expirant.","À la fin, reverrouille la barre."],"k":2},{"id":"Deficit_Deadlift","n":"Soulevé de terre en déficit","ne":"Deficit Deadlift","e":"barbell","c":"powerlifting","l":"intermediate","m":["lower back"],"s":["forearms","glutes","hamstrings","middle back","quadriceps","traps"],"i":["Monte sur une plateforme ou des disques de 3 à 8 cm. Barre au-dessus du milieu des pieds, pieds largeur de hanches. Penche-toi et prends la barre à largeur d'épaules (pronation ou prise mixte).","Inspire fort, descends les hanches jusqu'à ce que les tibias touchent la barre. Regard devant, poitrine haute, dos cambré, pousse sur les talons. Une fois les genoux passés, tire la barre vers toi en serrant les omoplates et en avançant les hanches.","Redescends en pliant les hanches et en guidant la barre jusqu'au sol."],"k":2},{"id":"Depth_Jump_Leap","n":"Saut en contrebas puis bond","ne":"Depth Jump Leap","e":"other","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["abductors","adductors","calves","glutes","hamstrings"],"i":["Il faut deux box : un de 30-40 cm et un de 55-65 cm.","Debout sur le petit box, pieds joints au bord ; le grand box est 60 à 90 cm devant toi.","Laisse-toi tomber du petit box et rebondis immédiatement des deux pieds.","Saute le plus fort possible vers le haut et l'avant, bras actifs, pour atterrir sur le grand box en amortissant avec les jambes."],"k":2},{"id":"Dip_Machine","n":"Dips à la machine","ne":"Dip Machine","e":"machine","c":"strength","l":"beginner","m":["triceps"],"s":["chest","shoulders"],"i":["Assieds-toi bien calé dans la machine à dips, choisis la charge et tiens fermement les poignées.","Coudes serrés le long du corps, pliés à 90°, pour cibler les triceps.","Pousse les bras vers le bas en contractant les triceps, en expirant. Garde un léger pli en bas pour maintenir la tension.","Remonte lentement en inspirant."],"k":2},{"id":"Dips_-_Chest_Version","n":"Dips version pectoraux","ne":"Dips - Chest Version","e":"other","c":"strength","l":"intermediate","m":["chest"],"s":["shoulders","triceps"],"i":["Aux barres parallèles, tiens-toi bras tendus au-dessus des barres.","En inspirant, descends lentement, buste penché vers l'avant d'environ 30°, coudes légèrement écartés, jusqu'à sentir l'étirement des pectoraux.","Remonte avec les pectoraux en expirant et serre une seconde en haut."],"k":2},{"id":"Dips_-_Triceps_Version","n":"Dips version triceps","ne":"Dips - Triceps Version","e":"body only","c":"strength","l":"beginner","m":["triceps"],"s":["chest","shoulders"],"i":["Tiens-toi bras presque tendus au-dessus des barres.","En inspirant, descends lentement, buste droit, coudes près du corps, jusqu'à 90° aux coudes.","Remonte avec les triceps en expirant."],"k":2},{"id":"Donkey_Calf_Raises","n":"Mollets à l'âne (donkey)","ne":"Donkey Calf Raises","e":"other","c":"strength","l":"intermediate","m":["calves"],"s":[],"i":["Sur la machine à mollets « âne », place le bas du dos et les hanches sous l'appui (au niveau du coccyx).","Mains sur les poignées, avant des pieds sur la cale, talons dans le vide, genoux tendus sans les verrouiller : c'est la position de départ.","Monte les talons le plus haut possible en expirant, genoux immobiles. Tiens une seconde.","Redescends lentement en inspirant jusqu'à bien étirer les mollets."],"k":2},{"id":"Double_Kettlebell_Alternating_Hang_Clean","n":"Épaulé suspendu alterné deux kettlebells","ne":"Double Kettlebell Alternating Hang Clean","e":"kettlebells","c":"strength","l":"intermediate","m":["hamstrings"],"s":["biceps","calves","forearms","glutes","lower back","quadriceps","traps"],"i":["Place deux kettlebells entre tes pieds, fesses en arrière, regard droit devant.","Monte une kettlebell à l'épaule ; l'autre reste suspendue.","D'un mouvement fluide, redescends celle du haut pendant que tu montes l'autre."],"k":2},{"id":"Double_Kettlebell_Jerk","n":"Jeté deux kettlebells","ne":"Double Kettlebell Jerk","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["calves","quadriceps","triceps"],"i":["Une kettlebell dans chaque main.","Monte-les aux épaules en poussant avec les jambes et les hanches, paumes vers l'avant : c'est la position de départ.","Fléchis légèrement les genoux, buste droit.","Inverse aussitôt en poussant sur les talons, comme pour sauter.","Profite de l'élan pour pousser les kettlebells au-dessus de la tête, bras verrouillés.","Réceptionne-toi pieds en fente, un devant, un derrière.","Charges au-dessus de la tête, ramène les pieds ensemble, puis redescends les kettlebells."],"k":2},{"id":"Double_Kettlebell_Push_Press","n":"Push press deux kettlebells","ne":"Double Kettlebell Push Press","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["calves","quadriceps","triceps"],"i":["Monte deux kettlebells aux épaules.","Fléchis les jambes de quelques centimètres puis remonte vivement ; utilise cet élan pour pousser les kettlebells au-dessus de la tête.","Une fois bras verrouillés, redescends-les aux épaules et recommence."],"k":2},{"id":"Double_Kettlebell_Snatch","n":"Arraché deux kettlebells","ne":"Double Kettlebell Snatch","e":"kettlebells","c":"strength","l":"expert","m":["shoulders"],"s":["glutes","hamstrings","quadriceps"],"i":["Place deux kettlebells derrière tes pieds. Plie les genoux et assieds-toi en arrière pour les attraper.","Balance-les fort entre les jambes puis inverse le mouvement.","Pousse avec les hanches et verrouille les kettlebells au-dessus de la tête en un seul mouvement."],"k":2},{"id":"Double_Kettlebell_Windmill","n":"Moulin deux kettlebells","ne":"Double Kettlebell Windmill","e":"kettlebells","c":"strength","l":"intermediate","m":["abdominals"],"s":["glutes","hamstrings","shoulders","triceps"],"i":["Place une kettlebell devant le pied avant et monte l'autre au-dessus de la tête avec le bras opposé (épaulé puis développé).","Bras toujours verrouillé, pousse les fesses du côté du bras levé, pieds tournés à 45°.","Penche-toi depuis la hanche jusqu'à attraper la kettlebell au sol, regard toujours sur celle du haut.","Marque une pause puis remonte."],"k":2},{"id":"Double_Leg_Butt_Kick","n":"Talons-fesses deux jambes","ne":"Double Leg Butt Kick","e":"body only","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["abductors","adductors","calves","glutes","hamstrings"],"i":["Debout, genoux légèrement fléchis.","Fléchis rapidement hanches et genoux puis saute le plus haut possible.","En l'air, ramène les talons vers les fesses.","Réceptionne-toi genoux légèrement fléchis en amortissant."],"k":2},{"id":"Downward_Facing_Balance","n":"Équilibre face au sol","ne":"Downward Facing Balance","e":"exercise ball","c":"strength","l":"intermediate","m":["glutes"],"s":["abdominals","hamstrings"],"i":["Allonge-toi à plat ventre sur un swiss ball.","Avance les mains au sol et décolle les jambes en tendant coudes et genoux, en équilibre sur le ballon."],"k":2},{"id":"Drag_Curl","n":"Curl glissé (drag curl)","ne":"Drag Curl","e":"barbell","c":"strength","l":"intermediate","m":["biceps"],"s":["forearms"],"i":["Prends une barre en supination, coudes près du corps et en arrière : c'est la position de départ.","En expirant, monte la barre en la faisant glisser contre ton buste, les coudes partant vers l'arrière, sans monter les épaules.","Redescends lentement, barre toujours au contact du buste."],"k":2},{"id":"Drop_Push","n":"Pompes en chute","ne":"Drop Push","e":"other","c":"plyometrics","l":"intermediate","m":["chest"],"s":["shoulders","triceps"],"i":["Place deux plateformes basses écartées de 60 à 90 cm.","Mets-toi en position de pompe entre elles, mains posées sur les plateformes.","Bien gainé, pousse et laisse-toi tomber entre les plateformes, mains au sol largeur d'épaules, en amortissant avec les bras."],"k":2},{"id":"Dumbbell_Alternate_Bicep_Curl","n":"Curl biceps haltères alterné","ne":"Dumbbell Alternate Bicep Curl","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":["forearms"],"i":["Debout, buste droit, un haltère dans chaque main bras tendus, coudes près du corps, paumes vers les cuisses.","Bras fixe, monte l'haltère droit en tournant la paume vers l'avant puis vers le haut, en expirant, jusqu'à hauteur d'épaule. Tiens une seconde.","Redescends lentement en inspirant en retournant la paume vers la cuisse.","Fais de même à gauche : cela fait une répétition.","Continue en alternant."],"k":2},{"id":"Dumbbell_Bench_Press","n":"Développé couché haltères","ne":"Dumbbell Bench Press","e":"dumbbell","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Allongé sur un banc plat, un haltère dans chaque main posé sur les cuisses, paumes face à face.","Aide-toi des cuisses pour monter les haltères un par un devant toi à largeur d'épaules.","Tourne les poignets paumes vers l'avant ; haltères juste à côté de la poitrine, coudes à 90° : c'est la position de départ.","Pousse avec les pectoraux en expirant, verrouille les bras et serre une seconde. Redescends lentement (environ deux fois plus lentement qu'à la montée)."],"k":2},{"id":"Dumbbell_Bench_Press_with_Neutral_Grip","n":"Développé couché haltères prise neutre","ne":"Dumbbell Bench Press with Neutral Grip","e":"dumbbell","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Un haltère dans chaque main, allonge-toi sur un banc plat, pieds au sol, omoplates serrées.","Prise neutre (paumes face à face), bras tendus au-dessus de toi : c'est la position de départ.","Plie les coudes pour descendre les bras le long du corps jusqu'à ce que les haltères arrivent au buste.","Pause, puis tends les coudes pour remonter."],"k":2},{"id":"Dumbbell_Bicep_Curl","n":"Curl biceps haltères","ne":"Dumbbell Bicep Curl","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":["forearms"],"i":["Debout, un haltère dans chaque main bras tendus, coudes près du corps, paumes vers l'avant.","Bras fixes, monte les haltères en contractant les biceps, en expirant, jusqu'à hauteur d'épaules. Serre une courte pause.","Redescends lentement en inspirant."],"k":2},{"id":"Dumbbell_Clean","n":"Épaulé haltères","ne":"Dumbbell Clean","e":"dumbbell","c":"strength","l":"intermediate","m":["hamstrings"],"s":["calves","forearms","glutes","lower back","quadriceps","shoulders","traps"],"i":["Debout, un haltère dans chaque main, pieds largeur d'épaules.","Descends les haltères au sol en reculant les hanches et en pliant les genoux : c'est la position de départ.","Saute violemment vers le haut en tendant hanches, genoux et chevilles, bras tendus, prise neutre.","Après l'extension, refléchis hanches et genoux pour réceptionner en squat, en guidant les haltères jusqu'aux épaules.","Relève-toi, haltères sur les épaules."],"k":2},{"id":"Dumbbell_Floor_Press","n":"Développé au sol haltères","ne":"Dumbbell Floor Press","e":"dumbbell","c":"powerlifting","l":"intermediate","m":["triceps"],"s":["chest","shoulders"],"i":["Allongé au sol, un haltère dans chaque main, genoux pliés si tu veux, bras tendus au-dessus de toi.","Descends jusqu'à ce que le haut du bras touche le sol. Coudes rentrés pour les triceps, écartés pour les pectoraux.","Pause en bas puis remonte en rapprochant les haltères en haut."],"k":2},{"id":"Dumbbell_Flyes","n":"Écarté haltères","ne":"Dumbbell Flyes","e":"dumbbell","c":"strength","l":"beginner","m":["chest"],"s":[],"i":["Allongé sur un banc plat, un haltère dans chaque main sur les cuisses, paumes face à face.","Monte les haltères un par un au-dessus de toi, paumes face à face, bras presque tendus : c'est la position de départ.","Coudes légèrement fléchis, ouvre les bras sur les côtés en grand arc jusqu'à sentir l'étirement des pectoraux, en inspirant. Seules les épaules bougent.","Remonte par le même arc en serrant les pectoraux, en expirant.","Tiens une seconde puis recommence."],"k":2},{"id":"Dumbbell_Incline_Row","n":"Rowing haltères sur banc incliné","ne":"Dumbbell Incline Row","e":"dumbbell","c":"strength","l":"beginner","m":["middle back"],"s":["biceps","forearms","lats","shoulders"],"i":["Penche-toi à plat ventre sur un banc incliné.","Un haltère dans chaque main, prise neutre, bras tendus : c'est la position de départ.","Serre les omoplates et plie les coudes pour tirer les haltères le long du corps.","Pause en haut puis redescends."],"k":2},{"id":"Dumbbell_Incline_Shoulder_Raise","n":"Élévation d'épaules haltères sur banc incliné","ne":"Dumbbell Incline Shoulder Raise","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":["triceps"],"i":["Assis sur un banc incliné, un haltère dans chaque main sur les cuisses.","Aide-toi des jambes pour monter les haltères et allonge-toi. Bras tendus et verticaux au-dessus des épaules, paumes vers l'avant : c'est la position de départ.","Bras tendus et verrouillés, monte les haltères en décollant les épaules du banc, en expirant.","Redescends en inspirant."],"k":2},{"id":"Dumbbell_Lunges","n":"Fentes haltères","ne":"Dumbbell Lunges","e":"dumbbell","c":"strength","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Debout, buste droit, un haltère dans chaque main le long du corps.","Fais un pas d'environ 60 cm en avant avec la jambe droite et descends, buste droit, en inspirant. Le genou ne dépasse pas les orteils, tibia avant vertical.","Remonte en poussant surtout sur le talon, en expirant.","Fais toutes les répétitions puis change de jambe."],"k":2},{"id":"Dumbbell_Lying_One-Arm_Rear_Lateral_Raise","n":"Oiseau allongé un bras haltère","ne":"Dumbbell Lying One-Arm Rear Lateral Raise","e":"dumbbell","c":"strength","l":"intermediate","m":["shoulders"],"s":["middle back"],"i":["Un haltère dans une main, allonge-toi à plat ventre sur un banc légèrement incliné (environ 15°). L'autre main peut tenir le pied du banc.","Paume tournée vers toi, bras tendu, coude légèrement fléchi : c'est la position de départ.","Monte le bras sur le côté jusqu'à hauteur d'épaule, en expirant, bras perpendiculaire au buste. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Dumbbell_Lying_Pronation","n":"Pronation allongé haltère","ne":"Dumbbell Lying Pronation","e":"dumbbell","c":"strength","l":"intermediate","m":["forearms"],"s":[],"i":["Allongé à plat ventre sur un banc plat, un haltère dans une main, l'autre bras replié sous la tête.","Plie le coude du bras chargé à 90°.","Monte le bras à l'horizontale, perpendiculaire au buste, avant-bras vertical vers le sol : c'est la position de départ.","En expirant, fais tourner l'avant-bras vers l'avant en gardant le coude à 90°, jusqu'à ce qu'il soit parallèle au sol. Tiens une seconde.","Reviens lentement en inspirant."],"k":2},{"id":"Dumbbell_Lying_Rear_Lateral_Raise","n":"Oiseau allongé haltères","ne":"Dumbbell Lying Rear Lateral Raise","e":"dumbbell","c":"strength","l":"intermediate","m":["shoulders"],"s":[],"i":["Un haltère dans chaque main, allonge-toi à plat ventre sur un banc légèrement incliné (environ 15°).","Paumes vers toi, bras tendus, coudes légèrement fléchis : c'est la position de départ.","Monte les bras sur les côtés jusqu'à hauteur d'épaules, en expirant. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Dumbbell_Lying_Supination","n":"Supination allongé haltère","ne":"Dumbbell Lying Supination","e":"dumbbell","c":"strength","l":"intermediate","m":["forearms"],"s":[],"i":["Allongé sur le côté sur un banc plat, haltère dans la main du dessus, l'autre bras replié sous la tête.","Plie le coude du bras chargé à 90°.","Bras collé au corps, avant-bras devant toi parallèle au sol : c'est la position de départ.","En expirant, fais tourner l'avant-bras vers le haut en demi-cercle, coude à 90°, jusqu'à ce qu'il soit vertical. Tiens une seconde.","Reviens lentement en inspirant.","Fais toutes les répétitions puis change de bras."],"k":2},{"id":"Dumbbell_One-Arm_Shoulder_Press","n":"Développé épaule un bras haltère","ne":"Dumbbell One-Arm Shoulder Press","e":"dumbbell","c":"strength","l":"intermediate","m":["shoulders"],"s":["triceps"],"i":["Prends un haltère, assis sur un banc à dossier ou debout.","Monte l'haltère à hauteur d'épaule ; l'autre main sur la hanche, sur le côté ou sur un appui.","Tourne le poignet paume vers l'avant : c'est la position de départ.","Pousse l'haltère jusqu'à bras tendu en expirant.","Après une seconde, redescends lentement en inspirant.","Fais toutes les répétitions puis change de bras."],"k":2},{"id":"Dumbbell_One-Arm_Triceps_Extension","n":"Extension triceps un bras haltère","ne":"Dumbbell One-Arm Triceps Extension","e":"dumbbell","c":"strength","l":"intermediate","m":["triceps"],"s":[],"i":["Prends un haltère, assis sur un banc à dossier ou debout.","Monte-le à l'épaule puis tends le bras au-dessus de la tête, bras vertical près de la tête. L'autre main peut soutenir le bras chargé.","Paume vers l'avant : c'est la position de départ.","Bras fixe, descends lentement l'haltère derrière la tête en inspirant, jusqu'à étirer le triceps.","Remonte en contractant le triceps, en expirant. Seul l'avant-bras bouge.","Fais toutes les répétitions puis change de bras."],"k":2},{"id":"Dumbbell_One-Arm_Upright_Row","n":"Rowing menton un bras haltère","ne":"Dumbbell One-Arm Upright Row","e":"dumbbell","c":"strength","l":"intermediate","m":["shoulders"],"s":["biceps","traps"],"i":["Debout, dos droit, un haltère contre la cuisse, paume vers la cuisse, coude légèrement fléchi.","L'autre main sur la hanche, sur le côté ou sur un appui : c'est la position de départ.","Monte l'haltère près du corps jusqu'au menton avec l'épaule, en expirant ; le coude reste toujours plus haut que l'avant-bras. Pause en haut.","Redescends lentement en inspirant.","Fais toutes les répétitions puis change de bras."],"k":2},{"id":"Dumbbell_Prone_Incline_Curl","n":"Curl incliné face au banc haltères","ne":"Dumbbell Prone Incline Curl","e":"dumbbell","c":"strength","l":"intermediate","m":["biceps"],"s":[],"i":["Un haltère dans chaque main, allonge-toi à plat ventre sur un banc incliné, épaules près du haut du dossier.","Laisse les bras pendre verticalement.","Coudes serrés, paumes vers l'avant : c'est la position de départ.","Monte les haltères en contractant les biceps, en expirant. Seuls les avant-bras bougent.","Redescends jusqu'à bras tendus."],"k":2},{"id":"Dumbbell_Raise","n":"Élévation haltères","ne":"Dumbbell Raise","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":["biceps"],"i":["Debout, dos droit, un haltère dans chaque main contre les cuisses, paumes vers l'arrière, coudes légèrement fléchis.","Monte les haltères le long du corps jusqu'au menton avec les épaules, en expirant ; les coudes restent plus hauts que les avant-bras. Pause en haut.","Redescends lentement en inspirant."],"k":2},{"id":"Dumbbell_Rear_Lunge","n":"Fente arrière haltères","ne":"Dumbbell Rear Lunge","e":"dumbbell","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Debout, buste droit, un haltère dans chaque main le long du corps.","Recule la jambe droite d'environ 60 cm et descends, buste droit, en inspirant. Tibia avant vertical. Une grande fente cible les fessiers, une petite les quadriceps.","Remonte en expirant (pousse sur l'avant du pied pour les quadriceps, sur le talon pour les fessiers).","Fais de même avec l'autre jambe."],"k":2},{"id":"Dumbbell_Scaption","n":"Élévations en Y haltères (scaption)","ne":"Dumbbell Scaption","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":["traps"],"i":["Exercice correctif qui renforce les stabilisateurs de l'omoplate. Un haltère léger dans chaque main, bras le long du corps, pouces vers le haut.","Monte les bras devant toi en les écartant d'environ 30° (en « Y »), bras tendus.","Monte jusqu'à l'horizontale puis redescends."],"k":2},{"id":"Dumbbell_Seated_Box_Jump","n":"Saut sur box depuis assis haltères","ne":"Dumbbell Seated Box Jump","e":"dumbbell","c":"plyometrics","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Place un box à environ 60 cm sur le côté d'un banc. Assis sur le banc face au box, haltère tenu contre la poitrine.","Pieds bien plantés, penche-toi et saute vers le haut et l'avant en tendant hanches et genoux.","Atterris sur le box des deux pieds en amortissant.","Redescends et reprends la position assise."],"k":2},{"id":"Dumbbell_Seated_One-Leg_Calf_Raise","n":"Mollet assis une jambe haltère","ne":"Dumbbell Seated One-Leg Calf Raise","e":"dumbbell","c":"strength","l":"beginner","m":["calves"],"s":[],"i":["Place une cale à environ 30 cm d'un banc plat.","Assis sur le banc, pose un haltère sur la cuisse gauche, près du genou.","Avant du pied gauche sur la cale : c'est la position de départ.","Monte sur la pointe le plus haut possible en expirant et tiens une seconde.","Redescends lentement en étirant au maximum.","Fais toutes les répétitions puis change de jambe."],"k":2},{"id":"Dumbbell_Shoulder_Press","n":"Développé épaules haltères","ne":"Dumbbell Shoulder Press","e":"dumbbell","c":"strength","l":"intermediate","m":["shoulders"],"s":["triceps"],"i":["Assis sur un banc à dossier, un haltère dans chaque main posé debout sur les cuisses.","Monte les haltères à hauteur d'épaules un par un en t'aidant des cuisses.","Tourne les poignets paumes vers l'avant : c'est la position de départ.","Pousse les haltères vers le haut en expirant jusqu'à ce qu'ils se touchent.","Après une courte pause, redescends lentement en inspirant."],"k":2},{"id":"Dumbbell_Shrug","n":"Shrug haltères","ne":"Dumbbell Shrug","e":"dumbbell","c":"strength","l":"beginner","m":["traps"],"s":[],"i":["Debout, un haltère dans chaque main le long du corps, paumes vers toi.","Monte les épaules le plus haut possible en expirant et tiens une seconde. Bras toujours tendus, seules les épaules bougent.","Redescends."],"k":2},{"id":"Dumbbell_Side_Bend","n":"Flexion latérale haltère","ne":"Dumbbell Side Bend","e":"dumbbell","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Debout, un haltère dans la main gauche (paume vers toi), main droite sur la taille, pieds largeur d'épaules.","Dos droit, tête haute, penche-toi uniquement à la taille vers la droite en inspirant. Tiens une seconde et remonte en expirant.","Fais de même vers la gauche.","Fais toutes les répétitions puis change de main."],"k":2},{"id":"Dumbbell_Squat","n":"Squat haltères","ne":"Dumbbell Squat","e":"dumbbell","c":"strength","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings","lower back"],"i":["Debout, un haltère dans chaque main le long des jambes.","Pieds largeur d'épaules, pointes légèrement ouvertes, tête haute, dos droit : c'est la position de départ.","Descends lentement en pliant les genoux jusqu'à avoir les cuisses parallèles au sol. Genoux dans l'axe des pieds.","Remonte en expirant en poussant surtout sur les talons."],"k":2},{"id":"Dumbbell_Squat_To_A_Bench","n":"Squat haltères jusqu'au banc","ne":"Dumbbell Squat To A Bench","e":"dumbbell","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings","lower back"],"i":["Debout, un banc plat derrière toi, un haltère dans chaque main le long des jambes.","Pieds largeur d'épaules, pointes légèrement ouvertes, tête haute, dos droit.","Descends lentement jusqu'à effleurer le banc, en inspirant. Genoux dans l'axe des pieds.","Remonte en expirant en poussant surtout sur les talons."],"k":2},{"id":"Dumbbell_Step_Ups","n":"Montées sur banc haltères","ne":"Dumbbell Step Ups","e":"dumbbell","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Debout, un haltère dans chaque main le long des jambes.","Pose le pied droit sur la marche et monte en poussant sur le talon, puis pose le pied gauche à côté, en expirant.","Redescends avec la jambe gauche puis la droite, en inspirant.","Fais toutes les répétitions puis change de jambe d'attaque."],"k":2},{"id":"Dumbbell_Tricep_Extension_-Pronated_Grip","n":"Extension triceps haltères prise pronation","ne":"Dumbbell Tricep Extension -Pronated Grip","e":"dumbbell","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Allongé sur un banc plat, deux haltères tenus au-dessus des épaules, bras tendus et verticaux.","Paumes vers l'avant, coudes rentrés : c'est la position de départ.","Inspire et descends lentement les haltères près des oreilles, bras fixes, coudes rentrés.","Remonte avec les triceps en expirant."],"k":2},{"id":"Dynamic_Back_Stretch","n":"Étirement dynamique du dos","ne":"Dynamic Back Stretch","e":"other","c":"stretching","l":"beginner","m":["lats"],"s":[],"i":["Debout, pieds largeur d'épaules.","Bras tendus, balance-les devant toi vers le haut 5 à 10 fois, en augmentant l'amplitude jusqu'à passer au-dessus de la tête."],"k":2},{"id":"Dynamic_Chest_Stretch","n":"Étirement dynamique des pectoraux","ne":"Dynamic Chest Stretch","e":"other","c":"stretching","l":"beginner","m":["chest"],"s":["middle back"],"i":["Debout, mains jointes, bras tendus devant toi.","Bras tendus, ouvre-les vivement vers l'arrière au maximum puis ramène-les, comme un grand applaudissement. 5 à 10 fois en accélérant."],"k":2},{"id":"EZ-Bar_Curl","n":"Curl barre EZ","ne":"EZ-Bar Curl","e":"e-z curl bar","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Debout, barre EZ tenue par les poignées extérieures, paumes vers l'avant, coudes près du corps.","Bras fixes, monte la barre en contractant les biceps, en expirant. Seuls les avant-bras bougent.","Continue jusqu'à hauteur d'épaules et serre un instant.","Redescends lentement en inspirant."],"k":2},{"id":"EZ-Bar_Skullcrusher","n":"Barre au front barre EZ","ne":"EZ-Bar Skullcrusher","e":"e-z curl bar","c":"strength","l":"beginner","m":["triceps"],"s":["forearms"],"i":["Allongé sur le banc, barre EZ en prise serrée, coudes rentrés, bras verticaux.","Bras fixes, plie les coudes pour descendre la barre, en inspirant. Pause quand la barre est au-dessus du front.","Remonte en tendant les coudes, en expirant."],"k":2},{"id":"Elbow_Circles","n":"Cercles de coudes","ne":"Elbow Circles","e":"other","c":"stretching","l":"beginner","m":["shoulders"],"s":["traps"],"i":["Assis ou debout, pieds légèrement écartés.","Mains sur les épaules, coudes à hauteur d'épaules pointés vers l'extérieur.","Fais lentement des cercles avec les coudes, en expirant au début du cercle et en inspirant à la fin."],"k":2},{"id":"Elbow_to_Knee","n":"Coude au genou","ne":"Elbow to Knee","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé au sol, jambe droite croisée sur le genou gauche plié, mains derrière la tête, omoplates au sol.","Enroule la colonne en tournant le buste pour amener le coude gauche vers le genou droit.","Reviens et fais toutes les répétitions avant de changer de côté."],"k":2},{"id":"Elbows_Back","n":"Coudes en arrière (étirement)","ne":"Elbows Back","e":"other","c":"stretching","l":"beginner","m":["chest"],"s":["shoulders"],"i":["Debout, bien droit.","Mains sur le bas du dos, doigts vers le bas, coudes écartés.","Ramène doucement les coudes vers l'arrière comme pour les faire se toucher."],"k":2},{"id":"Elevated_Back_Lunge","n":"Fente arrière surélevée","ne":"Elevated Back Lunge","e":"barbell","c":"strength","l":"intermediate","m":["quadriceps"],"s":["glutes","hamstrings"],"i":["Charge une barre sur un rack à hauteur d'épaules et place une petite plateforme surélevée derrière toi.","Pose la barre sur le haut du dos, dos cambré et gainé, et monte sur la plateforme : c'est la position de départ.","Recule une jambe et descends en pliant hanches et genoux jusqu'à ce que le genou touche le sol.","Pause, puis remonte jusqu'à la plateforme avant de changer de jambe."],"k":2},{"id":"Elevated_Cable_Rows","n":"Rowing poulie surélevé","ne":"Elevated Cable Rows","e":"cable","c":"strength","l":"intermediate","m":["lats"],"s":["middle back","traps"],"i":["Pose une petite plateforme de 10 à 15 cm sur le siège du tirage horizontal.","Assieds-toi dessus, pieds sur l'appui, genoux légèrement fléchis.","Penche-toi, dos naturel, et attrape la poignée en V.","Bras tendus, redresse-toi jusqu'à 90° entre buste et jambes, poitrine sortie, dos légèrement cambré, en sentant l'étirement du dos.","Buste fixe, tire la poignée vers le ventre, bras près du corps, en expirant. Serre fort le dos une seconde puis reviens lentement en inspirant."],"k":2},{"id":"Elliptical_Trainer","n":"Vélo elliptique","ne":"Elliptical Trainer","e":"machine","c":"cardio","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Monte sur le vélo elliptique et choisis un programme ou le mode manuel. Tu peux entrer âge et poids pour estimer les calories et régler l'inclinaison pour changer l'intensité.","Les poignées permettent de suivre ton rythme cardiaque."],"k":2},{"id":"Exercise_Ball_Crunch","n":"Crunch sur swiss ball","ne":"Exercise Ball Crunch","e":"exercise ball","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allonge-toi sur un swiss ball, bas du dos épousant le ballon, genoux fléchis, pieds bien au sol, haut du buste dans le vide. Bras le long du corps ou croisés sur la poitrine pour protéger la nuque.","Laisse le buste s'étirer en arrière, nuque fixe : c'est la position de départ.","Hanches fixes, enroule les épaules et le buste en contractant les abdos, bas du dos toujours sur le ballon, en expirant. Tiens une seconde.","Reviens en inspirant."],"k":2},{"id":"Exercise_Ball_Pull-In","n":"Genoux à la poitrine sur swiss ball","ne":"Exercise Ball Pull-In","e":"exercise ball","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allonge-toi devant un swiss ball en position de pompe, mains largeur d'épaules.","Pose le bas des tibias sur le ballon, jambes tendues, bras tendus : c'est la position de départ.","Dos bien droit, ramène les genoux vers la poitrine en faisant rouler le ballon sous les chevilles, en expirant. Serre les abdos une seconde.","Tends lentement les jambes pour revenir, en inspirant."],"k":2},{"id":"Extended_Range_One-Arm_Kettlebell_Floor_Press","n":"Développé au sol kettlebell un bras amplitude étendue","ne":"Extended Range One-Arm Kettlebell Floor Press","e":"kettlebells","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Allongé au sol, une kettlebell tenue par la poignée d'un bras. La jambe du même côté est pliée, genou croisé vers le milieu du corps.","Pousse la kettlebell au-dessus de toi en tendant le coude et en ramenant le bras vers le centre. Redescends."],"k":2},{"id":"External_Rotation","n":"Rotation externe","ne":"External Rotation","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Allongé sur le côté sur un banc plat, haltère dans la main du dessus, l'autre bras replié sous la tête.","Coude plié à 90°, bras collé le long du buste.","Avant-bras devant toi, parallèle au sol : c'est la position de départ.","En expirant, fais tourner l'avant-bras vers le haut en demi-cercle, coude à 90°, jusqu'à la verticale. Tiens une seconde.","Reviens lentement en inspirant.","Fais toutes les répétitions puis change de bras."],"k":2},{"id":"External_Rotation_with_Band","n":"Rotation externe à l'élastique","ne":"External Rotation with Band","e":"bands","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Accroche un élastique à un poteau, à hauteur du coude. Côté gauche vers le poteau, à environ 60 cm.","Prends l'élastique main droite, coude plaqué contre le corps (un petit coussin sous le coude aide).","Coude plié à 90°, main devant le ventre : c'est la position de départ.","Fais tourner le bras vers l'extérieur, comme un revers, coude fixe.","Va aussi loin que possible, pause, puis reviens."],"k":2},{"id":"External_Rotation_with_Cable","n":"Rotation externe à la poulie","ne":"External Rotation with Cable","e":"cable","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Règle la poulie à hauteur du coude. Côté gauche vers la machine, à environ 60 cm.","Prends la poignée main droite, coude plaqué contre le corps (un petit coussin sous le coude aide).","Coude plié à 90°, main devant le ventre : c'est la position de départ.","Fais tourner le bras vers l'extérieur, comme un revers, coude fixe, puis reviens."],"k":2},{"id":"Face_Pull","n":"Face pull","ne":"Face Pull","e":"cable","c":"strength","l":"intermediate","m":["shoulders"],"s":["middle back"],"i":["Face à une poulie haute avec une corde, tire la charge vers ton visage en écartant les mains, bras parallèles au sol."],"k":2},{"id":"Farmers_Walk","n":"Marche du fermier","ne":"Farmer's Walk","e":"other","c":"strongman","l":"intermediate","m":["forearms"],"s":["abdominals","glutes","hamstrings","lower back","quadriceps","traps"],"i":["Utilise des poignées de fermier, ou à défaut des haltères lourds. Place-toi entre les deux charges.","Saisis les poignées et soulève-les en poussant sur les talons, dos droit, tête haute.","Marche à petits pas rapides en respirant, sur 15 à 30 m, le plus vite possible."],"k":2},{"id":"Fast_Skipping","n":"Skipping rapide","ne":"Fast Skipping","e":"body only","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["abductors","adductors","calves","glutes","hamstrings"],"i":["Position détendue, une jambe légèrement en avant.","Fais des pas sautés : droite-droite puis gauche-gauche, en alternant.","Reste près du sol en limitant le temps en l'air et va le plus vite possible."],"k":2},{"id":"Finger_Curls","n":"Curl des doigts","ne":"Finger Curls","e":"barbell","c":"strength","l":"beginner","m":["forearms"],"s":[],"i":["Barre tenue à deux mains, paumes vers le haut, mains largeur d'épaules.","Pieds à plat, un peu plus écartés que les épaules : c'est la position de départ.","Ouvre les doigts pour laisser rouler la barre jusqu'à la dernière phalange.","Referme les mains pour remonter la barre le plus haut possible, en expirant. Tiens en haut."],"k":2},{"id":"Flat_Bench_Cable_Flyes","n":"Écarté poulie sur banc plat","ne":"Flat Bench Cable Flyes","e":"cable","c":"strength","l":"intermediate","m":["chest"],"s":[],"i":["Place un banc plat entre deux poulies basses, poitrine alignée avec les poulies.","Allonge-toi, pieds au sol.","Fais-toi passer les poignées, paumes vers le haut.","Bras écartés sur les côtés, parallèles au sol, coudes légèrement fléchis (garde ce pli) : c'est la position de départ.","Ramène les bras en demi-cercle au-dessus de la poitrine jusqu'à ce que les mains se touchent, en serrant les pectoraux et en expirant. Tiens une seconde.","Reviens lentement."],"k":2},{"id":"Flat_Bench_Leg_Pull-In","n":"Genoux à la poitrine sur banc plat","ne":"Flat Bench Leg Pull-In","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur un tapis ou un banc plat, jambes dépassant au bout.","Mains sous les fesses ou sur les côtés du banc, jambes tendues : c'est la position de départ.","Plie les genoux et ramène les cuisses vers le ventre en expirant, jusqu'à ce que les genoux soient près de la poitrine. Tiens une seconde.","Reviens lentement en inspirant."],"k":2},{"id":"Flat_Bench_Lying_Leg_Raise","n":"Relevés de jambes allongé sur banc","ne":"Flat Bench Lying Leg Raise","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur un banc, jambes tendues dépassant au bout.","Mains sous les fesses ou tenant le banc : c'est la position de départ.","Jambes presque tendues, monte-les jusqu'à 90° avec le sol, en expirant. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Flexor_Incline_Dumbbell_Curls","n":"Curl incliné haltères (fléchisseurs)","ne":"Flexor Incline Dumbbell Curls","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Tiens l'haltère décalé pour avoir plus de poids du côté du pouce, poignets bien en arrière pour les soulager.","Assieds-toi sur un banc incliné à 45°, un haltère dans chaque main.","Bras pendants, coudes rentrés, paumes vers l'avant, pouces vers l'extérieur ; garde cette position de main tout du long.","Monte les deux haltères ensemble en expirant, sans élan. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Floor_Glute-Ham_Raise","n":"Glute-ham raise au sol","ne":"Floor Glute-Ham Raise","e":"other","c":"strength","l":"intermediate","m":["hamstrings"],"s":["calves","glutes"],"i":["Avec un partenaire qui te tient les pieds, ou pieds calés sous un appui stable.","À genoux, cuisses et buste droits : c'est la position de départ.","Descends vers l'avant en tendant les genoux, sans plier les hanches.","Pose les mains au sol en arrivant. C'est très difficile : aide-toi d'une légère poussée des bras pour remonter."],"k":2},{"id":"Floor_Press","n":"Développé au sol","ne":"Floor Press","e":"barbell","c":"powerlifting","l":"intermediate","m":["triceps"],"s":["chest","shoulders"],"i":["Règle les crochets à la bonne hauteur. Allongé au sol, tête près du bout du rack, omoplates serrées, décroche la barre.","Descends-la vers le bas de la poitrine en la serrant fort, coudes rentrés, jusqu'à ce que le haut des bras touche le sol. Pause, sans rebond.","Pousse la barre le plus vite possible, barre, poignets et coudes alignés."],"k":2},{"id":"Floor_Press_with_Chains","n":"Développé au sol avec chaînes","ne":"Floor Press with Chains","e":"barbell","c":"powerlifting","l":"intermediate","m":["triceps"],"s":["chest","shoulders"],"i":["Règle les crochets à la bonne hauteur et pose les chaînes à cheval sur les extrémités de la barre.","Allongé au sol, tête près du bout du rack, omoplates serrées, décroche la barre.","Descends-la vers le bas de la poitrine, coudes rentrés, jusqu'à ce que le haut des bras touche le sol. Pause, sans rebond.","Pousse la barre le plus vite possible."],"k":2},{"id":"Flutter_Kicks","n":"Battements de jambes","ne":"Flutter Kicks","e":"body only","c":"strength","l":"beginner","m":["glutes"],"s":["hamstrings"],"i":["Allongé à plat ventre sur un banc, hanches au bord, jambes tendues, mains tenant l'avant du banc.","Serre fessiers et ischios pour monter les jambes à hauteur des hanches : c'est la position de départ.","Monte la jambe gauche plus haut que la droite.","Puis redescends-la en montant la droite.","Continue en alternant comme un battement de nage, en contrôlant et en respirant normalement."],"k":2},{"id":"Foot-SMR","n":"Auto-massage des pieds","ne":"Foot-SMR","e":"other","c":"stretching","l":"intermediate","m":["calves"],"s":[],"i":["Étire le fascia de la voûte plantaire. Assis, pieds nus, pose le pied sur un rouleau (ou un petit tube).","Appuie fermement et fais rouler sous la voûte plantaire pendant 10 à 30 s, puis change de pied."],"k":2},{"id":"Forward_Drag_with_Press","n":"Traîneau tiré en avançant avec développé","ne":"Forward Drag with Press","e":"other","c":"strongman","l":"intermediate","m":["chest"],"s":["calves","glutes","hamstrings","quadriceps","shoulders","triceps"],"i":["Fixe une double poignée au traîneau. Dos au traîneau, une poignée dans chaque main.","Avance d'un pas en te penchant et en poussant sur les jambes ; à chaque pas, marque une pause pour tendre les bras devant toi. Continue ainsi."],"k":2},{"id":"Frankenstein_Squat","n":"Squat Frankenstein","ne":"Frankenstein Squat","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["quadriceps"],"s":["abdominals","calves","glutes","hamstrings"],"i":["Cet exercice apprend le bon placement de la barre et du corps à l'épaulé et au squat avant.","Barre posée sur l'avant des épaules, lâche les mains et tends les bras devant toi. Avance les épaules pour former un appui, barre contre la gorge, sans arrondir le haut du dos.","Descends en squat entre tes jambes, buste droit, bras levés, épaules en avant ; la barre ne doit pas bouger. Descends jusqu'à ce que les ischios touchent les mollets.","Remonte en poussant sur l'avant des talons."],"k":2},{"id":"Freehand_Jump_Squat","n":"Squat sauté au poids du corps","ne":"Freehand Jump Squat","e":"body only","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Croise les bras sur la poitrine.","Tête haute, dos droit, pieds largeur d'épaules.","Descends en squat en inspirant jusqu'à avoir les cuisses parallèles au sol ou plus bas.","Pousse surtout sur l'avant des pieds et saute le plus haut possible, en expirant.","À la réception, redescends aussitôt et ressaute."],"k":2},{"id":"Frog_Hops","n":"Sauts de grenouille","ne":"Frog Hops","e":"other","c":"stretching","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Debout, mains derrière la tête, descends en squat, buste droit, tête haute : c'est la position de départ.","Saute vers l'avant d'un mètre environ, sans monter trop haut. Amortis avec les jambes et ressaute aussitôt. 5 à 10 sauts."],"k":2},{"id":"Frog_Sit-Ups","n":"Sit-ups grenouille","ne":"Frog Sit-Ups","e":"body only","c":"strength","l":"intermediate","m":["abdominals"],"s":[],"i":["Allongé sur le dos, jambes tendues.","Plie les genoux et laisse l'extérieur des cuisses tomber vers le sol, plantes des pieds l'une contre l'autre.","Ramène les pieds le plus près possible de toi, jambes en losange.","Croise les bras en touchant les épaules opposées : c'est la position de départ.","En expirant, plaque le bas du dos et enroule le buste (environ un quart de sit-up). Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Front_Barbell_Squat","n":"Squat avant barre","ne":"Front Barbell Squat","e":"barbell","c":"strength","l":"expert","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Idéalement dans une cage. Règle la barre à ta hauteur, passe les bras dessous, coudes hauts, bras presque à l'horizontale. Pose la barre sur l'avant des épaules et croise les bras pour la tenir.","Décroche la barre en poussant avec les jambes.","Recule, pieds largeur d'épaules, pointes légèrement ouvertes, tête haute, dos droit.","Descends lentement en pliant les genoux jusqu'à un angle un peu inférieur à 90°, en inspirant. Genoux dans l'axe des pieds.","Remonte en expirant en poussant avec le milieu du pied."],"k":2},{"id":"Front_Barbell_Squat_To_A_Bench","n":"Squat avant barre jusqu'au banc","ne":"Front Barbell Squat To A Bench","e":"barbell","c":"strength","l":"expert","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Idéalement dans une cage, un banc plat derrière toi. Pose la barre sur l'avant des épaules, coudes hauts, bras croisés pour la tenir.","Décroche la barre en poussant avec les jambes.","Recule, pieds largeur d'épaules, pointes légèrement ouvertes, tête haute, dos droit.","Descends lentement jusqu'à toucher le banc avec les fessiers, en inspirant.","Remonte en expirant en poussant sur les talons."],"k":2},{"id":"Front_Box_Jump","n":"Saut sur box de face","ne":"Front Box Jump","e":"other","c":"plyometrics","l":"beginner","m":["hamstrings"],"s":["abductors","adductors","calves","glutes","quadriceps"],"i":["Place un box adapté à 30-60 cm devant toi, pieds largeur d'épaules.","Fais une petite flexion en balançant les bras vers l'arrière.","Saute le plus haut possible en tendant hanches, genoux et chevilles, bras vers l'avant et le haut.","Atterris sur le box genoux fléchis en amortissant. Redescends de préférence une jambe après l'autre."],"k":2},{"id":"Front_Cable_Raise","n":"Élévation frontale à la poulie","ne":"Front Cable Raise","e":"cable","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Choisis la charge sur une poulie basse et prends la poignée main gauche.","Dos à la poulie, bras tendu, poignée devant les cuisses, paume vers les cuisses.","Buste fixe, monte le bras devant toi, coude légèrement fléchi, paume vers le bas, jusqu'à un peu au-dessus de l'horizontale, en expirant. Pause une seconde.","Redescends lentement en inspirant.","Fais toutes les répétitions puis change de bras."],"k":2},{"id":"Front_Cone_Hops_or_hurdle_hops","n":"Sauts de plots vers l'avant","ne":"Front Cone Hops (or hurdle hops)","e":"other","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["abductors","adductors","calves","glutes","hamstrings"],"i":["Aligne des plots ou petites haies espacés d'environ un mètre.","Face au premier, pieds largeur d'épaules.","Saute à pieds joints par-dessus le premier plot en balançant les bras.","Amortis en pliant les genoux et rebondis aussitôt par-dessus le suivant.","Continue jusqu'au dernier plot."],"k":2},{"id":"Front_Dumbbell_Raise","n":"Élévation frontale haltère","ne":"Front Dumbbell Raise","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Debout, buste droit, un haltère dans chaque main devant les cuisses, paumes vers les cuisses.","Buste fixe, monte l'haltère gauche devant toi, coude légèrement fléchi, paume vers le bas, jusqu'à un peu au-dessus de l'horizontale, en expirant. Pause une seconde.","Redescends-le lentement en montant le droit.","Continue en alternant."],"k":2},{"id":"Front_Incline_Dumbbell_Raise","n":"Élévation frontale haltères sur banc incliné","ne":"Front Incline Dumbbell Raise","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Assis sur un banc incliné (30 à 60°), un haltère dans chaque main. Change l'angle d'une séance à l'autre pour varier.","Bras tendus devant toi, paumes vers le bas, haltères juste au-dessus des cuisses : c'est la position de départ.","Coudes verrouillés, monte lentement les haltères jusqu'à un peu au-dessus des épaules en expirant. Serre une seconde, tête contre le banc, pieds au sol.","Redescends en inspirant."],"k":2},{"id":"Front_Leg_Raises","n":"Balancés de jambe vers l'avant","ne":"Front Leg Raises","e":"body only","c":"stretching","l":"beginner","m":["hamstrings"],"s":[],"i":["Debout à côté d'une chaise, tiens-toi d'une main.","Balance la jambe tendue vers l'avant, puis vers l'arrière aussi loin que ta souplesse le permet. 5 à 10 fois, puis change de jambe."],"k":2},{"id":"Front_Plate_Raise","n":"Élévation frontale avec disque","ne":"Front Plate Raise","e":"other","c":"strength","l":"intermediate","m":["shoulders"],"s":[],"i":["Debout, tiens un disque à deux mains (à 3 h et 9 h), paumes face à face, bras tendus avec un léger pli aux coudes, disque devant la taille.","Monte lentement le disque jusqu'à un peu au-dessus des épaules en expirant. Tiens une seconde, sans élan ni plier les coudes.","Redescends lentement en inspirant."],"k":2},{"id":"Front_Raise_And_Pullover","n":"Élévation frontale et pull-over","ne":"Front Raise And Pullover","e":"barbell","c":"strength","l":"beginner","m":["chest"],"s":["lats","shoulders","triceps"],"i":["Allongé sur un banc plat, barre en pronation, mains écartées d'environ 40 cm.","Barre sur le haut des cuisses, bras tendus avec un léger pli aux coudes : c'est la position de départ.","Bras tendus, monte la barre en demi-cercle en inspirant, jusqu'à ce qu'elle passe derrière la tête, bras parallèles au sol (environ 180° de trajet).","Reviens par le même chemin en expirant."],"k":2},{"id":"Front_Squat_Clean_Grip","n":"Squat avant (prise d'épaulé)","ne":"Front Squat (Clean Grip)","e":"barbell","c":"strength","l":"intermediate","m":["quadriceps"],"s":["abdominals","glutes","hamstrings"],"i":["Règle la barre un peu sous les épaules. Pose-la sur l'avant des épaules, contre les clavicules, effleurant la gorge, mains en prise d'épaulé (seulement les doigts sous la barre).","Décroche-la en poussant avec les jambes, recule, pieds largeur d'épaules, pointes légèrement ouvertes, tête et coudes hauts.","Descends entre tes jambes jusqu'à ce que les ischios touchent les mollets, en poussant les genoux vers l'extérieur.","Remonte en expirant en poussant sur les talons ou le milieu du pied."],"k":2},{"id":"Front_Squats_With_Two_Kettlebells","n":"Squat avant deux kettlebells","ne":"Front Squats With Two Kettlebells","e":"kettlebells","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes"],"i":["Monte deux kettlebells aux épaules en poussant avec les jambes et les hanches, en tournant les poignets.","Regard droit devant, descends en squat le plus bas possible et marque une pause. Pousse les genoux vers l'extérieur, buste droit, tête et poitrine hautes.","Remonte en poussant sur les talons."],"k":2},{"id":"Front_Two-Dumbbell_Raise","n":"Élévation frontale deux haltères","ne":"Front Two-Dumbbell Raise","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Debout, buste droit, un haltère dans chaque main devant les cuisses, paumes vers les cuisses.","Buste fixe, monte les deux haltères devant toi, coudes légèrement fléchis, paumes vers le bas, jusqu'à un peu au-dessus de l'horizontale, en expirant. Pause une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Full_Range-Of-Motion_Lat_Pulldown","n":"Tirage vertical amplitude complète","ne":"Full Range-Of-Motion Lat Pulldown","e":"cable","c":"strength","l":"intermediate","m":["lats"],"s":["biceps","middle back","shoulders"],"i":["Debout ou assis sur un banc haut, attrape les deux poignées des poulies hautes en croisant les bras (main droite à gauche et inversement), paumes vers l'avant.","Poitrine haute, bas du dos légèrement cambré, tire les poignées vers le bas en arc de cercle en tournant les mains pour finir paumes face à face. Remonte lentement."],"k":2},{"id":"Gironda_Sternum_Chins","n":"Tractions sternum Gironda","ne":"Gironda Sternum Chins","e":"other","c":"strength","l":"intermediate","m":["lats"],"s":["biceps","middle back"],"i":["Attrape la barre en supination, largeur d'épaules.","Suspendu bras tendus, sors la poitrine et penche-toi en arrière ; tu resteras penché tout le long.","Tire-toi vers la barre, dos cambré, tête rejetée en arrière, en expirant. En haut, hanches et jambes forment environ 45° avec le sol.","Continue jusqu'à ce que la clavicule passe la barre et que le sternum la touche. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Glute_Ham_Raise","n":"Glute-ham raise","ne":"Glute Ham Raise","e":"machine","c":"powerlifting","l":"intermediate","m":["hamstrings"],"s":["calves","glutes"],"i":["Règle l'appareil à ta taille : pieds contre la plateforme entre les rouleaux, à plat ventre, genoux juste derrière le coussin.","Pars d'en bas, dos cambré, et plie les genoux en poussant les orteils contre la plateforme. Haut du corps droit, monte jusqu'à être vertical.","Redescends en contrôlant."],"k":2},{"id":"Glute_Kickback","n":"Kickback fessier","ne":"Glute Kickback","e":"body only","c":"strength","l":"beginner","m":["glutes"],"s":["hamstrings"],"i":["À genoux sur un tapis, penche-toi en appui sur les mains (bras tendus largeur d'épaules), regard devant, genoux à 90°.","En expirant, monte la jambe droite jusqu'à ce que la cuisse soit dans l'alignement du dos, genou toujours à 90°. Serre les fessiers une seconde.","Reviens en inspirant et fais de même avec la jambe gauche.","Continue en alternant."],"k":2},{"id":"Goblet_Squat","n":"Goblet squat","ne":"Goblet Squat","e":"kettlebells","c":"strength","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings","shoulders"],"i":["Debout, tiens une kettlebell légère par les cornes contre la poitrine.","Descends entre tes jambes jusqu'à ce que les ischios touchent les mollets, poitrine et tête hautes, dos droit.","En bas, marque une pause et pousse les genoux vers l'extérieur avec les coudes. Remonte. 10 à 20 répétitions."],"k":2},{"id":"Good_Morning","n":"Good morning","ne":"Good Morning","e":"barbell","c":"powerlifting","l":"intermediate","m":["hamstrings"],"s":["abdominals","glutes","lower back"],"i":["Barre sur un rack à hauteur d'épaules. Pose-la sur l'arrière des épaules (comme un squat en force), dos gainé, omoplates serrées, genoux légèrement fléchis. Recule.","Penche-toi depuis les hanches en les reculant, jusqu'à être presque parallèle au sol, dos cambré, nuque alignée.","Redresse-toi en poussant les hanches avec les fessiers et les ischios."],"k":2},{"id":"Good_Morning_off_Pins","n":"Good morning depuis les supports","ne":"Good Morning off Pins","e":"barbell","c":"powerlifting","l":"intermediate","m":["hamstrings"],"s":["abdominals","glutes","lower back"],"i":["Barre sur des supports à hauteur du ventre. Penche-toi dessous et pose-la sur l'arrière des épaules ; à la bonne hauteur, tu es presque parallèle au sol. Dos gainé et cambré, omoplates serrées, genoux légèrement fléchis.","Redresse-toi en poussant les hanches avec les fessiers et les ischios, puis repose lentement la barre sur les supports."],"k":2},{"id":"Gorilla_Chin_Crunch","n":"Traction-crunch gorille","ne":"Gorilla Chin/Crunch","e":"body only","c":"strength","l":"intermediate","m":["abdominals"],"s":["biceps","lats"],"i":["Suspendu à la barre en supination, un peu plus large que les épaules.","Plie les genoux à 90°, tibias parallèles au sol : c'est la position de départ.","En expirant, tire-toi vers le haut en remontant en même temps les genoux à hauteur de poitrine ; arrête-toi quand le nez arrive au niveau de la barre.","Redescends lentement en inspirant."],"k":2},{"id":"Groin_and_Back_Stretch","n":"Étirement aine et dos","ne":"Groin and Back Stretch","e":"other","c":"stretching","l":"intermediate","m":["adductors"],"s":[],"i":["Assis au sol, genoux pliés, plantes des pieds jointes.","Mains croisées derrière la tête : c'est la position de départ.","Enroule-toi vers le bas en amenant les coudes à l'intérieur des cuisses. Après une courte pause, remonte tête haute, dos droit. 10 à 20 répétitions."],"k":2},{"id":"Groiners","n":"Groiners","ne":"Groiners","e":"body only","c":"stretching","l":"intermediate","m":["adductors"],"s":[],"i":["En position de pompe au sol.","Saute des deux pieds vers l'avant pour les poser à côté des mains, tête haute.","Reviens en position de pompe et enchaîne, 10 à 20 fois."],"k":2},{"id":"Hack_Squat","n":"Hack squat","ne":"Hack Squat","e":"machine","c":"strength","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Dos contre le dossier de la machine, épaules sous les appuis.","Pieds sur la plateforme largeur d'épaules, pointes légèrement ouvertes, tête haute, dos toujours plaqué.","Mains sur les poignées, déverrouille les sécurités.","Tends les jambes sans verrouiller les genoux : c'est la position de départ.","Descends lentement en pliant les genoux jusqu'à un angle un peu inférieur à 90°, en inspirant. Genoux dans l'axe des pieds.","Remonte en expirant en poussant surtout sur les talons."],"k":2},{"id":"Hammer_Curls","n":"Curl marteau","ne":"Hammer Curls","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Debout, buste droit, un haltère dans chaque main bras tendus, coudes près du corps.","Paumes tournées vers le corps : c'est la position de départ.","Bras fixes, monte les haltères en contractant les biceps, en expirant, jusqu'à hauteur d'épaules. Serre un instant. Seuls les avant-bras bougent.","Redescends lentement en inspirant."],"k":2},{"id":"Hammer_Grip_Incline_DB_Bench_Press","n":"Développé incliné haltères prise marteau","ne":"Hammer Grip Incline DB Bench Press","e":"dumbbell","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Allongé sur un banc incliné, un haltère dans chaque main sur les cuisses, paumes face à face.","Aide-toi des cuisses pour monter les haltères un par un à largeur d'épaules.","Prise neutre (paumes face à face), coudes écartés, bras dans l'alignement des épaules, coudes à 90° : c'est la position de départ.","Descends lentement les haltères sur les côtés en inspirant, en gardant le contrôle.","Pousse avec les pectoraux en expirant, tiens une seconde en haut. La descente doit durer deux fois plus longtemps que la montée.","À la fin, repose les haltères sur les cuisses puis au sol."],"k":2},{"id":"Hamstring-SMR","n":"Auto-massage des ischios","ne":"Hamstring-SMR","e":"foam roll","c":"stretching","l":"beginner","m":["hamstrings"],"s":[],"i":["Assis, jambes tendues sur un rouleau de massage placé sous l'arrière des cuisses, mains au sol à côté ou derrière toi.","Décolle les hanches et mets le poids sur une jambe, ischios relâchés.","Roule de la hanche jusqu'au-dessus du genou, en restant 10 à 30 s sur les points sensibles. Change de jambe."],"k":2},{"id":"Hamstring_Stretch","n":"Étirement des ischios","ne":"Hamstring Stretch","e":"other","c":"stretching","l":"beginner","m":["hamstrings"],"s":[],"i":["Allongé sur le dos, une jambe tendue vers le haut (hanche à 90°), l'autre à plat au sol.","Passe une sangle, un élastique ou une corde sous l'avant du pied.","Tire sur la sangle pour étirer mollet et ischios. Tiens 10 à 30 s puis change de jambe."],"k":2},{"id":"Handstand_Push-Ups","n":"Pompes en équilibre sur les mains","ne":"Handstand Push-Ups","e":"body only","c":"strength","l":"expert","m":["shoulders"],"s":["triceps"],"i":["Dos au mur, penche-toi et pose les mains au sol à largeur d'épaules.","Lance les jambes contre le mur pour te retrouver tête en bas, bras et jambes tendus, corps bien droit. La première fois, fais-toi aider et garde la tête face au mur.","Descends lentement en inspirant jusqu'à ce que la tête frôle le sol ; la lenteur évite de se blesser à la tête.","Remonte lentement en expirant jusqu'à bras presque tendus."],"k":2},{"id":"Hang_Clean","n":"Épaulé suspendu","ne":"Hang Clean","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["quadriceps"],"s":["calves","forearms","glutes","hamstrings","lower back","shoulders","traps"],"i":["Prise largeur d'épaules en pronation ou crochet, barre suspendue à mi-cuisse, dos droit légèrement incliné vers l'avant.","Tends explosivement hanches, genoux et chevilles pour lancer la barre vers le haut, en haussant les épaules, puis glisse-toi dessous et réceptionne-la sur les épaules.","Relève-toi aussitôt en poussant sur les talons, buste droit, coudes hauts."],"k":2},{"id":"Hang_Clean_-_Below_the_Knees","n":"Épaulé suspendu sous les genoux","ne":"Hang Clean - Below the Knees","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["quadriceps"],"s":["calves","forearms","glutes","hamstrings","lower back","shoulders","traps"],"i":["Prise largeur d'épaules en pronation ou crochet, barre suspendue juste sous les genoux, dos droit légèrement incliné vers l'avant.","Tends explosivement hanches, genoux et chevilles en haussant les épaules ; à l'extension complète, tire avec les bras, coudes hauts et écartés.","Tire-toi sous la barre en tournant les coudes et réceptionne-la en squat avant, barre sur l'avant des épaules.","Relève-toi aussitôt en poussant sur les talons, buste droit, coudes hauts."],"k":2},{"id":"Hang_Snatch","n":"Arraché suspendu","ne":"Hang Snatch","e":"barbell","c":"olympic weightlifting","l":"expert","m":["hamstrings"],"s":["abdominals","calves","forearms","glutes","lower back","quadriceps","shoulders","traps"],"i":["Prise large en pronation ou crochet, pieds sous les hanches légèrement ouverts, genoux légèrement fléchis, buste penché, dos bien droit, regard devant, barre au niveau des hanches.","Tends explosivement jambes et hanches. À l'extension, hausse les épaules et laisse les coudes partir sur les côtés.","En plaçant les pieds, tire-toi sous la barre en l'envoyant au-dessus de la tête ; réceptionne le plus bas possible, bras tendus.","Relève-toi, barre au-dessus de la tête, puis redescends-la en contrôlant."],"k":2},{"id":"Hang_Snatch_-_Below_Knees","n":"Arraché suspendu sous les genoux","ne":"Hang Snatch - Below Knees","e":"barbell","c":"olympic weightlifting","l":"expert","m":["hamstrings"],"s":["abdominals","calves","forearms","glutes","lower back","quadriceps","shoulders","traps"],"i":["Prise large en pronation ou crochet, pieds sous les hanches légèrement ouverts, genoux légèrement fléchis, buste penché, dos droit, barre juste sous les genoux.","Tends explosivement jambes et hanches. À l'extension, hausse les épaules et laisse les coudes partir sur les côtés.","Tire-toi sous la barre en l'envoyant au-dessus de la tête ; réceptionne le plus bas possible, bras tendus.","Relève-toi puis redescends la barre en contrôlant."],"k":2},{"id":"Hanging_Bar_Good_Morning","n":"Good morning suspendu à la barre","ne":"Hanging Bar Good Morning","e":"barbell","c":"powerlifting","l":"intermediate","m":["hamstrings"],"s":["abdominals","glutes","lower back"],"i":["Barre suspendue par des chaînes ou des sangles à hauteur du ventre.","Penche-toi dessous et pose-la sur l'arrière des épaules ; tu es presque parallèle au sol. Dos gainé et cambré, omoplates serrées, genoux légèrement fléchis.","Redresse-toi en poussant les hanches avec les fessiers et les ischios.","Redescends lentement jusqu'à ce que les chaînes reprennent la barre."],"k":2},{"id":"Hanging_Leg_Raise","n":"Relevés de jambes suspendu","ne":"Hanging Leg Raise","e":"body only","c":"strength","l":"expert","m":["abdominals"],"s":[],"i":["Suspendu à la barre, bras tendus, prise moyenne ou large, jambes tendues, bassin légèrement enroulé.","Monte les jambes jusqu'à former 90° avec le buste, en expirant. Tiens environ une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Hanging_Pike","n":"Pike suspendu","ne":"Hanging Pike","e":"body only","c":"strength","l":"expert","m":["abdominals"],"s":[],"i":["Suspendu à la barre en pronation, un peu plus large que les épaules, jambes et pieds joints (des sangles peuvent aider).","Plie les genoux à 90° et monte les cuisses à l'horizontale, tibias verticaux : c'est la position de départ.","Monte les jambes en expirant jusqu'à presque toucher la barre avec les tibias, en tendant les jambes au maximum en haut.","Redescends le plus lentement possible, sans balancer."],"k":2},{"id":"Heaving_Snatch_Balance","n":"Équilibre d'arraché dynamique","ne":"Heaving Snatch Balance","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["quadriceps"],"s":["abdominals","forearms","glutes","hamstrings","shoulders","triceps"],"i":["Exercice d'apprentissage de l'arraché. Barre légère sur l'arrière des épaules, pieds un peu plus larges que les hanches, pointes ouvertes (position de squat).","Fléchis légèrement les genoux puis remonte vivement pour décharger la barre un instant ; plonge sous la barre en la poussant au-dessus de la tête et descends en squat complet.","Relève-toi."],"k":2},{"id":"Heavy_Bag_Thrust","n":"Poussée sur sac de frappe","ne":"Heavy Bag Thrust","e":"other","c":"plyometrics","l":"beginner","m":["chest"],"s":["abdominals","shoulders","triceps"],"i":["Avec un sac de frappe lourd. Debout à côté du sac, pieds décalés et bien écartés, main posée sur le sac à hauteur de poitrine.","Tourne la taille et pousse le sac vers l'avant le plus fort et le plus vite possible.","Réceptionne le sac quand il revient en faisant le mouvement inverse."],"k":2},{"id":"High_Cable_Curls","n":"Curl poulie haute","ne":"High Cable Curls","e":"cable","c":"strength","l":"intermediate","m":["biceps"],"s":[],"i":["Debout entre deux poulies hautes, une poignée dans chaque main, bras à l'horizontale, paumes vers toi.","Ramène les poignées vers tes oreilles en contractant les biceps, en expirant. Bras fixes, seuls les avant-bras bougent. Serre une seconde.","Reviens lentement."],"k":2},{"id":"Hip_Circles_prone","n":"Cercles de hanche (à plat ventre)","ne":"Hip Circles (prone)","e":"body only","c":"stretching","l":"beginner","m":["abductors"],"s":["adductors"],"i":["À quatre pattes au sol, dos bien placé, décolle un genou plié.","Genou toujours plié, dessine un grand cercle avec le genou en faisant tourner la cuisse.","Fais plusieurs cercles lentement puis change de côté."],"k":2},{"id":"Hip_Extension_with_Bands","n":"Extension de hanche à l'élastique","ne":"Hip Extension with Bands","e":"bands","c":"strength","l":"beginner","m":["glutes"],"s":["hamstrings"],"i":["Fixe un élastique en bas d'un poteau et l'autre bout à une cheville.","Face au poteau, tiens-le pour l'équilibre.","Tête et poitrine hautes, recule la jambe au maximum, genou tendu.","Ramène la jambe."],"k":2},{"id":"Hip_Flexion_with_Band","n":"Flexion de hanche à l'élastique","ne":"Hip Flexion with Band","e":"bands","c":"strength","l":"beginner","m":["quadriceps"],"s":[],"i":["Fixe un élastique en bas d'un poteau et l'autre bout à une cheville.","Dos au poteau.","Tête et poitrine hautes, monte le genou à 90° et marque une pause.","Ramène la jambe."],"k":2},{"id":"Hip_Lift_with_Band","n":"Relevé de bassin à l'élastique","ne":"Hip Lift with Band","e":"bands","c":"powerlifting","l":"beginner","m":["glutes"],"s":["calves","hamstrings"],"i":["Choisis un élastique et fixe-le de chaque côté du rack (ou sous des haltères lourds bien calés), puis allonge-toi au milieu.","Élastique juste au-dessus des hanches, genoux pliés, pieds à plat. Mains au sol ou sur l'élastique.","Épaules au sol, pousse sur les talons pour monter les hanches le plus haut possible contre l'élastique.","Pause en haut puis redescends."],"k":2},{"id":"Hug_A_Ball","n":"Enlacer un ballon (étirement)","ne":"Hug A Ball","e":"exercise ball","c":"stretching","l":"beginner","m":["lower back"],"s":["calves","glutes"],"i":["Assieds-toi au sol.","Place un swiss ball entre tes jambes et descends les hanches vers le sol.","Entoure le ballon de tes bras pour te soutenir, pieds à plat, genoux au-dessus des chevilles. Tiens bien le ballon pour ne pas basculer en arrière."],"k":2},{"id":"Hug_Knees_To_Chest","n":"Genoux contre la poitrine","ne":"Hug Knees To Chest","e":"other","c":"stretching","l":"beginner","m":["lower back"],"s":["glutes"],"i":["Allongé sur le dos, ramène les deux genoux contre la poitrine.","Passe les bras sous les genoux (pas dessus, pour ne pas comprimer l'articulation).","Tire doucement les genoux vers les épaules ; cela étire aussi les fessiers."],"k":2},{"id":"Hurdle_Hops","n":"Sauts de haies","ne":"Hurdle Hops","e":"other","c":"plyometrics","l":"beginner","m":["hamstrings"],"s":["abductors","adductors","calves","glutes","hamstrings"],"i":["Aligne des haies basses espacées d'environ un mètre.","Face à la première, pieds largeur d'épaules.","Saute à pieds joints par-dessus la première en balançant les bras.","Amortis en pliant les genoux et rebondis aussitôt par-dessus la suivante, jusqu'à la dernière."],"k":2},{"id":"Hyperextensions_Back_Extensions","n":"Extensions lombaires (hyperextensions)","ne":"Hyperextensions (Back Extensions)","e":"other","c":"strength","l":"beginner","m":["lower back"],"s":["glutes","hamstrings"],"i":["Allongé à plat ventre sur un banc à lombaires, chevilles calées sous les boudins.","Règle l'appui pour que le haut des cuisses repose dessus et que tu puisses te pencher librement.","Corps droit, bras croisés devant toi ou derrière la tête (un disque contre la poitrine pour ajouter de la charge) : c'est la position de départ.","Penche-toi lentement en avant aussi loin que possible sans arrondir le dos, en inspirant, jusqu'à sentir l'étirement des ischios.","Remonte lentement jusqu'à l'alignement, sans te cambrer au-delà ni balancer."],"k":2},{"id":"Hyperextensions_With_No_Hyperextension_Bench","n":"Extensions lombaires sans banc","ne":"Hyperextensions With No Hyperextension Bench","e":"body only","c":"strength","l":"intermediate","m":["lower back"],"s":["glutes","hamstrings"],"i":["Quelqu'un te tient les jambes ; glisse-toi au bout d'un banc plat jusqu'à ce que les hanches dépassent, haut du corps pendant vers le sol.","Corps droit, bras croisés devant toi ou derrière la tête : c'est la position de départ.","Penche-toi lentement en avant sans arrondir le dos, en inspirant, jusqu'à presque toucher le sol ou sentir l'étirement des ischios.","Remonte lentement en expirant jusqu'à l'alignement, sans te cambrer au-delà ni balancer."],"k":2},{"id":"IT_Band_and_Glute_Stretch","n":"Étirement bandelette ilio-tibiale et fessiers","ne":"IT Band and Glute Stretch","e":"other","c":"stretching","l":"intermediate","m":["abductors"],"s":[],"i":["Allongé au sol, passe une sangle autour d'un pied et amène cette jambe tendue en travers du corps, de l'autre côté.","Pied décollé du sol, tire sur la sangle pour remonter les orteils. Tiens 10 à 20 s puis change de côté."],"k":2},{"id":"Iliotibial_Tract-SMR","n":"Auto-massage bandelette ilio-tibiale","ne":"Iliotibial Tract-SMR","e":"foam roll","c":"stretching","l":"intermediate","m":["abductors"],"s":[],"i":["Allongé sur le côté, la jambe du dessous sur un rouleau de massage entre la hanche et le genou, l'autre jambe croisée devant toi.","Mets autant de poids que tu le supportes sur la jambe du dessous, muscles relâchés.","Roule de la hanche au genou, en restant 10 à 30 s sur les points sensibles. Change de jambe."],"k":2},{"id":"Inchworm","n":"Chenille (inchworm)","ne":"Inchworm","e":"body only","c":"stretching","l":"beginner","m":["hamstrings"],"s":[],"i":["Debout, pieds serrés. Jambes tendues, penche-toi et pose les mains au sol devant toi.","Avance lentement les mains l'une après l'autre en pliant seulement les hanches, jambes tendues.","Continue jusqu'à être en position de pompe.","Mains fixes, avance les pieds à tout petits pas.","Continue jusqu'à ce que les pieds rejoignent les mains, jambes toujours tendues."],"k":2},{"id":"Incline_Barbell_Triceps_Extension","n":"Extension triceps barre sur banc incliné","ne":"Incline Barbell Triceps Extension","e":"barbell","c":"strength","l":"intermediate","m":["triceps"],"s":["forearms"],"i":["Barre en pronation, mains un peu plus serrées que les épaules.","Allonge-toi sur un banc incliné entre 45 et 75°.","Barre au-dessus de la tête, bras tendus dans le prolongement du buste, coudes rentrés : c'est la position de départ.","Descends la barre en arc derrière la tête jusqu'à ce que les avant-bras touchent les biceps, en inspirant. Bras fixes près de la tête.","Remonte en contractant les triceps, en expirant. Tiens une seconde."],"k":2},{"id":"Incline_Bench_Pull","n":"Tirage allongé sur banc incliné","ne":"Incline Bench Pull","e":"barbell","c":"strength","l":"beginner","m":["middle back"],"s":["lats","shoulders"],"i":["Un haltère dans chaque main, allonge-toi à plat ventre sur un banc incliné à environ 30°.","Laisse les bras pendre vers le sol.","Tourne les poignets en pronation.","Écarte les coudes : c'est la position de départ.","En expirant, tire les haltères vers le haut comme un développé couché inversé : coudes sur les côtés, bras qui montent jusqu'au niveau du dos (forme de « T »). Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Incline_Cable_Chest_Press","n":"Développé incliné à la poulie","ne":"Incline Cable Chest Press","e":"cable","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Choisis la charge et assieds-toi, poignées en main, bras à environ 45° du corps, coudes à 90°, tête et poitrine hautes.","Pousse les poignées droit devant toi en les rapprochant, omoplates serrées.","Après une pause bras tendus, reviens en gardant la tension."],"k":2},{"id":"Incline_Cable_Flye","n":"Écarté incliné à la poulie","ne":"Incline Cable Flye","e":"cable","c":"strength","l":"intermediate","m":["chest"],"s":["shoulders"],"i":["Place les poulies au plus bas.","Installe un banc incliné à 45° entre elles, choisis la charge et prends une poignée dans chaque main.","Allongé sur le banc, mains jointes au-dessus du visage, bras tendus : c'est la position de départ.","Coudes légèrement fléchis, ouvre les bras en grand arc jusqu'à sentir l'étirement des pectoraux, en inspirant. Seules les épaules bougent.","Reviens par le même arc en serrant les pectoraux, en expirant. Tiens une seconde."],"k":2},{"id":"Incline_Dumbbell_Bench_With_Palms_Facing_In","n":"Développé incliné haltères paumes face à face","ne":"Incline Dumbbell Bench With Palms Facing In","e":"dumbbell","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Allongé sur un banc incliné, un haltère dans chaque main sur les cuisses, paumes face à face.","Aide-toi des cuisses pour monter les haltères un par un à largeur d'épaules.","Prise neutre, coudes écartés, coudes à 90° : c'est la position de départ.","Descends lentement les haltères sur les côtés en inspirant.","Pousse avec les pectoraux en expirant, tiens une seconde en haut. La descente doit durer deux fois plus longtemps que la montée.","À la fin, repose les haltères sur les cuisses puis au sol."],"k":2},{"id":"Incline_Dumbbell_Curl","n":"Curl incliné haltères","ne":"Incline Dumbbell Curl","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Assis sur un banc incliné, un haltère dans chaque main bras tendus, coudes près du corps, paumes vers l'avant.","Bras fixes, monte les haltères en contractant les biceps, en expirant, jusqu'à hauteur d'épaules. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Incline_Dumbbell_Flyes","n":"Écarté incliné haltères","ne":"Incline Dumbbell Flyes","e":"dumbbell","c":"strength","l":"beginner","m":["chest"],"s":["shoulders"],"i":["Un haltère dans chaque main, allonge-toi sur un banc incliné à 30° maximum.","Bras tendus au-dessus de toi, coudes légèrement fléchis.","Tourne les poignets paumes vers toi, petits doigts côte à côte : c'est la position de départ.","En inspirant, ouvre lentement les bras sur les côtés en tournant les poignets jusqu'à avoir les paumes vers le plafond.","Remonte en expirant en faisant le mouvement inverse. Seules les épaules et les poignets bougent, pas les coudes."],"k":2},{"id":"Incline_Dumbbell_Flyes_-_With_A_Twist","n":"Écarté incliné haltères avec rotation","ne":"Incline Dumbbell Flyes - With A Twist","e":"dumbbell","c":"strength","l":"beginner","m":["chest"],"s":["shoulders"],"i":["Un haltère dans chaque main, allonge-toi sur un banc incliné à 30° maximum.","Bras tendus au-dessus de toi, coudes légèrement fléchis.","Paumes vers toi, petits doigts côte à côte : c'est la position de départ.","En inspirant, ouvre lentement les bras sur les côtés en tournant les poignets jusqu'à avoir les paumes vers le plafond.","Remonte en expirant en faisant le mouvement inverse. Seules les épaules et les poignets bougent."],"k":2},{"id":"Incline_Dumbbell_Press","n":"Développé incliné haltères","ne":"Incline Dumbbell Press","e":"dumbbell","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Allongé sur un banc incliné, un haltère dans chaque main sur les cuisses, paumes face à face.","Aide-toi des cuisses pour monter les haltères un par un à largeur d'épaules.","Tourne les poignets paumes vers l'avant : c'est la position de départ.","Garde le contrôle des haltères, expire et pousse-les vers le haut avec les pectoraux.","Bras verrouillés en haut, tiens une seconde puis redescends lentement (environ deux fois plus lentement).","À la fin, repose les haltères sur les cuisses puis au sol."],"k":2},{"id":"Incline_Hammer_Curls","n":"Curl marteau incliné","ne":"Incline Hammer Curls","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Assis sur un banc incliné, dos bien plaqué, pieds joints, un haltère dans chaque main pendant le long du corps en prise neutre.","Plie les coudes en gardant le haut des bras immobile.","Monte jusqu'en haut, marque une pause, puis redescends lentement."],"k":2},{"id":"Incline_Inner_Biceps_Curl","n":"Curl incliné biceps intérieur","ne":"Incline Inner Biceps Curl","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Un haltère dans chaque main, allonge-toi sur un banc incliné.","Haltères pendants bras tendus, paumes vers l'extérieur : c'est la position de départ.","En expirant, monte les haltères vers l'extérieur et le haut, avant-bras alignés avec les épaules, jusqu'à hauteur d'épaules (comme une pose double biceps).","Après une seconde, redescends lentement en inspirant par le même chemin."],"k":2},{"id":"Incline_Push-Up","n":"Pompes inclinées","ne":"Incline Push-Up","e":"body only","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Debout face à un banc ou une plateforme stable, mains sur le bord, un peu plus larges que les épaules.","Recule les pieds, bras et corps droits, bras perpendiculaires au corps. Corps gainé, descends la poitrine vers le bord en pliant les bras.","Remonte jusqu'à bras tendus."],"k":2},{"id":"Incline_Push-Up_Close-Grip","n":"Pompes inclinées prise serrée","ne":"Incline Push-Up Close-Grip","e":"body only","c":"strength","l":"beginner","m":["triceps"],"s":["chest","shoulders"],"i":["Face à la barre d'une Smith machine (ou une plateforme stable) à hauteur adaptée.","Mains l'une contre l'autre sur la barre.","Recule les pieds, bras et corps droits : c'est la position de départ.","Corps gainé, descends la poitrine vers la barre en pliant les bras.","Remonte en tendant les coudes."],"k":2},{"id":"Incline_Push-Up_Depth_Jump","n":"Pompes inclinées pliométriques","ne":"Incline Push-Up Depth Jump","e":"other","c":"plyometrics","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Il faut un box d'environ 30 cm et deux steps ou tapis épais.","Place les steps juste à l'extérieur des épaules, pieds sur le box, en position de pompe inclinée, mains entre les steps.","Plie les coudes puis pousse explosivement pour décoller ; pose les mains sur les steps en amortissant.","Refais le mouvement pour revenir."],"k":2},{"id":"Incline_Push-Up_Medium","n":"Pompes inclinées prise moyenne","ne":"Incline Push-Up Medium","e":"body only","c":"strength","l":"beginner","m":["chest"],"s":["abdominals","shoulders","triceps"],"i":["Face à la barre d'une Smith machine (ou une plateforme stable) à hauteur adaptée.","Mains sur la barre, largeur d'épaules.","Recule les pieds, bras et corps droits : c'est la position de départ.","Corps gainé, descends la poitrine vers la barre en pliant les bras.","Remonte en tendant les coudes."],"k":2},{"id":"Incline_Push-Up_Reverse_Grip","n":"Pompes inclinées prise inversée","ne":"Incline Push-Up Reverse Grip","e":"body only","c":"strength","l":"beginner","m":["chest"],"s":["abdominals","shoulders","triceps"],"i":["Face à la barre d'une Smith machine (ou une plateforme stable) à hauteur adaptée.","Mains sur la barre paumes vers le haut, largeur d'épaules.","Recule les pieds, bras et corps droits : c'est la position de départ.","Corps gainé, descends la poitrine vers la barre en pliant les bras.","Remonte en tendant les coudes."],"k":2},{"id":"Incline_Push-Up_Wide","n":"Pompes inclinées prise large","ne":"Incline Push-Up Wide","e":"body only","c":"strength","l":"beginner","m":["chest"],"s":["abdominals","shoulders","triceps"],"i":["Face à la barre d'une Smith machine (ou une plateforme stable) à hauteur adaptée.","Mains sur la barre, plus larges que les épaules.","Recule les pieds, bras et corps droits, bras perpendiculaires au corps : c'est la position de départ.","Corps gainé, descends la poitrine vers la barre en pliant les bras.","Remonte en tendant les coudes."],"k":2},{"id":"Intermediate_Groin_Stretch","n":"Étirement intermédiaire de l'aine","ne":"Intermediate Groin Stretch","e":"other","c":"stretching","l":"intermediate","m":["hamstrings"],"s":[],"i":["Allongé sur le dos, jambes tendues. Passe une sangle autour d'un pied et écarte cette jambe le plus possible sur le côté.","Tire doucement sur la sangle pour étirer l'aine et les ischios. Tiens 10 à 20 s puis change de côté."],"k":2},{"id":"Intermediate_Hip_Flexor_and_Quad_Stretch","n":"Étirement fléchisseurs de hanche et quadriceps","ne":"Intermediate Hip Flexor and Quad Stretch","e":"other","c":"stretching","l":"intermediate","m":["quadriceps"],"s":[],"i":["Allongé à plat ventre, une sangle autour d'un pied.","Plie le genou et tire la sangle à deux mains pour décoller genou et hanche du sol, en étirant le fléchisseur de hanche et le quadriceps. Tiens 10 à 20 s puis change de jambe."],"k":2},{"id":"Internal_Rotation_with_Band","n":"Rotation interne à l'élastique","ne":"Internal Rotation with Band","e":"bands","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Accroche un élastique à un poteau, à hauteur du coude. Côté droit vers le poteau, à environ 60 cm.","Prends l'élastique main droite, coude plaqué contre le corps (un petit coussin sous le coude aide).","Coude à 90°, main tournée vers l'extérieur : c'est la position de départ.","Fais tourner le bras vers l'intérieur, comme un coup droit, coude fixe.","Va aussi loin que possible, pause, puis reviens."],"k":2},{"id":"Inverted_Row","n":"Rowing inversé","ne":"Inverted Row","e":"other","c":"strength","l":"beginner","m":["middle back"],"s":["lats"],"i":["Place une barre dans un rack (ou une Smith machine) à hauteur de taille.","Prends-la plus large que les épaules et suspends-toi dessous, corps droit, talons au sol, bras tendus : c'est la position de départ.","Plie les coudes pour tirer la poitrine vers la barre en serrant les omoplates.","Pause en haut puis redescends."],"k":2},{"id":"Inverted_Row_with_Straps","n":"Rowing inversé aux sangles","ne":"Inverted Row with Straps","e":"other","c":"strength","l":"beginner","m":["middle back"],"s":["biceps","lats"],"i":["Accroche une corde ou des sangles de suspension à un rack. Tiens les poignées et suspends-toi sur le dos, corps droit, talons au sol, bras tendus.","Plie les coudes pour amener la poitrine vers les mains en serrant les omoplates.","Pause en haut puis redescends."],"k":2},{"id":"Iron_Cross","n":"Croix de fer","ne":"Iron Cross","e":"dumbbell","c":"strength","l":"intermediate","m":["shoulders"],"s":["chest","glutes","hamstrings","lower back","quadriceps","traps"],"i":["Exercice d'épaules avec haltères : debout, bras tendus devant toi, écarte-les sur les côtés jusqu'à former une croix, puis ramène-les devant toi en contrôlant."],"k":2},{"id":"Iron_Crosses_stretch","n":"Croix de fer (étirement)","ne":"Iron Crosses (stretch)","e":"other","c":"stretching","l":"intermediate","m":["quadriceps"],"s":[],"i":["Allongé à plat ventre, bras écartés sur les côtés, paumes au sol.","Plie un genou et fais passer la jambe derrière toi en travers du corps pour aller toucher le sol près de la main opposée.","Reviens aussitôt et fais de même avec l'autre jambe. Alterne 10 à 20 fois."],"k":2},{"id":"Isometric_Chest_Squeezes","n":"Contractions isométriques des pectoraux","ne":"Isometric Chest Squeezes","e":"body only","c":"plyometrics","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Assis ou debout, bras pliés à 90°, paumes jointes devant la poitrine, doigts vers l'avant.","Presse les mains l'une contre l'autre en contractant les pectoraux, en augmentant progressivement la tension, en respirant normalement.","Tiens le nombre de secondes prévu.","Relâche lentement.","Récupère puis recommence."],"k":2},{"id":"Isometric_Neck_Exercise_-_Front_And_Back","n":"Gainage du cou avant et arrière","ne":"Isometric Neck Exercise - Front And Back","e":"body only","c":"strength","l":"beginner","m":["neck"],"s":[],"i":["Tête droite, regard devant, mains posées sur le front.","Pousse doucement la tête vers l'avant contre les mains, sans laisser la tête bouger, en augmentant progressivement la tension et en respirant normalement.","Tiens le nombre de secondes prévu.","Relâche lentement.","Récupère puis recommence avec les mains derrière la tête."],"k":2},{"id":"Isometric_Neck_Exercise_-_Sides","n":"Gainage du cou sur les côtés","ne":"Isometric Neck Exercise - Sides","e":"body only","c":"strength","l":"beginner","m":["neck"],"s":[],"i":["Tête droite, regard devant, main gauche posée sur le côté gauche de la tête.","Pousse doucement la tête vers la gauche contre la main, sans laisser la tête bouger, en augmentant progressivement la tension et en respirant normalement.","Tiens le nombre de secondes prévu.","Relâche lentement.","Récupère puis recommence à droite."],"k":2},{"id":"Isometric_Wipers","n":"Essuie-glaces isométriques","ne":"Isometric Wipers","e":"body only","c":"strength","l":"beginner","m":["chest"],"s":["abdominals","shoulders","triceps"],"i":["En position de pompe, corps droit, mains juste à l'extérieur des épaules.","Déplace ton poids au maximum d'un côté en pliant le coude de ce côté pour descendre.","Remonte en tendant ce bras puis descends de l'autre côté."],"k":2},{"id":"JM_Press","n":"Développé JM","ne":"JM Press","e":"barbell","c":"strength","l":"beginner","m":["triceps"],"s":["chest","shoulders"],"i":["Comme un développé couché prise serrée : allongé, barre tenue bras tendus, coudes rentrés, mais la barre est alignée au-dessus du haut de la poitrine.","Descends la barre comme pour une barre au front, en inspirant. À mi-chemin, laisse-la reculer de quelques centimètres en ramenant les bras vers les jambes jusqu'à ce qu'ils soient perpendiculaires au buste, angle des coudes constant.","Pousse la barre avec les triceps en expirant, comme un développé prise serrée.","Reviens à la position de départ."],"k":2},{"id":"Jackknife_Sit-Up","n":"Sit-up en canif","ne":"Jackknife Sit-Up","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur le dos, bras tendus derrière la tête, jambes tendues : c'est la position de départ.","En expirant, plie-toi en deux en montant en même temps jambes et bras pour qu'ils se rejoignent (jambes à environ 35-45° du sol, bras parallèles aux jambes, haut du buste décollé).","Redescends en inspirant."],"k":2},{"id":"Janda_Sit-Up","n":"Sit-up Janda","ne":"Janda Sit-Up","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Position de sit-up : genoux à 90°, pieds à plat, bras croisés sur la poitrine ou le long du corps.","Serre fort fessiers et ischios, inspire, puis monte très lentement (3 à 6 s) en expirant. Contracter les fessiers met les fléchisseurs de hanche au repos.","Redescends lentement en inspirant."],"k":2},{"id":"Jefferson_Squats","n":"Squat Jefferson","ne":"Jefferson Squats","e":"barbell","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings","lower back","traps"],"i":["Pose une barre au sol.","Place-toi au milieu, à cheval sur la barre dans le sens de la longueur.","Plie les genoux, dos droit, et attrape l'avant de la barre main droite, paume vers la gauche.","Attrape l'arrière de la barre main gauche, paume vers la droite ; mains à égale distance de ton corps.","Redresse-toi avec la barre, pieds largeur d'épaules, pointes légèrement ouvertes.","Descends en squat, dos droit et le plus vertical possible, tête haute, jusqu'à avoir les cuisses parallèles au sol, en inspirant.","Remonte en poussant sur les pieds. Les bras ne sont que des crochets : ce sont les cuisses qui travaillent."],"k":2},{"id":"Jerk_Balance","n":"Équilibre de jeté","ne":"Jerk Balance","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["shoulders"],"s":["glutes","hamstrings","quadriceps","triceps"],"i":["Cet exercice apprend à descendre assez bas au jeté et corrige ceux qui reculent. Barre sur l'avant des épaules, buste droit, pieds légèrement en fente.","Fléchis les genoux, buste vertical, puis repousse fort pour monter la barre avec l'élan, pas avec les bras.","Garde le pied arrière en place et projette-toi vers l'avant en fente complète en jetant la barre. Relève-toi, barre au-dessus de la tête."],"k":2},{"id":"Jerk_Dip_Squat","n":"Flexion d'appel du jeté","ne":"Jerk Dip Squat","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["quadriceps"],"s":["abdominals","calves"],"i":["Renforce la flexion d'appel du jeté. Barre posée sur l'avant des épaules, contre la gorge, pieds sous les hanches légèrement ouverts.","Buste vertical, fléchis les genoux vers l'avant sans reculer les hanches, sans descendre trop. Remonte en poussant fort sur les pieds."],"k":2},{"id":"Jogging_Treadmill","n":"Course sur tapis","ne":"Jogging, Treadmill","e":"machine","c":"cardio","l":"beginner","m":["quadriceps"],"s":["glutes","hamstrings"],"i":["Monte sur le tapis et choisis un programme ou le mode manuel. Tu peux entrer âge et poids pour estimer les calories et régler l'inclinaison pour l'intensité.","Le tapis amortit mieux qu'une course dehors. Garde une bonne posture et ne tiens les poignées que si nécessaire (pour descendre ou mesurer ton pouls)."],"k":2},{"id":"Keg_Load","n":"Chargement de fût","ne":"Keg Load","e":"other","c":"strongman","l":"intermediate","m":["lower back"],"s":["abdominals","biceps","calves","forearms","glutes","hamstrings","middle back","quadriceps","shoulders","traps"],"i":["Place les fûts à 10-15 m de la plateforme de chargement.","Attrape la poignée la plus proche du premier fût, bascule-le pour saisir le bord opposé du fond et monte-le contre ta poitrine.","Plus tu le portes haut, plus tu avances vite. Tiens-le fermement, va le plus vite possible à la plateforme et charge-le en tendant hanches, genoux et chevilles.","Reviens chercher le fût suivant."],"k":2},{"id":"Kettlebell_Arnold_Press","n":"Développé Arnold kettlebell","ne":"Kettlebell Arnold Press","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["triceps"],"i":["Monte une kettlebell à l'épaule en poussant avec les jambes et les hanches, paume vers l'intérieur.","Regard devant, pousse la kettlebell au-dessus de la tête en tournant le poignet pour finir paume vers l'avant.","Redescends-la à l'épaule, paume vers l'intérieur."],"k":2},{"id":"Kettlebell_Dead_Clean","n":"Épaulé kettlebell depuis le sol","ne":"Kettlebell Dead Clean","e":"kettlebells","c":"strength","l":"intermediate","m":["hamstrings"],"s":["calves","glutes","lower back","quadriceps","traps"],"i":["Place la kettlebell entre tes pieds, fesses en arrière, regard droit devant.","Monte la kettlebell à l'épaule en poussant avec les jambes et les hanches, en tournant le poignet.","Redescends-la en gardant le dos droit et les fesses en arrière."],"k":2},{"id":"Kettlebell_Figure_8","n":"Huit avec kettlebell","ne":"Kettlebell Figure 8","e":"kettlebells","c":"strength","l":"intermediate","m":["abdominals"],"s":["hamstrings","shoulders"],"i":["Place une kettlebell entre tes jambes, pieds plus écartés que les épaules. Penche-toi, fesses en arrière, dos plat.","Prends la kettlebell et passe-la à l'autre main entre les jambes, la main qui reçoit venant de derrière la jambe. Fais des huit plusieurs fois."],"k":2},{"id":"Kettlebell_Halo","n":"Halo kettlebell","ne":"Kettlebell Halo","e":"kettlebells","c":"strength","l":"beginner","m":["shoulders"],"s":["traps","middle back","abdominals","triceps"],"i":["Debout, pieds largeur de hanches, kettlebell tenue à l'envers par les cornes contre la poitrine. Abdos gainés, fessiers serrés pour garder les côtes basses : c'est la position de départ.","Coudes près de la tête, fais passer la kettlebell près d'une oreille puis derrière la tête.","Continue le cercle près de l'autre oreille et reviens devant la poitrine, la kettlebell restant près du corps.","Fais les cercles prévus dans un sens puis autant dans l'autre.","Mouvement lent, tête, hanches et bas du dos immobiles. Si le dos se cambre, prends plus léger."],"k":0},{"id":"Kettlebell_Halo_With_Overhead_Extension","n":"Halo kettlebell avec extension","ne":"Kettlebell Halo with Overhead Extension","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders","triceps"],"s":["traps","middle back","abdominals"],"i":["Debout, pieds largeur de hanches, kettlebell tenue à l'envers par les cornes contre la poitrine, abdos et fessiers serrés.","Coudes près de la tête, fais passer la kettlebell près d'une oreille jusque derrière la tête. Pause.","De là, tends les coudes pour pousser la kettlebell au-dessus de la tête, bras près de la tête.","Plie les coudes pour revenir derrière la tête en contrôlant.","Termine le cercle par l'autre oreille jusqu'à la poitrine : cela fait une répétition.","Change de sens à chaque répétition. Si le dos se cambre, prends plus léger ou fais les deux mouvements séparément."],"k":0},{"id":"Kettlebell_Hang_Clean","n":"Épaulé suspendu kettlebell","ne":"Kettlebell Hang Clean","e":"kettlebells","c":"strength","l":"intermediate","m":["hamstrings"],"s":["calves","glutes","lower back","shoulders","traps"],"i":["Place la kettlebell entre tes pieds, fesses en arrière, regard droit devant.","Monte la kettlebell à l'épaule en poussant avec les jambes et les hanches, en tournant le poignet.","Redescends-la suspendue entre les jambes en gardant les ischios en tension, tête haute."],"k":2},{"id":"Kettlebell_One-Legged_Deadlift","n":"Soulevé de terre une jambe kettlebell","ne":"Kettlebell One-Legged Deadlift","e":"kettlebells","c":"strength","l":"intermediate","m":["hamstrings"],"s":["glutes","lower back"],"i":["Kettlebell dans une main ; tiens-toi debout sur la jambe du même côté.","Genou légèrement fléchi, penche-toi depuis la hanche jambes tendues, la jambe libre partant derrière pour l'équilibre.","Descends jusqu'à être parallèle au sol puis redresse-toi."],"k":2},{"id":"Kettlebell_Overhead_Triceps_Extension","n":"Extension triceps nuque kettlebell","ne":"Kettlebell Overhead Triceps Extension","e":"kettlebells","c":"strength","l":"beginner","m":["triceps"],"s":["shoulders","abdominals"],"i":["Debout, pieds largeur de hanches, kettlebell tenue par les cornes à deux mains, poussée au-dessus de la tête, la boule pendant derrière les mains.","Abdos gainés, bras verticaux près de la tête : c'est la position de départ.","Plie les coudes pour descendre la kettlebell derrière la tête, aussi loin que tes épaules le permettent, sans écarter les coudes.","Tends les coudes pour remonter, bras immobiles.","Garde les côtes basses, sans cambrer le bas du dos."],"k":0},{"id":"Kettlebell_Pass_Between_The_Legs","n":"Passage de kettlebell entre les jambes","ne":"Kettlebell Pass Between The Legs","e":"kettlebells","c":"strength","l":"intermediate","m":["abdominals"],"s":["glutes","hamstrings","shoulders"],"i":["Place une kettlebell entre tes jambes, pieds confortablement écartés. Penche-toi, fesses en arrière, dos plat.","Prends la kettlebell et passe-la à l'autre main entre les jambes, en dessinant un « W ». Fais plusieurs allers-retours."],"k":2},{"id":"Kettlebell_Pirate_Ships","n":"Bateaux pirates kettlebell","ne":"Kettlebell Pirate Ships","e":"kettlebells","c":"strength","l":"beginner","m":["shoulders"],"s":["abdominals"],"i":["Pieds écartés, tiens une kettlebell à deux mains, bras tendus, à hauteur de taille.","Tourne-toi d'un côté en balançant la kettlebell jusqu'à hauteur de tête. Courte pause en haut.","Laisse-la redescendre en tournant de l'autre côté, de nouveau jusqu'à hauteur de tête."],"k":2},{"id":"Kettlebell_Pistol_Squat","n":"Squat pistolet kettlebell","ne":"Kettlebell Pistol Squat","e":"kettlebells","c":"strength","l":"expert","m":["quadriceps"],"s":["calves","glutes","hamstrings","shoulders"],"i":["Tiens une kettlebell par les cornes à deux mains. Décolle une jambe du sol et squatte sur l'autre.","Descends en pliant le genou et en reculant les hanches, kettlebell tenue devant toi.","Tiens une seconde en bas puis remonte en poussant sur le talon, tête et poitrine hautes.","Redescends et recommence."],"k":2},{"id":"Kettlebell_Seated_Press","n":"Développé assis kettlebell","ne":"Kettlebell Seated Press","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["triceps"],"i":["Assis au sol, jambes confortablement écartées.","Monte une kettlebell à l'épaule.","Pousse-la au-dessus de la tête jusqu'à verrouiller le bras. Redescends."],"k":2},{"id":"Kettlebell_Seesaw_Press","n":"Développé en balançoire kettlebell","ne":"Kettlebell Seesaw Press","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["triceps"],"i":["Monte deux kettlebells aux épaules.","Pousse-en une au-dessus de la tête.","Redescends-la et pousse aussitôt l'autre. Même nombre de répétitions de chaque côté."],"k":2},{"id":"Kettlebell_Sumo_High_Pull","n":"Tirage haut sumo kettlebell","ne":"Kettlebell Sumo High Pull","e":"kettlebells","c":"strength","l":"intermediate","m":["traps"],"s":["adductors","glutes","hamstrings","quadriceps","shoulders"],"i":["Kettlebell au sol entre les pieds, pieds écartés, prise à deux mains. Hanches bien en arrière, genoux fléchis, poitrine et tête hautes : c'est la position de départ.","Tends hanches et genoux en tirant en même temps la kettlebell jusqu'aux épaules, coudes hauts. Redescends."],"k":2},{"id":"Kettlebell_Thruster","n":"Thruster kettlebell","ne":"Kettlebell Thruster","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["quadriceps","triceps"],"i":["Monte deux kettlebells aux épaules en poussant avec les jambes et les hanches, en tournant les poignets : c'est la position de départ.","Descends en squat entre tes jambes, dos droit, le plus bas possible.","En bas, remonte en poussant sur les talons et utilise l'élan pour pousser les kettlebells au-dessus de la tête, bras tendus.","Ramène les charges aux épaules pour la répétition suivante."],"k":2},{"id":"Kettlebell_Turkish_Get-Up_Lunge_style","n":"Relevé turc kettlebell (version fente)","ne":"Kettlebell Turkish Get-Up (Lunge style)","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["abdominals","hamstrings","quadriceps","triceps"],"i":["Allongé sur le dos, pousse une kettlebell à bras tendu au-dessus de toi. Plie le genou du même côté.","Bras toujours verrouillé, pivote vers l'autre côté et aide-toi de la main libre pour te redresser en position assise, puis sur un genou, en fente.","Regard sur la kettlebell, relève-toi lentement. Fais le chemin inverse jusqu'au sol."],"k":2},{"id":"Kettlebell_Turkish_Get-Up_Squat_style","n":"Relevé turc kettlebell (version squat)","ne":"Kettlebell Turkish Get-Up (Squat style)","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["abdominals","calves","hamstrings","quadriceps","triceps"],"i":["Allongé sur le dos, pousse une kettlebell à bras tendu au-dessus de toi. Plie le genou du même côté.","Bras toujours verrouillé, pivote vers l'autre côté en t'aidant de la main libre.","Pousse-toi en position assise puis sur tes pieds en passant par un squat. Regard sur la kettlebell, relève-toi lentement. Fais le chemin inverse."],"k":2},{"id":"Kettlebell_Windmill","n":"Moulin kettlebell","ne":"Kettlebell Windmill","e":"kettlebells","c":"strength","l":"intermediate","m":["abdominals"],"s":["glutes","hamstrings","shoulders","triceps"],"i":["Place une kettlebell devant le pied avant, puis monte-la à l'épaule et au-dessus de la tête avec le bras opposé, paume vers l'avant.","Bras toujours verrouillé, pousse les fesses du côté du bras levé, pieds tournés à 45°. Penche-toi depuis la hanche jusqu'à toucher le sol avec la main libre, regard toujours sur la kettlebell.","Marque une pause puis remonte."],"k":2},{"id":"Kipping_Muscle_Up","n":"Muscle-up avec élan","ne":"Kipping Muscle Up","e":"other","c":"strength","l":"intermediate","m":["lats"],"s":["abdominals","biceps","forearms","middle back","shoulders","traps","triceps"],"i":["Agrippe les anneaux en fausse prise (la base des paumes sur les anneaux).","Balance légèrement les jambes vers l'arrière.","Puis lance-les vers l'avant et le haut en rejetant menton et poitrine en arrière et en tirant des deux bras. En haut de la traction, ramène les anneaux aux aisselles en basculant les épaules vers l'avant, coudes vers l'arrière, pour passer en position de dips.","Avec contrôle, tends les coudes pour finir.","Redescends prudemment."],"k":2},{"id":"Knee_Across_The_Body","n":"Genou croisé devant le corps","ne":"Knee Across The Body","e":"other","c":"stretching","l":"beginner","m":["glutes"],"s":["abductors","lower back"],"i":["Allongé, jambe droite tendue. Plie la jambe gauche et fais-la passer en travers du corps, genou maintenu vers le sol avec la main droite (sans forcer s'il ne touche pas).","Bras gauche sur le côté, tourne la tête à gauche. Laisse le coccyx descendre vers le sol pendant que la poitrine part dans l'autre sens pour étirer le bas du dos. Change de côté."],"k":2},{"id":"Knee_Circles","n":"Cercles de genoux","ne":"Knee Circles","e":"body only","c":"stretching","l":"beginner","m":["calves"],"s":["hamstrings","quadriceps"],"i":["Debout, jambes serrées, mains à la taille.","Fais des cercles avec les genoux en respirant normalement."],"k":2},{"id":"Knee_Hip_Raise_On_Parallel_Bars","n":"Relevés de genoux aux barres parallèles","ne":"Knee/Hip Raise On Parallel Bars","e":"other","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Sur le banc de relevés de jambes, avant-bras posés sur les appuis, mains sur les poignées, bras à 90°.","Buste droit, bas du dos contre le dossier, jambes tendues vers le sol : c'est la position de départ.","En expirant, monte les jambes tendues jusqu'à ce qu'elles soient à peu près parallèles au sol. Tiens une seconde, sans élan.","Redescends lentement en inspirant."],"k":2},{"id":"Knee_Tuck_Jump","n":"Sauts genoux groupés","ne":"Knee Tuck Jump","e":"body only","c":"plyometrics","l":"beginner","m":["hamstrings"],"s":["abductors","adductors","calves","glutes","quadriceps"],"i":["Debout, genoux légèrement fléchis, mains devant toi à hauteur de poitrine, paumes vers le bas.","Fléchis rapidement les jambes puis saute explosivement en amenant les genoux vers les paumes.","Saute le plus haut possible puis réceptionne-toi jambes tendues qui se replient pour amortir."],"k":2},{"id":"Kneeling_Arm_Drill","n":"Mouvement de bras à genoux","ne":"Kneeling Arm Drill","e":"other","c":"plyometrics","l":"beginner","m":["shoulders"],"s":["abdominals"],"i":["Améliore l'efficacité des bras en course. À genoux, pied gauche devant, genou droit au sol, appui sur le talon avant pour activer fessiers et ischios.","Commence par de longs balancés de bras en pendule, puis ferme l'angle des bras comme en footing, puis en course, puis en sprint.","Dès que la main passe la hanche, accélère-la vers l'avant au maximum.","Change de genou."],"k":2},{"id":"Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists","n":"Crunch poulie à genoux avec rotations","ne":"Kneeling Cable Crunch With Alternating Oblique Twists","e":"cable","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Fixe une corde à une poulie haute et pose un tapis devant.","Prends la corde à deux mains et mets-toi à genoux à environ 60 cm de la machine.","Corde derrière la tête, mains près des oreilles.","Mains fixes, contracte les abdos et enroule-toi vers le bas jusqu'à ce que les coudes touchent les genoux.","Pause en bas puis remonte lentement.","Redescends ; à mi-chemin, tourne pour amener un coude vers le genou opposé.","Pause puis remonte lentement.","Recommence en tournant de l'autre côté.","Continue jusqu'à l'échec."],"k":2},{"id":"Kneeling_Cable_Triceps_Extension","n":"Extension triceps poulie à genoux","ne":"Kneeling Cable Triceps Extension","e":"cable","c":"strength","l":"intermediate","m":["triceps"],"s":[],"i":["Place un banc en travers devant une poulie haute.","Tiens la barre droite au-dessus de la tête, mains écartées d'environ 15 cm, paumes vers le bas.","Dos à la machine, mets-toi à genoux.","Pose la tête et l'arrière des bras sur le banc, coudes pliés, avant-bras vers la poulie : c'est la position de départ.","Bras près de la tête, coudes rentrés, pousse la barre en arc jusqu'à verrouiller les coudes, bras parallèles au sol. Serre fort une seconde en expirant.","Reviens lentement en inspirant."],"k":2},{"id":"Kneeling_Forearm_Stretch","n":"Étirement avant-bras à genoux","ne":"Kneeling Forearm Stretch","e":"other","c":"stretching","l":"beginner","m":["forearms"],"s":[],"i":["À genoux sur un tapis, paumes à plat, doigts pointés vers les genoux.","Penche-toi doucement en arrière, paumes toujours au sol, jusqu'à sentir l'étirement des poignets et des avant-bras. Tiens 20 à 30 s."],"k":2},{"id":"Kneeling_High_Pulley_Row","n":"Rowing poulie haute à genoux","ne":"Kneeling High Pulley Row","e":"cable","c":"strength","l":"beginner","m":["lats"],"s":["biceps","middle back"],"i":["Choisis la charge sur une poulie au-dessus de la tête, fixe une corde et mets-toi à genoux à 60 cm environ, corde tenue devant toi bras tendus.","Plie les coudes et serre les omoplates pour tirer la corde vers le haut de la poitrine, coudes écartés.","Après une courte pause, reviens lentement."],"k":2},{"id":"Kneeling_Hip_Flexor","n":"Étirement fléchisseurs de hanche à genoux","ne":"Kneeling Hip Flexor","e":"other","c":"stretching","l":"beginner","m":["quadriceps"],"s":["quadriceps"],"i":["À genoux sur un tapis, avance le pied droit à plat au sol et tends la jambe gauche derrière toi, dessus du pied au sol.","Avance ton poids jusqu'à sentir l'étirement de la hanche. Tiens 15 s puis change de côté."],"k":2},{"id":"Kneeling_Jump_Squat","n":"Squat sauté depuis les genoux","ne":"Kneeling Jump Squat","e":"barbell","c":"olympic weightlifting","l":"expert","m":["glutes"],"s":["calves","hamstrings","quadriceps"],"i":["À genoux au sol, barre sur le haut du dos (dans un rack pour la décrocher facilement) ou au poids du corps.","Assieds-toi en arrière jusqu'à ce que les fesses touchent les pieds, tête et poitrine hautes.","Pousse explosivement avec les hanches pour retomber pieds à plat au sol.","Enchaîne en te relevant en poussant sur les talons."],"k":2},{"id":"Kneeling_Single-Arm_High_Pulley_Row","n":"Rowing poulie haute un bras à genoux","ne":"Kneeling Single-Arm High Pulley Row","e":"cable","c":"strength","l":"beginner","m":["lats"],"s":["biceps","middle back"],"i":["Fixe une poignée à une poulie haute et choisis la charge.","À genoux face à la machine, tiens le câble d'une main, bras tendu : c'est la position de départ.","Paume vers l'avant, tire la poignée vers le buste en pliant le coude et en serrant l'omoplate, en tournant le poignet pour finir paume vers toi.","Après une courte pause, reviens."],"k":2},{"id":"Kneeling_Squat","n":"Squat à genoux","ne":"Kneeling Squat","e":"barbell","c":"powerlifting","l":"intermediate","m":["glutes"],"s":["abdominals","hamstrings","lower back"],"i":["Règle la barre à la bonne hauteur dans un rack. À genoux derrière (un tapis protège les genoux), glisse-toi dessous et pose-la sur le haut du dos, omoplates serrées. Décroche la barre.","Regard devant, assieds-toi en arrière jusqu'à toucher les mollets.","Redresse le buste."],"k":2},{"id":"Landmine_180s","n":"Landmine 180","ne":"Landmine 180's","e":"barbell","c":"strength","l":"beginner","m":["abdominals"],"s":["glutes","lower back","shoulders"],"i":["Place une barre dans un landmine (ou cale un bout dans un coin) et charge l'autre extrémité.","Monte la barre à hauteur d'épaules à deux mains, bras tendus devant toi, pieds écartés : c'est la position de départ.","Tourne buste et hanches pour amener la charge tout en bas d'un côté, bras toujours tendus.","Fais de même vers l'autre côté.","Continue en alternant."],"k":2},{"id":"Landmine_Linear_Jammer","n":"Landmine jammer","ne":"Landmine Linear Jammer","e":"barbell","c":"strength","l":"intermediate","m":["shoulders"],"s":["abdominals","calves","chest","hamstrings","quadriceps","triceps"],"i":["Place une barre dans un landmine (ou cale un bout dans un coin), charge-la et fixe la poignée.","Monte les poignées aux épaules : c'est la position de départ.","En position athlétique, descends en squat en reculant les hanches, bras fléchis.","Remonte explosivement en tendant hanches, genoux et chevilles tout en tendant les bras.","Reviens à la position de départ."],"k":2},{"id":"Lateral_Bound","n":"Bond latéral","ne":"Lateral Bound","e":"body only","c":"plyometrics","l":"beginner","m":["adductors"],"s":["abductors","calves","glutes","hamstrings","quadriceps"],"i":["En demi-squat, de profil par rapport au sens de déplacement.","Fais un léger contre-mouvement de la jambe avant vers l'intérieur en mettant le poids sur la jambe extérieure.","Pousse aussitôt pour bondir le plus loin possible sur le côté.","À la réception, repousse aussitôt dans l'autre sens.","Fais plusieurs allers-retours."],"k":2},{"id":"Lateral_Box_Jump","n":"Saut latéral sur box","ne":"Lateral Box Jump","e":"other","c":"plyometrics","l":"beginner","m":["adductors"],"s":["abductors","calves","glutes","hamstrings","quadriceps"],"i":["Debout, un box bas à côté de toi.","Fléchis vivement en quart de squat puis saute vers le haut et le côté.","Monte assez les genoux pour bien passer au-dessus du box.","Atterris au centre du box en amortissant.","Redescends prudemment de l'autre côté et fais plusieurs allers-retours."],"k":2},{"id":"Lateral_Cone_Hops","n":"Sauts latéraux de plots","ne":"Lateral Cone Hops","e":"other","c":"plyometrics","l":"beginner","m":["adductors"],"s":["abductors","calves","glutes","hamstrings","quadriceps"],"i":["Aligne plusieurs plots espacés d'un mètre environ.","Place-toi au bout, de profil par rapport au sens de déplacement.","Fléchis légèrement les genoux puis saute vers le haut et le côté par-dessus le plot.","Amortis à la réception et enchaîne aussitôt le saut suivant jusqu'au bout de la ligne."],"k":2},{"id":"Lateral_Raise_-_With_Bands","n":"Élévations latérales aux élastiques","ne":"Lateral Raise - With Bands","e":"bands","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Debout sur un élastique, tension dès bras tendus. Prends les poignées en pronation, mains un peu plus serrées que les épaules, contre les cuisses, coudes légèrement fléchis, dos droit.","Monte les poignées sur les côtés avec les épaules jusqu'à un peu au-dessus de l'horizontale, en expirant, en inclinant légèrement les mains comme pour verser de l'eau. Pause en haut.","Redescends lentement en inspirant."],"k":2},{"id":"Latissimus_Dorsi-SMR","n":"Auto-massage du grand dorsal","ne":"Latissimus Dorsi-SMR","e":"foam roll","c":"stretching","l":"beginner","m":["lats"],"s":[],"i":["Allongé au sol, rouleau de massage sous le dos, sur un côté, juste derrière l'aisselle.","Bras du côté étiré tendu derrière toi, mets ton poids sur le grand dorsal, buste décollé du sol. Tiens 10 à 30 s puis change de côté."],"k":2},{"id":"Leg-Over_Floor_Press","n":"Développé au sol jambe croisée","ne":"Leg-Over Floor Press","e":"kettlebells","c":"strength","l":"intermediate","m":["chest"],"s":["shoulders","triceps"],"i":["Allongé au sol, une kettlebell sur la poitrine tenue par la poignée. Passe la jambe du côté qui travaille par-dessus l'autre ; l'autre bras sur le côté pour l'équilibre.","Pousse la kettlebell jusqu'à verrouiller le bras.","Redescends jusqu'à ce que le coude touche le sol, kettlebell au-dessus du coude."],"k":2},{"id":"Leg-Up_Hamstring_Stretch","n":"Étirement ischios jambe levée","ne":"Leg-Up Hamstring Stretch","e":"other","c":"stretching","l":"beginner","m":["hamstrings"],"s":[],"i":["Allongé sur le dos, un genou plié, pied à plat au sol pour stabiliser le dos.","Lève l'autre jambe ; si tu es raide, elle ne se tendra pas complètement, ce n'est pas grave. Plante du pied vers le plafond.","Tends la jambe au maximum puis tire-la vers ton nez. Change de côté."],"k":2},{"id":"Leg_Extensions","n":"Leg extension","ne":"Leg Extensions","e":"machine","c":"strength","l":"beginner","m":["quadriceps"],"s":[],"i":["Choisis la charge sur la machine à leg extension, assieds-toi, jambes sous l'appui (au-dessus des pieds), mains sur les poignées. Genoux à 90° au départ, pas moins.","Tends les jambes au maximum avec les quadriceps, en expirant ; le reste du corps ne bouge pas. Pause d'une seconde.","Redescends lentement en inspirant, sans dépasser 90°."],"k":2},{"id":"Leg_Lift","n":"Lever de jambe","ne":"Leg Lift","e":"body only","c":"strength","l":"beginner","m":["glutes"],"s":["hamstrings"],"i":["Debout, pieds largeur d'épaules, tiens-toi à un appui stable.","Avec ou sans lest à la cheville, plie une jambe vers l'arrière comme un leg curl debout, l'autre jambe tendue, en expirant.","Redescends lentement en inspirant.","Fais de même avec l'autre jambe."],"k":2},{"id":"Leg_Press","n":"Presse à cuisses","ne":"Leg Press","e":"machine","c":"strength","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Assieds-toi sur la presse, pieds largeur d'épaules sur la plateforme.","Déverrouille les sécurités et pousse jusqu'à jambes tendues, sans verrouiller les genoux ; buste et jambes à 90° : c'est la position de départ.","En inspirant, descends lentement jusqu'à 90° aux genoux.","Remonte en poussant surtout sur les talons, en expirant.","À la fin, reverrouille bien les sécurités."],"k":2},{"id":"Leg_Pull-In","n":"Genoux à la poitrine","ne":"Leg Pull-In","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur un tapis, jambes tendues, mains au sol à côté de toi ou sous les fesses : c'est la position de départ.","Plie les genoux et ramène les cuisses vers le ventre en expirant, jusqu'à ce que les genoux arrivent vers la poitrine ; tibias parallèles au sol. Contracte les abdos une seconde.","Reviens en inspirant."],"k":2},{"id":"Leverage_Chest_Press","n":"Développé pectoraux à la machine guidée","ne":"Leverage Chest Press","e":"machine","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Charge la machine et règle le siège : poignées au niveau du bas ou du milieu des pectoraux.","Poitrine et tête hautes, omoplates serrées : c'est la position de départ.","Pousse les poignées vers l'avant en tendant les coudes.","Après une courte pause, reviens juste avant la butée pour garder la tension jusqu'à la fin de la série."],"k":2},{"id":"Leverage_Deadlift","n":"Soulevé de terre à la machine guidée","ne":"Leverage Deadlift","e":"machine","c":"strength","l":"beginner","m":["quadriceps"],"s":["glutes","hamstrings"],"i":["Charge la machine et place-toi entre les poignées. Saisis les poignées du bas, descends les hanches en inspirant, regard devant, poitrine haute : c'est la position de départ.","Pousse sur les talons pour te redresser en tendant hanches et genoux, puis redescends la charge."],"k":2},{"id":"Leverage_Decline_Chest_Press","n":"Développé décliné à la machine guidée","ne":"Leverage Decline Chest Press","e":"machine","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Charge la machine et règle le siège : poignées au niveau du bas des pectoraux. Poitrine et tête hautes, omoplates serrées : c'est la position de départ.","Pousse les poignées vers l'avant en tendant les coudes.","Après une courte pause, reviens juste avant la butée pour garder la tension."],"k":2},{"id":"Leverage_High_Row","n":"Rowing haut à la machine guidée","ne":"Leverage High Row","e":"machine","c":"strength","l":"beginner","m":["middle back"],"s":["lats"],"i":["Charge la machine et règle le siège pour atteindre tout juste les poignées au-dessus de toi ; cale les genoux sous l'appui. Prise en pronation : c'est la position de départ.","Tire les poignées vers le buste en serrant les omoplates.","Pause en bas puis remonte lentement.","Ne repose pas complètement la charge entre les répétitions."],"k":2},{"id":"Leverage_Incline_Chest_Press","n":"Développé incliné à la machine guidée","ne":"Leverage Incline Chest Press","e":"machine","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Charge la machine et règle le siège : poignées au niveau du haut des pectoraux. Poitrine et tête hautes, omoplates serrées : c'est la position de départ.","Pousse les poignées en tendant les coudes.","Après une courte pause, reviens juste avant la butée pour garder la tension."],"k":2},{"id":"Leverage_Iso_Row","n":"Rowing iso à la machine guidée","ne":"Leverage Iso Row","e":"machine","c":"strength","l":"beginner","m":["lats"],"s":["biceps","middle back"],"i":["Charge la machine et règle le siège : poignées à hauteur de poitrine. Prise neutre ou pronation : c'est la position de départ.","Tire les poignées vers le buste en serrant les omoplates.","Pause puis reviens lentement, sans reposer complètement la charge entre les répétitions."],"k":2},{"id":"Leverage_Shoulder_Press","n":"Développé épaules à la machine guidée","ne":"Leverage Shoulder Press","e":"machine","c":"strength","l":"beginner","m":["shoulders"],"s":["triceps"],"i":["Charge la machine et règle le siège : poignées au niveau du haut des épaules. Poitrine et tête hautes, prise en pronation : c'est la position de départ.","Pousse les poignées vers le haut en tendant les coudes.","Après une courte pause, reviens juste avant la butée pour garder la tension."],"k":2},{"id":"Leverage_Shrug","n":"Shrug à la machine guidée","ne":"Leverage Shrug","e":"machine","c":"strength","l":"beginner","m":["traps"],"s":["forearms"],"i":["Charge la machine et place-toi entre les poignées.","Saisis les poignées du haut, descends les hanches en inspirant, regard devant, poitrine haute.","Pousse sur les talons pour te redresser, bras tendus, épaules en arrière : c'est la position de départ.","Monte les épaules vers les oreilles, bien verticalement.","Pause en haut puis redescends."],"k":2},{"id":"Linear_3-Part_Start_Technique","n":"Technique de départ en 3 temps","ne":"Linear 3-Part Start Technique","e":"other","c":"plyometrics","l":"beginner","m":["hamstrings"],"s":["calves","quadriceps"],"i":["Apprend à accélérer depuis l'arrêt. Pars d'une ligne : pointe du pied gauche à côté de la cheville droite, pied droit 10-15 cm derrière.","Main droite sur la ligne, nez près du genou gauche.","Fléchis en te penchant, tête plus basse que les hanches, poids sur la jambe gauche : c'est la position de départ.","Monte la main gauche parallèle au sol vers l'arrière et pars explosivement quand tu es prêt."],"k":2},{"id":"Linear_Acceleration_Wall_Drill","n":"Exercice d'accélération au mur","ne":"Linear Acceleration Wall Drill","e":"other","c":"plyometrics","l":"beginner","m":["hamstrings"],"s":["calves","glutes","quadriceps"],"i":["Penche-toi à environ 45° contre un mur, pieds joints, fessiers contractés.","Monte vivement le genou droit, pause, puis frappe le sol droit vers le bas.","Fais de même avec l'autre genou.","Encore une fois à droite, puis dès que le pied touche le sol, enchaîne le plus vite possible en alternant gauche et droite."],"k":2},{"id":"Linear_Depth_Jump","n":"Saut en contrebas linéaire","ne":"Linear Depth Jump","e":"other","c":"plyometrics","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Il faut deux box ou bancs espacés d'un mètre environ. Debout sur l'un, face à l'autre.","Laisse-toi tomber doucement au sol entre les deux, hanches et genoux fléchis.","Rebondis explosivement en tendant hanches, genoux et chevilles pour sauter sur l'autre box.","Réceptionne-toi en douceur en amortissant avec les jambes."],"k":2},{"id":"Log_Lift","n":"Développé au tronc (log lift)","ne":"Log Lift","e":"other","c":"strongman","l":"intermediate","m":["shoulders"],"s":["abdominals","chest","glutes","hamstrings","lower back","middle back","quadriceps","traps","triceps"],"i":["Debout, le tronc (log) devant toi. Saisis les poignées et monte-le contre ta poitrine le plus haut possible, puis tends hanches et genoux pour finir l'épaulé.","Tête en arrière, regard vers le haut, pose le tronc sur ta poitrine. Fléchis légèrement les genoux puis repousse pour lancer le tronc vers le haut, et tends les bras au-dessus de la tête en passant la tête dessous.","Fais un maximum de répétitions en contrôlant la descente."],"k":2},{"id":"London_Bridges","n":"Ponts de Londres (corde)","ne":"London Bridges","e":"other","c":"strength","l":"intermediate","m":["lats"],"s":["biceps","forearms","middle back"],"i":["Accroche une corde d'escalade à une poutre haute. Dessous, verrouille la barre d'une Smith machine avec les sécurités (ou utilise un box solide).","Debout sur la barre, tiens la corde pour l'équilibre : c'est la position de départ.","Corps droit, penche-toi en arrière en descendant main après main le long de la corde jusqu'à être perpendiculaire au sol.","Corps droit, remonte main après main jusqu'au départ."],"k":2},{"id":"Looking_At_Ceiling","n":"Regard au plafond (étirement)","ne":"Looking At Ceiling","e":"other","c":"stretching","l":"beginner","m":["quadriceps"],"s":[],"i":["À genoux, mains sur les talons.","Avance et monte les fesses en rejetant la tête en arrière pour regarder le plafond, dos cambré."],"k":2},{"id":"Low_Cable_Crossover","n":"Écarté poulie basse vis-à-vis","ne":"Low Cable Crossover","e":"cable","c":"strength","l":"beginner","m":["chest"],"s":["shoulders"],"i":["Place les poulies en bas, choisis la charge et prends une poignée dans chaque main.","Avance pour mettre les câbles en tension, paumes vers l'avant, mains sous la taille, bras tendus.","Bras légèrement fléchis, monte les mains vers le centre jusqu'à ce qu'elles se rejoignent devant la poitrine, paumes vers le haut.","Après une courte pause, reviens."],"k":2},{"id":"Low_Cable_Triceps_Extension","n":"Extension triceps poulie basse","ne":"Low Cable Triceps Extension","e":"cable","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Choisis la charge et allonge-toi sur le dos sur le banc du tirage horizontal muni d'une corde, tête vers la poulie.","Attrape l'extérieur de la corde, paumes face à face.","Coudes pliés à 90°, bras verticaux, coudes rentrés, avant-bras vers la poulie : c'est la position de départ.","En expirant, tends les avant-bras jusqu'à la verticale ; bras et coudes immobiles. Serre fort une seconde.","Reviens lentement en inspirant."],"k":2},{"id":"Low_Pulley_Row_To_Neck","n":"Rowing poulie basse vers le cou","ne":"Low Pulley Row To Neck","e":"cable","c":"strength","l":"beginner","m":["shoulders"],"s":["biceps","middle back","traps"],"i":["Assis au tirage horizontal avec une corde.","Prends la corde en pronation, dos droit presque vertical, genoux légèrement fléchis, bras tendus : c'est la position de départ.","Buste immobile, monte les coudes et tire la corde vers le cou en expirant, bras parallèles au sol, jusqu'à ce que les mains soient près des oreilles, coudes écartés.","Tiens environ une seconde puis reviens lentement en inspirant, sans bouger le buste."],"k":2},{"id":"Lower_Back-SMR","n":"Auto-massage du bas du dos","ne":"Lower Back-SMR","e":"foam roll","c":"stretching","l":"beginner","m":["lower back"],"s":[],"i":["Assis, rouleau de massage sous le bas du dos, bras croisés devant toi, épaules en avant.","Décolle les hanches et penche-toi en arrière, poids sur le bas du dos ; décale-toi légèrement d'un côté pour masser les muscles à côté de la colonne. Roule en restant 10 à 30 s sur les points sensibles. Fais l'autre côté."],"k":2},{"id":"Lower_Back_Curl","n":"Enroulement du bas du dos","ne":"Lower Back Curl","e":"body only","c":"stretching","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur le ventre, bras écartés sur les côtés.","Avec les muscles du bas du dos, décolle la poitrine du sol sans pousser avec les bras, tête haute. 10 à 20 répétitions."],"k":2},{"id":"Lunge_Pass_Through","n":"Fente avec passage de charge","ne":"Lunge Pass Through","e":"kettlebells","c":"strength","l":"intermediate","m":["hamstrings"],"s":["calves","glutes","quadriceps"],"i":["Debout, buste droit, kettlebell dans la main droite.","Fais un pas en avant du pied gauche et descends, buste droit, jusqu'à ce que le genou arrière frôle le sol.","Pendant la fente, passe la kettlebell sous la jambe avant à l'autre main.","Reviens en poussant sur le talon.","Continue en alternant les jambes."],"k":2},{"id":"Lunge_Sprint","n":"Fentes sprint","ne":"Lunge Sprint","e":"machine","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Règle une barre de Smith machine à la bonne hauteur, passe dessous et pose-la sur le haut du dos. Décroche-la et place les pieds en fente, un devant, un derrière.","Descends le genou arrière presque au sol.","En bas, remonte aussitôt explosivement en poussant sur le talon avant, saute et inverse les jambes."],"k":2},{"id":"Lying_Bent_Leg_Groin","n":"Étirement aine allongé jambes fléchies","ne":"Lying Bent Leg Groin","e":"other","c":"stretching","l":"expert","m":["adductors"],"s":[],"i":["Allongé sur le dos, genoux pliés, plantes des pieds jointes ; ton partenaire tient tes genoux.","Essaie de serrer les genoux pendant qu'il t'en empêche.","Après 10 à 20 s, relâche pendant qu'il pousse doucement tes genoux vers le sol. Préviens-le dès que l'étirement est suffisant."],"k":2},{"id":"Lying_Cable_Curl","n":"Curl allongé à la poulie","ne":"Lying Cable Curl","e":"cable","c":"strength","l":"intermediate","m":["biceps"],"s":[],"i":["Prends la barre (droite ou EZ) d'une poulie basse en supination, largeur d'épaules.","Allongé sur le dos sur un tapis devant la machine, pieds contre le châssis, jambes tendues.","Bras tendus, coudes près du corps, légèrement fléchis : c'est la position de départ.","Bras fixes, monte lentement la barre vers la poitrine en serrant les biceps, en expirant.","Après une seconde, reviens lentement."],"k":2},{"id":"Lying_Cambered_Barbell_Row","n":"Rowing allongé barre cambrée","ne":"Lying Cambered Barbell Row","e":"barbell","c":"strength","l":"beginner","m":["middle back"],"s":["biceps","lats","traps"],"i":["Place une barre cambrée sous un banc.","Allongé à plat ventre sur le banc, prends-la en pronation, plus large que les épaules : c'est la position de départ.","En expirant, tire la barre, coudes près du corps, vers la poitrine (haut du dos) ou vers le ventre (grand dorsal).","Après une seconde en haut, redescends lentement en inspirant."],"k":2},{"id":"Lying_Close-Grip_Bar_Curl_On_High_Pulley","n":"Curl barre prise serrée allongé poulie haute","ne":"Lying Close-Grip Bar Curl On High Pulley","e":"cable","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Place un banc plat devant une poulie haute.","Prends la barre droite en supination, largeur d'épaules.","Allonge-toi sur le dos, tête au bout du banc.","Tends les bras au-dessus des épaules, à 90° du buste, coudes rentrés : c'est la position de départ.","En expirant, ramène la barre en arc jusqu'au menton. Serre les biceps une seconde ; seuls les avant-bras bougent.","Reviens lentement."],"k":2},{"id":"Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head","n":"Extension triceps barre prise serrée derrière la tête","ne":"Lying Close-Grip Barbell Triceps Extension Behind The Head","e":"barbell","c":"strength","l":"intermediate","m":["triceps"],"s":[],"i":["Barre ou barre EZ en pronation (largeur d'épaules ou poignées intérieures), allonge-toi sur un banc plat, tête près du bout.","Bras tendus, amène la barre en arc au-dessus de la tête jusqu'à ce que les bras soient parallèles au sol, coudes rentrés : c'est la position de départ.","En inspirant, plie les coudes, bras fixes, jusqu'à ce que les avant-bras soient verticaux.","En expirant, remonte la barre en arc jusqu'à ce que les avant-bras soient aussi parallèles au sol. Serre les triceps une seconde."],"k":2},{"id":"Lying_Close-Grip_Barbell_Triceps_Press_To_Chin","n":"Développé triceps barre prise serrée vers le menton","ne":"Lying Close-Grip Barbell Triceps Press To Chin","e":"e-z curl bar","c":"strength","l":"intermediate","m":["triceps"],"s":[],"i":["Barre ou barre EZ en pronation, allonge-toi sur un banc plat, tête dépassant du bout.","Bras tendus au-dessus de la poitrine, perpendiculaires au buste : c'est la position de départ.","En inspirant, plie les coudes en arc, bras fixes et coudes rentrés, jusqu'à effleurer le menton.","En expirant, remonte la barre en arc. Serre les triceps une seconde ; seuls les avant-bras bougent."],"k":2},{"id":"Lying_Crossover","n":"Écarté croisé allongé","ne":"Lying Crossover","e":"body only","c":"stretching","l":"expert","m":["abductors"],"s":[],"i":["Allongé sur le dos, jambes tendues.","Croise une jambe genou plié par-dessus le corps, en essayant de poser le genou au sol. Ton partenaire, à genoux à côté, tient ton épaule au sol et contrôle la jambe croisée.","Essaie de soulever le genou pendant qu'il t'en empêche.","Après 10 à 20 s, relâche pendant qu'il pousse doucement le genou vers le sol. Change de côté."],"k":2},{"id":"Lying_Dumbbell_Tricep_Extension","n":"Extension triceps allongé haltère","ne":"Lying Dumbbell Tricep Extension","e":"dumbbell","c":"strength","l":"intermediate","m":["triceps"],"s":["chest","shoulders"],"i":["Allongé sur un banc plat, deux haltères tenus devant toi, bras tendus à 90° du buste, paumes face à face, coudes rentrés.","En inspirant, bras fixes, descends lentement les haltères près des oreilles.","Remonte avec les triceps en expirant."],"k":2},{"id":"Lying_Face_Down_Plate_Neck_Resistance","n":"Résistance du cou avec disque à plat ventre","ne":"Lying Face Down Plate Neck Resistance","e":"other","c":"strength","l":"intermediate","m":["neck"],"s":[],"i":["Allongé à plat ventre sur un banc plat, épaules dépassant légèrement du bout (haut de la poitrine, cou et tête dans le vide), disque tenu derrière la tête.","Disque bien tenu, baisse lentement la tête (comme pour dire « oui ») en inspirant.","Remonte la tête en arc en expirant. Tiens une seconde."],"k":2},{"id":"Lying_Face_Up_Plate_Neck_Resistance","n":"Résistance du cou avec disque sur le dos","ne":"Lying Face Up Plate Neck Resistance","e":"other","c":"strength","l":"intermediate","m":["neck"],"s":[],"i":["Allongé sur le dos sur un banc plat, épaules dépassant légèrement du bout (cou et tête dans le vide), disque posé sur le front.","Disque bien tenu, laisse lentement la tête descendre en arrière en inspirant.","Remonte la tête en expirant. Tiens une seconde."],"k":2},{"id":"Lying_Glute","n":"Étirement fessier allongé","ne":"Lying Glute","e":"body only","c":"stretching","l":"expert","m":["glutes"],"s":["abductors"],"i":["Allongé sur le dos, ton partenaire à genoux à côté.","Monte une jambe et tourne-la pour que le pied passe au-dessus de la hanche opposée, tibia perpendiculaire au corps ; ton partenaire tient genou et cheville.","Pousse la jambe vers lui pendant qu'il t'en empêche.","Après 10 à 20 s, relâche complètement pendant qu'il pousse doucement cheville et genou vers ta poitrine. Préviens-le dès que c'est suffisant."],"k":2},{"id":"Lying_Hamstring","n":"Étirement ischios allongé","ne":"Lying Hamstring","e":"other","c":"stretching","l":"expert","m":["hamstrings"],"s":["calves"],"i":["Allongé sur le dos, jambes tendues, ton partenaire à genoux à côté. Monte une jambe vers le plafond ; il tient ta cheville (ou la cale sur son épaule).","Essaie de plier le genou en contractant les ischios pendant 10 à 20 s.","Relâche et laisse-le pousser doucement la jambe vers ta tête. Préviens-le dès que c'est suffisant. Change de côté."],"k":2},{"id":"Lying_High_Bench_Barbell_Curl","n":"Curl barre allongé sur banc haut","ne":"Lying High Bench Barbell Curl","e":"barbell","c":"strength","l":"intermediate","m":["biceps"],"s":[],"i":["Allongé à plat ventre sur un banc haut, barre en supination (largeur d'épaules ou poignées intérieures d'une EZ), haut de la poitrine au bout du banc, barre pendante bras tendus : c'est la position de départ.","Coudes rentrés, bras fixes, monte la barre en arc en contractant les biceps, en expirant. Tiens une seconde.","Redescends lentement en inspirant, sans balancer."],"k":2},{"id":"Lying_Leg_Curls","n":"Leg curl allongé","ne":"Lying Leg Curls","e":"machine","c":"strength","l":"beginner","m":["hamstrings"],"s":[],"i":["Règle la machine à ta taille et allonge-toi à plat ventre, boudin quelques centimètres sous les mollets (une machine inclinée est préférable).","Buste à plat, jambes tendues, mains sur les poignées : c'est la position de départ.","En expirant, ramène les jambes le plus haut possible sans décoller les cuisses. Tiens une seconde.","Redescends en inspirant."],"k":2},{"id":"Lying_Machine_Squat","n":"Squat allongé à la machine","ne":"Lying Machine Squat","e":"machine","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Règle la machine pour y entrer genoux pliés, cuisses légèrement sous la parallèle.","Charge et installe-toi sur le dos, dos et tête contre la machine, épaules sous les appuis ; genoux pas au-delà des orteils.","Mains sur les poignées, pieds largeur d'épaules, pointes légèrement ouvertes : c'est la position de départ.","Pousse avec l'avant des pieds pour te tendre complètement en expirant. Tiens une seconde (tu peux t'aider des mains sur les cuisses à la première répétition).","Redescends lentement en inspirant, mais arrête-toi à cuisses parallèles (90°)."],"k":2},{"id":"Lying_One-Arm_Lateral_Raise","n":"Élévation latérale un bras allongé","ne":"Lying One-Arm Lateral Raise","e":"dumbbell","c":"strength","l":"intermediate","m":["shoulders"],"s":[],"i":["Un haltère dans une main, allonge-toi à plat ventre sur un banc plat ; l'autre main tient le pied du banc.","Paume vers toi, bras tendu, coude légèrement fléchi : c'est la position de départ.","Monte le bras sur le côté jusqu'à hauteur d'épaule, en expirant. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Lying_Prone_Quadriceps","n":"Étirement quadriceps à plat ventre","ne":"Lying Prone Quadriceps","e":"body only","c":"stretching","l":"expert","m":["quadriceps"],"s":[],"i":["À plat ventre, ton partenaire à genoux à côté. Plie un genou pour amener le pied vers les fesses ; il tient genou et cheville.","Essaie de tendre le genou pendant qu'il t'en empêche.","Après 10 à 20 s, relâche pendant qu'il pousse doucement le pied vers tes fesses.","Après 10 à 20 s, change de côté."],"k":2},{"id":"Lying_Rear_Delt_Raise","n":"Oiseau allongé","ne":"Lying Rear Delt Raise","e":"dumbbell","c":"strength","l":"intermediate","m":["shoulders"],"s":[],"i":["Un haltère dans chaque main, allonge-toi à plat ventre sur un banc plat.","Paumes vers toi, bras tendus, coudes légèrement fléchis : c'est la position de départ.","Monte les bras sur les côtés jusqu'à hauteur d'épaules, en expirant. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Lying_Supine_Dumbbell_Curl","n":"Curl haltères allongé sur le dos","ne":"Lying Supine Dumbbell Curl","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Allongé sur le dos sur un banc plat, un haltère dans chaque main sur les cuisses.","Amène les haltères sur les côtés, bras tendus, paumes vers les cuisses.","Bras près du corps, coudes rentrés, descends les bras le plus bas possible vers le sol puis bloque-les : c'est la position de départ.","En expirant, monte les haltères en tournant les paumes vers le haut, jusqu'à contraction complète. Serre fort une seconde ; seuls les avant-bras bougent.","Redescends très lentement."],"k":2},{"id":"Lying_T-Bar_Row","n":"Rowing T-bar allongé","ne":"Lying T-Bar Row","e":"machine","c":"strength","l":"intermediate","m":["middle back"],"s":["biceps","lats"],"i":["Charge la machine de rowing T-bar et règle-la pour que le haut de ta poitrine soit au bord de l'appui.","Allonge-toi à plat ventre et prends les poignées (pronation, supination ou neutre selon la zone du dos visée).","Décroche la barre, bras tendus : c'est la position de départ.","En expirant, tire lentement en serrant le dos, bras près du corps, sans décoller de l'appui.","Après une seconde, redescends lentement en inspirant."],"k":2},{"id":"Lying_Triceps_Press","n":"Barre au front (développé triceps allongé)","ne":"Lying Triceps Press","e":"e-z curl bar","c":"strength","l":"intermediate","m":["triceps"],"s":[],"i":["Allongé sur un banc plat, une barre EZ ou droite posée au sol derrière ta tête, pieds au sol.","Prends la barre en pronation, prise moyenne, et monte-la bras tendus, verticaux, coudes rentrés : c'est la position de départ.","En inspirant, descends lentement la barre jusqu'à effleurer le front, bras et coudes immobiles.","Remonte avec les triceps en expirant."],"k":2},{"id":"Machine_Bench_Press","n":"Développé couché à la machine","ne":"Machine Bench Press","e":"machine","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Assieds-toi sur la machine et choisis la charge.","Appuie sur le levier pour avancer les poignées, attrape-les et tends les bras.","Prise en pronation, coudes montés pour que les bras soient parallèles au sol : c'est la position de départ.","Ramène les poignées vers toi en inspirant.","Repousse-les en contractant les pectoraux, en expirant. Tiens une seconde.","À la fin, appuie sur le levier pour reposer les poignées doucement."],"k":2},{"id":"Machine_Bicep_Curl","n":"Curl biceps à la machine","ne":"Machine Bicep Curl","e":"machine","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Règle le siège et choisis la charge. Bras posés contre les appuis, mains sur les poignées : c'est la position de départ.","Plie les coudes pour ramener l'avant-bras vers le bras.","Pause en haut puis redescends lentement.","Ne repose pas la charge jusqu'en butée avant la fin de la série."],"k":2},{"id":"Machine_Preacher_Curls","n":"Curl pupitre à la machine","ne":"Machine Preacher Curls","e":"machine","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Assieds-toi sur la machine à curl pupitre et choisis la charge.","Pose l'arrière des bras sur l'appui, coudes rentrés, et prends les poignées en supination : c'est la position de départ.","Monte les poignées en contractant les biceps, en expirant. Tiens une seconde ; bras toujours sur l'appui.","Redescends lentement en inspirant."],"k":2},{"id":"Machine_Shoulder_Military_Press","n":"Développé militaire à la machine","ne":"Machine Shoulder (Military) Press","e":"machine","c":"strength","l":"beginner","m":["shoulders"],"s":["triceps"],"i":["Assieds-toi sur la machine de développé épaules et choisis la charge.","Prends les poignées sur les côtés, coudes pliés dans l'alignement du buste : c'est la position de départ.","Pousse les poignées jusqu'à bras tendus en expirant. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Machine_Triceps_Extension","n":"Extension triceps à la machine","ne":"Machine Triceps Extension","e":"machine","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Règle le siège et choisis la charge. Bras posés contre les appuis, mains sur les poignées : c'est la position de départ.","Tends les coudes pour éloigner l'avant-bras du bras.","Pause en fin de mouvement puis reviens lentement.","Ne repose pas la charge jusqu'en butée avant la fin de la série."],"k":2},{"id":"Medicine_Ball_Chest_Pass","n":"Passe poitrine médecine-ball","ne":"Medicine Ball Chest Pass","e":"medicine ball","c":"plyometrics","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["À faire avec un partenaire, sinon contre un mur.","Face à lui, médecine-ball tenu à deux mains devant le buste.","Ramène le ballon à la poitrine puis lance-le en tendant les bras (tu peux faire un pas en lançant).","Ton partenaire le rattrape et te le renvoie.","Réceptionne-le à deux mains à hauteur de poitrine."],"k":2},{"id":"Medicine_Ball_Full_Twist","n":"Rotation complète médecine-ball","ne":"Medicine Ball Full Twist","e":"medicine ball","c":"plyometrics","l":"beginner","m":["abdominals"],"s":["shoulders"],"i":["Il faut un médecine-ball et un partenaire. Dos à dos, à 60-90 cm l'un de l'autre.","Ballon devant le buste, ouvre les hanches et tourne les épaules en même temps que ton partenaire.","Tournez tous les deux dans le même sens pour une rotation complète.","Passe-lui le ballon, puis tournez dans l'autre sens."],"k":2},{"id":"Medicine_Ball_Scoop_Throw","n":"Lancer en cuillère médecine-ball","ne":"Medicine Ball Scoop Throw","e":"medicine ball","c":"plyometrics","l":"beginner","m":["shoulders"],"s":["abdominals","hamstrings","quadriceps"],"i":["En demi-squat, médecine-ball en main, bras pendants, ballon près des pieds.","Projette les hanches vers l'avant en tendant les jambes et saute.","Balance en même temps les bras tendus au-dessus de la tête et lâche le ballon au point haut pour l'envoyer le plus loin possible derrière toi."],"k":2},{"id":"Middle_Back_Shrug","n":"Shrug milieu du dos","ne":"Middle Back Shrug","e":"dumbbell","c":"strength","l":"intermediate","m":["middle back"],"s":[],"i":["Allongé à plat ventre sur un banc incliné, un haltère dans chaque main, bras pendants, paumes face à face.","En expirant, serre les omoplates et tiens une seconde complète (comme l'inverse d'un câlin).","Reviens en inspirant."],"k":2},{"id":"Middle_Back_Stretch","n":"Étirement milieu du dos","ne":"Middle Back Stretch","e":"other","c":"stretching","l":"beginner","m":["middle back"],"s":["abdominals","lats","lower back"],"i":["Debout, pieds largeur d'épaules, mains sur les hanches.","Tourne-toi à la taille jusqu'à sentir l'étirement. Tiens 10 à 15 s puis tourne de l'autre côté."],"k":2},{"id":"Mixed_Grip_Chin","n":"Traction prise mixte","ne":"Mixed Grip Chin","e":"other","c":"strength","l":"expert","m":["middle back"],"s":["biceps","lats"],"i":["Mains environ 2-3 cm plus larges que les épaules, prends la barre une paume vers l'avant, l'autre vers toi.","Tire-toi vers le haut en expirant : côté supination, coude près du corps ; côté pronation, coude écarté dans l'alignement du buste.","Après une seconde en haut, redescends lentement en inspirant.","À la série suivante, inverse les prises."],"k":2},{"id":"Monster_Walk","n":"Marche du monstre (élastique)","ne":"Monster Walk","e":"bands","c":"strength","l":"beginner","m":["abductors"],"s":[],"i":["Place un élastique autour des chevilles et un autour des genoux, tendus quand les pieds sont écartés largeur d'épaules.","Avance à petits pas en alternant les pieds.","Après quelques pas, recule de la même façon jusqu'au départ."],"k":2},{"id":"Mountain_Climbers","n":"Mountain climbers","ne":"Mountain Climbers","e":"other","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["chest","hamstrings","shoulders"],"i":["En position de pompe, appui sur les mains et les orteils. Ramène un genou sous la hanche : c'est la position de départ.","Inverse explosivement les jambes : tends la jambe pliée en appui sur les orteils et ramène l'autre genou. Alterne pendant 20 à 30 s."],"k":2},{"id":"Moving_Claw_Series","n":"Série griffes en mouvement","ne":"Moving Claw Series","e":"other","c":"plyometrics","l":"beginner","m":["hamstrings"],"s":["calves","quadriceps"],"i":["Prépare ta foulée de sprint. En courant, plie le genou en cherchant à toucher les fesses avec le talon quand la hanche s'étend.","Recharge le quadriceps en ramenant la jambe vers l'avant pour attaquer le sol au pas suivant.","Bras actifs, en coups rapides « 1-2 »."],"k":2},{"id":"Muscle_Snatch","n":"Arraché en force musculaire","ne":"Muscle Snatch","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["hamstrings"],"s":["glutes","lower back","quadriceps","shoulders","triceps"],"i":["Barre chargée tenue à mi-cuisse en prise large, pieds sous les hanches légèrement ouverts. Hanches basses, poitrine haute, regard devant, épaules juste devant la barre.","Pousse sur l'avant des talons pour monter la barre, puis tends explosivement hanches, genoux et chevilles, barre près du corps.","Continue à monter la barre jusqu'au-dessus de la tête sans replier les genoux."],"k":2},{"id":"Muscle_Up","n":"Muscle-up","ne":"Muscle Up","e":"other","c":"strength","l":"intermediate","m":["lats"],"s":["abdominals","biceps","forearms","middle back","shoulders","traps","triceps"],"i":["Agrippe les anneaux en fausse prise. Commence une traction en tirant les coudes vers les côtés.","En haut de la traction, ramène les anneaux aux aisselles en basculant les épaules vers l'avant, coudes vers l'arrière, pour passer en position de dips.","Avec contrôle, tends les coudes pour finir.","Redescends prudemment."],"k":2},{"id":"Narrow_Stance_Hack_Squats","n":"Hack squat pieds serrés","ne":"Narrow Stance Hack Squats","e":"machine","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Dos contre le dossier du hack squat, épaules sous les appuis.","Pieds serrés (moins de 8 cm d'écart), pointes légèrement ouvertes, tête haute, dos plaqué.","Mains sur les poignées, déverrouille les sécurités.","Tends les jambes sans verrouiller les genoux : c'est la position de départ.","Descends lentement jusqu'à un angle un peu inférieur à 90° aux genoux, en inspirant.","Remonte en expirant en poussant surtout sur les talons."],"k":2},{"id":"Narrow_Stance_Leg_Press","n":"Presse à cuisses pieds serrés","ne":"Narrow Stance Leg Press","e":"machine","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Assis sur la presse, pieds serrés (moins de 8 cm d'écart), pointes légèrement ouvertes, dos plaqué.","Déverrouille les sécurités et pousse jusqu'à jambes tendues, sans verrouiller les genoux : c'est la position de départ.","En inspirant, descends lentement jusqu'à 90° aux genoux.","Remonte en poussant surtout sur les talons, en expirant.","À la fin, reverrouille bien les sécurités."],"k":2},{"id":"Narrow_Stance_Squats","n":"Squat pieds serrés","ne":"Narrow Stance Squats","e":"barbell","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings","lower back"],"i":["Idéalement dans une cage. Pose la barre sur le haut du dos (sous la nuque).","Décroche-la en poussant avec les jambes.","Recule, pieds serrés (8 à 15 cm d'écart), pointes légèrement ouvertes, tête haute, dos droit.","Descends lentement jusqu'à un angle un peu inférieur à 90° aux genoux, en inspirant. Genoux dans l'axe des pieds.","Remonte en expirant en poussant surtout sur les talons."],"k":2},{"id":"Natural_Glute_Ham_Raise","n":"Glute-ham raise naturel","ne":"Natural Glute Ham Raise","e":"body only","c":"strength","l":"intermediate","m":["hamstrings"],"s":["calves","glutes","lower back"],"i":["Sur l'appui à genoux d'un poste de tirage ou un pupitre : chevilles sous les boudins, genoux sur l'assise, dos à la machine, buste droit.","Descends lentement vers l'avant en contrôlant, jusqu'à ce que les genoux soient presque tendus.","Remonte en contrôlant.","Si tu n'y arrives pas, aide-toi d'un élastique, d'un partenaire ou en poussant sur un box."],"k":2},{"id":"Neck-SMR","n":"Auto-massage du cou","ne":"Neck-SMR","e":"other","c":"stretching","l":"intermediate","m":["neck"],"s":[],"i":["Place un rouleau de massage derrière la nuque, légèrement de côté pour appuyer sur les muscles à côté de la colonne, pas sur la colonne.","Roule lentement du haut vers le bas du cou en restant 10 à 30 s sur les points sensibles."],"k":2},{"id":"Neck_Press","n":"Développé vers le cou","ne":"Neck Press","e":"barbell","c":"strength","l":"intermediate","m":["chest"],"s":["shoulders","triceps"],"i":["Allongé sur un banc plat, prise moyenne, sors la barre et tiens-la bras tendus au-dessus du cou.","En inspirant, descends lentement jusqu'à sentir la barre au niveau du cou.","Après une seconde, pousse avec les pectoraux en expirant et serre en haut. La descente doit durer deux fois plus longtemps que la montée.","À la fin, repose la barre."],"k":2},{"id":"Oblique_Crunches","n":"Crunchs obliques","ne":"Oblique Crunches","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé au sol, bas du dos plaqué, une main près de la tête, l'autre au sol sur le côté.","Pieds surélevés, posés sur un support plat.","Décolle l'épaule du côté de la main près de la tête.","Monte jusqu'à ce que le coude touche le genou opposé (coude droit vers genou gauche, ou l'inverse).","Redescends jusqu'au départ.","Inspire en descendant, expire en montant.","Continue en alternant les côtés."],"k":2},{"id":"Oblique_Crunches_-_On_The_Floor","n":"Crunchs obliques au sol","ne":"Oblique Crunches - On The Floor","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur le côté droit, jambes l'une sur l'autre, genoux légèrement pliés.","Main gauche derrière la tête.","Monte le coude gauche comme pour un crunch, en ciblant les obliques.","Monte aussi haut que possible, tiens une seconde puis redescends lentement.","Inspire en descendant, expire en montant."],"k":2},{"id":"Olympic_Squat","n":"Squat olympique","ne":"Olympic Squat","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Barre posée sur le haut des trapèzes, poitrine haute, regard devant, pieds largeur de hanches légèrement ouverts.","Descends en pliant les genoux en reculant le moins possible les hanches : les genoux avancent en restant dans l'axe des pieds, buste le plus droit possible, poids sur l'avant des talons. Descends jusqu'en bas.","Dès que les cuisses touchent les mollets, remonte."],"k":2},{"id":"On-Your-Back_Quad_Stretch","n":"Étirement quadriceps sur le dos","ne":"On-Your-Back Quad Stretch","e":"other","c":"stretching","l":"beginner","m":["quadriceps"],"s":[],"i":["Allongé sur un banc plat, une jambe et un bras dans le vide sur le côté.","Plie le genou et attrape le dessus du pied, sans cambrer le bas du dos.","Rentre le nombril pour rester neutre. Pousse le pied contre la main. Pour étirer aussi la hanche, monte la hanche de cette jambe vers le plafond.","Change de côté."],"k":2},{"id":"On_Your_Side_Quad_Stretch","n":"Étirement quadriceps sur le côté","ne":"On Your Side Quad Stretch","e":"other","c":"stretching","l":"beginner","m":["quadriceps"],"s":[],"i":["Allongé sur le côté droit, genou droit plié à 90° posé au sol devant toi pour stabiliser le buste.","Plie le genou gauche derrière toi et attrape le pied gauche avec la main gauche. Pousse la hanche gauche vers l'avant en repoussant le pied dans la main. Change de côté."],"k":2},{"id":"One-Arm_Dumbbell_Row","n":"Rowing haltère un bras","ne":"One-Arm Dumbbell Row","e":"dumbbell","c":"strength","l":"beginner","m":["middle back"],"s":["biceps","lats","shoulders"],"i":["Place un haltère de chaque côté d'un banc plat.","Pose le genou droit au bout du banc, penche le buste jusqu'à l'horizontale et pose la main droite sur l'autre bout du banc.","Prends l'haltère avec la main gauche, dos droit, paume vers toi : c'est la position de départ.","Tire l'haltère vers le côté de la poitrine, bras près du corps, buste immobile, en expirant. Serre le dos ; c'est le dos qui tire, pas le bras.","Redescends en inspirant.","Change de côté."],"k":2},{"id":"One-Arm_Flat_Bench_Dumbbell_Flye","n":"Écarté un bras haltère sur banc plat","ne":"One-Arm Flat Bench Dumbbell Flye","e":"dumbbell","c":"strength","l":"beginner","m":["chest"],"s":[],"i":["Allongé sur un banc plat, un haltère dans une main sur la cuisse, prise neutre.","Monte l'haltère au-dessus de toi bras tendu, prise neutre ; l'autre main tient le banc.","Coude légèrement fléchi, ouvre le bras en grand arc jusqu'à sentir l'étirement des pectoraux, en inspirant. Seule l'épaule bouge.","Remonte par le même arc en serrant les pectoraux, en expirant.","Tiens une seconde puis recommence.","Change de bras."],"k":2},{"id":"One-Arm_High-Pulley_Cable_Side_Bends","n":"Flexions latérales un bras à la poulie haute","ne":"One-Arm High-Pulley Cable Side Bends","e":"cable","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Fixe une poignée à la poulie la plus haute.","De profil, attrape la poignée d'une main en supination.","Tire jusqu'à ce que le coude touche ton flanc, poignée près de l'épaule.","Pieds largeur de hanches, main libre sur la hanche.","Bras fixe, contracte l'oblique pour faire une flexion latérale vers le bas.","Au maximum, reviens lentement sans relâcher la charge.","Continue jusqu'à l'échec.","Puis fais l'autre côté."],"k":2},{"id":"One-Arm_Incline_Lateral_Raise","n":"Élévation latérale un bras sur banc incliné","ne":"One-Arm Incline Lateral Raise","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Allongé sur le côté sur un banc incliné, épaule contre le dossier, haltère dans la main du dessus, bras devant le corps, main vers le nombril.","Bras tendu devant toi, parallèle au sol : c'est la position de départ.","Haltère toujours parallèle au sol, monte le bras jusqu'à la verticale en expirant. Tiens une seconde.","Redescends en travers du corps en inspirant.","Change de bras."],"k":2},{"id":"One-Arm_Kettlebell_Clean","n":"Épaulé kettlebell un bras","ne":"One-Arm Kettlebell Clean","e":"kettlebells","c":"strength","l":"intermediate","m":["hamstrings"],"s":["glutes","lower back","shoulders","traps"],"i":["Place une kettlebell entre tes pieds. En te penchant pour la prendre, recule les fesses, regard devant.","Monte-la à l'épaule en poussant avec les jambes et les hanches, en tournant le poignet.","Redescends-la."],"k":2},{"id":"One-Arm_Kettlebell_Clean_and_Jerk","n":"Épaulé-jeté kettlebell un bras","ne":"One-Arm Kettlebell Clean and Jerk","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":[],"i":["Tiens une kettlebell par la poignée.","Monte-la à l'épaule en poussant avec les jambes et les hanches, paume vers l'avant.","Fléchis légèrement les genoux, buste droit.","Inverse aussitôt en poussant sur les talons, comme pour sauter, et pousse la kettlebell au-dessus de la tête avec l'élan.","Réceptionne-la en te replaçant en squat dessous.","Relève-toi, charge au-dessus de la tête, puis redescends-la au sol."],"k":2},{"id":"One-Arm_Kettlebell_Floor_Press","n":"Développé au sol kettlebell un bras","ne":"One-Arm Kettlebell Floor Press","e":"kettlebells","c":"strength","l":"intermediate","m":["chest"],"s":["triceps"],"i":["Allongé au sol, une kettlebell dans une main, bras posé au sol, paume vers l'intérieur.","Pousse la kettlebell vers le plafond en tournant le poignet.","Redescends et recommence."],"k":2},{"id":"One-Arm_Kettlebell_Jerk","n":"Jeté kettlebell un bras","ne":"One-Arm Kettlebell Jerk","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["calves","quadriceps","triceps"],"i":["Monte une kettlebell à l'épaule en poussant avec les jambes et les hanches, paume vers l'avant : c'est la position de départ.","Fléchis légèrement les genoux, buste droit.","Inverse aussitôt comme pour sauter et pousse la kettlebell au-dessus de la tête avec l'élan ; réceptionne-la en te replaçant en squat dessous, puis relève-toi.","Redescends-la pour la répétition suivante."],"k":2},{"id":"One-Arm_Kettlebell_Military_Press_To_The_Side","n":"Développé militaire kettlebell un bras sur le côté","ne":"One-Arm Kettlebell Military Press To The Side","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["triceps"],"i":["Monte une kettlebell à l'épaule, paume vers l'intérieur : c'est la position de départ.","Regard sur la kettlebell, pousse-la vers le haut et légèrement vers l'extérieur jusqu'à verrouiller le bras.","Redescends-la à l'épaule en contrôlant. Contracte fort dorsal, fessiers et abdos pour la stabilité."],"k":2},{"id":"One-Arm_Kettlebell_Para_Press","n":"Développé para kettlebell un bras","ne":"One-Arm Kettlebell Para Press","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["triceps"],"i":["Monte une kettlebell à l'épaule, paume vers l'avant : c'est la position de départ.","Coude écarté sur le côté, pousse la kettlebell vers le haut et l'extérieur jusqu'à verrouiller le bras.","Redescends-la à l'épaule en contrôlant. Contracte fort dorsal, fessiers et abdos."],"k":2},{"id":"One-Arm_Kettlebell_Push_Press","n":"Push press kettlebell un bras","ne":"One-Arm Kettlebell Push Press","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["calves","quadriceps","triceps"],"i":["Monte une kettlebell à l'épaule en poussant avec les jambes et les hanches, paume vers l'avant : c'est la position de départ.","Fléchis légèrement les genoux, buste droit.","Inverse aussitôt en poussant sur les talons et utilise l'élan pour pousser la kettlebell au-dessus de la tête. Redescends-la pour la répétition suivante."],"k":2},{"id":"One-Arm_Kettlebell_Row","n":"Rowing kettlebell un bras","ne":"One-Arm Kettlebell Row","e":"kettlebells","c":"strength","l":"intermediate","m":["middle back"],"s":["biceps","lats"],"i":["Place une kettlebell devant tes pieds. Genoux légèrement fléchis, fesses bien en arrière, penche-toi. Attrape la kettlebell et tire-la vers le ventre en serrant l'omoplate, dos droit. Redescends et recommence."],"k":2},{"id":"One-Arm_Kettlebell_Snatch","n":"Arraché kettlebell un bras","ne":"One-Arm Kettlebell Snatch","e":"kettlebells","c":"strength","l":"expert","m":["shoulders"],"s":["calves","glutes","hamstrings","lower back","traps","triceps"],"i":["Place une kettlebell entre tes pieds, genoux fléchis, fesses en arrière.","Regard devant, balance la kettlebell en arrière entre les jambes.","Inverse aussitôt en poussant hanches et genoux pour l'accélérer vers le haut. Quand elle arrive à l'épaule, tourne la main et pousse droit vers le haut pour la réceptionner bras verrouillé."],"k":2},{"id":"One-Arm_Kettlebell_Split_Jerk","n":"Jeté fendu kettlebell un bras","ne":"One-Arm Kettlebell Split Jerk","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["glutes","hamstrings","quadriceps","triceps"],"i":["Monte une kettlebell à l'épaule, paume vers l'avant : c'est la position de départ.","Fléchis légèrement les genoux, buste droit.","Inverse aussitôt comme pour sauter et pousse la kettlebell au-dessus de la tête avec l'élan.","Réceptionne-la en fente, une jambe devant, une derrière.","Charge au-dessus de la tête, ramène les pieds ensemble, puis redescends-la."],"k":2},{"id":"One-Arm_Kettlebell_Split_Snatch","n":"Arraché fendu kettlebell un bras","ne":"One-Arm Kettlebell Split Snatch","e":"kettlebells","c":"strength","l":"expert","m":["shoulders"],"s":["hamstrings","quadriceps"],"i":["Tiens une kettlebell d'une main par la poignée.","Fléchis vers le sol puis inverse en tendant hanches, genoux et chevilles pour envoyer la kettlebell au-dessus de la tête.","Après l'extension, réceptionne-la en fente, une jambe devant, une derrière, bras verrouillé, en un seul mouvement.","Relève-toi, charge au-dessus de la tête, ramène les pieds puis redescends-la."],"k":2},{"id":"One-Arm_Kettlebell_Swings","n":"Swing kettlebell un bras","ne":"One-Arm Kettlebell Swings","e":"kettlebells","c":"strength","l":"intermediate","m":["hamstrings"],"s":["calves","glutes","lower back","shoulders"],"i":["Kettlebell dans une main entre les jambes, pieds un peu plus larges que les épaules. Balance-la entre les jambes en reculant les fesses, puis pousse les hanches vers l'avant pour la projeter jusqu'à hauteur d'épaule, bras tendu. Laisse-la redescendre et enchaîne."],"k":2},{"id":"One-Arm_Long_Bar_Row","n":"Rowing T-bar un bras","ne":"One-Arm Long Bar Row","e":"barbell","c":"strength","l":"beginner","m":["middle back"],"s":["biceps","lats"],"i":["Place une barre dans un landmine (ou cale un bout dans un coin) et charge ton extrémité.","À côté de la barre, prends-la d'une main près du manchon et redresse-toi avec les jambes.","Genoux fléchis, hanches en arrière, poitrine haute, bras tendu : c'est la position de départ.","Tire la charge vers ton flanc en serrant l'omoplate, sans à-coup.","Après une courte pause, redescends."],"k":2},{"id":"One-Arm_Medicine_Ball_Slam","n":"Slam médecine-ball un bras","ne":"One-Arm Medicine Ball Slam","e":"medicine ball","c":"strength","l":"beginner","m":["abdominals"],"s":["lats","shoulders"],"i":["Debout, pieds décalés en position athlétique, médecine-ball dans la main du côté de la jambe arrière.","Arme le bras en montant le ballon au-dessus de la tête, en tendant hanches, genoux et chevilles.","Au maximum de l'extension, enroule épaules, colonne et hanches pour lancer le ballon fort au sol juste devant toi.","Rattrape-le au rebond et enchaîne."],"k":2},{"id":"One-Arm_Open_Palm_Kettlebell_Clean","n":"Épaulé kettlebell main ouverte un bras","ne":"One-Arm Open Palm Kettlebell Clean","e":"kettlebells","c":"strength","l":"intermediate","m":["hamstrings"],"s":["forearms","glutes","lower back","quadriceps","shoulders"],"i":["Place une kettlebell entre tes pieds.","Prends la poignée d'une main, monte-la vivement et laisse-la basculer pour que la boule tombe dans ta paume ouverte.","Relance-la devant toi et rattrape la poignée d'une main.","Repose-la au sol et recommence. Travaille les deux bras."],"k":2},{"id":"One-Arm_Overhead_Kettlebell_Squats","n":"Squat kettlebell bras tendu au-dessus de la tête","ne":"One-Arm Overhead Kettlebell Squats","e":"kettlebells","c":"strength","l":"expert","m":["quadriceps"],"s":["calves","glutes","hamstrings","shoulders"],"i":["Monte une kettlebell à l'épaule puis au-dessus de la tête à un bras : c'est la position de départ.","Regard devant, kettlebell verrouillée, plie genoux et hanches pour descendre entre tes jambes, tête et poitrine hautes.","Pause d'une seconde en bas puis remonte en poussant sur les talons."],"k":2},{"id":"One-Arm_Side_Deadlift","n":"Soulevé de terre latéral un bras","ne":"One-Arm Side Deadlift","e":"barbell","c":"strength","l":"expert","m":["quadriceps"],"s":["abdominals","calves","glutes","hamstrings","lower back","traps"],"i":["Debout à côté du milieu d'une barre posée au sol. Plie les genoux pour l'atteindre.","Saisis-la comme une valise (paume vers toi). Des sangles aident si c'est lourd.","Redresse-toi en poussant avec les jambes, bras tendu, en expirant.","Redescends lentement en pliant les genoux, en inspirant.","Change de bras."],"k":2},{"id":"One-Arm_Side_Laterals","n":"Élévation latérale un bras","ne":"One-Arm Side Laterals","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Un haltère dans une main ; l'autre main tient un appui stable. Penche-toi légèrement vers le bras qui travaille pour l'équilibre.","Buste droit, haltère le long du corps, paume vers toi : c'est la position de départ.","Sans élan, monte l'haltère sur le côté, coude légèrement fléchi, main légèrement inclinée comme pour verser un verre, jusqu'à l'horizontale, en expirant. Pause en haut.","Redescends lentement en inspirant.","Change de bras."],"k":2},{"id":"One-Legged_Cable_Kickback","n":"Kickback une jambe à la poulie","ne":"One-Legged Cable Kickback","e":"cable","c":"strength","l":"intermediate","m":["glutes"],"s":["hamstrings"],"i":["Attache une sangle de cheville à une poulie basse et à ta cheville.","Face à la machine à environ 60 cm, tiens le cadre.","Genoux et hanches légèrement fléchis, abdos serrés, contracte les fessiers pour repousser la jambe vers l'arrière en arc, aussi haut que confortable, en expirant. Serre une seconde.","Ramène lentement la jambe en résistant au câble.","Change de jambe."],"k":2},{"id":"One_Arm_Against_Wall","n":"Étirement un bras contre le mur","ne":"One Arm Against Wall","e":"other","c":"stretching","l":"beginner","m":["lats"],"s":[],"i":["Debout, pose un bras plié contre un mur ou un encadrement de porte.","Penche-toi doucement vers le bras jusqu'à sentir l'étirement du grand dorsal."],"k":2},{"id":"One_Arm_Chin-Up","n":"Traction supination un bras","ne":"One Arm Chin-Up","e":"other","c":"strength","l":"expert","m":["middle back"],"s":["biceps","forearms","lats"],"i":["Passe une serviette autour de la barre de traction.","Une main sur la barre paume vers toi, l'autre sur la serviette.","Recule le buste d'environ 30°, poitrine sortie, bas du dos cambré : c'est la position de départ.","Tire-toi jusqu'à ce que la barre touche le haut de la poitrine en abaissant épaules et bras, en expirant. Serre le dos.","Après une seconde, redescends lentement en inspirant jusqu'à bras tendu.","Change de bras."],"k":2},{"id":"One_Arm_Dumbbell_Bench_Press","n":"Développé couché haltère un bras","ne":"One Arm Dumbbell Bench Press","e":"dumbbell","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Allongé sur un banc plat, un haltère sur la cuisse.","Monte-le au-dessus de toi à largeur d'épaule en t'aidant de la cuisse et de l'autre main.","Tourne le poignet paume vers l'avant : c'est la position de départ.","Descends lentement l'haltère sur le côté en inspirant, en gardant le contrôle (l'autre main peut aider à l'équilibre si besoin).","Pousse avec les pectoraux en expirant, serre une seconde. Descente deux fois plus lente que la montée.","Change de bras."],"k":2},{"id":"One_Arm_Dumbbell_Preacher_Curl","n":"Curl pupitre haltère un bras","ne":"One Arm Dumbbell Preacher Curl","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Haltère dans la main droite, bras posé sur un pupitre ou un banc incliné, haltère à hauteur d'épaule : c'est la position de départ.","En inspirant, descends lentement jusqu'à bras tendu.","En expirant, remonte avec le biceps jusqu'à hauteur d'épaule, petit doigt plus haut que le pouce.","Serre fort une seconde puis recommence.","Change de bras."],"k":2},{"id":"One_Arm_Floor_Press","n":"Développé au sol un bras","ne":"One Arm Floor Press","e":"barbell","c":"strength","l":"intermediate","m":["triceps"],"s":["chest","shoulders"],"i":["Allongé sur le dos au sol, genoux pliés.","Fais-toi passer une barre dans une main ; bras presque tendu, prise neutre (paume vers toi).","L'autre main le long du corps.","Descends la barre jusqu'à ce que le coude touche le sol, en inspirant.","Remonte en expirant.","Change de bras."],"k":2},{"id":"One_Arm_Lat_Pulldown","n":"Tirage vertical un bras","ne":"One Arm Lat Pulldown","e":"cable","c":"strength","l":"beginner","m":["lats"],"s":["biceps","middle back"],"i":["Choisis la charge et cale les genoux sous l'appui. Prends la poignée en pronation : c'est la position de départ.","Tire la poignée vers le bas en ramenant le coude contre ton flanc.","Pause en bas puis remonte lentement.","Ne relâche pas complètement la charge entre les répétitions."],"k":2},{"id":"One_Arm_Pronated_Dumbbell_Triceps_Extension","n":"Extension triceps haltère un bras prise pronation","ne":"One Arm Pronated Dumbbell Triceps Extension","e":"dumbbell","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Allongé sur un banc, haltère tenu bras tendu, perpendiculaire au corps, paume tournée vers les pieds.","L'autre main sur le biceps pour stabiliser.","Descends lentement l'haltère en pliant le coude, en inspirant.","Remonte en contractant le triceps, en expirant.","Change de bras."],"k":2},{"id":"One_Arm_Supinated_Dumbbell_Triceps_Extension","n":"Extension triceps haltère un bras prise supination","ne":"One Arm Supinated Dumbbell Triceps Extension","e":"dumbbell","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Allongé sur un banc, haltère tenu bras tendu, perpendiculaire au corps, paume tournée vers ton visage.","L'autre main sur le biceps pour stabiliser.","Descends lentement l'haltère en pliant le coude, en inspirant.","Remonte en contractant le triceps, en expirant.","Change de bras."],"k":2},{"id":"One_Half_Locust","n":"Demi-sauterelle (yoga)","ne":"One Half Locust","e":"other","c":"stretching","l":"beginner","m":["quadriceps"],"s":["abdominals","biceps","chest"],"i":["Allongé à plat ventre.","Main gauche sous l'os de la hanche gauche pour protéger hanche et pubis.","Plie le genou droit et attrape le pied avec la main droite.","Monte le pied et décolle en même temps les épaules du sol ; cela étire aussi le fléchisseur de hanche, la poitrine et les épaules. Change de côté. Si ton dos le supporte, essaie avec les deux bras et les deux jambes."],"k":2},{"id":"One_Handed_Hang","n":"Suspension à une main","ne":"One Handed Hang","e":"other","c":"stretching","l":"beginner","m":["lats"],"s":["biceps"],"i":["Attrape une barre de traction d'une main en pronation, pieds au sol ou sur une marche. Laisse pendre la majeure partie de ton poids sur cette main, pieds au sol. Tiens 10 à 20 s puis change de côté."],"k":2},{"id":"One_Knee_To_Chest","n":"Un genou contre la poitrine","ne":"One Knee To Chest","e":"other","c":"stretching","l":"beginner","m":["glutes"],"s":["hamstrings","lower back"],"i":["Allongé au sol.","Une jambe tendue, ramène l'autre genou contre la poitrine en tenant sous le genou pour protéger la rotule.","Tire doucement le genou vers le nez.","Change de côté. Étire les fessiers et le bas du dos de la jambe pliée et le fléchisseur de hanche de la jambe tendue."],"k":2},{"id":"One_Leg_Barbell_Squat","n":"Squat une jambe barre","ne":"One Leg Barbell Squat","e":"barbell","c":"strength","l":"expert","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Debout à 60-90 cm devant un banc plat, dos au banc, barre au sol devant toi, pieds largeur d'épaules.","Plie les genoux, prends la barre en pronation, plus large que les épaules, et monte-la jusqu'à la poitrine.","Passe-la au-dessus de la tête et pose-la sur la base de la nuque. Recule un pied pour poser les orteils sur le banc ; l'autre pied reste devant. Tête haute, dos droit, poitrine sortie.","En inspirant, descends lentement jusqu'à avoir la cuisse avant parallèle au sol, poitrine au-dessus du milieu de la cuisse.","Remonte en contractant le quadriceps, en expirant.","Change de jambe."],"k":2},{"id":"Open_Palm_Kettlebell_Clean","n":"Épaulé kettlebell main ouverte","ne":"Open Palm Kettlebell Clean","e":"kettlebells","c":"strength","l":"expert","m":["hamstrings"],"s":["glutes","lower back","quadriceps","shoulders"],"i":["Place une kettlebell entre tes pieds et monte-la vers les épaules en poussant avec les jambes et les hanches.","Lâche-la en montant et laisse-la basculer pour que la boule tombe dans tes paumes ouvertes.","Relance-la devant toi et rattrape la poignée à deux mains. Redescends-la et recommence."],"k":2},{"id":"Otis-Up","n":"Otis-up","ne":"Otis-Up","e":"other","c":"strength","l":"beginner","m":["abdominals"],"s":["chest","shoulders","triceps"],"i":["Pieds calés, allongé au sol, genoux pliés, un poids tenu à deux mains contre la poitrine : c'est la position de départ.","Monte le buste en enroulant hanches et colonne.","En montant, pousse le poids au-dessus de la tête.","Ramène le poids à la poitrine en redescendant, sans aller jusqu'au sol."],"k":2},{"id":"Overhead_Cable_Curl","n":"Curl poulie haute au-dessus de la tête","ne":"Overhead Cable Curl","e":"cable","c":"strength","l":"intermediate","m":["biceps"],"s":[],"i":["Règle la même charge des deux côtés du vis-à-vis.","Place les poulies plus haut que tes épaules.","Debout au milieu, prends chaque poignée en supination, bras tendus parallèles au sol, pieds largeur d'épaules : c'est la position de départ.","En expirant, serre les biceps pour ramener les mains vers la tête jusqu'à ce que les avant-bras touchent les biceps.","Reviens en inspirant. Seuls les avant-bras bougent."],"k":2},{"id":"Overhead_Lat","n":"Étirement grand dorsal au-dessus de la tête","ne":"Overhead Lat","e":"other","c":"stretching","l":"expert","m":["lats"],"s":["triceps"],"i":["Assis droit au sol, ton partenaire derrière toi. Lève un bras, plie le coude comme pour toucher ton dos ; il tient ton triceps et ton poignet.","Essaie de ramener le bras vers ton flanc pendant qu'il t'en empêche.","Après 10 à 20 s, relâche et laisse-le étirer davantage le grand dorsal en appuyant doucement sur le triceps. Tiens 10 à 20 s puis change de côté."],"k":2},{"id":"Overhead_Slam","n":"Slam au-dessus de la tête","ne":"Overhead Slam","e":"medicine ball","c":"plyometrics","l":"beginner","m":["lats"],"s":[],"i":["Debout, pieds largeur d'épaules, médecine-ball à deux mains.","Monte le ballon au-dessus de la tête en t'étirant complètement.","Lance-le au sol juste devant toi le plus fort possible.","Rattrape-le au rebond et recommence."],"k":2},{"id":"Overhead_Squat","n":"Squat barre au-dessus de la tête","ne":"Overhead Squat","e":"barbell","c":"olympic weightlifting","l":"expert","m":["quadriceps"],"s":["abdominals","calves","glutes","hamstrings","lower back","shoulders","triceps"],"i":["Barre au sol devant toi, pieds plus larges que les épaules.","Plie les genoux et prends la barre en pronation, mains plus larges que les épaules, puis monte-la jusqu'à la poitrine.","Passe-la au-dessus et légèrement derrière la tête, bras tendus, tête haute, dos droit, omoplates serrées : c'est la position de départ.","En inspirant, descends lentement jusqu'à avoir les cuisses parallèles au sol, bras toujours tendus au-dessus de la tête, dos droit.","Remonte en expirant."],"k":2},{"id":"Overhead_Stretch","n":"Étirement bras au-dessus de la tête","ne":"Overhead Stretch","e":"other","c":"stretching","l":"beginner","m":["abdominals"],"s":["chest","forearms","lats","triceps"],"i":["Debout, doigts entrelacés, paumes tournées vers le plafond, bras tendus vers le haut, épaules basses.","Pour étirer tout le buste, descends le coccyx et stabilise le tronc ; étire l'avant et l'arrière du buste."],"k":2},{"id":"Overhead_Triceps","n":"Étirement triceps au-dessus de la tête","ne":"Overhead Triceps","e":"body only","c":"stretching","l":"expert","m":["triceps"],"s":["lats"],"i":["Assis droit au sol, ton partenaire derrière toi. Lève un bras, plie le coude comme pour toucher ton dos ; il tient ton coude et ton poignet.","Essaie de tendre le bras vers le haut pendant qu'il t'en empêche.","Après 10 à 20 s, relâche et laisse-le étirer davantage le triceps en appuyant doucement sur le poignet. Tiens 10 à 20 s puis change de côté."],"k":2},{"id":"Pallof_Press","n":"Pallof press","ne":"Pallof Press","e":"cable","c":"strength","l":"beginner","m":["abdominals"],"s":["chest","shoulders","triceps"],"i":["Fixe une poignée à une poulie, idéalement à hauteur d'épaules (sinon en bas).","De profil, prends la poignée à deux mains et éloigne-toi d'environ une longueur de bras, câble en tension.","Pieds largeur de hanches, genoux légèrement fléchis, poignée au milieu de la poitrine : c'est la position de départ.","Pousse la poignée devant toi jusqu'à bras tendus, abdos gainés pour ne pas tourner.","Tiens plusieurs secondes puis reviens.","Fais la série de l'autre côté."],"k":2},{"id":"Pallof_Press_With_Rotation","n":"Pallof press avec rotation","ne":"Pallof Press With Rotation","e":"cable","c":"strength","l":"beginner","m":["abdominals"],"s":["chest","shoulders","triceps"],"i":["Fixe une poignée à une poulie à hauteur d'épaules.","De profil, prends la poignée d'une main et éloigne-toi d'environ une longueur de bras, câble en tension, bras aligné avec le câble.","Pieds largeur de hanches, ramène la poignée contre la poitrine et prends-la à deux mains.","Face devant, pousse la poignée devant toi, abdos gainés.","Hanches fixes, tourne le buste d'un quart de tour à l'opposé de la poulie.","Bras tendus et posture solide, reviens lentement au centre.","Ramène les mains à la poitrine puis repousse aussitôt : cela fait une répétition.","Continue jusqu'à l'échec.","Puis fais l'autre côté."],"k":2},{"id":"Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench","n":"Curl poignets paumes vers le bas haltères sur banc","ne":"Palms-Down Dumbbell Wrist Curl Over A Bench","e":"dumbbell","c":"strength","l":"beginner","m":["forearms"],"s":[],"i":["Pose deux haltères d'un côté d'un banc plat.","À genoux face au banc.","Prends les haltères en pronation, avant-bras posés sur le banc, poignets dans le vide.","Monte les poignets en expirant.","Redescends lentement en inspirant.","Seuls les poignets bougent."],"k":2},{"id":"Palms-Down_Wrist_Curl_Over_A_Bench","n":"Curl poignets paumes vers le bas sur banc","ne":"Palms-Down Wrist Curl Over A Bench","e":"barbell","c":"strength","l":"beginner","m":["forearms"],"s":[],"i":["Pose une barre d'un côté d'un banc plat.","À genoux face au banc.","Prends la barre en pronation, avant-bras posés sur le banc, poignets dans le vide.","Monte les poignets en expirant.","Redescends lentement en inspirant.","Seuls les poignets bougent."],"k":2},{"id":"Palms-Up_Barbell_Wrist_Curl_Over_A_Bench","n":"Curl poignets paumes vers le haut barre sur banc","ne":"Palms-Up Barbell Wrist Curl Over A Bench","e":"barbell","c":"strength","l":"beginner","m":["forearms"],"s":[],"i":["Pose une barre d'un côté d'un banc plat.","À genoux face au banc.","Prends la barre en supination, avant-bras posés sur le banc, poignets dans le vide.","Monte les poignets en expirant.","Redescends lentement en inspirant.","Seuls les poignets bougent."],"k":2},{"id":"Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench","n":"Curl poignets paumes vers le haut haltères sur banc","ne":"Palms-Up Dumbbell Wrist Curl Over A Bench","e":"dumbbell","c":"strength","l":"beginner","m":["forearms"],"s":[],"i":["Pose deux haltères d'un côté d'un banc plat.","À genoux face au banc.","Prends les haltères en supination, avant-bras posés sur le banc, poignets dans le vide.","Monte les poignets en expirant.","Redescends lentement en inspirant.","Seuls les poignets bougent."],"k":2},{"id":"Parallel_Bar_Dip","n":"Dips aux barres parallèles","ne":"Parallel Bar Dip","e":"other","c":"strength","l":"beginner","m":["triceps"],"s":["chest","shoulders"],"i":["Debout entre deux barres parallèles, une main sur chaque barre ; fais un petit saut pour te retrouver bras verrouillés.","Plie les coudes pour descendre jusqu'à passer sous 90°, sans balancer, bonne posture.","Remonte en tendant les coudes."],"k":2},{"id":"Pelvic_Tilt_Into_Bridge","n":"Bascule du bassin vers le pont","ne":"Pelvic Tilt Into Bridge","e":"other","c":"stretching","l":"intermediate","m":["lower back"],"s":[],"i":["Allongé, pieds au sol, talons sous les genoux.","Monte seulement le coccyx vers le plafond pour étirer le bas du dos (pas encore toute la colonne), ventre rentré.","Pour passer en pont, décolle toute la colonne sauf la nuque."],"k":2},{"id":"Peroneals-SMR","n":"Auto-massage des péroniers","ne":"Peroneals-SMR","e":"foam roll","c":"stretching","l":"intermediate","m":["calves"],"s":[],"i":["Allongé sur le côté, appui sur l'avant-bras et sur un rouleau placé à l'extérieur de la jambe du dessous ; l'autre jambe dessus ou croisée devant.","Décolle les hanches et roule du genou à la cheville sur le côté de la jambe, en restant 10 à 30 s sur les points sensibles. Change de jambe."],"k":2},{"id":"Peroneals_Stretch","n":"Étirement des péroniers","ne":"Peroneals Stretch","e":"other","c":"stretching","l":"intermediate","m":["calves"],"s":[],"i":["Assis, passe une sangle autour d'un pied.","Jambe tendue, talon décollé, tire sur la sangle pour tourner la plante du pied vers l'intérieur. Tiens 10 à 20 s puis change de côté."],"k":2},{"id":"Physioball_Hip_Bridge","n":"Pont de hanches sur swiss ball","ne":"Physioball Hip Bridge","e":"exercise ball","c":"strength","l":"beginner","m":["glutes"],"s":["hamstrings"],"i":["Allongé sur un swiss ball, haut du dos sur le ballon, hanches dans le vide, pieds à plat écartés au moins largeur de hanches : c'est la position de départ.","Monte les hanches avec les fessiers et les ischios pour faire un pont.","Pause en haut puis redescends."],"k":2},{"id":"Pin_Presses","n":"Développé depuis les supports","ne":"Pin Presses","e":"barbell","c":"powerlifting","l":"intermediate","m":["triceps"],"s":["chest","forearms","lats","middle back","shoulders"],"i":["Le développé depuis les supports supprime la phase de descente et développe la force de démarrage, sur l'amplitude choisie.","Banc dans une cage, supports réglés au point voulu (de la quasi-extension à quelques centimètres de la poitrine) ; barre posée dessus.","Allonge-toi, barre au-dessus du point de contact habituel, pieds ramenés sous toi, dos cambré, omoplates serrées et plaquées.","Prise classique ou largeur d'épaules pour les triceps ; barre, poignets et coudes alignés.","Pousse la barre le plus fort possible, coudes rentrés.","Repose-la sur les supports et marque une pause avant la répétition suivante."],"k":2},{"id":"Piriformis-SMR","n":"Auto-massage du piriforme","ne":"Piriformis-SMR","e":"foam roll","c":"stretching","l":"intermediate","m":["glutes"],"s":[],"i":["Assis sur un rouleau de massage, genoux pliés, croise une jambe (cheville sur le genou opposé).","Penche-toi du côté de la jambe croisée et roule sur la fesse jusqu'à sentir la tension en haut du fessier. Tu peux tirer le genou vers la poitrine. Tiens 10 à 30 s puis change de côté."],"k":2},{"id":"Plank","n":"Planche","ne":"Plank","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé face au sol, appui sur les orteils et les avant-bras, coudes sous les épaules.","Garde le corps parfaitement droit et tiens le plus longtemps possible. Pour corser, lève un bras ou une jambe."],"k":2},{"id":"Plate_Pinch","n":"Pince de disques","ne":"Plate Pinch","e":"other","c":"strength","l":"intermediate","m":["forearms"],"s":[],"i":["Prends deux disques à large rebord et colle-les, faces lisses vers l'extérieur.","Tiens-les ensemble avec les doigts d'un côté et le pouce de l'autre : c'est la position de départ.","Serre et tiens le plus longtemps possible.","Fais le nombre de séries prévu.","Change de main."],"k":2},{"id":"Plate_Twist","n":"Rotation avec disque","ne":"Plate Twist","e":"other","c":"strength","l":"intermediate","m":["abdominals"],"s":[],"i":["Assis au sol, jambes tendues, buste droit. Tiens un disque à deux mains devant le ventre, bras légèrement fléchis.","Croise les jambes aux chevilles et décolle-les du sol, genoux légèrement fléchis, buste un peu en arrière pour l'équilibre : c'est la position de départ.","Amène le disque à gauche jusqu'à toucher le sol, en expirant.","Reviens en inspirant puis fais de même à droite. Mouvement lent, sans à-coups pour protéger le dos."],"k":2},{"id":"Platform_Hamstring_Slides","n":"Glissés ischios sur plateforme","ne":"Platform Hamstring Slides","e":"other","c":"strength","l":"beginner","m":["hamstrings"],"s":["glutes"],"i":["Sur un parquet ou un sol glissant, allongé sur le dos, jambes tendues, une serviette ou un disque léger sous un talon.","Plie le genou, l'autre jambe tendue.","Fais glisser le talon vers toi.","Genou complètement plié, reviens en tendant la jambe."],"k":2},{"id":"Plie_Dumbbell_Squat","n":"Squat plié haltère","ne":"Plie Dumbbell Squat","e":"dumbbell","c":"strength","l":"beginner","m":["quadriceps"],"s":["abdominals","calves","glutes","hamstrings"],"i":["Debout, tiens un haltère par la base à deux mains. Pieds plus larges que les épaules, genoux légèrement fléchis.","Pointes de pieds vers l'extérieur ; les bras ne bougent pas : c'est la position de départ.","Plie lentement les genoux jusqu'à avoir les cuisses parallèles au sol, en inspirant.","Remonte en poussant surtout sur les talons, en expirant."],"k":2},{"id":"Plyo_Kettlebell_Pushups","n":"Pompes pliométriques sur kettlebells","ne":"Plyo Kettlebell Pushups","e":"kettlebells","c":"strength","l":"expert","m":["chest"],"s":["shoulders","triceps"],"i":["Kettlebell au sol. En position de pompe, une main au sol, l'autre sur la kettlebell, bras tendus : c'est la position de départ.","Descends le plus bas possible, dos droit.","Repousse vivement pour passer de l'autre côté de la kettlebell en changeant de main. Continue en allant d'un côté à l'autre."],"k":2},{"id":"Plyo_Push-up","n":"Pompes pliométriques","ne":"Plyo Push-up","e":"body only","c":"plyometrics","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["En position de pompe, appui sur les mains et les orteils.","Bras tendus, mains largeur d'épaules, corps droit : c'est la position de départ.","Descends en pliant les coudes, poitrine vers le sol.","En bas, pousse le plus vite possible pour que les mains décollent du sol.","Réceptionne-toi et recommence.","Pour corser, frappe dans les mains en l'air."],"k":2},{"id":"Posterior_Tibialis_Stretch","n":"Étirement du tibial postérieur","ne":"Posterior Tibialis Stretch","e":"other","c":"stretching","l":"intermediate","m":["calves"],"s":[],"i":["Assis, passe une sangle autour d'un pied.","Jambe tendue, talon décollé, tire sur la sangle pour tourner la plante du pied vers l'extérieur. Tiens 10 à 20 s puis change de côté."],"k":2},{"id":"Power_Clean","n":"Épaulé en force","ne":"Power Clean","e":"barbell","c":"strength","l":"intermediate","m":["hamstrings"],"s":["calves","forearms","glutes","lower back","middle back","quadriceps","shoulders","traps","triceps"],"i":["Pieds un peu plus larges que les épaules, pointes légèrement ouvertes.","Descends et saisis la barre en pronation, mains un peu plus larges que les épaules, bras tendus.","Barre à environ 2 cm devant les tibias, au-dessus de l'avant des pieds.","Dos plat ou légèrement cambré, poitrine sortie, omoplates serrées.","Tête neutre, regard devant ; inspire.","Décolle la barre en tendant hanches et genoux, en expirant ; le buste garde le même angle et les hanches ne montent pas avant les épaules.","Coudes tendus, épaules au-dessus de la barre.","Garde la barre près des tibias en montant.","Une fois les genoux passés, avance les hanches et fléchis légèrement les genoux ; les cuisses touchent la barre.","Dos plat, coudes tendus, tête neutre ; bloque ta respiration.","Tends explosivement hanches et genoux en montant sur la pointe des pieds.","Barre près du corps, coudes vers l'extérieur, épaules au-dessus de la barre, bras tendus le plus longtemps possible.","Une fois les jambes tendues, hausse vivement les épaules sans plier les coudes, en expirant.","Au point haut des épaules, plie les coudes pour commencer à passer sous la barre.","Continue à tirer avec les bras le plus haut possible ; les pieds peuvent décoller.","Barre presque au maximum, glisse-toi dessous en tournant les bras autour de la barre.","En même temps, fléchis hanches et genoux en quart de squat.","Bras sous la barre, monte les coudes pour avoir les bras parallèles au sol et pose la barre sur l'avant des épaules.","Réceptionne buste droit et gainé, tête neutre, pieds à plat, en expirant.","Relève-toi complètement.","Redescends la barre aux cuisses en relâchant progressivement les bras, en inspirant.","En même temps, fléchis hanches et genoux pour amortir.","Descends, bras tendus, jusqu'à poser la barre au sol."],"k":2},{"id":"Power_Clean_from_Blocks","n":"Épaulé en force depuis des blocs","ne":"Power Clean from Blocks","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["hamstrings"],"s":["quadriceps"],"i":["Barre sur des blocs à la hauteur voulue, prise juste à l'extérieur des jambes. Hanches basses, poids sur les talons, dos droit, regard devant, épaules juste devant la barre.","Pousse sur les talons en tendant les genoux, angle du dos constant, bras tendus ; à mi-cuisse, commence à ouvrir les hanches.","Comme pour sauter, tends explosivement hanches, genoux et chevilles, sans tirer avec les bras.","À l'extension, hausse les épaules, coudes hauts, et glisse-toi sous la barre juste assez pour la poser sur les épaules.","Relève-toi aussitôt en poussant sur les talons, buste droit, coudes hauts, puis repose la barre sur les blocs."],"k":2},{"id":"Power_Jerk","n":"Jeté en force","ne":"Power Jerk","e":"barbell","c":"olympic weightlifting","l":"expert","m":["quadriceps"],"s":["abdominals","calves","glutes","hamstrings","shoulders","triceps"],"i":["Debout, barre posée sur l'avant des épaules. Pieds sous les hanches, fléchis légèrement les genoux sans reculer les hanches, puis inverse le plus puissamment possible.","Pousse fort sur les talons et écarte la tête du trajet de la barre.","Replace aussitôt les pieds un peu plus écartés, genoux légèrement fléchis.","Réceptionne la barre bras verrouillés au-dessus de la tête.","Relève-toi."],"k":2},{"id":"Power_Partials","n":"Partiels en force","ne":"Power Partials","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Debout, buste droit, un haltère dans chaque main bras tendus, coudes près du corps.","Paumes vers le corps, pieds largeur d'épaules : c'est la position de départ.","Bras tendus, buste fixe, monte les haltères sur les côtés jusqu'à hauteur d'épaules, en expirant.","Tiens une seconde puis redescends en inspirant. Paumes vers le bas, petit doigt légèrement plus haut, pour concentrer le travail sur les épaules."],"k":2},{"id":"Power_Snatch","n":"Arraché en force","ne":"Power Snatch","e":"barbell","c":"olympic weightlifting","l":"expert","m":["hamstrings"],"s":["calves","glutes","lower back","quadriceps","shoulders","traps","triceps"],"i":["Barre chargée au sol contre les tibias, prise large. Pieds sous les hanches légèrement ouverts, hanches basses, poitrine haute, regard devant, épaules juste devant la barre.","Premier tirage : pousse sur l'avant des talons pour décoller la barre, angle du dos constant jusqu'aux genoux.","Deuxième tirage : tends explosivement hanches, genoux et chevilles, barre près du corps. À l'extension, hausse les épaules et laisse les coudes partir sur les côtés.","En écartant légèrement les pieds, glisse-toi sous la barre en l'envoyant au-dessus de la tête ; réceptionne en squat partiel, bras verrouillés.","Relève-toi, barre au-dessus de la tête."],"k":2},{"id":"Power_Snatch_from_Blocks","n":"Arraché en force depuis des blocs","ne":"Power Snatch from Blocks","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["quadriceps"],"s":["calves","forearms","glutes","hamstrings","lower back","shoulders","traps","triceps"],"i":["Barre chargée sur des blocs, prise large. Pieds sous les hanches légèrement ouverts, hanches basses, poitrine haute, regard devant, épaules juste devant la barre, coudes vers l'extérieur.","Pousse sur l'avant des talons pour décoller la barre des blocs.","Tends explosivement hanches, genoux et chevilles, barre près du corps. À l'extension, hausse les épaules et laisse les coudes partir sur les côtés.","Glisse-toi sous la barre en l'envoyant au-dessus de la tête, pieds juste à l'extérieur des hanches ; réceptionne au-dessus du squat complet, bras tendus.","Barre au-dessus de l'avant des talons, tête et poitrine hautes, relève-toi en poussant sur les talons. Repose la barre sur les blocs."],"k":2},{"id":"Power_Stairs","n":"Escaliers de force","ne":"Power Stairs","e":"other","c":"strongman","l":"intermediate","m":["hamstrings"],"s":["adductors","calves","glutes","lower back","quadriceps","shoulders","traps"],"i":["Épreuve où l'on monte des charges sur des marches ; à l'entraînement, avec un pneu ou un box.","Saisis la charge à deux mains, pieds écartés, tête et poitrine hautes. Pousse sur les talons en tendant genoux et hanches pour la décoller.","En te penchant en arrière, balance la charge sur la marche (40-45 cm environ), en t'aidant des jambes.","Fais 3 à 5 répétitions puis passe à une charge plus lourde, le plus vite possible."],"k":2},{"id":"Preacher_Curl","n":"Curl pupitre","ne":"Preacher Curl","e":"barbell","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Il faut un pupitre et une barre EZ. Prends la barre par les poignées intérieures, paumes vers l'avant (fais-la-toi passer ou prends-la sur le support du pupitre).","Bras et poitrine contre l'appui, barre à hauteur d'épaules : c'est la position de départ.","En inspirant, descends lentement jusqu'à bras tendus.","En expirant, remonte avec les biceps jusqu'à hauteur d'épaules. Serre fort une seconde."],"k":2},{"id":"Preacher_Hammer_Dumbbell_Curl","n":"Curl marteau pupitre haltère","ne":"Preacher Hammer Dumbbell Curl","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":["forearms"],"i":["Bras posés sur le pupitre, un haltère dans chaque main, paumes face à face.","En inspirant, descends lentement jusqu'à bras tendus.","En expirant, remonte avec les biceps jusqu'à hauteur d'épaules.","Serre fort une seconde puis recommence."],"k":2},{"id":"Press_Sit-Up","n":"Sit-up avec développé","ne":"Press Sit-Up","e":"barbell","c":"strength","l":"expert","m":["abdominals"],"s":["chest","shoulders","triceps"],"i":["Allongé sur un banc à abdos, barre posée sur la poitrine, jambes bien calées : c'est la position de départ.","Inspire en serrant abdos et fessiers, puis enroule le buste comme un sit-up en poussant la barre au-dessus de la tête, en expirant.","Redescends le buste en ramenant la barre sur la poitrine, en inspirant."],"k":2},{"id":"Prone_Manual_Hamstring","n":"Étirement manuel des ischios à plat ventre","ne":"Prone Manual Hamstring","e":"other","c":"strength","l":"beginner","m":["hamstrings"],"s":[],"i":["Il faut un partenaire. À plat ventre, jambes tendues ; il pose la main sur ton talon.","Plie le genou pour ramener la jambe ; il résiste, d'abord légèrement puis de plus en plus. Communiquez sur la résistance.","Pause en haut puis redescends pendant qu'il résiste dans l'autre sens."],"k":2},{"id":"Prowler_Sprint","n":"Sprint au prowler","ne":"Prowler Sprint","e":"other","c":"cardio","l":"beginner","m":["hamstrings"],"s":["calves","chest","glutes","quadriceps","shoulders"],"i":["Place le prowler sur une surface adaptée, chargé assez pour demander un effort sans trop te ralentir.","Mains sur les poignées hautes ou basses, bras tendus, penche-toi contre l'appareil.","Bonne posture, pousse dans le sol à petits pas alternés, le plus vite possible sur une courte distance."],"k":2},{"id":"Pull_Through","n":"Tirage entre les jambes à la poulie","ne":"Pull Through","e":"cable","c":"strength","l":"beginner","m":["glutes"],"s":["hamstrings","lower back"],"i":["Debout à un mètre d'une poulie basse munie d'une corde, dos à la machine, câble entre les jambes, pieds écartés.","Penche-toi depuis les hanches en allant chercher la corde entre les jambes, genoux légèrement fléchis. Bras tendus, redresse-toi en poussant les hanches vers l'avant ; tout le mouvement vient des hanches, pas des épaules."],"k":2},{"id":"Pullups","n":"Tractions","ne":"Pullups","e":"body only","c":"strength","l":"beginner","m":["lats"],"s":["biceps","middle back"],"i":["Attrape la barre paumes vers l'avant (prise large, moyenne ou serrée selon le programme).","Bras tendus, recule le buste d'environ 30°, bas du dos cambré, poitrine sortie : c'est la position de départ.","Tire-toi jusqu'à ce que la barre touche le haut de la poitrine en abaissant épaules et bras, en expirant. Serre le dos ; le buste ne bouge pas, les avant-bras ne font que tenir.","Après une seconde, redescends lentement en inspirant jusqu'à bras tendus."],"k":2},{"id":"Push-Up_Wide","n":"Pompes prise large","ne":"Push-Up Wide","e":"body only","c":"strength","l":"beginner","m":["chest"],"s":["abdominals","shoulders","triceps"],"i":["Mains très écartées, en planche sur les orteils et les mains, coudes tendus, corps droit, hanches sans s'affaisser.","Plie les coudes pour descendre la poitrine vers le sol, en inspirant.","Remonte avec les pectoraux en tendant les coudes, en expirant.","Pause en haut puis recommence."],"k":2},{"id":"Push-Ups_-_Close_Triceps_Position","n":"Pompes prise serrée triceps","ne":"Push-Ups - Close Triceps Position","e":"body only","c":"strength","l":"intermediate","m":["triceps"],"s":["chest","shoulders"],"i":["Face au sol, mains plus serrées que les épaules, bras tendus.","Descends jusqu'à ce que la poitrine frôle le sol, en inspirant.","Remonte avec les triceps (et un peu les pectoraux), en expirant.","Pause d'une seconde en haut puis recommence."],"k":2},{"id":"Push-Ups_With_Feet_Elevated","n":"Pompes pieds surélevés","ne":"Push-Ups With Feet Elevated","e":"body only","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Face au sol, mains écartées d'environ 90 cm, bras tendus.","Pose les orteils sur un banc plat ; plus il est haut, plus c'est difficile.","Descends jusqu'à ce que la poitrine frôle le sol, en inspirant.","Remonte avec les pectoraux en expirant et serre.","Pause d'une seconde en haut puis recommence."],"k":2},{"id":"Push-Ups_With_Feet_On_An_Exercise_Ball","n":"Pompes pieds sur swiss ball","ne":"Push-Ups With Feet On An Exercise Ball","e":"exercise ball","c":"strength","l":"intermediate","m":["chest"],"s":["shoulders","triceps"],"i":["Face au sol, mains écartées d'environ 90 cm, bras tendus.","Pose les orteils sur un swiss ball.","Descends jusqu'à ce que la poitrine frôle le sol, en inspirant.","Remonte avec les pectoraux en expirant et serre.","Pause d'une seconde en haut puis recommence."],"k":2},{"id":"Push_Press","n":"Push press","ne":"Push Press","e":"barbell","c":"olympic weightlifting","l":"expert","m":["shoulders"],"s":["quadriceps","triceps"],"i":["Barre posée sur l'avant des épaules. Fléchis légèrement les genoux, buste droit, puis repousse explosivement avec les jambes et utilise cet élan pour pousser la barre au-dessus de la tête, bras tendus. Redescends-la sur les épaules en amortissant avec les jambes."],"k":2},{"id":"Push_Press_-_Behind_the_Neck","n":"Push press derrière la nuque","ne":"Push Press - Behind the Neck","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["shoulders"],"s":["calves","quadriceps","triceps"],"i":["Barre posée sur l'arrière des épaules. Pieds sous les hanches, fléchis légèrement les genoux sans reculer les hanches, puis repousse fort sur les talons pour lancer la barre verticalement.","Avec cet élan, termine en poussant la barre au-dessus de la tête, bras tendus.","Redescends-la en amortissant avec les jambes."],"k":2},{"id":"Push_Up_to_Side_Plank","n":"Pompe vers planche latérale","ne":"Push Up to Side Plank","e":"body only","c":"strength","l":"beginner","m":["chest"],"s":["abdominals","shoulders","triceps"],"i":["En position de pompe sur les orteils, mains juste à l'extérieur des épaules.","Fais une pompe, corps droit.","En remontant, bascule ton poids à gauche et tourne-toi en levant le bras droit vers le plafond (planche latérale).","Repose la main, refais une pompe et tourne-toi de l'autre côté."],"k":2},{"id":"Pushups","n":"Pompes","ne":"Pushups","e":"body only","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Face au sol, mains écartées d'environ 90 cm, bras tendus.","Descends jusqu'à ce que la poitrine frôle le sol, en inspirant.","Expire et remonte en serrant les pectoraux.","Après une courte pause en haut, recommence."],"k":2},{"id":"Pushups_Close_and_Wide_Hand_Positions","n":"Pompes prise serrée et large","ne":"Pushups (Close and Wide Hand Positions)","e":"body only","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Face au sol, corps droit, orteils au sol ; mains plus larges que les épaules (prise large) ou plus serrées (prise serrée), bras tendus.","Descends jusqu'à ce que la poitrine frôle le sol, en inspirant.","Remonte avec les pectoraux en expirant et serre.","Pause d'une seconde en haut puis recommence."],"k":2},{"id":"Pyramid","n":"Pyramide (étirement)","ne":"Pyramid","e":"exercise ball","c":"stretching","l":"beginner","m":["lower back"],"s":["shoulders"],"i":["Roule le buste vers l'avant sur un swiss ball pour que les hanches soient posées dessus et deviennent le point le plus haut du corps.","Mains et pieds au sol, bras et jambes tendus ou légèrement fléchis selon la taille du ballon. Cela renforce aussi la stabilité du tronc et des épaules."],"k":2},{"id":"Quad_Stretch","n":"Étirement des quadriceps","ne":"Quad Stretch","e":"other","c":"stretching","l":"intermediate","m":["quadriceps"],"s":[],"i":["Allongé sur le côté, sangle autour du pied du dessus. Plie le genou et tends la hanche pour amener le pied vers les fesses, sangle en main.","Sangle par-dessus l'épaule ou au-dessus de la tête, tire doucement pour étirer le quadriceps. Tiens 10 à 20 s puis change de côté."],"k":2},{"id":"Quadriceps-SMR","n":"Auto-massage des quadriceps","ne":"Quadriceps-SMR","e":"foam roll","c":"stretching","l":"intermediate","m":["quadriceps"],"s":[],"i":["Allongé face au sol, appui sur les mains ou les avant-bras, rouleau sous le quadriceps d'une jambe, pied décollé, jambe relâchée.","Mets autant de poids que tu le supportes et roule du genou à la hanche, en restant 10 à 30 s sur les points sensibles. Change de côté."],"k":2},{"id":"Quick_Leap","n":"Bond rapide","ne":"Quick Leap","e":"other","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["calves","hamstrings"],"i":["Il faut un box.","Face au box, à 30-60 cm du bord.","Avec les hanches, saute sur le box et réceptionne-toi des deux pieds, jambes fléchies, pieds à plat.","Dès la réception, tends tout le corps et lance les bras au-dessus de la tête pour sauter du box. Amortis avec les jambes."],"k":2},{"id":"Rack_Delivery","n":"Réception en rack","ne":"Rack Delivery","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["shoulders"],"s":["forearms","traps"],"i":["Apprend à poser la barre sur les épaules. Tiens la barre en position d'épouvantail (bras à l'horizontale, avant-bras pendants), prise crochet.","Fais tourner les coudes autour de la barre pour la poser sur les épaules, en relâchant la prise. Épaules en avant pour former un appui, barre contre la gorge.","La barre reste toujours près du corps. Augmente vitesse et charge progressivement."],"k":2},{"id":"Rack_Pull_with_Bands","n":"Rack pull aux élastiques","ne":"Rack Pull with Bands","e":"barbell","c":"powerlifting","l":"intermediate","m":["lower back"],"s":["forearms","glutes","hamstrings","quadriceps","traps"],"i":["Dans une cage, barre posée sur les supports (sous les genoux, au-dessus ou à mi-cuisse). Fixe des élastiques au bas du rack (ou sous des haltères) et à la barre.","Place-toi comme pour un soulevé de terre : pieds sous les hanches, prise largeur d'épaules, dos cambré, hanches en arrière. Prise mixte, crochet ou sangles si c'est lourd.","Regard devant, tends hanches et genoux pour monter la barre jusqu'au verrouillage, épaules en arrière. Repose-la sur les supports."],"k":2},{"id":"Rack_Pulls","n":"Rack pull","ne":"Rack Pulls","e":"barbell","c":"powerlifting","l":"intermediate","m":["lower back"],"s":["forearms","glutes","hamstrings","traps"],"i":["Dans une cage, barre posée sur les supports (sous les genoux, au-dessus ou à mi-cuisse). Place-toi comme pour un soulevé de terre : pieds sous les hanches, prise largeur d'épaules, dos cambré, hanches en arrière. Prise mixte, crochet ou sangles si c'est lourd.","Regard devant, tends hanches et genoux pour monter la barre jusqu'au verrouillage, épaules en arrière.","Repose la barre sur les supports."],"k":2},{"id":"Rear_Leg_Raises","n":"Élévations de jambe arrière","ne":"Rear Leg Raises","e":"body only","c":"stretching","l":"beginner","m":["quadriceps"],"s":[],"i":["À quatre pattes sur un tapis, regard devant, genoux à 90°.","Tends une jambe vers le haut et l'arrière, genou et hanche en extension. 5 à 10 répétitions puis change de côté."],"k":2},{"id":"Recumbent_Bike","n":"Vélo semi-allongé","ne":"Recumbent Bike","e":"machine","c":"cardio","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Installe-toi sur le vélo semi-allongé et règle le siège.","Choisis un programme ou le mode manuel (pédaler allume souvent l'écran). Tu peux entrer âge et poids pour estimer les calories, changer la résistance et suivre ton pouls avec les poignées.","Ce vélo est pratique, bon pour le cœur et doux pour les articulations."],"k":2},{"id":"Return_Push_from_Stance","n":"Poussée retour depuis l'appui","ne":"Return Push from Stance","e":"medicine ball","c":"plyometrics","l":"beginner","m":["shoulders"],"s":["chest","triceps"],"i":["Il faut un partenaire.","En position athlétique (appui sur 2 ou 3 points).","Au signal, place-toi pour recevoir la passe.","Attrape le médecine-ball à deux mains et renvoie-le aussitôt.","Tu peux varier en courant différents trajets."],"k":2},{"id":"Reverse_Band_Bench_Press","n":"Développé couché élastiques inversés","ne":"Reverse Band Bench Press","e":"barbell","c":"powerlifting","l":"intermediate","m":["triceps"],"s":["chest","forearms","lats","middle back","shoulders"],"i":["Banc dans une cage, barre à la bonne hauteur. Accroche des élastiques en haut du rack et à la barre (ils allègent la charge en bas).","Allongé, pieds ramenés sous toi, dos cambré, omoplates serrées et plaquées. Prise couvrant les bagues.","Sors la barre sans avancer les épaules et descends-la vers le bas de la poitrine, barre, poignets et coudes alignés.","Pause au contact, puis pousse fort, coudes rentrés."],"k":2},{"id":"Reverse_Band_Box_Squat","n":"Box squat élastiques inversés","ne":"Reverse Band Box Squat","e":"barbell","c":"powerlifting","l":"intermediate","m":["quadriceps"],"s":["abductors","adductors","calves","forearms","glutes","hamstrings","lower back"],"i":["Dans une cage, box derrière toi. Accroche des élastiques en haut du rack, juste au-dessus de la barre, et à la barre.","Pose la barre sur le haut du dos, serre les omoplates, décroche-la en cambrant le bas du dos et recule. Regard devant.","Gainé, pousse genoux et fesses vers l'extérieur et descends jusqu'à t'asseoir sur le box. Pause, sans rebondir.","Poids sur les talons, relève-toi en menant avec la tête. Repose la barre avec précaution."],"k":2},{"id":"Reverse_Band_Deadlift","n":"Soulevé de terre élastiques inversés","ne":"Reverse Band Deadlift","e":"barbell","c":"powerlifting","l":"expert","m":["lower back"],"s":["abductors","adductors","calves","glutes","hamstrings","quadriceps"],"i":["Barre dans une cage, élastiques accrochés en haut du rack et à la barre.","Barre au-dessus du milieu des pieds, pieds largeur de hanches. Penche-toi et prends la barre à largeur d'épaules.","Inspire fort, descends jusqu'à ce que les tibias touchent la barre. Regard devant, poitrine haute, dos cambré, pousse sur les talons.","Une fois les genoux passés, tire la barre vers toi en avançant les hanches.","Redescends en pliant les hanches jusqu'au sol."],"k":2},{"id":"Reverse_Band_Power_Squat","n":"Squat en force élastiques inversés","ne":"Reverse Band Power Squat","e":"barbell","c":"powerlifting","l":"expert","m":["quadriceps"],"s":["adductors","calves","glutes","hamstrings","lower back"],"i":["Dans une cage, supports et barre à la bonne hauteur. Accroche des élastiques en haut du rack et à la barre.","Pose la barre sur le haut du dos, serre les omoplates, décroche-la et recule, pieds écartés.","Regard devant, gainé, pousse genoux et fesses vers l'extérieur et descends en reculant les hanches, tibias verticaux, jusqu'à passer la parallèle.","Poids sur les talons, remonte en menant avec la tête, gainé jusqu'en haut."],"k":2},{"id":"Reverse_Band_Sumo_Deadlift","n":"Soulevé de terre sumo élastiques inversés","ne":"Reverse Band Sumo Deadlift","e":"barbell","c":"powerlifting","l":"expert","m":["hamstrings"],"s":["abductors","adductors","calves","forearms","glutes","lower back","quadriceps","traps"],"i":["Barre chargée au sol dans une cage, élastiques accrochés en haut du rack et à la barre.","Barre au milieu des pieds, pieds très écartés près des disques. Penche-toi pour saisir la barre, bras sous les épaules, entre les jambes. Épaules relâchées.","Inspire, descends les hanches, regard devant, poitrine haute. Pousse dans le sol en écartant les pieds, poids sur l'arrière des pieds.","Une fois les genoux passés, penche-toi en arrière et avance les hanches vers la barre en serrant les omoplates.","Redescends en pliant les hanches et en contrôlant."],"k":2},{"id":"Reverse_Barbell_Curl","n":"Curl barre inversé","ne":"Reverse Barbell Curl","e":"barbell","c":"strength","l":"beginner","m":["biceps"],"s":["forearms"],"i":["Debout, buste droit, barre en pronation à largeur d'épaules, coudes près du corps : c'est la position de départ.","Bras fixes, monte la barre en expirant jusqu'à hauteur d'épaules. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Reverse_Barbell_Preacher_Curls","n":"Curl pupitre barre inversé","ne":"Reverse Barbell Preacher Curls","e":"e-z curl bar","c":"strength","l":"intermediate","m":["biceps"],"s":["forearms"],"i":["Prends une barre EZ en pronation, largeur d'épaules.","Bras posés sur le pupitre, tendus : c'est la position de départ.","En expirant, monte la barre jusqu'à hauteur d'épaules. Serre une seconde.","Redescends lentement en inspirant jusqu'à bras tendus."],"k":2},{"id":"Reverse_Cable_Curl","n":"Curl inversé à la poulie","ne":"Reverse Cable Curl","e":"cable","c":"strength","l":"beginner","m":["biceps"],"s":["forearms"],"i":["Debout, buste droit, barre d'une poulie basse en pronation, largeur d'épaules, coudes près du corps.","Bras fixes, monte la barre en expirant jusqu'à hauteur d'épaules. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Reverse_Crunch","n":"Crunch inversé","ne":"Reverse Crunch","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé au sol, jambes tendues, bras le long du corps, paumes au sol (ils ne bougent pas).","Monte les jambes : cuisses verticales, pieds joints, tibias parallèles au sol : c'est la position de départ.","Ramène les jambes vers le buste en enroulant le bassin pour décoller les hanches, jusqu'à ce que les genoux touchent la poitrine.","Tiens une seconde puis reviens."],"k":2},{"id":"Reverse_Flyes","n":"Oiseau (écarté inversé)","ne":"Reverse Flyes","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Allongé à plat ventre sur un banc incliné, un haltère dans chaque main, paumes face à face.","Bras tendus vers le sol, perpendiculaires au banc, appui sur l'avant des pieds : c'est la position de départ.","Coudes légèrement fléchis, écarte les haltères sur les côtés en arc en expirant, en serrant les omoplates.","Monte jusqu'à ce que les bras soient parallèles au sol.","Redescends lentement en inspirant."],"k":2},{"id":"Reverse_Flyes_With_External_Rotation","n":"Oiseau avec rotation externe","ne":"Reverse Flyes With External Rotation","e":"dumbbell","c":"strength","l":"intermediate","m":["shoulders"],"s":[],"i":["Allongé à plat ventre sur un banc incliné à 30°.","Un haltère dans chaque main, paumes vers le sol, bras tendus perpendiculaires au banc, coudes légèrement fléchis, appui sur l'avant des pieds : c'est la position de départ.","Écarte les haltères en arc en expirant.","En montant, tourne les poignets de 90° pour finir paumes face à face, en serrant les omoplates.","Monte jusqu'à hauteur de tête.","Redescends lentement en inspirant."],"k":2},{"id":"Reverse_Grip_Bent-Over_Rows","n":"Rowing barre penché prise inversée","ne":"Reverse Grip Bent-Over Rows","e":"barbell","c":"strength","l":"intermediate","m":["middle back"],"s":["biceps","lats","shoulders"],"i":["Debout, barre en supination.","Genoux légèrement fléchis, penche le buste dos droit jusqu'à être presque parallèle au sol, tête haute, barre pendante : c'est la position de départ.","Buste fixe, tire la barre vers toi en expirant, coudes près du corps. Serre le dos une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Reverse_Grip_Triceps_Pushdown","n":"Extension triceps poulie prise inversée","ne":"Reverse Grip Triceps Pushdown","e":"cable","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Fixe une barre (droite ou EZ) à une poulie haute.","Face à la machine, prends-la en supination, largeur d'épaules, et descends-la jusqu'à bras tendus le long du corps, coudes serrés, pieds largeur d'épaules : c'est la position de départ.","Remonte lentement la barre jusqu'à la poitrine en inspirant ; seuls les avant-bras bougent.","Redescends en expirant en contractant fort les triceps."],"k":2},{"id":"Reverse_Hyperextension","n":"Hyperextension inversée","ne":"Reverse Hyperextension","e":"machine","c":"strength","l":"intermediate","m":["hamstrings"],"s":["calves","glutes"],"i":["Charge la machine, cale les pieds entre les boudins et allonge-toi sur l'appui, hanches dans le vide, mains sur les poignées.","Fléchis les hanches en ramenant les jambes vers l'avant.","Puis tends les hanches en lançant les jambes vers l'arrière, sans hyper-extension : arrête-toi avant la fin de ton amplitude.","Ramène les jambes vers l'avant le plus loin possible."],"k":2},{"id":"Reverse_Machine_Flyes","n":"Oiseau à la machine","ne":"Reverse Machine Flyes","e":"machine","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Règle les poignées complètement vers l'arrière, choisis la charge et le siège pour avoir les poignées à hauteur d'épaules. Prends-les paumes vers l'intérieur : c'est la position de départ.","Écarte les bras en demi-cercle sur les côtés et vers l'arrière en contractant l'arrière des épaules.","Bras légèrement fléchis, seules les épaules bougent.","Pause en arrière puis reviens lentement."],"k":2},{"id":"Reverse_Plate_Curls","n":"Curl inversé avec disque","ne":"Reverse Plate Curls","e":"other","c":"strength","l":"beginner","m":["biceps"],"s":["forearms"],"i":["Debout, tiens un disque à deux mains bras tendus, en pronation, doigts sur la face rugueuse, pouces sur la face lisse (vers 11 h et 13 h).","Pieds largeur d'épaules, disque devant le bassin : c'est la position de départ.","Coudes serrés, bras fixes, monte le disque jusqu'à ce que biceps et avant-bras se touchent, en expirant.","Tiens une seconde puis redescends en inspirant."],"k":2},{"id":"Reverse_Triceps_Bench_Press","n":"Développé triceps prise inversée","ne":"Reverse Triceps Bench Press","e":"barbell","c":"strength","l":"intermediate","m":["triceps"],"s":["chest","shoulders"],"i":["Allongé sur un banc plat, prise serrée en supination (environ largeur d'épaules), barre tenue bras tendus et verticaux.","En inspirant, descends lentement jusqu'au milieu de la poitrine, coudes près du corps.","Après une seconde, pousse avec les triceps en expirant et tiens en haut. Descente deux fois plus lente que la montée.","À la fin, repose la barre."],"k":2},{"id":"Rhomboids-SMR","n":"Auto-massage des rhomboïdes","ne":"Rhomboids-SMR","e":"foam roll","c":"stretching","l":"intermediate","m":["middle back"],"s":["traps"],"i":["Allongé sur le dos, rouleau sous le haut du dos, bras croisés devant toi, épaules en avant.","Décolle les hanches pour mettre le poids sur le rouleau. Décale-toi d'un côté puis de l'autre en roulant sur le milieu et le haut du dos, 10 à 30 s sur les points sensibles."],"k":2},{"id":"Rickshaw_Carry","n":"Portage rickshaw","ne":"Rickshaw Carry","e":"other","c":"strongman","l":"intermediate","m":["forearms"],"s":["abdominals","calves","glutes","hamstrings","lower back","quadriceps","traps"],"i":["Place le cadre au départ et charge-le. Debout au centre, saisis les poignées et pousse sur les talons pour le soulever, poitrine et tête hautes, dos droit.","Marche aussitôt d'un bon pas, à pas rapides et contrôlés, en respirant. Pose le cadre à l'arrivée."],"k":2},{"id":"Rickshaw_Deadlift","n":"Soulevé de terre rickshaw","ne":"Rickshaw Deadlift","e":"other","c":"strongman","l":"intermediate","m":["quadriceps"],"s":["forearms","glutes","hamstrings","lower back","traps"],"i":["Charge le cadre et place-toi au centre, pieds largeur de hanches. Penche-toi pour saisir les poignées.","Inspire fort, descends les hanches et plie les genoux. Regard devant, poitrine haute, dos cambré, pousse sur les talons ; en montant, serre les omoplates et avance les hanches.","Redescends en pliant les hanches jusqu'au sol."],"k":2},{"id":"Ring_Dips","n":"Dips aux anneaux","ne":"Ring Dips","e":"other","c":"strength","l":"intermediate","m":["triceps"],"s":["chest","shoulders"],"i":["Un anneau dans chaque main, fais un petit saut pour te retrouver bras verrouillés.","Plie les coudes pour descendre jusqu'à passer sous 90°, sans balancer.","Remonte en tendant les coudes."],"k":2},{"id":"Rocket_Jump","n":"Saut fusée","ne":"Rocket Jump","e":"body only","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["calves","hamstrings"],"i":["Debout détendu, pieds largeur d'épaules, bras près du corps.","Descends à mi-squat puis saute le plus haut possible.","Tends tout le corps en allant chercher le plafond avec les bras. Amortis la réception avec les jambes."],"k":2},{"id":"Rocking_Standing_Calf_Raise","n":"Mollets debout avec bascule","ne":"Rocking Standing Calf Raise","e":"barbell","c":"strength","l":"beginner","m":["calves"],"s":[],"i":["Idéalement dans une cage. Pose la barre sur le haut du dos.","Décroche-la en poussant avec les jambes.","Recule, pieds largeur d'épaules, pointes légèrement ouvertes, tête haute, dos droit, genoux légèrement fléchis.","Monte les talons le plus haut possible en expirant, genoux fixes. Tiens une seconde.","Redescends lentement en inspirant jusqu'à étirer les mollets.","Puis monte les pointes de pieds en contractant l'avant des tibias, en expirant.","Tiens une seconde et redescends."],"k":2},{"id":"Rocky_Pull-Ups_Pulldowns","n":"Tractions / tirages Rocky","ne":"Rocky Pull-Ups/Pulldowns","e":"other","c":"strength","l":"intermediate","m":["lats"],"s":["biceps","middle back","shoulders"],"i":["Attrape la barre paumes vers l'avant en prise large.","Bras tendus, recule le buste d'environ 30°, bas du dos cambré, poitrine sortie.","Tire-toi jusqu'à ce que la barre touche le haut de la poitrine, en expirant. Serre le dos.","Après une seconde, redescends lentement jusqu'à bras tendus.","Puis fais une traction buste droit, barre derrière la nuque, en penchant légèrement la tête vers l'avant.","Redescends et alterne ainsi."],"k":2},{"id":"Romanian_Deadlift","n":"Soulevé de terre roumain","ne":"Romanian Deadlift","e":"barbell","c":"strength","l":"intermediate","m":["hamstrings"],"s":["calves","glutes","lower back"],"i":["Barre au sol devant toi, prise en pronation un peu plus large que les épaules (sangles et plateforme surélevée possibles).","Genoux légèrement fléchis, tibias verticaux, hanches en arrière, dos droit : c'est la position de départ.","Dos et bras toujours droits, monte la barre avec les hanches en expirant, de façon lente et contrôlée.","Une fois debout, redescends en reculant les hanches, genoux à peine fléchis. Inspire au départ, poitrine haute, bloque en descendant et expire en remontant."],"k":2},{"id":"Romanian_Deadlift_from_Deficit","n":"Soulevé de terre roumain en déficit","ne":"Romanian Deadlift from Deficit","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["hamstrings"],"s":["forearms","glutes","lower back","traps"],"i":["Debout, barre tenue bras tendus devant toi ; monte sur une plateforme pour augmenter l'amplitude.","Fléchis légèrement les genoux puis penche-toi depuis les hanches en reculant les fesses au maximum, aussi bas que ta souplesse le permet. Dos toujours droit, barre au contact des jambes ; tu dois sentir une forte tension dans les ischios.","Redresse-toi."],"k":2},{"id":"Rope_Climb","n":"Montée de corde","ne":"Rope Climb","e":"other","c":"strength","l":"intermediate","m":["lats"],"s":["biceps","forearms","middle back","shoulders"],"i":["Attrape la corde à deux mains au-dessus de la tête et tire en faisant un petit saut.","Enroule la corde autour d'une jambe et pince-la avec les pieds. Monte les mains le plus haut possible.","Relâche les pieds et tire avec les bras en ramenant les genoux vers la poitrine.","Recoince la corde avec les pieds, redresse-toi et reprends plus haut. Continue jusqu'en haut.","Pour descendre, desserre les pieds et descends main après main."],"k":2},{"id":"Rope_Crunch","n":"Crunch à la corde","ne":"Rope Crunch","e":"cable","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["À genoux à 30-60 cm d'une poulie munie d'une corde.","Choisis la charge et prends la corde à deux mains au-dessus de la tête, buste droit.","Enroule la colonne pour rapprocher les côtes des jambes en tirant le câble.","Pause en bas puis remonte lentement.","Avec une rotation ou vers le côté, tu cibles les obliques."],"k":2},{"id":"Rope_Jumping","n":"Corde à sauter","ne":"Rope Jumping","e":"other","c":"cardio","l":"intermediate","m":["quadriceps"],"s":["calves","hamstrings"],"i":["Une poignée dans chaque main, corde posée au sol derrière toi. Fais passer la corde au-dessus de la tête puis devant toi, et saute par-dessus quand elle arrive au sol. Trouve un rythme régulier ; varie vitesse et techniques.","La corde à sauter fait travailler la coordination et brûle beaucoup d'énergie."],"k":2},{"id":"Rope_Straight-Arm_Pulldown","n":"Tirage bras tendus à la corde","ne":"Rope Straight-Arm Pulldown","e":"cable","c":"strength","l":"beginner","m":["lats"],"s":[],"i":["Fixe une corde à une poulie haute et choisis la charge. Recule d'un pas ou deux, pieds décalés, corde à deux mains. Penche-toi depuis les hanches, dos droit, bras tendus devant toi vers le haut : c'est la position de départ.","Bras tendus, tire la corde jusqu'aux cuisses en ramenant les épaules.","Pause en bas en serrant le grand dorsal.","Remonte sans reposer la charge complètement."],"k":2},{"id":"Round_The_World_Shoulder_Stretch","n":"Étirement des épaules tour du monde","ne":"Round The World Shoulder Stretch","e":"other","c":"stretching","l":"beginner","m":["shoulders"],"s":["biceps","chest"],"i":["Debout, jambes serrées, tiens un bâton.","Bâton derrière les hanches, prise plus large que les épaules, paumes vers le bas, pouces vers l'extérieur.","Monte lentement les bras derrière toi, sans forcer."],"k":2},{"id":"Rowing_Stationary","n":"Rameur","ne":"Rowing, Stationary","e":"machine","c":"cardio","l":"intermediate","m":["quadriceps"],"s":["biceps","calves","glutes","hamstrings","lower back","middle back"],"i":["Assieds-toi sur le rameur, talons calés au bas des repose-pieds, sangles serrées. Choisis un programme si besoin. Dos droit, penche-toi depuis les hanches.","Trois phases : d'abord tu avances, genoux pliés contre la poitrine, buste légèrement penché, dos droit. Puis tu pousses sur les pieds pour tendre les jambes en ramenant les mains vers le haut du ventre, épaules en arrière. Ce sont surtout les jambes et les hanches qui travaillent, pour ménager le dos.","Le retour : tends les bras, plie les genoux et ramène le corps vers l'avant pour recommencer."],"k":2},{"id":"Runners_Stretch","n":"Étirement du coureur","ne":"Runner's Stretch","e":"other","c":"stretching","l":"beginner","m":["hamstrings"],"s":["calves"],"i":["Debout, recule une jambe et descends le buste vers le sol.","Garde le talon avant au sol (sinon recule davantage la jambe arrière).","Mains de chaque côté du pied avant. Pour accentuer, monte les fesses vers le plafond puis redescends doucement. Étire le fléchisseur de hanche arrière et l'ischio et le fessier avant."],"k":2},{"id":"Running_Treadmill","n":"Course sur tapis","ne":"Running, Treadmill","e":"machine","c":"cardio","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Monte sur le tapis et choisis un programme ou le mode manuel. Tu peux entrer âge et poids pour estimer les calories et régler l'inclinaison pour l'intensité.","Le tapis amortit mieux qu'une course dehors. Garde une bonne posture et ne tiens les poignées que si nécessaire."],"k":2},{"id":"Russian_Twist","n":"Rotations russes","ne":"Russian Twist","e":"body only","c":"strength","l":"intermediate","m":["abdominals"],"s":["lower back"],"i":["Assis au sol, pieds calés sous un appui ou tenus par un partenaire, genoux fléchis.","Monte le buste pour former un V avec les cuisses, bras tendus devant toi, mains jointes : c'est la position de départ.","Tourne le buste vers la droite jusqu'à ce que les bras soient parallèles au sol, en expirant.","Tiens une seconde, reviens au centre, puis fais de même à gauche."],"k":2},{"id":"Sandbag_Load","n":"Chargement de sac de sable","ne":"Sandbag Load","e":"other","c":"strongman","l":"beginner","m":["quadriceps"],"s":["abdominals","biceps","calves","forearms","glutes","hamstrings","lower back","middle back","shoulders","traps"],"i":["Place les sacs de sable à une quinzaine de mètres de la plateforme.","Soulève le sac : c'est peu pratique, entoure-le au maximum de tes bras et tends hanches et genoux pour le monter haut. Pas sur l'épaule en général.","Va le plus vite possible à la plateforme et charge-le en tendant hanches, genoux et chevilles, sans qu'il retombe.","Reviens chercher le sac suivant."],"k":2},{"id":"Scapular_Pull-Up","n":"Traction scapulaire","ne":"Scapular Pull-Up","e":"other","c":"strength","l":"beginner","m":["traps"],"s":["lats","middle back"],"i":["Prends la barre de traction en pronation.","Suspendu, monte de quelques centimètres sans plier les bras, en abaissant les épaules (haussement inversé).","Pause en haut puis redescends lentement."],"k":2},{"id":"Scissor_Kick","n":"Ciseaux de jambes","ne":"Scissor Kick","e":"body only","c":"stretching","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur le dos, bras écartés sur les côtés, paumes au sol (ils ne bougent pas).","Genoux légèrement fléchis, monte les jambes, talons à environ 15 cm du sol : c'est la position de départ.","Monte la jambe gauche à environ 45° pendant que la droite descend à quelques centimètres du sol.","Inverse les jambes, en respirant normalement."],"k":2},{"id":"Scissors_Jump","n":"Sauts en ciseaux","ne":"Scissors Jump","e":"body only","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["glutes","hamstrings"],"i":["En fente, un pied devant genou plié, genou arrière près du sol.","Genou avant au-dessus du milieu du pied. Pousse sur les deux jambes pour sauter le plus haut possible, bras lancés.","En l'air, inverse les jambes.","Réceptionne-toi en fente en amortissant, puis recommence."],"k":2},{"id":"Seated_Band_Hamstring_Curl","n":"Leg curl assis à l'élastique","ne":"Seated Band Hamstring Curl","e":"other","c":"strength","l":"beginner","m":["hamstrings"],"s":[],"i":["Fixe un élastique près du sol et place un banc à 60 cm environ.","Assis sur le banc, élastique derrière les chevilles, jambes tendues : c'est la position de départ.","Plie les genoux pour ramener les pieds vers le banc (penche-toi un peu en arrière si besoin).","Pause puis reviens lentement."],"k":2},{"id":"Seated_Barbell_Military_Press","n":"Développé militaire assis barre","ne":"Seated Barbell Military Press","e":"barbell","c":"strength","l":"intermediate","m":["shoulders"],"s":["triceps"],"i":["Assis sur un banc de développé militaire, barre derrière la tête ; fais-la-toi passer ou prends-la prudemment en pronation, prise plus large que les épaules.","Monte la barre bras tendus au-dessus de la tête, légèrement devant : c'est la position de départ.","Descends lentement la barre jusqu'aux clavicules en inspirant.","Remonte en expirant."],"k":2},{"id":"Seated_Barbell_Twist","n":"Rotation assis avec barre","ne":"Seated Barbell Twist","e":"barbell","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Assis au bout d'un banc plat, barre sur les cuisses, pieds largeur d'épaules.","Prends la barre en pronation, mains plus larges que les épaules, et monte-la au-dessus de la tête.","Descends-la derrière la tête sur la base de la nuque : c'est la position de départ.","Pieds et tête fixes, tourne la taille d'un côté à l'autre pour contracter les obliques, sans forcer l'amplitude, lentement.","Expire en tournant, inspire en revenant au centre."],"k":2},{"id":"Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension","n":"Extension triceps assis penché un bras haltère","ne":"Seated Bent-Over One-Arm Dumbbell Triceps Extension","e":"dumbbell","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Assis au bout d'un banc plat, un haltère dans une main, prise neutre.","Genoux légèrement fléchis, penche le buste dos droit jusqu'à presque l'horizontale, tête haute.","Bras collé au buste, parallèle au sol, avant-bras vers le sol (coude à 90°) : c'est la position de départ.","Bras fixe, tends l'avant-bras avec le triceps jusqu'à ce que tout le bras soit tendu, en expirant.","Après une seconde, redescends lentement en inspirant.","Change de bras."],"k":2},{"id":"Seated_Bent-Over_Rear_Delt_Raise","n":"Oiseau assis penché","ne":"Seated Bent-Over Rear Delt Raise","e":"dumbbell","c":"strength","l":"intermediate","m":["shoulders"],"s":[],"i":["Place deux haltères devant un banc plat.","Assis au bout du banc, jambes serrées, haltères derrière les mollets.","Penche-toi dos droit pour les prendre, paumes face à face : c'est la position de départ.","Buste penché et fixe, coudes légèrement fléchis, monte les haltères sur les côtés jusqu'à l'horizontale, en expirant, sans élan.","Après une seconde, redescends lentement."],"k":2},{"id":"Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension","n":"Extension triceps assis penché deux bras haltère","ne":"Seated Bent-Over Two-Arm Dumbbell Triceps Extension","e":"dumbbell","c":"strength","l":"intermediate","m":["triceps"],"s":[],"i":["Assis au bout d'un banc plat, un haltère dans chaque main, prise neutre.","Genoux légèrement fléchis, penche le buste dos droit jusqu'à presque l'horizontale, tête haute.","Bras collés au buste, parallèles au sol, avant-bras vers le sol : c'est la position de départ.","Bras fixes, tends les avant-bras avec les triceps en expirant.","Après une seconde, redescends lentement en inspirant."],"k":2},{"id":"Seated_Biceps","n":"Étirement biceps assis","ne":"Seated Biceps","e":"body only","c":"stretching","l":"expert","m":["biceps"],"s":["chest","shoulders"],"i":["Assis au sol, genoux pliés, ton partenaire debout derrière toi. Tends les bras derrière toi, paumes face à face ; il tient tes poignets.","Essaie de plier les coudes pendant qu'il t'en empêche.","Après 10 à 20 s, relâche pendant qu'il monte doucement tes poignets pour étirer les biceps. Préviens-le dès que c'est suffisant."],"k":2},{"id":"Seated_Cable_Rows","n":"Tirage horizontal à la poulie","ne":"Seated Cable Rows","e":"cable","c":"strength","l":"beginner","m":["middle back"],"s":["biceps","lats","shoulders"],"i":["Il faut un poste de tirage horizontal avec une poignée en V (prise neutre). Assieds-toi, pieds sur l'appui, genoux légèrement fléchis.","Penche-toi, dos naturel, et attrape la poignée.","Bras tendus, redresse-toi jusqu'à 90° entre buste et jambes, dos légèrement cambré, poitrine sortie, en sentant l'étirement du dos : c'est la position de départ.","Buste fixe, tire la poignée vers le ventre, bras près du corps, en expirant. Serre fort le dos une seconde, puis reviens lentement en inspirant."],"k":2},{"id":"Seated_Cable_Shoulder_Press","n":"Développé épaules assis à la poulie","ne":"Seated Cable Shoulder Press","e":"cable","c":"strength","l":"beginner","m":["shoulders"],"s":["triceps"],"i":["Choisis la charge et assieds-toi, poignées en main, bras à 90° du corps, coudes à 90°, tête et poitrine hautes.","Pousse les poignées au-dessus de la tête en les rapprochant.","Pause en haut puis reviens en gardant la tension.","Variante : dos décollé ou un bras à la fois."],"k":2},{"id":"Seated_Calf_Raise","n":"Mollets assis","ne":"Seated Calf Raise","e":"machine","c":"strength","l":"beginner","m":["calves"],"s":[],"i":["Assis sur la machine, avant des pieds sur la plateforme, talons dans le vide.","Cale le bas des cuisses sous l'appui (réglé à ta taille), mains dessus.","Monte légèrement les talons et retire la sécurité : c'est la position de départ.","Descends lentement les talons jusqu'à étirer les mollets, en inspirant.","Monte les talons le plus haut possible en contractant les mollets, en expirant. Tiens une seconde."],"k":2},{"id":"Seated_Calf_Stretch","n":"Étirement mollets assis","ne":"Seated Calf Stretch","e":"other","c":"stretching","l":"beginner","m":["calves"],"s":["hamstrings","lower back"],"i":["Assis droit sur un tapis.","Plie un genou, pied au sol, pour stabiliser le buste.","Tends l'autre jambe, cheville fléchie.","Avec une sangle, une serviette ou la main, tire les orteils vers toi. Tiens 10 à 20 s puis change de côté."],"k":2},{"id":"Seated_Close-Grip_Concentration_Barbell_Curl","n":"Curl concentration barre prise serrée assis","ne":"Seated Close-Grip Concentration Barbell Curl","e":"barbell","c":"strength","l":"intermediate","m":["biceps"],"s":[],"i":["Assis au bout d'un banc plat, jambes écartées, barre ou barre EZ au sol entre les pieds.","Prends la barre en supination, prise serrée, arrière des bras posé contre l'intérieur des cuisses, bras tendus : c'est la position de départ.","Bras fixes, monte la barre en contractant les biceps, en expirant, jusqu'à hauteur d'épaules. Tiens une seconde.","Redescends lentement en inspirant, sans balancer."],"k":2},{"id":"Seated_Dumbbell_Curl","n":"Curl haltères assis","ne":"Seated Dumbbell Curl","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Assis sur un banc plat, un haltère dans chaque main bras tendus, coudes près du corps.","Paumes vers le corps : c'est la position de départ.","Bras fixes, monte les haltères en tournant les poignets dès qu'ils dépassent les cuisses, pour finir paumes vers le haut, en expirant. Tiens une seconde.","Redescends lentement en inspirant en revenant en prise neutre."],"k":2},{"id":"Seated_Dumbbell_Inner_Biceps_Curl","n":"Curl biceps intérieur haltères assis","ne":"Seated Dumbbell Inner Biceps Curl","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Assis au bout d'un banc plat, un haltère dans chaque main bras tendus, coudes près du corps.","Paumes vers l'intérieur : c'est la position de départ.","Bras fixes, monte les haltères vers l'extérieur et le haut en tournant les paumes, avant-bras alignés avec les épaules.","Continue jusqu'à hauteur d'épaules et serre une seconde.","Redescends lentement en inspirant en revenant en prise neutre."],"k":2},{"id":"Seated_Dumbbell_Palms-Down_Wrist_Curl","n":"Curl poignets paumes vers le bas assis haltère","ne":"Seated Dumbbell Palms-Down Wrist Curl","e":"dumbbell","c":"strength","l":"beginner","m":["forearms"],"s":[],"i":["Pose deux haltères au sol devant un banc plat.","Assis au bord du banc, pieds au sol largeur d'épaules.","Prends les haltères, avant-bras posés sur les cuisses, paumes vers le bas, poignets dans le vide au-delà des genoux.","Monte les poignets en expirant.","Redescends lentement en inspirant ; seuls les poignets bougent.","À la fin, repose les haltères au sol."],"k":2},{"id":"Seated_Dumbbell_Palms-Up_Wrist_Curl","n":"Curl poignets paumes vers le haut assis haltère","ne":"Seated Dumbbell Palms-Up Wrist Curl","e":"dumbbell","c":"strength","l":"beginner","m":["forearms"],"s":[],"i":["Pose deux haltères au sol devant un banc plat.","Assis au bord du banc, pieds au sol largeur d'épaules.","Prends les haltères, avant-bras posés sur les cuisses, paumes vers le haut, poignets dans le vide au-delà des genoux.","Monte les poignets en expirant.","Redescends lentement en inspirant ; seuls les poignets bougent.","À la fin, repose les haltères au sol."],"k":2},{"id":"Seated_Dumbbell_Press","n":"Développé haltères assis","ne":"Seated Dumbbell Press","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":["triceps"],"i":["Prends deux haltères et assieds-toi sur un banc à dossier, haltères debout sur les cuisses.","Monte-les un par un à hauteur d'épaules en t'aidant des cuisses.","Tourne les poignets paumes vers l'avant : c'est la position de départ.","Pousse les haltères vers le haut en expirant jusqu'à ce qu'ils se touchent.","Après une seconde, redescends lentement en inspirant."],"k":2},{"id":"Seated_Flat_Bench_Leg_Pull-In","n":"Genoux à la poitrine assis sur banc","ne":"Seated Flat Bench Leg Pull-In","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Assis sur un banc, jambes tendues devant toi un peu sous l'horizontale, mains sur les côtés du banc, buste penché en arrière à environ 45° : c'est la position de départ.","Ramène les genoux vers toi en rapprochant en même temps le buste, en expirant.","Après une seconde, reviens en inspirant."],"k":2},{"id":"Seated_Floor_Hamstring_Stretch","n":"Étirement ischios assis au sol","ne":"Seated Floor Hamstring Stretch","e":"other","c":"stretching","l":"beginner","m":["hamstrings"],"s":["calves"],"i":["Assis sur un tapis, jambe droite tendue devant toi, jambe gauche pliée, pied contre l'intérieur de la cuisse droite.","Penche-toi depuis les hanches vers la cheville jusqu'à sentir l'étirement de l'ischio. Tiens 15 s puis change de côté."],"k":2},{"id":"Seated_Front_Deltoid","n":"Étirement deltoïde avant assis","ne":"Seated Front Deltoid","e":"body only","c":"stretching","l":"expert","m":["shoulders"],"s":["chest"],"i":["Assis droit au sol, jambes pliées, ton partenaire debout derrière toi. Bras tendus sur les côtés, paumes vers le sol, ramène-les le plus en arrière possible ; il tient tes poignets.","Coudes tendus, essaie de ramener les bras vers l'avant pendant 10 à 20 s pendant qu'il t'en empêche.","Relâche et laisse-le accentuer doucement l'étirement des épaules et de la poitrine. Tiens 10 à 20 s."],"k":2},{"id":"Seated_Glute","n":"Étirement fessier assis","ne":"Seated Glute","e":"body only","c":"stretching","l":"expert","m":["glutes"],"s":["adductors"],"i":["Assis, genoux pliés, croise une cheville sur le genou opposé ; ton partenaire derrière toi. Penche-toi en avant pendant qu'il tient tes épaules.","Essaie de repousser le buste en arrière pendant 10 à 20 s pendant qu'il t'en empêche.","Relâche pendant qu'il pousse doucement ton buste vers l'avant pendant 10 à 20 s."],"k":2},{"id":"Seated_Good_Mornings","n":"Good morning assis","ne":"Seated Good Mornings","e":"barbell","c":"powerlifting","l":"intermediate","m":["lower back"],"s":["glutes"],"i":["Place un box dans une cage, supports à la bonne hauteur. Passe sous la barre et pose-la sur l'arrière des épaules, omoplates serrées.","Décroche la barre en cambrant le bas du dos, regard devant, gainé, et descends jusqu'à t'asseoir sur le box : c'est la position de départ.","Barre serrée, penche-toi en avant depuis les hanches le plus possible. Avec les supports à hauteur de la parallèle, tu sais quand t'arrêter et tu es en sécurité.","Pause juste au-dessus des supports puis redresse le buste."],"k":2},{"id":"Seated_Hamstring","n":"Étirement ischios assis","ne":"Seated Hamstring","e":"other","c":"stretching","l":"expert","m":["hamstrings"],"s":["calves"],"i":["Assis, jambes tendues, ton partenaire derrière toi. Penche-toi en avant pendant qu'il tient tes épaules.","Essaie de repousser le buste en arrière pendant 10 à 20 s pendant qu'il t'en empêche.","Relâche pendant qu'il pousse doucement ton buste vers l'avant pendant 10 à 20 s."],"k":2},{"id":"Seated_Hamstring_and_Calf_Stretch","n":"Étirement ischios et mollets assis","ne":"Seated Hamstring and Calf Stretch","e":"other","c":"stretching","l":"intermediate","m":["hamstrings"],"s":["calves"],"i":["Passe une sangle autour d'un pied, assis jambes tendues.","Légèrement penché en avant, tire la sangle pour ramener les orteils vers toi. Tiens 10 à 20 s puis change de jambe."],"k":2},{"id":"Seated_Head_Harness_Neck_Resistance","n":"Résistance du cou au harnais assis","ne":"Seated Head Harness Neck Resistance","e":"other","c":"strength","l":"intermediate","m":["neck"],"s":[],"i":["Pose un harnais de nuque lesté au sol au bout d'un banc plat. Assis au bout du banc, pieds plus larges que les épaules, pointes ouvertes.","Penche le buste presque à l'horizontale et place le harnais autour de la tête, charges encore au sol. Redresse le buste presque à la verticale en tenant la charge ; tête et buste légèrement penchés vers l'avant.","Mains sur les genoux : c'est la position de départ.","Baisse lentement la tête jusqu'à toucher le haut de la poitrine avec le menton, en inspirant.","Remonte en expirant."],"k":2},{"id":"Seated_Leg_Curl","n":"Leg curl assis","ne":"Seated Leg Curl","e":"machine","c":"strength","l":"beginner","m":["hamstrings"],"s":[],"i":["Règle la machine à ta taille et assieds-toi, dos contre le dossier.","Arrière des jambes sur le boudin (quelques centimètres sous les mollets), appui serré sur les cuisses au-dessus des genoux, mains sur les poignées, jambes tendues : c'est la position de départ.","En expirant, ramène le boudin le plus loin possible sous les cuisses en pliant les genoux, buste fixe. Tiens une seconde.","Reviens lentement en inspirant."],"k":2},{"id":"Seated_Leg_Tucks","n":"Genoux groupés assis","ne":"Seated Leg Tucks","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Assis sur un banc, jambes tendues devant toi un peu sous l'horizontale, mains sur les côtés du banc, buste penché en arrière à environ 45° : c'est la position de départ.","Ramène les genoux vers toi en rapprochant en même temps le buste, en expirant.","Après une seconde, reviens en inspirant."],"k":2},{"id":"Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl","n":"Curl poignet un bras paume vers le bas assis","ne":"Seated One-Arm Dumbbell Palms-Down Wrist Curl","e":"dumbbell","c":"strength","l":"intermediate","m":["forearms"],"s":[],"i":["Assis sur un banc plat, un haltère dans la main droite.","Pieds à plat, un peu plus larges que les épaules.","Penche-toi et pose l'avant-bras droit sur la cuisse, paume vers le bas, poignet au niveau du genou : c'est la position de départ.","Descends l'haltère le plus bas possible en le tenant fermement, en inspirant.","Remonte-le le plus haut possible en contractant l'avant-bras, en expirant. Tiens une seconde ; seul le poignet bouge.","Change de bras."],"k":2},{"id":"Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl","n":"Curl poignet un bras paume vers le haut assis","ne":"Seated One-Arm Dumbbell Palms-Up Wrist Curl","e":"dumbbell","c":"strength","l":"beginner","m":["forearms"],"s":[],"i":["Assis sur un banc plat, un haltère dans la main droite.","Pieds à plat, un peu plus larges que les épaules.","Penche-toi et pose l'avant-bras droit sur la cuisse, paume vers le haut, poignet au niveau du genou : c'est la position de départ.","Descends l'haltère le plus bas possible en le tenant fermement, en inspirant.","Remonte-le le plus haut possible en contractant l'avant-bras, en expirant. Tiens une seconde ; seul le poignet bouge.","Change de bras."],"k":2},{"id":"Seated_One-arm_Cable_Pulley_Rows","n":"Rowing poulie un bras assis","ne":"Seated One-arm Cable Pulley Rows","e":"cable","c":"strength","l":"intermediate","m":["middle back"],"s":["biceps","lats","traps"],"i":["Assieds-toi au poste de tirage horizontal, pieds sur l'appui, genoux légèrement fléchis.","Penche-toi et attrape la poignée simple main gauche, paume vers le bas.","Bras tendu, redresse-toi jusqu'à 90° entre buste et jambes, dos légèrement cambré, poitrine sortie ; l'autre main sur la taille : c'est la position de départ.","Buste fixe, tire la poignée vers le ventre en tournant le poignet pour finir paume vers toi, en expirant. Serre fort le dos.","Tiens une seconde puis reviens lentement en inspirant en retournant le poignet.","Fais toutes les répétitions puis change de main."],"k":2},{"id":"Seated_Overhead_Stretch","n":"Étirement bras au-dessus de la tête assis","ne":"Seated Overhead Stretch","e":"other","c":"stretching","l":"beginner","m":["abdominals"],"s":[],"i":["Assis droit sur un tapis.","Plantes des pieds jointes, pieds à 15-20 cm devant les hanches.","Une main au sol à côté de toi, l'autre derrière la tête.","Monte le coude vers le plafond en inclinant le buste de l'autre côté. Tiens 10 à 20 s puis change de côté."],"k":2},{"id":"Seated_Palm-Up_Barbell_Wrist_Curl","n":"Curl poignets paumes vers le haut barre assis","ne":"Seated Palm-Up Barbell Wrist Curl","e":"barbell","c":"strength","l":"beginner","m":["forearms"],"s":[],"i":["Barre tenue à deux mains, paumes vers le haut, largeur d'épaules.","Pieds à plat, un peu plus larges que les épaules.","Penche-toi et pose les avant-bras sur les cuisses, paumes vers le haut, poignets au niveau des genoux : c'est la position de départ.","Descends la barre le plus bas possible en inspirant, prise ferme.","Remonte-la le plus haut possible en contractant les avant-bras, en expirant. Tiens une seconde ; seuls les poignets bougent."],"k":2},{"id":"Seated_Palms-Down_Barbell_Wrist_Curl","n":"Curl poignets paumes vers le bas barre assis","ne":"Seated Palms-Down Barbell Wrist Curl","e":"barbell","c":"strength","l":"beginner","m":["forearms"],"s":[],"i":["Barre tenue à deux mains, paumes vers le bas, largeur d'épaules.","Pieds à plat, un peu plus larges que les épaules.","Penche-toi et pose les avant-bras sur les cuisses, paumes vers le bas, poignets au niveau des genoux : c'est la position de départ.","Descends la barre le plus bas possible en inspirant, prise ferme.","Remonte-la le plus haut possible en contractant les avant-bras, en expirant. Tiens une seconde ; seuls les poignets bougent."],"k":2},{"id":"Seated_Side_Lateral_Raise","n":"Élévations latérales assis","ne":"Seated Side Lateral Raise","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Prends deux haltères et assieds-toi au bout d'un banc plat, pieds bien au sol, haltères le long du corps, paumes vers l'intérieur.","Sans élan, monte les haltères sur les côtés, coudes légèrement fléchis, mains légèrement inclinées comme pour verser un verre, jusqu'à l'horizontale, en expirant. Pause en haut.","Redescends lentement en inspirant."],"k":2},{"id":"Seated_Triceps_Press","n":"Développé triceps assis","ne":"Seated Triceps Press","e":"dumbbell","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Assis sur un banc à dossier, tiens un haltère à deux mains au-dessus de la tête, bras tendus (fais-le-toi passer s'il est lourd), le disque dans les paumes, pouces autour.","Bras verticaux près de la tête, coudes rentrés, descends l'haltère en arc derrière la tête jusqu'à ce que les avant-bras touchent les biceps, en inspirant. Seuls les avant-bras bougent.","Remonte avec les triceps en expirant."],"k":2},{"id":"Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl","n":"Curl poignets poulie basse deux bras assis","ne":"Seated Two-Arm Palms-Up Low-Pulley Wrist Curl","e":"cable","c":"strength","l":"beginner","m":["forearms"],"s":[],"i":["Place un banc devant une poulie basse munie d'une barre.","Recule le banc pour que le câble soit en tension quand la barre est sur tes cuisses.","Prends la barre à deux mains, paumes vers le haut, largeur d'épaules.","Assieds-toi, pieds au sol largeur d'épaules.","Penche-toi, avant-bras sur les cuisses, poignets au-dessus des genoux : c'est la position de départ.","Descends la barre le plus bas possible en inspirant, prise ferme.","Remonte-la le plus haut possible en contractant les avant-bras ; seuls les poignets bougent.","Après une seconde, redescends en inspirant."],"k":2},{"id":"See-Saw_Press_Alternating_Side_Press","n":"Développé en balançoire (alterné latéral)","ne":"See-Saw Press (Alternating Side Press)","e":"dumbbell","c":"strength","l":"intermediate","m":["shoulders"],"s":["abdominals","triceps"],"i":["Debout, un haltère dans chaque main.","Monte les haltères à hauteur d'épaules, paumes tournées vers toi (comme pour un développé Arnold) : c'est la position de départ.","Pousse le bras gauche au-dessus de la tête en tournant la paume vers l'avant, coude vers l'extérieur, tout en te penchant depuis la hanche vers la droite, comme pour attraper quelque chose en hauteur à droite avec la main gauche. Expire.","En haut, inspire, puis enchaîne de l'autre côté."],"k":2},{"id":"Shotgun_Row","n":"Rowing fusil (shotgun row)","ne":"Shotgun Row","e":"cable","c":"strength","l":"beginner","m":["lats"],"s":["biceps","middle back"],"i":["Fixe une poignée simple à une poulie basse.","Choisis la charge et recule d'un pas ou deux en fente large, bras tendu, épaule en avant : c'est la position de départ.","Ramène l'épaule en arrière et plie le coude en tournant la paume vers le haut pendant que tu tires.","Après une courte pause, reviens."],"k":2},{"id":"Shoulder_Circles","n":"Cercles d'épaules","ne":"Shoulder Circles","e":"other","c":"stretching","l":"beginner","m":["shoulders"],"s":["traps"],"i":["Épaules relâchées, bras le long du corps (ou sur les cuisses si tu es assis), fais rouler doucement les épaules vers l'avant, le haut, l'arrière et le bas.","Change de sens. Une épaule à la fois ou les deux ensemble."],"k":2},{"id":"Shoulder_Press_-_With_Bands","n":"Développé épaules aux élastiques","ne":"Shoulder Press - With Bands","e":"bands","c":"strength","l":"beginner","m":["shoulders"],"s":["triceps"],"i":["Debout sur un élastique, tension dès bras tendus. Monte les poignées à hauteur d'épaules.","Tourne les poignets paumes vers l'avant, coudes pliés, bras dans l'alignement du buste : c'est la position de départ.","En expirant, pousse les poignées jusqu'à bras tendus au-dessus de la tête, puis redescends."],"k":2},{"id":"Shoulder_Raise","n":"Élévation des épaules","ne":"Shoulder Raise","e":"other","c":"stretching","l":"beginner","m":["shoulders"],"s":["lats"],"i":["Bras relâchés le long du corps, monte les épaules vers les oreilles puis redescends-les."],"k":2},{"id":"Shoulder_Stretch","n":"Étirement des épaules","ne":"Shoulder Stretch","e":"other","c":"stretching","l":"beginner","m":["shoulders"],"s":[],"i":["Passe le bras gauche tendu devant le corps et tiens-le avec l'autre bras. Tiens 15 à 20 s puis change de côté."],"k":2},{"id":"Side-Lying_Floor_Stretch","n":"Étirement allongé sur le côté","ne":"Side-Lying Floor Stretch","e":"other","c":"stretching","l":"beginner","m":["lats"],"s":[],"i":["Allongé sur le côté gauche, genou gauche plié devant toi pour stabiliser le buste, abdos engagés.","Tends la jambe droite, pied posé au sol derrière la gauche. Tends le bras droit au-dessus de la tête et tire doucement le poignet droit pour étirer tout le côté droit. Change de côté."],"k":2},{"id":"Side_Bridge","n":"Gainage latéral","ne":"Side Bridge","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":["shoulders"],"i":["Allongé sur le côté, appui sur l'avant-bras (coude sous l'épaule) et le bord du pied, jambes tendues. Décolle les hanches pour aligner le corps de la tête aux pieds et tiens la position. Change de côté."],"k":2},{"id":"Side_Hop-Sprint","n":"Saut latéral puis sprint","ne":"Side Hop-Sprint","e":"other","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["abductors","adductors","calves","hamstrings"],"i":["Debout à côté d'un plot ou d'une petite haie.","Saute latéralement par-dessus puis rebondis aussitôt pour revenir au départ.","Enchaîne les sauts le plus vite possible, puis sprinte sur une courte distance après le dernier."],"k":2},{"id":"Side_Jackknife","n":"Canif latéral","ne":"Side Jackknife","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur le côté, jambes tendues, main du dessus derrière la tête. Monte en même temps le buste et les jambes sur le côté pour rapprocher le coude des hanches en contractant les obliques. Redescends lentement. Change de côté."],"k":2},{"id":"Side_Lateral_Raise","n":"Élévations latérales","ne":"Side Lateral Raise","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Debout, buste droit, un haltère dans chaque main le long du corps, paumes vers toi : c'est la position de départ.","Sans élan, monte les haltères sur les côtés, coudes légèrement fléchis, mains légèrement inclinées comme pour verser un verre, jusqu'à l'horizontale, en expirant. Pause une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Side_Laterals_to_Front_Raise","n":"Élévations latérales puis frontales","ne":"Side Laterals to Front Raise","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":["traps"],"i":["Debout, un haltère dans chaque main le long du corps.","Coudes légèrement fléchis, monte les haltères devant toi jusqu'à hauteur d'épaules, sans élan.","En haut, écarte-les sur les côtés, bras tendus.","Redescends en contrôlant.","À la répétition suivante, monte-les sur les côtés puis ramène-les devant toi.","Redescends."],"k":2},{"id":"Side_Leg_Raises","n":"Élévations de jambe latérales","ne":"Side Leg Raises","e":"body only","c":"stretching","l":"beginner","m":["adductors"],"s":[],"i":["Debout à côté d'une chaise, tiens-toi si besoin, sur une jambe.","Jambe tendue, écarte l'autre sur le côté le plus loin possible puis laisse-la redescendre en croisant devant la jambe d'appui.","Balance 5 à 10 fois en augmentant l'amplitude."],"k":2},{"id":"Side_Lying_Groin_Stretch","n":"Étirement de l'aine allongé sur le côté","ne":"Side Lying Groin Stretch","e":"other","c":"stretching","l":"beginner","m":["adductors"],"s":["hamstrings"],"i":["Allongé sur le côté droit, genou droit plié devant toi pour stabiliser le buste.","Tête sur la main ou l'épaule droite. Monte la jambe gauche et tiens-la derrière le genou (plus facile) ou par le pied (plus dur).","Ramène le genou gauche vers l'épaule gauche tout en poussant le pied ou le genou vers le sol. Pour accentuer, tends la jambe gauche. Change de côté."],"k":2},{"id":"Side_Neck_Stretch","n":"Étirement latéral du cou","ne":"Side Neck Stretch","e":"other","c":"stretching","l":"beginner","m":["neck"],"s":[],"i":["Épaules relâchées, incline doucement la tête vers une épaule.","Accentue en tirant doucement sur le côté de la tête avec la main. Change de côté."],"k":2},{"id":"Side_Standing_Long_Jump","n":"Saut en longueur latéral","ne":"Side Standing Long Jump","e":"other","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Debout, pieds largeur de hanches, en position athlétique, tête et poitrine hautes, genoux et hanches légèrement fléchis.","Penche-toi vers la droite et saute le plus loin possible sur le côté en tendant hanches, genoux et chevilles, bras actifs.","Réceptionne-toi dans la même orientation, pieds largeur de hanches, en amortissant."],"k":2},{"id":"Side_To_Side_Chins","n":"Tractions d'un côté à l'autre","ne":"Side To Side Chins","e":"other","c":"strength","l":"intermediate","m":["lats"],"s":["biceps","forearms","middle back","shoulders"],"i":["Attrape la barre paumes vers l'avant, prise large.","Bras tendus, recule le buste d'environ 30°, bas du dos cambré, poitrine sortie : c'est la position de départ.","Tire-toi vers le haut en te penchant vers la gauche jusqu'à ce que la barre frôle le haut de la poitrine, en expirant, sans balancer.","Après une seconde, redescends en inspirant.","Puis tire-toi en te penchant vers la droite.","Redescends en inspirant.","Continue en alternant les côtés."],"k":2},{"id":"Side_Wrist_Pull","n":"Tirage latéral du poignet (étirement)","ne":"Side Wrist Pull","e":"other","c":"stretching","l":"beginner","m":["shoulders"],"s":["forearms","lats"],"i":["Debout, passe le bras gauche devant le corps et tiens le poignet gauche avec la main droite, à hauteur des hanches, bras gauche plié.","Tends doucement le bras en le tirant et en le montant jusqu'à hauteur d'épaule. L'étirement doit se sentir dans le dos, sans forcer sur l'épaule. Change de côté."],"k":2},{"id":"Side_to_Side_Box_Shuffle","n":"Pas chassés autour d'un box","ne":"Side to Side Box Shuffle","e":"other","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["abductors","adductors","calves","hamstrings"],"i":["Debout à côté d'un box, pied gauche posé au milieu.","Saute de l'autre côté du box pour retomber pied droit sur le box et pied gauche au sol, bras actifs.","Continue d'un côté à l'autre."],"k":2},{"id":"Single-Arm_Cable_Crossover","n":"Écarté poulie vis-à-vis un bras","ne":"Single-Arm Cable Crossover","e":"cable","c":"strength","l":"beginner","m":["chest"],"s":[],"i":["Place les poulies en haut, choisis la charge et prends une poignée dans chaque main.","Avance devant les poulies, bras tendus devant toi, mains jointes, buste légèrement penché, pieds décalés : c'est la position de départ.","Bras gauche fixe, laisse le bras droit s'ouvrir sur le côté jusqu'à hauteur d'épaule, coude légèrement fléchi.","Ramène la main au centre.","Tiens une seconde puis fais de même de l'autre côté, en alternant."],"k":2},{"id":"Single-Arm_Linear_Jammer","n":"Landmine jammer un bras","ne":"Single-Arm Linear Jammer","e":"barbell","c":"strength","l":"intermediate","m":["shoulders"],"s":["chest","triceps"],"i":["Place une barre dans un landmine (ou cale un bout dans un coin) et charge-la.","Monte la barre à l'épaule à une ou deux mains, pieds écartés : c'est la position de départ.","Pousse la barre vers le haut en tendant le bras, explosivement, en tendant aussi hanches et genoux.","Reviens à la position de départ."],"k":2},{"id":"Single-Arm_Push-Up","n":"Pompe sur un bras","ne":"Single-Arm Push-Up","e":"body only","c":"strength","l":"intermediate","m":["chest"],"s":["shoulders","triceps"],"i":["Allongé face au sol, mets-toi en appui sur les orteils et un bras, tendu sous l'épaule ; pieds plus écartés qu'une pompe normale.","Bonne posture, l'autre main dans le dos : c'est la position de départ.","Descends en pliant le coude jusqu'à toucher le sol.","Descends lentement et remonte en tendant le bras."],"k":2},{"id":"Single-Cone_Sprint_Drill","n":"Sprint autour d'un plot","ne":"Single-Cone Sprint Drill","e":"other","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Travaille la vitesse d'appuis. Debout à côté d'un plot, un bras devant, un bras derrière.","Fais des appuis très rapides en tournant autour du plot, genoux hauts, bras actifs.","Récupère après trois tours."],"k":2},{"id":"Single-Leg_High_Box_Squat","n":"Squat une jambe sur box haut","ne":"Single-Leg High Box Squat","e":"other","c":"strength","l":"beginner","m":["quadriceps"],"s":["glutes","hamstrings"],"i":["Place un box dans un rack et fixe un élastique ou une corde au-dessus.","Face au box, monte dessus sur une jambe jusqu'à être debout, l'autre jambe dans le vide, en te tenant à l'élastique pour l'équilibre.","Monte et descends sur la même jambe, puis change."],"k":2},{"id":"Single-Leg_Hop_Progression","n":"Progression de sauts sur une jambe","ne":"Single-Leg Hop Progression","e":"other","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["abductors","adductors","calves","hamstrings"],"i":["Aligne des plots devant toi. Debout en équilibre sur une jambe, l'autre genou levé : c'est la position de départ.","Saute en avant par-dessus le plot et retombe sur la même jambe.","Enchaîne d'un plot à l'autre.","Au bout, fais demi-tour et reviens sur l'autre jambe."],"k":2},{"id":"Single-Leg_Lateral_Hop","n":"Saut latéral sur une jambe","ne":"Single-Leg Lateral Hop","e":"other","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["abductors","adductors","calves","hamstrings"],"i":["Debout à côté d'un plot ou d'une petite haie, sur une jambe, genou légèrement fléchi.","Saute latéralement par-dessus le plot.","Retombe sur la même jambe et rebondis aussitôt pour revenir.","Continue d'un côté à l'autre."],"k":2},{"id":"Single-Leg_Leg_Extension","n":"Leg extension une jambe","ne":"Single-Leg Leg Extension","e":"machine","c":"strength","l":"beginner","m":["quadriceps"],"s":[],"i":["Installe-toi sur la machine : boudin contre le bas du tibia (pas sur la cheville), axe aligné avec le genou. Choisis la charge.","Bonne posture, tends complètement une jambe et marque une pause en haut.","Redescends sans reposer la charge, pour garder la tension."],"k":2},{"id":"Single-Leg_Stride_Jump","n":"Saut en foulée une jambe","ne":"Single-Leg Stride Jump","e":"other","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["abductors","adductors","calves","hamstrings"],"i":["Debout à côté d'un box, pied intérieur posé dessus près du bord.","Balance les bras vers le haut en poussant sur la jambe du dessus pour sauter le plus haut possible, en montant le genou opposé.","Réceptionne-toi dans la même position en freinant avec la jambe intérieure."],"k":2},{"id":"Single_Dumbbell_Raise","n":"Élévation un haltère","ne":"Single Dumbbell Raise","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":["forearms","traps"],"i":["Pieds écartés, tiens un haltère à deux mains par le disque, bras tendus devant la taille.","Monte l'haltère au-dessus de la hauteur d'épaules, bras tendus, buste et hanches immobiles.","Redescends et recommence."],"k":2},{"id":"Single_Leg_Butt_Kick","n":"Talons-fesses une jambe","ne":"Single Leg Butt Kick","e":"body only","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["calves","hamstrings"],"i":["Debout sur une jambe, l'autre genou plié et levé.","Saute vers le haut en tendant hanche, genou et cheville de la jambe d'appui.","Plie aussitôt le genou pour amener le talon vers les fesses.","Ramène la jambe sous les hanches et réceptionne-toi. L'autre jambe ne bouge presque pas."],"k":2},{"id":"Single_Leg_Glute_Bridge","n":"Pont fessier une jambe","ne":"Single Leg Glute Bridge","e":"body only","c":"strength","l":"beginner","m":["glutes"],"s":["hamstrings"],"i":["Allongé au sol, pieds à plat, genoux pliés.","Décolle une jambe en ramenant le genou vers la poitrine : c'est la position de départ.","Pousse sur le talon de l'autre jambe pour monter les hanches et décoller les fesses.","Monte au maximum, pause puis redescends."],"k":2},{"id":"Single_Leg_Push-off","n":"Poussée sur une jambe","ne":"Single Leg Push-off","e":"other","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["calves","hamstrings"],"i":["Debout, un pied posé sur un box, talon près du bord.","Pousse sur le pied du haut pour monter le plus haut possible en tendant hanche et genou.","Retombe avec le même pied sur le box, l'autre revenant au sol."],"k":2},{"id":"Sit-Up","n":"Sit-up","ne":"Sit-Up","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé, pieds calés sous un appui ou tenus par un partenaire, genoux pliés.","Mains croisées derrière la tête : c'est la position de départ.","Monte le buste pour former un V avec les cuisses, en expirant.","Tiens une seconde puis redescends en inspirant."],"k":2},{"id":"Sit_Squats","n":"Squats assis","ne":"Sit Squats","e":"other","c":"stretching","l":"beginner","m":["quadriceps"],"s":["abductors","glutes","hamstrings"],"i":["Debout, pieds largeur d'épaules.","Plie genoux et hanches en reculant les fesses.","Descends à mi-chemin, sans atteindre la parallèle, puis remonte vite. 5 à 10 répétitions."],"k":2},{"id":"Skating","n":"Patinage","ne":"Skating","e":"other","c":"cardio","l":"intermediate","m":["quadriceps"],"s":["abductors","adductors","calves","glutes","hamstrings"],"i":["Le roller est une activité ludique qui améliore l'endurance cardio et musculaire ; il demande équilibre et coordination. Apprends à tourner et freiner, et porte des protections.","Patine 30 minutes à allure confortable, ou fais du fractionné : 2 minutes vite toutes les 5 minutes, 3 minutes pour récupérer."],"k":2},{"id":"Sled_Drag_-_Harness","n":"Traîneau tiré au harnais","ne":"Sled Drag - Harness","e":"other","c":"strongman","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Charge le traîneau et attache la sangle de traction (poignées, harnais ou ceinture).","En avant ou en arrière, penche-toi dans le sens de la marche et avance en poussant sur hanches et genoux."],"k":2},{"id":"Sled_Overhead_Backward_Walk","n":"Marche arrière avec traîneau au-dessus de la tête","ne":"Sled Overhead Backward Walk","e":"other","c":"strength","l":"beginner","m":["shoulders"],"s":["calves","middle back","quadriceps"],"i":["Fixe une double poignée au traîneau légèrement chargé.","Face au traîneau, recule jusqu'à tendre la corde. Mains au-dessus de la tête, bras tendus : c'est la position de départ.","Recule en gardant les bras levés, sans à-coups."],"k":2},{"id":"Sled_Overhead_Triceps_Extension","n":"Extension triceps au traîneau","ne":"Sled Overhead Triceps Extension","e":"other","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Fixe une double poignée au traîneau chargé.","Dos au traîneau, avance jusqu'à tendre la corde. Mains jointes au-dessus de la tête, paumes face à face, coudes pliés vers le haut : c'est la position de départ.","Tends les coudes, bras fixes pour isoler les triceps.","Bras tendus, avance d'un pas pour retendre la corde. Pieds décalés pour la stabilité."],"k":2},{"id":"Sled_Push","n":"Poussée de traîneau","ne":"Sled Push","e":"other","c":"strongman","l":"beginner","m":["quadriceps"],"s":["calves","chest","glutes","hamstrings","triceps"],"i":["Charge le traîneau de poussée.","Posture athlétique, penche-toi contre le traîneau bras tendus, mains sur les poignées. Pousse le plus vite possible en tendant hanches et genoux."],"k":2},{"id":"Sled_Reverse_Flye","n":"Oiseau au traîneau","ne":"Sled Reverse Flye","e":"other","c":"strength","l":"beginner","m":["shoulders"],"s":[],"i":["Fixe une double poignée au traîneau légèrement chargé.","Face au traîneau, recule jusqu'à tendre la corde. Poignées bras tendus à hauteur de taille, genoux légèrement fléchis, poitrine et tête hautes : c'est la position de départ.","Coudes tendus, écarte les poignées vers le haut et l'extérieur (oiseau), paumes vers l'avant.","Reviens et recule d'un ou deux pas pour retendre la corde."],"k":2},{"id":"Sled_Row","n":"Rowing au traîneau","ne":"Sled Row","e":"other","c":"strength","l":"beginner","m":["middle back"],"s":["biceps","lats"],"i":["Fixe une double poignée au traîneau chargé. Face au traîneau, recule jusqu'à tendre la corde.","Une poignée dans chaque main, genoux légèrement fléchis, tête et poitrine hautes, bras tendus.","Plie les coudes en serrant les omoplates pour tirer le traîneau vers toi.","Recule d'un ou deux pas pour retendre la corde et recommence."],"k":2},{"id":"Sledgehammer_Swings","n":"Frappes à la masse","ne":"Sledgehammer Swings","e":"other","c":"plyometrics","l":"beginner","m":["abdominals"],"s":["calves","forearms","lats","middle back","shoulders"],"i":["Il faut un pneu et une masse. Debout à environ 60 cm du pneu, pieds décalés, masse en main.","Droitier : main gauche en bas du manche, main droite près de la tête.","En montant la masse, la main droite glisse vers la tête ; en descendant, elle redescend rejoindre la main gauche. Frappe le pneu le plus fort possible et contrôle le rebond.","Fais de même de l'autre côté."],"k":2},{"id":"Smith_Incline_Shoulder_Raise","n":"Élévation d'épaules incliné à la Smith","ne":"Smith Incline Shoulder Raise","e":"barbell","c":"strength","l":"beginner","m":["shoulders"],"s":["chest"],"i":["Place un banc incliné sous la Smith machine, barre réglée pour être atteinte bras presque tendus. Allonge-toi, épaules sous la barre.","Prise en pronation largeur d'épaules, déverrouille la barre et tiens-la au-dessus de toi, coudes légèrement fléchis.","En expirant, monte la barre jusqu'à bras tendus en avançant les épaules.","Après une seconde, redescends en inspirant.","À la fin, reverrouille la barre."],"k":2},{"id":"Smith_Machine_Behind_the_Back_Shrug","n":"Shrug derrière le dos à la Smith","ne":"Smith Machine Behind the Back Shrug","e":"machine","c":"strength","l":"beginner","m":["traps"],"s":["shoulders"],"i":["Barre réglée à hauteur des cuisses, chargée.","Dos à la barre, prends-la en pronation largeur d'épaules et décroche-la ; debout, tête et poitrine hautes, bras tendus.","Monte les épaules bien verticalement, sans plier bras ni poignets.","Après une courte pause, redescends.","À la fin, reverrouille la barre."],"k":2},{"id":"Smith_Machine_Bench_Press","n":"Développé couché à la Smith","ne":"Smith Machine Bench Press","e":"machine","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Place un banc plat sous la Smith machine, barre réglée pour être atteinte bras presque tendus. Allongé, prise en pronation plus large que les épaules, déverrouille la barre et tiens-la bras tendus.","En inspirant, descends lentement jusqu'au milieu de la poitrine.","Après une seconde, pousse avec les pectoraux en expirant. Descente deux fois plus lente que la montée.","À la fin, reverrouille la barre."],"k":2},{"id":"Smith_Machine_Bent_Over_Row","n":"Rowing penché à la Smith","ne":"Smith Machine Bent Over Row","e":"machine","c":"strength","l":"beginner","m":["middle back"],"s":["biceps","lats","shoulders"],"i":["Règle la barre environ 5 cm sous les genoux.","Genoux légèrement fléchis, penche le buste dos droit jusqu'à presque l'horizontale, tête haute.","Prends la barre en pronation et déverrouille-la, bras tendus : c'est la position de départ.","Buste fixe, tire la barre vers toi en expirant, coudes près du corps. Serre le dos une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Smith_Machine_Calf_Raise","n":"Mollets à la Smith","ne":"Smith Machine Calf Raise","e":"machine","c":"strength","l":"beginner","m":["calves"],"s":[],"i":["Place une cale ou un disque sous la barre de la Smith machine et règle la barre à ta hauteur. Monte avec l'avant des pieds sur la cale, barre sur l'arrière des épaules.","Prends la barre et tourne-la pour la déverrouiller : c'est la position de départ.","Monte les talons le plus haut possible, genoux tendus. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Smith_Machine_Close-Grip_Bench_Press","n":"Développé couché prise serrée à la Smith","ne":"Smith Machine Close-Grip Bench Press","e":"machine","c":"strength","l":"beginner","m":["triceps"],"s":["chest","shoulders"],"i":["Place un banc plat sous la Smith machine. Allongé, prise serrée en pronation (environ largeur d'épaules), déverrouille la barre et tiens-la bras tendus.","En inspirant, descends lentement jusqu'au milieu de la poitrine, coudes près du corps.","Après une seconde, pousse avec les triceps en expirant. Descente deux fois plus lente que la montée.","À la fin, reverrouille la barre."],"k":2},{"id":"Smith_Machine_Decline_Press","n":"Développé décliné à la Smith","ne":"Smith Machine Decline Press","e":"machine","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Place un banc décliné dans la Smith machine, barre au-dessus de la poitrine. Charge et installe-toi.","Tourne la barre pour la décrocher et tends les bras, dos légèrement cambré, omoplates serrées : c'est la position de départ.","Plie les bras pour descendre la barre jusqu'à la poitrine.","Courte pause puis remonte.","À la fin, tourne la barre pour la raccrocher."],"k":2},{"id":"Smith_Machine_Hang_Power_Clean","n":"Épaulé suspendu à la Smith","ne":"Smith Machine Hang Power Clean","e":"machine","c":"strength","l":"intermediate","m":["hamstrings"],"s":["glutes","lower back","quadriceps","shoulders","traps"],"i":["Barre réglée à hauteur des genoux, chargée.","Prise en pronation plus large que les épaules, décroche la barre : bras tendus, tête et poitrine hautes, coudes vers l'extérieur, épaules en arrière, hanches en arrière (ischios en tension).","Tends explosivement hanches et genoux, bras tendus.","À l'extension, refléchis hanches et genoux pour descendre sous la barre.","Plie alors les bras et tourne les coudes pour réceptionner la barre sur les épaules.","Relève-toi, barre sur les épaules."],"k":2},{"id":"Smith_Machine_Hip_Raise","n":"Relevé de bassin à la Smith","ne":"Smith Machine Hip Raise","e":"machine","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Place un banc dans la Smith machine et charge la barre. Allongé, plante des pieds contre la barre ; déverrouille-la et tends les jambes (aide-toi des mains si besoin). Tiens les montants pour la stabilité.","Enroule le bassin et la colonne pour décoller les hanches du banc, genoux légèrement fléchis.","Courte pause puis repose les hanches."],"k":2},{"id":"Smith_Machine_Incline_Bench_Press","n":"Développé incliné à la Smith","ne":"Smith Machine Incline Bench Press","e":"machine","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Place un banc incliné sous la Smith machine, haut de la poitrine aligné avec la barre. Prise en pronation plus large que les épaules, déverrouille la barre et tiens-la bras tendus.","En inspirant, descends lentement jusqu'au haut de la poitrine.","Après une seconde, pousse avec les pectoraux en expirant. Descente deux fois plus lente que la montée.","À la fin, reverrouille la barre."],"k":2},{"id":"Smith_Machine_Leg_Press","n":"Presse à cuisses à la Smith","ne":"Smith Machine Leg Press","e":"machine","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Règle la barre de la Smith machine à environ 60 cm du sol, posée sur les sécurités. Chargée, allonge-toi dessous, milieu des pieds contre la barre, genoux ramenés vers la poitrine.","Pousse avec les pieds pour monter la barre en tendant hanches et genoux, sans verrouiller les genoux.","Courte pause en haut puis redescends."],"k":2},{"id":"Smith_Machine_One-Arm_Upright_Row","n":"Rowing menton un bras à la Smith","ne":"Smith Machine One-Arm Upright Row","e":"machine","c":"strength","l":"beginner","m":["shoulders"],"s":["biceps","traps"],"i":["Barre réglée à hauteur des cuisses, chargée.","Prise large, décroche la barre puis lâche l'autre main ; bras tendu, debout, tête et poitrine hautes : c'est la position de départ.","Plie le coude en montant le bras, coude vers l'extérieur, jusqu'à ce que le bras soit parallèle au sol.","Courte pause puis redescends.","À la fin, reverrouille la barre."],"k":2},{"id":"Smith_Machine_Overhead_Shoulder_Press","n":"Développé militaire à la Smith","ne":"Smith Machine Overhead Shoulder Press","e":"machine","c":"strength","l":"beginner","m":["shoulders"],"s":["triceps"],"i":["Place un banc (idéalement à dossier) sous la Smith machine, barre réglée pour être atteinte bras presque tendus, assis.","Assieds-toi légèrement derrière la barre (alignée avec le bout du nez), pieds fixes. Prends-la paumes vers l'avant, déverrouille-la et tends les bras : c'est la position de départ.","Descends lentement la barre jusqu'au niveau du menton en inspirant.","Remonte avec les épaules en expirant."],"k":2},{"id":"Smith_Machine_Pistol_Squat","n":"Squat pistolet à la Smith","ne":"Smith Machine Pistol Squat","e":"machine","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Règle la barre de la Smith machine à ta hauteur et pose-la sur l'arrière des épaules.","Prends-la paumes vers l'avant, déverrouille-la et décroche-la en tendant les jambes.","Avance un pied d'environ 30 cm devant la barre et tends l'autre jambe devant toi, décollée du sol. Regard devant, dos neutre : c'est la position de départ.","Bonne posture, descends en pliant genou et hanche aussi bas que ta souplesse le permet.","Courte pause en bas puis remonte en poussant sur le talon."],"k":2},{"id":"Smith_Machine_Reverse_Calf_Raises","n":"Mollets inversés à la Smith","ne":"Smith Machine Reverse Calf Raises","e":"machine","c":"strength","l":"beginner","m":["calves"],"s":[],"i":["Règle la barre à ta hauteur et place une plateforme juste dessous.","Debout sur la plateforme, talons dessus et avant des pieds dans le vide, pieds largeur d'épaules.","Place les épaules sous la barre et redresse-toi, genoux légèrement fléchis (la barre sert surtout à l'équilibre) : c'est la position de départ.","Monte les pointes de pieds le plus haut possible en expirant, genoux fixes. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Smith_Machine_Squat","n":"Squat à la Smith","ne":"Smith Machine Squat","e":"machine","c":"strength","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings","lower back"],"i":["Règle la barre de la Smith machine à ta hauteur, passe dessous et pose-la sur le haut du dos.","Prends-la paumes vers l'avant, déverrouille-la et décroche-la en poussant avec les jambes.","Pieds largeur d'épaules, pointes légèrement ouvertes, tête haute, dos droit.","Descends lentement jusqu'à un angle un peu inférieur à 90° aux genoux, en inspirant. Genoux dans l'axe des pieds.","Remonte en expirant en poussant sur les talons."],"k":2},{"id":"Smith_Machine_Stiff-Legged_Deadlift","n":"Soulevé de terre jambes tendues à la Smith","ne":"Smith Machine Stiff-Legged Deadlift","e":"machine","c":"strength","l":"beginner","m":["hamstrings"],"s":["glutes","lower back"],"i":["Règle la barre vers le milieu des cuisses et prends-la en pronation, largeur d'épaules (sangles si lourd).","Monte la barre bras tendus, dos droit, pieds largeur d'épaules ou plus serrés, genoux légèrement fléchis : c'est la position de départ.","Genoux fixes, descends la barre jusqu'au-dessus des pieds en te penchant depuis les hanches, dos droit, jusqu'à sentir l'étirement des ischios.","Redresse-toi en poussant les hanches."],"k":2},{"id":"Smith_Machine_Upright_Row","n":"Rowing menton à la Smith","ne":"Smith Machine Upright Row","e":"machine","c":"strength","l":"beginner","m":["traps"],"s":["biceps","middle back","shoulders"],"i":["Règle la barre vers le milieu des cuisses et prends-la en pronation, largeur d'épaules.","Monte la barre bras tendus, dos droit, coudes légèrement fléchis : c'est la position de départ.","Monte la barre près du corps jusqu'au menton avec les épaules, en expirant ; les coudes restent plus hauts que les avant-bras. Pause en haut.","Redescends lentement en inspirant."],"k":2},{"id":"Smith_Single-Leg_Split_Squat","n":"Squat bulgare à la Smith","ne":"Smith Single-Leg Split Squat","e":"machine","c":"strength","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Place un banc plat 60 à 90 cm derrière la Smith machine et règle la barre à ta hauteur. Pose-la sur le haut du dos.","Prends-la paumes vers l'avant, déverrouille-la et décroche-la en poussant avec les jambes.","Un pied légèrement en avant sous la barre, l'autre tendu en arrière, dessus du pied posé sur le banc : c'est la position de départ.","Descends lentement en pliant le genou avant jusqu'à un angle un peu inférieur à 90°, en inspirant, genou dans l'axe du pied.","Remonte en poussant surtout sur le talon, en expirant.","Change de jambe."],"k":2},{"id":"Snatch","n":"Arraché","ne":"Snatch","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["quadriceps"],"s":["biceps","glutes","hamstrings","lower back","shoulders","traps","triceps"],"i":["Pieds largeur d'épaules, barre au-dessus de l'avant des pieds.","Plie les genoux, dos plat, et prends la barre en pronation, prise plus large que les épaules. Descends les hanches comme pour t'asseoir : c'est la position de départ.","Pousse dans le sol et monte la barre près des jambes.","À mi-cuisse, pousse explosivement pour tendre complètement le corps.","Hausse les épaules en montant la barre, coudes vers l'extérieur et au-dessus de la barre le plus longtemps possible.","Très vite, glisse-toi sous la barre en verrouillant les bras au-dessus de la tête, en position de squat.","Relève-toi, pieds alignés, bras tendus, barre au-dessus de la tête."],"k":2},{"id":"Snatch_Balance","n":"Équilibre d'arraché","ne":"Snatch Balance","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings","shoulders","triceps"],"i":["Pieds en position de tirage, barre sur l'arrière des épaules, mains en prise large d'arraché.","Fléchis brusquement les genoux puis repousse, et plonge sous la barre en replaçant les pieds.","Réceptionne la barre bras verrouillés près du bas du squat, buste vertical, hanches entre les jambes.","Descends en squat complet puis relève-toi. Repose la barre prudemment."],"k":2},{"id":"Snatch_Deadlift","n":"Soulevé de terre d'arraché","ne":"Snatch Deadlift","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["hamstrings"],"s":["forearms","glutes","hamstrings","lower back","quadriceps","traps"],"i":["Renforce le premier tirage de l'arraché. Prise large, barre au sol, pieds sous les hanches légèrement ouverts. Descends vers la barre, dos bien droit, regard devant.","Pousse sur les talons pour monter les hanches ; angle du dos constant jusqu'aux genoux.","Puis avance les hanches vers la barre en basculant en arrière. Redescends la barre en faisant l'inverse."],"k":2},{"id":"Snatch_Pull","n":"Tirage d'arraché","ne":"Snatch Pull","e":"barbell","c":"strength","l":"intermediate","m":["hamstrings"],"s":["calves","glutes","lower back","quadriceps","traps"],"i":["Barre au sol contre les tibias, prise large d'arraché. Hanches basses, poids sur les talons, dos droit, regard devant, épaules juste devant la barre.","Premier tirage : pousse sur les talons, angle du dos constant, bras tendus, jusqu'au-dessus des genoux.","Deuxième tirage : à mi-cuisse, tends explosivement hanches, genoux et chevilles comme pour sauter.","Les bras ne tirent pas : en fin de mouvement, le corps est en extension complète, légèrement en arrière, sans prolonger l'extension."],"k":2},{"id":"Snatch_Shrug","n":"Shrug d'arraché","ne":"Snatch Shrug","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["traps"],"s":["forearms","shoulders"],"i":["Prise large, barre suspendue à mi-cuisse (prise crochet ou pronation), dos droit légèrement incliné vers l'avant.","Monte les épaules vers les oreilles. On peut charger plus lourd qu'à l'arraché, mais pas au point de ralentir le mouvement."],"k":2},{"id":"Snatch_from_Blocks","n":"Arraché depuis des blocs","ne":"Snatch from Blocks","e":"barbell","c":"olympic weightlifting","l":"expert","m":["quadriceps"],"s":["calves","forearms","glutes","hamstrings","lower back","shoulders","traps","triceps"],"i":["Barre chargée sur des blocs, prise large. Pieds sous les hanches légèrement ouverts, hanches basses, poitrine haute, regard devant, épaules juste devant la barre, coudes vers l'extérieur.","Pousse sur l'avant des talons pour décoller la barre des blocs.","Tends explosivement hanches, genoux et chevilles, barre près du corps ; à l'extension, hausse les épaules et laisse les coudes partir sur les côtés.","Glisse-toi sous la barre en l'envoyant au-dessus de la tête, pieds juste à l'extérieur des hanches ; réceptionne le plus bas possible, bras tendus.","Relève-toi en poussant sur les talons, puis repose la barre sur les blocs."],"k":2},{"id":"Speed_Band_Overhead_Triceps","n":"Extension triceps rapide à l'élastique","ne":"Speed Band Overhead Triceps","e":"bands","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Fixe un élastique au sol (par exemple au pied d'un banc incliné) ou marche dessus.","Tire l'élastique derrière la tête, prise en pronation, coudes vers le haut : c'est la position de départ.","Tends les coudes, bras fixes.","Pause puis reviens."],"k":2},{"id":"Speed_Box_Squat","n":"Box squat rapide","ne":"Speed Box Squat","e":"barbell","c":"powerlifting","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Fixe des élastiques à la barre et près du sol pour avoir une bonne tension.","Utilise un box à bonne hauteur et une charge qui demande un effort sans ralentir le mouvement (environ 50 à 70 % de ton maximum).","Barre sur le haut du dos, omoplates serrées, dos cambré, tout le corps gainé.","Décroche la barre, place-toi devant le box et assieds-toi en reculant les hanches, en contrôlant la descente.","Courte pause puis relève-toi explosivement."],"k":2},{"id":"Speed_Squats","n":"Squats rapides","ne":"Speed Squats","e":"barbell","c":"strength","l":"expert","m":["quadriceps"],"s":["calves","glutes","hamstrings","lower back"],"i":["Idéalement dans une cage. Pose la barre sur le haut du dos.","Décroche-la en poussant avec les jambes.","Recule, pieds largeur d'épaules, pointes légèrement ouvertes, tête haute, dos droit.","Descends jusqu'à un angle un peu inférieur à 90° aux genoux, en inspirant.","Remonte le plus vite possible en poussant sur les talons, sans élan et sans perdre la technique."],"k":2},{"id":"Spell_Caster","n":"Jeteur de sorts (rotation haltère)","ne":"Spell Caster","e":"dumbbell","c":"strength","l":"beginner","m":["abdominals"],"s":["glutes","shoulders"],"i":["Un haltère dans chaque main en pronation, pieds écartés, hanches et genoux tendus.","Amène les deux haltères d'un côté près de la hanche en tournant le buste.","Bras tendus, haltères parallèles au sol, tourne le buste pour les balancer de l'autre côté.","Continue en alternant."],"k":2},{"id":"Spider_Crawl","n":"Marche de l'araignée","ne":"Spider Crawl","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":["chest","shoulders","triceps"],"i":["En position de pompe, pieds joints, corps droit, bras pliés à 90°.","Décolle un pied, tourne la jambe vers l'extérieur et amène le genou vers le coude, le plus loin possible vers l'avant.","Ramène la jambe et fais de même de l'autre côté."],"k":2},{"id":"Spider_Curl","n":"Curl araignée","ne":"Spider Curl","e":"e-z curl bar","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Pose la barre sur l'assise d'un pupitre, bien en équilibre.","Place-toi de l'autre côté du pupitre, buste et ventre contre l'appui, penché à environ 45°.","Pieds bien posés, bras sur la face intérieure de l'appui.","Prends la barre en supination, largeur d'épaules ou un peu moins.","Monte lentement la barre en expirant. Serre une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Spinal_Stretch","n":"Étirement de la colonne","ne":"Spinal Stretch","e":"other","c":"stretching","l":"beginner","m":["middle back"],"s":["lats","lower back","neck","traps"],"i":["Assis sur une chaise, dos droit, pieds au sol.","Doigts croisés derrière la tête, coudes écartés, menton baissé.","Tourne le haut du corps d'un côté environ 3 fois au maximum, puis penche-toi et tourne pour amener le coude vers le sol à l'intérieur du genou.","Redresse-toi et fais l'autre côté."],"k":2},{"id":"Split_Clean","n":"Épaulé fendu","ne":"Split Clean","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["quadriceps"],"s":["calves","forearms","glutes","hamstrings","lower back","shoulders","traps"],"i":["Barre au sol contre les tibias, prise en pronation juste à l'extérieur des jambes. Hanches basses, dos droit, regard devant, épaules juste devant la barre.","Premier tirage : pousse sur les talons, angle du dos constant, bras tendus, jusqu'au-dessus des genoux.","Deuxième tirage : à mi-cuisse, tends explosivement hanches, genoux et chevilles, bras tendus.","Troisième tirage : haussement d'épaules, coudes hauts, puis tire-toi sous la barre en tournant les coudes.","Réceptionne pieds en fente (un devant, un derrière), barre posée sur l'avant des épaules.","Relève-toi en poussant sur les talons, buste droit, en ramenant les pieds."],"k":2},{"id":"Split_Jerk","n":"Jeté fendu","ne":"Split Jerk","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["quadriceps"],"s":["glutes","hamstrings","shoulders","triceps"],"i":["Debout, barre posée sur l'avant des épaules. Pieds sous les hanches, fléchis légèrement les genoux sans reculer les hanches.","Inverse le plus puissamment possible en poussant sur les talons et écarte la tête du trajet de la barre ; replace vite les pieds.","Pieds en fente, un devant, un derrière, genoux légèrement fléchis. Réceptionne la barre bras verrouillés au-dessus de la tête.","Relève-toi en ramenant les pieds."],"k":2},{"id":"Split_Jump","n":"Sauts fendus","ne":"Split Jump","e":"body only","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["En fente, un pied devant genou plié, genou arrière près du sol.","Genou avant au-dessus du milieu du pied.","Pousse sur les deux jambes pour sauter le plus haut possible, bras lancés.","En l'air, rapproche les pieds puis replace-les dans la même position à la réception.","Amortis en revenant en fente."],"k":2},{"id":"Split_Snatch","n":"Arraché fendu","ne":"Split Snatch","e":"barbell","c":"olympic weightlifting","l":"expert","m":["hamstrings"],"s":["calves","forearms","glutes","hamstrings","lower back","quadriceps","shoulders","traps","triceps"],"i":["Barre chargée au sol contre les tibias, prise large. Pieds sous les hanches légèrement ouverts, hanches basses, poitrine haute, regard devant, épaules juste devant la barre.","Premier tirage : pousse sur l'avant des talons, angle du dos constant jusqu'aux genoux.","Deuxième tirage : tends explosivement hanches, genoux et chevilles, barre près du corps ; hausse les épaules, coudes sur les côtés.","Glisse-toi sous la barre en l'envoyant au-dessus de la tête, pieds en fente ; réceptionne le plus bas possible, bras tendus.","Relève-toi en ramenant les pieds.","Repose la barre au sol prudemment."],"k":2},{"id":"Split_Squat_with_Dumbbells","n":"Squat fendu haltères","ne":"Split Squat with Dumbbells","e":"dumbbell","c":"strength","l":"beginner","m":["quadriceps"],"s":["glutes","hamstrings"],"i":["En fente, pied arrière surélevé sur un banc, pied avant devant.","Un haltère dans chaque main le long du corps : c'est la position de départ.","Descends en pliant genou et hanche avant, bonne posture, genou dans l'axe du pied.","En bas, remonte en poussant sur le talon avant."],"k":2},{"id":"Split_Squats","n":"Squats fendus","ne":"Split Squats","e":"other","c":"stretching","l":"intermediate","m":["hamstrings"],"s":["calves","glutes","quadriceps"],"i":["Debout. Saute en position de fente (une jambe devant, une derrière), genoux fléchis, hanches légèrement descendues.","Dès la descente, remonte en sautant et inverse les jambes. 5 à 10 fois par jambe."],"k":2},{"id":"Squat_Jerk","n":"Jeté en squat","ne":"Squat Jerk","e":"barbell","c":"strength","l":"expert","m":["quadriceps"],"s":["calves","glutes","hamstrings","shoulders","triceps"],"i":["Debout, barre posée sur l'avant des épaules. Pieds sous les hanches, fléchis légèrement les genoux sans reculer les hanches, puis inverse le plus puissamment possible en écartant la tête du trajet de la barre.","Replace vite les pieds juste à l'extérieur des hanches et réceptionne la barre en squat complet, bras tendus au-dessus de la tête.","Relève-toi en poussant sur les talons, tête et poitrine hautes, puis repose la barre prudemment."],"k":2},{"id":"Squat_with_Bands","n":"Squat aux élastiques","ne":"Squat with Bands","e":"barbell","c":"powerlifting","l":"intermediate","m":["quadriceps"],"s":["adductors","calves","glutes","hamstrings","lower back"],"i":["Fixe les élastiques aux extrémités de la barre et au sol (crochets, rack ou haltères) pour une bonne tension.","Pose la barre sur le haut du dos, serre les omoplates, décroche-la en cambrant le bas du dos et recule. Pieds écartés, regard devant.","Gainé, pousse genoux et fesses vers l'extérieur et descends en reculant les hanches, tibias verticaux, jusqu'à passer la parallèle.","Poids sur les talons, remonte en menant avec la tête, gainé jusqu'en haut."],"k":2},{"id":"Squat_with_Chains","n":"Squat avec chaînes","ne":"Squat with Chains","e":"barbell","c":"powerlifting","l":"intermediate","m":["quadriceps"],"s":["adductors","calves","glutes","hamstrings","lower back"],"i":["Accroche les chaînes aux extrémités de la barre ; quelques maillons restent au sol en haut du mouvement.","Pose la barre sur le haut du dos, serre les omoplates, décroche-la en cambrant le bas du dos et recule. Pieds écartés, regard devant.","Gainé, descends en reculant les hanches, tibias verticaux, jusqu'à passer la parallèle.","Poids sur les talons, remonte en menant avec la tête."],"k":2},{"id":"Squat_with_Plate_Movers","n":"Squat avec déplacement de disques","ne":"Squat with Plate Movers","e":"barbell","c":"strength","l":"intermediate","m":["quadriceps"],"s":["abductors","adductors","calves","glutes","hamstrings"],"i":["Règle la barre juste sous les épaules et pose un disque au sol à 60 cm environ du rack. Pose la barre sur le haut du dos.","Décroche-la en poussant avec les jambes.","Recule, pieds écartés, pointes légèrement ouvertes, un pied sur le disque, tête haute.","Descends lentement jusqu'à un angle un peu inférieur à 90° aux genoux.","Remonte en expirant en poussant sur les talons.","En haut, fais un pas de côté pour rapprocher les pieds de l'autre côté du disque.","Avec le pied intérieur, fais glisser le disque jusqu'à l'endroit où tu étais.","Pose le pied intérieur dessus, pieds écartés, pour la répétition suivante."],"k":2},{"id":"Squats_-_With_Bands","n":"Squats aux élastiques","ne":"Squats - With Bands","e":"bands","c":"strength","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings","lower back"],"i":["Place les deux pieds au milieu d'un élastique, largeur d'épaules, même longueur de chaque côté.","Poignées à hauteur du visage, paumes vers l'avant : c'est la position de départ.","Plie lentement les genoux jusqu'à avoir les cuisses parallèles au sol.","Remonte en poussant sur les talons, en expirant."],"k":2},{"id":"Stairmaster","n":"Simulateur d'escalier","ne":"Stairmaster","e":"machine","c":"cardio","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Monte sur le simulateur d'escalier et choisis un programme ou le mode manuel. Tu peux entrer âge et poids pour estimer les calories.","Monte et descends les jambes à un rythme régulier sans enfoncer les marches jusqu'en bas. Tiens les poignées pour ne pas tomber ; elles permettent aussi de suivre ton pouls.","C'est plus exigeant que la plupart des machines cardio, mais doux pour les articulations."],"k":2},{"id":"Standing_Alternating_Dumbbell_Press","n":"Développé haltères debout alterné","ne":"Standing Alternating Dumbbell Press","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":["triceps"],"i":["Debout, un haltère dans chaque main à hauteur d'épaules, paumes vers l'avant, coudes écartés : c'est la position de départ.","Pousse un haltère droit vers le haut, l'autre reste en place, sans te pencher ni donner d'élan.","Après une courte pause, redescends.","Fais de même avec l'autre bras, en alternant."],"k":2},{"id":"Standing_Barbell_Calf_Raise","n":"Mollets debout barre","ne":"Standing Barbell Calf Raise","e":"barbell","c":"strength","l":"beginner","m":["calves"],"s":[],"i":["Idéalement dans une cage. Pose la barre sur le haut du dos.","Décroche-la en poussant avec les jambes.","Recule, pieds largeur d'épaules, pointes légèrement ouvertes, tête haute, dos droit, genoux légèrement fléchis. Une cale sous l'avant des pieds augmente l'amplitude mais demande plus d'équilibre.","Monte les talons le plus haut possible en expirant, genoux fixes. Tiens une seconde.","Redescends lentement en inspirant jusqu'à étirer les mollets."],"k":2},{"id":"Standing_Barbell_Press_Behind_Neck","n":"Développé nuque debout barre","ne":"Standing Barbell Press Behind Neck","e":"barbell","c":"strength","l":"intermediate","m":["shoulders"],"s":["triceps"],"i":["Idéalement dans une cage pour récupérer la barre facilement. Pose la barre sur l'arrière des épaules.","Décroche-la en poussant avec les jambes.","Recule, pieds largeur d'épaules, dos droit : c'est la position de départ.","Pousse la barre au-dessus de la tête jusqu'à bras tendus en expirant.","Tiens une seconde puis redescends derrière la nuque en inspirant."],"k":2},{"id":"Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension","n":"Extension triceps debout penché un bras haltère","ne":"Standing Bent-Over One-Arm Dumbbell Triceps Extension","e":"dumbbell","c":"strength","l":"beginner","m":["triceps"],"s":["shoulders"],"i":["Un haltère dans une main, paume vers toi, genoux légèrement fléchis, penche le buste dos droit jusqu'à presque l'horizontale, tête haute.","Bras collé au buste et parallèle au sol, avant-bras vers le sol (coude à 90°) : c'est la position de départ.","Bras fixe, tends l'avant-bras avec le triceps jusqu'à ce que tout le bras soit tendu, en expirant.","Après une seconde, redescends lentement en inspirant.","Change de bras."],"k":2},{"id":"Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension","n":"Extension triceps debout penché deux bras haltère","ne":"Standing Bent-Over Two-Arm Dumbbell Triceps Extension","e":"dumbbell","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Un haltère dans chaque main, paumes vers toi, genoux légèrement fléchis, penche le buste dos droit jusqu'à presque l'horizontale, tête haute. Bras collés au buste, avant-bras vers le sol (coudes à 90°) : c'est la position de départ.","Bras fixes, tends les avant-bras avec les triceps en expirant.","Après une seconde, redescends lentement en inspirant."],"k":2},{"id":"Standing_Biceps_Cable_Curl","n":"Curl biceps debout à la poulie","ne":"Standing Biceps Cable Curl","e":"cable","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Debout, buste droit, barre d'une poulie basse en supination, largeur d'épaules, coudes près du corps : c'est la position de départ.","Bras fixes, monte la barre en contractant les biceps, en expirant, jusqu'à hauteur d'épaules. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Standing_Biceps_Stretch","n":"Étirement biceps debout","ne":"Standing Biceps Stretch","e":"other","c":"stretching","l":"beginner","m":["biceps"],"s":["chest","shoulders"],"i":["Mains jointes dans le dos, paumes l'une contre l'autre ; tends les bras puis tourne-les pour avoir les paumes vers le bas.","Monte les bras et tiens jusqu'à sentir l'étirement des biceps."],"k":2},{"id":"Standing_Bradford_Press","n":"Développé Bradford debout","ne":"Standing Bradford Press","e":"barbell","c":"strength","l":"beginner","m":["shoulders"],"s":["triceps"],"i":["Barre chargée dans un rack à hauteur d'épaules, prise en pronation largeur d'épaules, barre posée sur l'avant des épaules : c'est la position de départ.","Pousse la barre au-dessus de la tête sans verrouiller les coudes, en la faisant passer derrière la tête.","Descends-la derrière la tête jusqu'à 90° aux coudes.","Remonte au-dessus de la tête.","Redescends-la devant.","Continue en alternant devant / derrière."],"k":2},{"id":"Standing_Cable_Chest_Press","n":"Développé pectoraux debout à la poulie","ne":"Standing Cable Chest Press","e":"cable","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Règle deux poulies à hauteur de poitrine et choisis la charge. Debout à 30-60 cm devant les câbles, une poignée dans chaque main, pieds décalés pour la stabilité.","Bras à 90°, omoplates serrées : c'est la position de départ.","Corps immobile, tends les bras pour pousser les poignées devant toi en les rapprochant.","Pause puis reviens."],"k":2},{"id":"Standing_Cable_Lift","n":"Levé diagonal à la poulie","ne":"Standing Cable Lift","e":"cable","c":"strength","l":"beginner","m":["abdominals"],"s":["shoulders"],"i":["Fixe une poignée à la poulie la plus basse.","De profil, prends-la d'une main et éloigne-toi d'environ une longueur de bras, câble en tension, bras aligné avec le câble.","Pieds largeur d'épaules, descends en squat et prends la poignée à deux mains, bras tendus.","D'un seul mouvement, tire la poignée vers le haut en diagonale devant toi jusqu'au-dessus de la tête, bras tendus.","Dos droit, bras près du corps, pivote sur le pied arrière et tends les jambes pour une amplitude complète.","Reviens lentement au centre.","Continue jusqu'à l'échec.","Puis fais l'autre côté."],"k":2},{"id":"Standing_Cable_Wood_Chop","n":"Bûcheron à la poulie","ne":"Standing Cable Wood Chop","e":"cable","c":"strength","l":"beginner","m":["abdominals"],"s":["shoulders"],"i":["Fixe une poignée à la poulie la plus haute.","De profil, prends-la d'une main et éloigne-toi d'environ une longueur de bras, câble en tension, bras aligné avec le câble.","Pieds largeur d'épaules, prends la poignée à deux mains, bras tendus.","D'un seul mouvement, tire la poignée vers le bas en diagonale jusqu'au genou avant en tournant le buste, comme un bûcheron.","Dos et bras droits, abdos gainés, pivote sur le pied arrière en pliant les genoux.","Reviens lentement au centre.","Continue jusqu'à l'échec.","Puis fais l'autre côté."],"k":2},{"id":"Standing_Calf_Raises","n":"Mollets debout","ne":"Standing Calf Raises","e":"machine","c":"strength","l":"beginner","m":["calves"],"s":[],"i":["Règle l'appui de la machine à mollets à ta taille.","Épaules sous les appuis, avant des pieds sur la cale, talons dans le vide, pointes vers l'avant. Redresse-toi, genoux légèrement fléchis : c'est la position de départ.","Monte les talons le plus haut possible en expirant, genoux fixes. Tiens une seconde.","Redescends lentement en inspirant jusqu'à étirer les mollets."],"k":2},{"id":"Standing_Concentration_Curl","n":"Curl concentration debout","ne":"Standing Concentration Curl","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":["forearms"],"i":["Haltère dans la main qui travaille, penche-toi en avant, bras pendant vers le sol, coude vers l'extérieur : c'est la position de départ.","Plie le coude pour monter l'haltère, bras fixe. En haut, contracte le biceps et marque une pause.","Redescends."],"k":2},{"id":"Standing_Dumbbell_Calf_Raise","n":"Mollets debout haltères","ne":"Standing Dumbbell Calf Raise","e":"dumbbell","c":"strength","l":"intermediate","m":["calves"],"s":[],"i":["Debout, buste droit, un haltère dans chaque main le long du corps, avant des pieds sur une planche de 5 à 8 cm, talons au sol : c'est la position de départ.","Pointes droites (tout le mollet), vers l'intérieur ou vers l'extérieur, monte les talons en contractant les mollets, en expirant. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Standing_Dumbbell_Press","n":"Développé haltères debout","ne":"Standing Dumbbell Press","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":["triceps"],"i":["Debout, pieds largeur d'épaules, un haltère dans chaque main à hauteur de tête, coudes écartés à environ 90° : c'est la position de départ.","Sans élan des jambes ni te pencher en arrière, pousse les haltères ensemble au-dessus de la tête.","Pause puis redescends lentement."],"k":2},{"id":"Standing_Dumbbell_Reverse_Curl","n":"Curl inversé haltères debout","ne":"Standing Dumbbell Reverse Curl","e":"dumbbell","c":"strength","l":"intermediate","m":["biceps"],"s":["forearms"],"i":["Debout, un haltère dans chaque main en pronation (paumes vers le bas), bras tendus, pieds largeur d'épaules : c'est la position de départ.","Bras fixes, monte les haltères en expirant jusqu'à hauteur d'épaules. Tiens une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head","n":"Élévation frontale haltère bras tendus au-dessus de la tête","ne":"Standing Dumbbell Straight-Arm Front Delt Raise Above Head","e":"dumbbell","c":"strength","l":"intermediate","m":["shoulders"],"s":[],"i":["Haltères devant les cuisses, paumes vers les cuisses.","Bras tendus, coudes légèrement fléchis mais bloqués : c'est la position de départ.","Monte les haltères en arc de cercle jusqu'au-dessus de la tête, bras tendus, en expirant.","Redescends lentement par le même chemin en inspirant."],"k":2},{"id":"Standing_Dumbbell_Triceps_Extension","n":"Extension triceps haltère debout","ne":"Standing Dumbbell Triceps Extension","e":"dumbbell","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Debout, pieds largeur d'épaules, tiens un haltère à deux mains et monte-le au-dessus de la tête bras tendus.","Le disque repose dans tes paumes, pouces autour, paumes vers le plafond : c'est la position de départ.","Bras près de la tête, coudes rentrés et verticaux, descends l'haltère en arc derrière la tête jusqu'à ce que les avant-bras touchent les biceps, en inspirant.","Remonte avec les triceps en expirant."],"k":2},{"id":"Standing_Dumbbell_Upright_Row","n":"Rowing menton haltères debout","ne":"Standing Dumbbell Upright Row","e":"dumbbell","c":"strength","l":"beginner","m":["traps"],"s":["biceps","shoulders"],"i":["Un haltère dans chaque main en pronation, mains un peu plus serrées que les épaules, haltères contre les cuisses, coudes légèrement fléchis, dos droit.","Monte les haltères près du corps jusqu'au menton avec les épaules, en expirant ; les coudes mènent et restent plus hauts que les avant-bras. Pause en haut.","Redescends lentement en inspirant."],"k":2},{"id":"Standing_Elevated_Quad_Stretch","n":"Étirement quadriceps pied surélevé","ne":"Standing Elevated Quad Stretch","e":"other","c":"stretching","l":"beginner","m":["quadriceps"],"s":[],"i":["Debout, dos à un banc ou une marche, à 60-90 cm.","Lève une jambe derrière toi et pose le pied sur la marche (dessus du pied ou avant du pied, comme c'est le plus confortable).","Genou d'appui légèrement fléchi, sans dépasser les orteils. Change de côté."],"k":2},{"id":"Standing_Front_Barbell_Raise_Over_Head","n":"Élévation frontale barre au-dessus de la tête","ne":"Standing Front Barbell Raise Over Head","e":"barbell","c":"strength","l":"intermediate","m":["shoulders"],"s":[],"i":["Debout, barre en main en pronation, mains plus serrées que les épaules.","Pieds largeur d'épaules, coudes légèrement fléchis : c'est la position de départ.","Monte la barre jusqu'au-dessus de la tête en expirant, coudes toujours légèrement fléchis.","Redescends en inspirant."],"k":2},{"id":"Standing_Gastrocnemius_Calf_Stretch","n":"Étirement des mollets (gastrocnémiens) debout","ne":"Standing Gastrocnemius Calf Stretch","e":"other","c":"stretching","l":"beginner","m":["calves"],"s":["hamstrings"],"i":["Pose le talon droit sur une marche, genou tendu, et penche-toi pour attraper les orteils droits avec la main droite. Genou gauche légèrement fléchi, dos droit.","Appui sur la jambe gauche, main gauche sur la cuisse gauche.","Tire les orteils droits vers le genou jusqu'à sentir l'étirement du mollet."],"k":2},{"id":"Standing_Hamstring_and_Calf_Stretch","n":"Étirement ischios et mollets debout","ne":"Standing Hamstring and Calf Stretch","e":"other","c":"stretching","l":"beginner","m":["hamstrings"],"s":[],"i":["Passe une sangle autour d'un pied et avance ce pied.","Plie la jambe arrière, jambe avant tendue ; décolle les orteils avant du sol et penche-toi.","Tire la sangle pour accentuer l'étirement du mollet. Tiens 10 à 20 s puis change de pied."],"k":2},{"id":"Standing_Hip_Circles","n":"Cercles de hanches debout","ne":"Standing Hip Circles","e":"body only","c":"stretching","l":"beginner","m":["abductors"],"s":["adductors"],"i":["Debout sur une jambe, tiens-toi à un appui vertical.","Monte l'autre genou à 90° : c'est la position de départ.","Ouvre la hanche au maximum en dessinant un grand cercle avec le genou.","Fais plusieurs cercles lentement puis change de côté."],"k":2},{"id":"Standing_Hip_Flexors","n":"Étirement fléchisseurs de hanche debout","ne":"Standing Hip Flexors","e":"other","c":"stretching","l":"beginner","m":["quadriceps"],"s":[],"i":["Debout, dos droit, pied gauche légèrement devant le droit.","Plie les deux genoux et décolle le talon arrière en poussant la hanche droite vers l'avant. L'étirement reste modéré car il est difficile de relâcher le muscle en étant dessus. Change de côté."],"k":2},{"id":"Standing_Inner-Biceps_Curl","n":"Curl biceps intérieur debout","ne":"Standing Inner-Biceps Curl","e":"dumbbell","c":"strength","l":"intermediate","m":["biceps"],"s":[],"i":["Debout, un haltère dans chaque main bras tendus, coudes près du corps, pieds largeur d'épaules.","Paumes vers l'intérieur : c'est la position de départ.","Bras fixes, monte les haltères vers l'extérieur en tournant les poignets pour finir paumes vers le haut, en expirant.","Seuls les avant-bras bougent, alignés avec l'extérieur des épaules, jusqu'à hauteur d'épaules.","Serre une seconde.","Redescends lentement en inspirant en revenant en prise neutre."],"k":2},{"id":"Standing_Lateral_Stretch","n":"Étirement latéral debout","ne":"Standing Lateral Stretch","e":"other","c":"stretching","l":"beginner","m":["abdominals"],"s":[],"i":["Pieds un peu plus écartés que les hanches, genoux légèrement fléchis.","Main droite sur la hanche droite pour soutenir le dos.","Lève le bras gauche et pose la main gauche derrière la tête, puis incline le buste vers la droite.","Garde ton poids réparti sur les deux jambes. Change de côté."],"k":2},{"id":"Standing_Leg_Curl","n":"Leg curl debout","ne":"Standing Leg Curl","e":"machine","c":"strength","l":"beginner","m":["hamstrings"],"s":[],"i":["Règle la machine à ta taille, buste penché à 30-45°, boudin derrière la jambe droite (quelques centimètres sous le mollet), avant de la cuisse contre l'appui.","Buste penché, jambe tendue, mains sur les poignées : c'est la position de départ.","En expirant, ramène la jambe droite le plus haut possible sans décoller la cuisse. Tiens une seconde.","Redescends en inspirant.","Fais de même avec la jambe gauche."],"k":2},{"id":"Standing_Long_Jump","n":"Saut en longueur sans élan","ne":"Standing Long Jump","e":"body only","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Idéalement sur du sable ou un sol amortissant, avec de quoi mesurer. Pieds largeur d'épaules, en demi-squat.","Grand balancé de bras et contre-mouvement des jambes, saute le plus loin possible vers l'avant.","Lance les pieds devant toi à la réception.","Mesure la distance et note tes progrès."],"k":2},{"id":"Standing_Low-Pulley_Deltoid_Raise","n":"Élévation deltoïde poulie basse debout","ne":"Standing Low-Pulley Deltoid Raise","e":"cable","c":"strength","l":"beginner","m":["shoulders"],"s":["forearms"],"i":["Debout à droite d'une poulie basse. Main gauche en travers du corps sur la poignée, en pronation, bras devant toi ; main droite sur la machine.","Dos droit, pieds largeur d'épaules : c'est la position de départ.","Monte le bras gauche en travers du corps jusqu'à hauteur d'épaule, en expirant.","Tiens une seconde puis redescends lentement en inspirant.","Change de bras."],"k":2},{"id":"Standing_Low-Pulley_One-Arm_Triceps_Extension","n":"Extension triceps un bras poulie basse debout","ne":"Standing Low-Pulley One-Arm Triceps Extension","e":"cable","c":"strength","l":"intermediate","m":["triceps"],"s":["chest","shoulders"],"i":["Prends la poignée d'une poulie basse main gauche, dos à la machine. Monte la poignée au-dessus de la tête à deux mains, paume vers l'avant, bras vertical, main droite sur le coude gauche : c'est la position de départ.","Bras près de la tête, descends la poignée en arc derrière la tête jusqu'à ce que l'avant-bras touche le biceps, en inspirant.","Remonte avec le triceps en expirant.","Change de bras."],"k":2},{"id":"Standing_Military_Press","n":"Développé militaire debout","ne":"Standing Military Press","e":"barbell","c":"strength","l":"beginner","m":["shoulders"],"s":["triceps"],"i":["Place la barre à hauteur de poitrine sur un rack et prends-la en pronation, plus large que les épaules.","Fléchis légèrement les genoux, pose la barre sur les clavicules et décroche-la. Recule, pieds largeur d'épaules.","Monte la barre au-dessus de la tête bras tendus, légèrement devant : c'est la position de départ.","Descends lentement jusqu'aux clavicules en inspirant.","Remonte en expirant."],"k":2},{"id":"Standing_Olympic_Plate_Hand_Squeeze","n":"Serrage de disque olympique debout","ne":"Standing Olympic Plate Hand Squeeze","e":"other","c":"strength","l":"beginner","m":["forearms"],"s":["biceps"],"i":["Debout, tiens un disque par le rebord dans chaque main, bras tendus, prise neutre, pieds largeur d'épaules.","Laisse glisser les disques jusqu'à avoir les doigts presque ouverts, en inspirant.","Referme les mains pour remonter les disques, en expirant."],"k":2},{"id":"Standing_One-Arm_Cable_Curl","n":"Curl un bras poulie debout","ne":"Standing One-Arm Cable Curl","e":"cable","c":"strength","l":"intermediate","m":["biceps"],"s":[],"i":["Prends la poignée d'une poulie basse, assez loin de la machine pour que le bras porte la charge.","Bras vertical et fixe, coude rentré, paume vers l'avant, l'autre main sur la taille.","Monte lentement la poignée jusqu'à ce que l'avant-bras touche le biceps, en expirant ; seul l'avant-bras bouge.","Serre puis redescends en inspirant.","Change de bras."],"k":2},{"id":"Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench","n":"Curl un bras haltère sur banc incliné debout","ne":"Standing One-Arm Dumbbell Curl Over Incline Bench","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Debout derrière un banc incliné (comme un pareur), un haltère dans une main en supination, bras posé sur le dossier.","L'autre main tient le banc, poitrine contre le haut du dossier, pieds écartés au sol : c'est la position de départ.","Bras fixe, monte l'haltère en contractant le biceps, en expirant, jusqu'à hauteur d'épaule. Tiens une seconde.","Redescends lentement en inspirant.","Change de bras."],"k":2},{"id":"Standing_One-Arm_Dumbbell_Triceps_Extension","n":"Extension triceps un bras haltère debout","ne":"Standing One-Arm Dumbbell Triceps Extension","e":"dumbbell","c":"strength","l":"beginner","m":["triceps"],"s":["chest","shoulders"],"i":["Debout, pieds largeur d'épaules, un haltère dans une main tendu au-dessus de la tête, petit doigt vers le plafond, paume vers l'avant.","C'est la position de départ.","Bras près de la tête et vertical, descends l'haltère en arc derrière la tête jusqu'à ce que l'avant-bras touche le biceps, en inspirant.","Remonte avec le triceps en expirant.","Change de bras."],"k":2},{"id":"Standing_Overhead_Barbell_Triceps_Extension","n":"Extension triceps barre au-dessus de la tête debout","ne":"Standing Overhead Barbell Triceps Extension","e":"barbell","c":"strength","l":"beginner","m":["triceps"],"s":["shoulders"],"i":["Debout, barre ou barre EZ en pronation, mains plus serrées que les épaules, pieds largeur d'épaules.","Monte la barre au-dessus de la tête bras tendus, coudes rentrés : c'est la position de départ.","Bras fixes près de la tête, descends la barre en arc derrière la tête jusqu'à ce que les avant-bras touchent les biceps, en inspirant.","Remonte avec les triceps en expirant."],"k":2},{"id":"Standing_Palm-In_One-Arm_Dumbbell_Press","n":"Développé un bras haltère paume vers l'intérieur debout","ne":"Standing Palm-In One-Arm Dumbbell Press","e":"dumbbell","c":"strength","l":"beginner","m":["shoulders"],"s":["triceps"],"i":["Un haltère dans une main, bras tendu sur le côté, prise neutre ; l'autre main tient un banc incliné pour l'équilibre.","Pieds largeur d'épaules, monte l'haltère jusqu'à 90° au coude, avant-bras vertical, prise neutre tout du long.","Pousse l'haltère jusqu'à bras tendu : c'est la position de départ.","En inspirant, redescends jusqu'à 90° au coude.","Tiens une seconde puis remonte en expirant.","Change de bras."],"k":2},{"id":"Standing_Palms-In_Dumbbell_Press","n":"Développé haltères paumes face à face debout","ne":"Standing Palms-In Dumbbell Press","e":"dumbbell","c":"strength","l":"intermediate","m":["shoulders"],"s":["triceps"],"i":["Un haltère dans chaque main, prise neutre, pieds largeur d'épaules. Monte les haltères jusqu'à 90° aux coudes, avant-bras verticaux : c'est la position de départ.","Prise neutre tout du long, pousse les haltères jusqu'à bras tendus.","Redescends en inspirant jusqu'à 90°."],"k":2},{"id":"Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl","n":"Curl poignets barre derrière le dos debout","ne":"Standing Palms-Up Barbell Behind The Back Wrist Curl","e":"barbell","c":"strength","l":"beginner","m":["forearms"],"s":[],"i":["Debout, barre tenue derrière les fessiers, bras tendus, paumes vers l'arrière, mains largeur d'épaules.","Regard devant, pieds largeur d'épaules : c'est la position de départ.","En expirant, monte la barre en enroulant les poignets vers le plafond ; seuls les poignets bougent.","Tiens une seconde puis redescends en inspirant.","À la fin, repose la barre en pliant les genoux (plus simple de la prendre sur un rack ou qu'on te la passe)."],"k":2},{"id":"Standing_Pelvic_Tilt","n":"Bascule du bassin debout","ne":"Standing Pelvic Tilt","e":"other","c":"stretching","l":"beginner","m":["lower back"],"s":["glutes"],"i":["Pieds largeur de hanches.","Genoux légèrement fléchis, souples.","Bascule le bassin d'avant en arrière plusieurs fois, puis tiens le coccyx vers l'avant pour étirer."],"k":2},{"id":"Standing_Rope_Crunch","n":"Crunch debout à la corde","ne":"Standing Rope Crunch","e":"cable","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Fixe une corde à une poulie haute et choisis la charge.","Dos à la machine, tiens la corde à deux mains par-dessus les épaules, contre le haut de la poitrine : c'est la position de départ.","Enroule la colonne pour descendre la charge le plus bas possible.","Tiens un instant puis reviens."],"k":2},{"id":"Standing_Soleus_And_Achilles_Stretch","n":"Étirement soléaire et tendon d'Achille debout","ne":"Standing Soleus And Achilles Stretch","e":"other","c":"stretching","l":"beginner","m":["calves"],"s":[],"i":["Pieds largeur de hanches, un pied légèrement devant l'autre.","Plie les deux genoux, talon arrière au sol. Change de côté."],"k":2},{"id":"Standing_Toe_Touches","n":"Toucher des orteils debout","ne":"Standing Toe Touches","e":"other","c":"stretching","l":"beginner","m":["hamstrings"],"s":["calves"],"i":["Debout avec de la place devant et derrière toi.","Penche-toi depuis la taille, jambes tendues, et laisse pendre le haut du corps, bras et mains relâchés. Tiens 10 à 20 s."],"k":2},{"id":"Standing_Towel_Triceps_Extension","n":"Extension triceps à la serviette debout","ne":"Standing Towel Triceps Extension","e":"body only","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Debout, pieds largeur d'épaules, bras tendus au-dessus de la tête tenant une extrémité d'une serviette à deux mains, coudes rentrés, paumes face à face : c'est la position de départ.","Ton partenaire tient l'autre extrémité pour résister. Bras près de la tête, descends les mains en arc derrière la tête jusqu'à ce que les avant-bras touchent les biceps, en inspirant.","Remonte avec les triceps en expirant."],"k":2},{"id":"Standing_Two-Arm_Overhead_Throw","n":"Lancer au-dessus de la tête deux bras debout","ne":"Standing Two-Arm Overhead Throw","e":"medicine ball","c":"plyometrics","l":"beginner","m":["shoulders"],"s":["chest","lats"],"i":["Debout, pieds largeur d'épaules, médecine-ball à deux mains. Amène le ballon loin derrière la tête en fléchissant légèrement les genoux et en te penchant en arrière.","Lance violemment le ballon vers l'avant en fléchissant les hanches, avec tout le corps.","Lance-le à un partenaire ou contre un mur et rattrape-le au rebond."],"k":2},{"id":"Star_Jump","n":"Saut en étoile","ne":"Star Jump","e":"body only","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings","shoulders"],"i":["Debout détendu, pieds largeur d'épaules, bras près du corps.","Descends à mi-squat puis saute le plus haut possible en écartant bras et jambes en étoile.","En retombant, ramène bras et jambes et amortis avec les jambes."],"k":2},{"id":"Step-up_with_Knee_Raise","n":"Montée sur banc avec levée de genou","ne":"Step-up with Knee Raise","e":"body only","c":"strength","l":"beginner","m":["glutes"],"s":["hamstrings","quadriceps"],"i":["Face à un box ou un banc adapté, pieds joints.","Monte le pied gauche sur le banc et tends hanche et genou pour te hisser ; en même temps, monte le genou droit le plus haut possible.","Redescends puis recommence avec l'autre jambe."],"k":2},{"id":"Step_Mill","n":"Escalier mécanique","ne":"Step Mill","e":"machine","c":"cardio","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Monte sur l'escalier mécanique et choisis un programme ou le mode manuel. Tu peux entrer âge et poids pour estimer les calories. Fais attention à ne pas trébucher et garde les mains sur les poignées.","Exigeant, bon pour le cœur et plus doux pour les articulations que la course."],"k":2},{"id":"Stiff-Legged_Barbell_Deadlift","n":"Soulevé de terre jambes tendues barre","ne":"Stiff-Legged Barbell Deadlift","e":"barbell","c":"strength","l":"intermediate","m":["hamstrings"],"s":["glutes","lower back"],"i":["Barre en pronation (sangles si lourd).","Debout, buste droit, pieds largeur d'épaules ou plus serrés, genoux légèrement fléchis : c'est la position de départ.","Genoux fixes, descends la barre jusqu'au-dessus des pieds en te penchant depuis les hanches, dos droit, jusqu'à sentir l'étirement des ischios, en inspirant.","Redresse-toi en poussant les hanches, en expirant."],"k":2},{"id":"Stiff-Legged_Dumbbell_Deadlift","n":"Soulevé de terre jambes tendues haltères","ne":"Stiff-Legged Dumbbell Deadlift","e":"dumbbell","c":"strength","l":"beginner","m":["hamstrings"],"s":["glutes","lower back"],"i":["Un haltère dans chaque main le long du corps.","Debout, buste droit, pieds largeur d'épaules ou plus serrés, genoux légèrement fléchis : c'est la position de départ.","Genoux fixes, descends les haltères jusqu'au-dessus des pieds en te penchant, dos droit, jusqu'à sentir l'étirement des ischios.","Redresse-toi en poussant les hanches."],"k":2},{"id":"Stiff_Leg_Barbell_Good_Morning","n":"Good morning jambes tendues barre","ne":"Stiff Leg Barbell Good Morning","e":"barbell","c":"strength","l":"beginner","m":["lower back"],"s":["glutes","hamstrings"],"i":["Idéalement dans une cage. Pose la barre sur l'arrière des épaules (sous la nuque).","Décroche-la en poussant avec les jambes.","Recule, pieds largeur d'épaules, tête haute, dos droit : c'est la position de départ.","Jambes tendues et fixes, penche le buste depuis les hanches jusqu'à l'horizontale, en inspirant.","Redresse-toi en expirant."],"k":2},{"id":"Stomach_Vacuum","n":"Vacuum abdominal","ne":"Stomach Vacuum","e":"body only","c":"stretching","l":"beginner","m":["abdominals"],"s":[],"i":["Debout, pieds largeur d'épaules, mains sur les hanches : c'est la position de départ.","Inspire au maximum puis expire au maximum en rentrant le ventre le plus possible, comme si le nombril touchait la colonne. Tiens.","Une contraction dure environ 20 s, en respirant normalement, puis relâche.","Avec l'entraînement, va jusqu'à 40-60 s.","Fais le nombre de séries prévu."],"k":2},{"id":"Straight-Arm_Dumbbell_Pullover","n":"Pull-over haltère bras tendus","ne":"Straight-Arm Dumbbell Pullover","e":"dumbbell","c":"strength","l":"intermediate","m":["chest"],"s":["lats","shoulders","triceps"],"i":["Pose un haltère debout sur un banc plat.","Allonge-toi en travers du banc, seules les épaules posées, hanches plus basses, pieds au sol, tête dans le vide.","Tiens l'haltère à deux mains au-dessus de la poitrine, bras tendus, paumes contre un disque. Vérifie que l'haltère est bien serré.","Bras tendus, descends l'haltère en arc derrière la tête en inspirant, jusqu'à étirer les pectoraux.","Ramène-le par le même arc en expirant.","Tiens une seconde puis recommence."],"k":2},{"id":"Straight-Arm_Pulldown","n":"Tirage bras tendus à la poulie","ne":"Straight-Arm Pulldown","e":"cable","c":"strength","l":"beginner","m":["lats"],"s":[],"i":["Prends la barre large d'une poulie haute en pronation, plus large que les épaules, et recule d'environ 60 cm.","Penche le buste d'environ 30°, bras tendus devant toi, coudes légèrement fléchis (recule si les bras ne sont pas tendus). Contracte le grand dorsal.","Bras tendus, tire la barre vers le bas jusqu'aux cuisses en contractant le dos, en expirant.","Remonte bras tendus en inspirant."],"k":2},{"id":"Straight_Bar_Bench_Mid_Rows","n":"Rowing barre droite allongé sur banc","ne":"Straight Bar Bench Mid Rows","e":"barbell","c":"strength","l":"beginner","m":["middle back"],"s":["biceps","lats"],"i":["Pose une barre chargée au bout d'un banc. Debout sur le banc derrière la barre, prise moyenne en pronation, hanches en arrière, poitrine haute, dos neutre.","Tire la barre vers le buste en serrant les omoplates, sans à-coup.","Après une courte pause, redescends complètement."],"k":2},{"id":"Straight_Raises_on_Incline_Bench","n":"Élévations bras tendus sur banc incliné","ne":"Straight Raises on Incline Bench","e":"barbell","c":"strength","l":"beginner","m":["shoulders"],"s":["traps"],"i":["Pose une barre au sol au bout d'un banc incliné, côté tête.","Allongé à plat ventre sur le banc, prends la barre en pronation, bras tendus, barre pendante : c'est la position de départ.","Monte la barre devant ta tête, bras tendus.","Redescends."],"k":2},{"id":"Stride_Jump_Crossover","n":"Saut en foulée croisé","ne":"Stride Jump Crossover","e":"other","c":"plyometrics","l":"beginner","m":["quadriceps"],"s":["abductors","adductors","calves","hamstrings"],"i":["Debout à côté d'un box, pied intérieur posé dessus près du bord.","Balance les bras vers le haut en poussant sur la jambe du dessus pour sauter le plus haut possible, en montant le genou opposé.","Retombe de l'autre côté du box, pieds inversés : celui qui était sur le box est au sol, l'autre sur le box.","Recommence pour revenir."],"k":2},{"id":"Sumo_Deadlift","n":"Soulevé de terre sumo","ne":"Sumo Deadlift","e":"barbell","c":"powerlifting","l":"intermediate","m":["hamstrings"],"s":["adductors","forearms","glutes","lower back","middle back","quadriceps","traps"],"i":["Barre chargée au sol, au milieu des pieds ; pieds très écartés, près des disques. Penche-toi pour saisir la barre, bras sous les épaules, entre les jambes (pronation, prise mixte ou crochet). Épaules relâchées.","Inspire, descends les hanches, regard devant, poitrine haute. Pousse dans le sol en écartant les pieds, poids sur l'arrière des pieds, en tendant hanches et genoux.","Une fois les genoux passés, penche-toi en arrière et avance les hanches vers la barre en serrant les omoplates.","Redescends en pliant les hanches et en contrôlant."],"k":2},{"id":"Sumo_Deadlift_with_Bands","n":"Soulevé de terre sumo aux élastiques","ne":"Sumo Deadlift with Bands","e":"barbell","c":"powerlifting","l":"intermediate","m":["hamstrings"],"s":["adductors","forearms","glutes","lower back","middle back","quadriceps","traps"],"i":["Avec des élastiques courts, passe-les sur la barre et glisse les pieds dedans, sous l'arrière des pieds.","Barre au milieu des pieds, pieds très écartés près des disques. Penche-toi et saisis la barre, bras sous les épaules, entre les jambes.","Inspire, descends les hanches, regard devant, poitrine haute, pousse dans le sol en écartant les pieds.","Une fois les genoux passés, penche-toi en arrière et avance les hanches vers la barre.","Redescends en contrôlant."],"k":2},{"id":"Sumo_Deadlift_with_Chains","n":"Soulevé de terre sumo avec chaînes","ne":"Sumo Deadlift with Chains","e":"barbell","c":"powerlifting","l":"intermediate","m":["hamstrings"],"s":["abductors","adductors","forearms","glutes","lower back","middle back","quadriceps","traps"],"i":["Accroche les chaînes aux extrémités de la barre ou pose-les à cheval dessus, loin des disques.","Barre au milieu des pieds, pieds très écartés près des disques. Penche-toi et saisis la barre, bras sous les épaules, entre les jambes. Épaules relâchées.","Inspire, descends les hanches, regard devant, poitrine haute, pousse dans le sol en écartant les pieds.","Une fois les genoux passés, penche-toi en arrière et avance les hanches vers la barre.","Redescends en contrôlant."],"k":2},{"id":"Superman","n":"Superman","ne":"Superman","e":"body only","c":"stretching","l":"beginner","m":["lower back"],"s":["glutes","hamstrings"],"i":["Allongé à plat ventre au sol, bras tendus devant toi : c'est la position de départ.","Décolle en même temps bras, jambes et poitrine et tiens 2 secondes, comme Superman en vol, en serrant le bas du dos, en expirant.","Redescends lentement en inspirant."],"k":2},{"id":"Supine_Chest_Throw","n":"Lancer de poitrine allongé","ne":"Supine Chest Throw","e":"medicine ball","c":"plyometrics","l":"beginner","m":["triceps"],"s":["chest","shoulders"],"i":["Idéal pour les passes sans partenaire ni mur. Allongé sur le dos, genoux pliés.","Ballon sur la poitrine, tenu à deux mains par-dessous.","Lance-le explosivement le plus haut possible au-dessus de toi en tendant les bras.","Rattrape-le à deux mains."],"k":2},{"id":"Supine_One-Arm_Overhead_Throw","n":"Lancer au-dessus de la tête un bras allongé","ne":"Supine One-Arm Overhead Throw","e":"medicine ball","c":"plyometrics","l":"beginner","m":["abdominals"],"s":["chest","lats","shoulders"],"i":["Allongé sur le dos, genoux pliés, ballon tenu d'une main, bras tendu derrière la tête.","Lance le ballon devant toi en te redressant, le plus loin possible, en partant de l'épaule.","Lance-le à un partenaire ou contre un mur."],"k":2},{"id":"Supine_Two-Arm_Overhead_Throw","n":"Lancer au-dessus de la tête deux bras allongé","ne":"Supine Two-Arm Overhead Throw","e":"medicine ball","c":"plyometrics","l":"beginner","m":["abdominals"],"s":["chest","lats","shoulders"],"i":["Allongé sur le dos, genoux pliés.","Ballon tenu à deux mains, bras tendus derrière la tête.","Lance le ballon devant toi en te redressant, le plus loin possible.","Lance-le à un partenaire ou contre un mur."],"k":2},{"id":"Suspended_Fallout","n":"Fallout aux sangles","ne":"Suspended Fallout","e":"other","c":"strength","l":"intermediate","m":["abdominals"],"s":["chest","lower back","shoulders"],"i":["Règle les sangles pour avoir les poignées sous la taille.","Debout, poignées en main, penche-toi en position de pompe inclinée : c'est la position de départ.","Bras tendus, penche-toi davantage en montant les bras au-dessus de la tête, le corps se rapprochant du sol.","Dos neutre, corps droit : seules les épaules bougent.","Pause puis reviens."],"k":2},{"id":"Suspended_Push-Up","n":"Pompes aux sangles","ne":"Suspended Push-Up","e":"other","c":"strength","l":"beginner","m":["chest"],"s":["shoulders","triceps"],"i":["Accroche solidement les sangles en haut d'un rack.","Une poignée dans chaque main, penche-toi en planche de pompe, le plus près possible de l'horizontale, bras tendus.","Buste gainé, descends lentement en pliant les coudes.","Passe sous 90° aux coudes, pause, puis remonte."],"k":2},{"id":"Suspended_Reverse_Crunch","n":"Crunch inversé aux sangles","ne":"Suspended Reverse Crunch","e":"other","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Sangles réglées à environ 30 cm du sol. Mets-toi en planche de pompe, dos au rack.","Pose les pieds dans les poignées, corps droit sans affaisser les hanches : c'est la position de départ.","Ramène les genoux vers le buste en enroulant le bassin et la colonne.","En haut, reviens en contrôlant."],"k":2},{"id":"Suspended_Row","n":"Rowing aux sangles","ne":"Suspended Row","e":"other","c":"strength","l":"beginner","m":["middle back"],"s":["biceps","lats"],"i":["Sangles à hauteur de poitrine. Une poignée dans chaque main, penche-toi en arrière, corps droit, tête et poitrine hautes, bras tendus : c'est la position de départ.","Plie les coudes pour te tirer vers les poignées en serrant les omoplates.","Pause puis redescends."],"k":2},{"id":"Suspended_Split_Squat","n":"Squat fendu aux sangles","ne":"Suspended Split Squat","e":"other","c":"strength","l":"intermediate","m":["quadriceps"],"s":["abductors","adductors","calves","glutes","hamstrings"],"i":["Sangles réglées à 45-75 cm du sol.","Dos aux sangles, pose le pied arrière dans la poignée, regard devant, poitrine haute, genou légèrement fléchi : c'est la position de départ.","Descends en pliant genou et hanche, poids sur le talon avant, bonne posture.","En bas, remonte."],"k":2},{"id":"Svend_Press","n":"Svend press","ne":"Svend Press","e":"other","c":"strength","l":"beginner","m":["chest"],"s":["forearms","shoulders","triceps"],"i":["Debout.","Presse deux disques légers entre tes mains, contre la poitrine, doigts vers l'avant, en contractant les pectoraux : c'est la position de départ.","Serre les disques et tends les bras devant toi en contrôlant.","Pause puis ramène-les lentement."],"k":2},{"id":"T-Bar_Row_with_Handle","n":"Rowing T-bar avec poignée","ne":"T-Bar Row with Handle","e":"barbell","c":"strength","l":"beginner","m":["middle back"],"s":["biceps","lats"],"i":["Place une barre dans un landmine (ou cale un bout dans un coin) et charge ton extrémité.","Au-dessus de la barre, place une poignée double (en V) contre le manchon et redresse-toi avec les jambes.","Pieds écartés, hanches en arrière, poitrine haute, bras tendus : c'est la position de départ.","Tire la charge vers le haut du ventre en serrant les omoplates, sans à-coup.","Après une courte pause, redescends."],"k":2},{"id":"Tate_Press","n":"Tate press","ne":"Tate Press","e":"dumbbell","c":"strength","l":"intermediate","m":["triceps"],"s":["chest","shoulders"],"i":["Allongé sur un banc plat, un haltère dans chaque main sur les cuisses.","Monte-les au-dessus de toi, bras plus écartés que les épaules, en pronation, coudes vers l'extérieur : c'est la position de départ.","Bras fixes, descends lentement les haltères vers l'intérieur et le bas en arc jusqu'à toucher le haut de la poitrine, en inspirant, sans les poser.","Remonte avec les triceps par le même arc, en expirant, haltères proches. Descente deux fois plus lente que la montée."],"k":2},{"id":"The_Straddle","n":"Le grand écart (étirement)","ne":"The Straddle","e":"other","c":"stretching","l":"beginner","m":["hamstrings"],"s":["adductors","calves"],"i":["Assis droit, jambes tendues et écartées en V.","Mains au sol, penche-toi en avant le plus possible. Tiens 10 à 20 s."],"k":2},{"id":"Thigh_Abductor","n":"Abducteurs à la machine","ne":"Thigh Abductor","e":"machine","c":"strength","l":"beginner","m":["abductors"],"s":["glutes"],"i":["Assieds-toi sur la machine à abducteurs et choisis la charge. Jambes bien placées, mains sur les poignées, haut du corps immobile : c'est la position de départ.","Écarte lentement les jambes contre la machine, en expirant.","Tiens une seconde puis reviens en inspirant, haut du corps fixe."],"k":2},{"id":"Thigh_Adductor","n":"Adducteurs à la machine","ne":"Thigh Adductor","e":"machine","c":"strength","l":"beginner","m":["adductors"],"s":["glutes","hamstrings"],"i":["Assieds-toi sur la machine à adducteurs et choisis la charge. Jambes sur les appuis, mains sur les poignées, haut du corps immobile : c'est la position de départ.","Rapproche lentement les jambes contre la machine, en expirant.","Tiens une seconde puis reviens en inspirant, sans à-coups."],"k":2},{"id":"Tire_Flip","n":"Retournement de pneu","ne":"Tire Flip","e":"other","c":"strongman","l":"intermediate","m":["quadriceps"],"s":["calves","chest","forearms","glutes","hamstrings","lower back","shoulders","traps","triceps"],"i":["Saisis le bas du pneu par la bande de roulement, pieds un peu en arrière, poitrine contre le pneu.","Soulève-le en tendant hanches, genoux et chevilles, en poussant vers le haut et l'avant.","Vers 45°, avance et pousse avec un genou, change de prise vers le haut du pneu et pousse-le le plus fort possible pour le retourner. Recommence."],"k":2},{"id":"Toe_Touchers","n":"Toucher des orteils allongé","ne":"Toe Touchers","e":"body only","c":"stretching","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur le dos, bras le long du corps, paumes au sol.","Jambes serrées, monte-les presque à la verticale, genoux légèrement fléchis, pieds parallèles au sol.","Tends les bras vers le haut à environ 45° du sol : c'est la position de départ.","Bas du dos plaqué au sol, monte lentement le buste et va chercher tes orteils avec les mains, en expirant.","Redescends lentement en inspirant, bras toujours tendus vers les orteils."],"k":2},{"id":"Torso_Rotation","n":"Rotation du buste","ne":"Torso Rotation","e":"exercise ball","c":"stretching","l":"beginner","m":["abdominals"],"s":[],"i":["Debout, tiens un swiss ball à deux mains, bras tendus devant toi : c'est la position de départ.","Tourne le buste d'un côté en suivant le ballon des yeux, puis de l'autre. 10 à 20 répétitions."],"k":2},{"id":"Trail_Running_Walking","n":"Course / marche en nature","ne":"Trail Running/Walking","e":"other","c":"cardio","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Courir ou marcher en sentier fait vite monter le cardio. Porte de bonnes chaussures. En montée, mollets et fessiers travaillent ; en descente, genoux et chevilles encaissent : fais de plus petits pas, genoux fléchis, et ralentis pour ne pas tomber."],"k":2},{"id":"Trap_Bar_Deadlift","n":"Soulevé de terre trap bar","ne":"Trap Bar Deadlift","e":"other","c":"strength","l":"beginner","m":["quadriceps"],"s":["glutes","hamstrings"],"i":["Charge une trap bar (barre hexagonale) posée au sol. Place-toi au centre et saisis les deux poignées.","Descends les hanches, regard devant, poitrine haute.","Pousse sur les talons en tendant hanches et genoux, sans jamais arrondir le dos.","Redescends la charge au sol en contrôlant."],"k":2},{"id":"Tricep_Dumbbell_Kickback","n":"Kickback triceps haltère","ne":"Tricep Dumbbell Kickback","e":"dumbbell","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Un haltère dans chaque main, paumes vers toi. Dos droit, genoux légèrement fléchis, penche le buste presque à l'horizontale, tête haute. Bras collés au buste et parallèles au sol, avant-bras vers le sol, coudes à 90° : c'est la position de départ.","Bras fixes, expire et tends les avant-bras vers l'arrière avec les triceps jusqu'à bras tendus.","Après une courte pause, redescends lentement en inspirant."],"k":2},{"id":"Tricep_Side_Stretch","n":"Étirement latéral des triceps","ne":"Tricep Side Stretch","e":"other","c":"stretching","l":"beginner","m":["triceps"],"s":["shoulders"],"i":["Passe le bras droit en travers du corps par-dessus l'épaule gauche et tiens le coude avec la main gauche jusqu'à sentir l'étirement du triceps. Change de bras."],"k":2},{"id":"Triceps_Overhead_Extension_with_Rope","n":"Extension triceps nuque à la corde","ne":"Triceps Overhead Extension with Rope","e":"cable","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Fixe une corde à une poulie basse, choisis la charge et prends la corde à deux mains, dos à la machine.","Mains derrière la tête, coudes pliés pointés vers le haut ; pieds décalés, légèrement penché vers l'avant pour la stabilité : c'est la position de départ.","Tends les coudes pour monter les mains au-dessus de la tête, bras fixes.","Serre les triceps en haut puis redescends lentement."],"k":2},{"id":"Triceps_Pushdown","n":"Extension triceps à la poulie","ne":"Triceps Pushdown","e":"cable","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Fixe une barre droite ou coudée à une poulie haute et prends-la en pronation, largeur d'épaules.","Debout, buste droit très légèrement penché, bras collés au corps et verticaux, avant-bras vers la poulie : c'est la position de départ.","Pousse la barre vers le bas avec les triceps jusqu'à toucher l'avant des cuisses, bras tendus, en expirant. Seuls les avant-bras bougent.","Après une seconde, remonte lentement en inspirant."],"k":2},{"id":"Triceps_Pushdown_-_Rope_Attachment","n":"Extension triceps poulie à la corde","ne":"Triceps Pushdown - Rope Attachment","e":"cable","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Fixe une corde à une poulie haute et prends-la en prise neutre.","Debout, buste droit très légèrement penché, bras collés au corps et verticaux, avant-bras vers la poulie : c'est la position de départ.","Pousse la corde vers le bas avec les triceps en écartant les extrémités vers les cuisses, jusqu'à bras tendus, en expirant. Seuls les avant-bras bougent.","Après une seconde, remonte lentement en inspirant."],"k":2},{"id":"Triceps_Pushdown_-_V-Bar_Attachment","n":"Extension triceps poulie barre en V","ne":"Triceps Pushdown - V-Bar Attachment","e":"cable","c":"strength","l":"beginner","m":["triceps"],"s":[],"i":["Fixe une barre en V à une poulie haute et prends-la en pronation, largeur d'épaules.","Debout, buste droit très légèrement penché, bras collés au corps et verticaux, avant-bras vers la poulie, pouces plus hauts que les petits doigts : c'est la position de départ.","Pousse la barre vers le bas avec les triceps jusqu'à toucher l'avant des cuisses, bras tendus, en expirant.","Après une seconde, remonte lentement en inspirant."],"k":2},{"id":"Triceps_Stretch","n":"Étirement des triceps","ne":"Triceps Stretch","e":"other","c":"stretching","l":"beginner","m":["triceps"],"s":["lats"],"i":["Passe une main derrière la tête, attrape le coude avec l'autre main et tire doucement. Tiens 10 à 20 s puis change de côté."],"k":2},{"id":"Tuck_Crunch","n":"Crunch genoux groupés","ne":"Tuck Crunch","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur le dos, bras le long du corps, paumes au sol.","Chevilles croisées, monte les jambes jusqu'à avoir les cuisses verticales, genoux légèrement fléchis.","Croise les bras sur la poitrine : c'est la position de départ.","Bas du dos plaqué, monte lentement le buste en expirant.","Redescends lentement en inspirant."],"k":2},{"id":"Two-Arm_Dumbbell_Preacher_Curl","n":"Curl pupitre deux haltères","ne":"Two-Arm Dumbbell Preacher Curl","e":"dumbbell","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Un haltère dans chaque main, bras posés sur un pupitre ou un banc incliné, haltères à hauteur d'épaules : c'est la position de départ.","En inspirant, descends lentement jusqu'à bras tendus.","En expirant, remonte avec les biceps jusqu'à hauteur d'épaules.","Serre fort une seconde puis recommence."],"k":2},{"id":"Two-Arm_Kettlebell_Clean","n":"Épaulé deux kettlebells","ne":"Two-Arm Kettlebell Clean","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["calves","glutes","hamstrings","lower back","traps"],"i":["Place deux kettlebells entre tes pieds, fesses en arrière, regard droit devant.","Monte-les aux épaules en poussant avec les jambes et les hanches, en tournant les poignets.","Redescends-les et recommence."],"k":2},{"id":"Two-Arm_Kettlebell_Jerk","n":"Jeté deux kettlebells","ne":"Two-Arm Kettlebell Jerk","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["calves","quadriceps","triceps"],"i":["Monte deux kettlebells aux épaules en poussant avec les jambes et les hanches, paumes vers l'avant. Fléchis de quelques centimètres puis repousse vivement pour envoyer les kettlebells au-dessus de la tête ; aussitôt, refléchis pour passer dessous. Une fois les bras verrouillés, redresse-toi."],"k":2},{"id":"Two-Arm_Kettlebell_Military_Press","n":"Développé militaire deux kettlebells","ne":"Two-Arm Kettlebell Military Press","e":"kettlebells","c":"strength","l":"intermediate","m":["shoulders"],"s":["triceps"],"i":["Monte deux kettlebells aux épaules en poussant avec les jambes et les hanches, paumes vers l'avant.","Pousse-les vers le haut et légèrement vers l'extérieur ; quand elles passent la tête, avance légèrement sous les charges pour les bloquer au-dessus. Contracte dorsaux, fessiers et abdos pour la stabilité."],"k":2},{"id":"Two-Arm_Kettlebell_Row","n":"Rowing deux kettlebells","ne":"Two-Arm Kettlebell Row","e":"kettlebells","c":"strength","l":"intermediate","m":["middle back"],"s":["biceps","lats"],"i":["Place deux kettlebells devant tes pieds. Genoux légèrement fléchis, fesses bien en arrière, penche-toi.","Attrape-les et tire-les vers le ventre en serrant les omoplates, dos droit. Redescends et recommence."],"k":2},{"id":"Underhand_Cable_Pulldowns","n":"Tirage vertical prise supination","ne":"Underhand Cable Pulldowns","e":"cable","c":"strength","l":"beginner","m":["lats"],"s":["biceps","middle back","shoulders"],"i":["Assieds-toi au poste de tirage avec une barre large, genoux calés sous les boudins.","Prends la barre en supination, mains plus serrées que les épaules.","Bras tendus, recule le buste d'environ 30°, poitrine sortie, bas du dos cambré : c'est la position de départ.","En expirant, tire la barre jusqu'au haut de la poitrine, coudes près du corps. Serre le dos ; le buste ne bouge pas.","Après une seconde, remonte lentement en inspirant jusqu'à bras tendus."],"k":2},{"id":"Upper_Back-Leg_Grab","n":"Étirement haut du dos en attrapant les jambes","ne":"Upper Back-Leg Grab","e":"other","c":"stretching","l":"beginner","m":["hamstrings"],"s":["lower back","middle back"],"i":["Assis, penche-toi et entoure tes cuisses par-dessous avec les bras.","Genoux serrés, jambes tendues, descends la poitrine vers les genoux. Pour étirer le milieu du dos, repousse le dos en arrière tout en tenant les jambes."],"k":2},{"id":"Upper_Back_Stretch","n":"Étirement du haut du dos","ne":"Upper Back Stretch","e":"other","c":"stretching","l":"beginner","m":["middle back"],"s":["middle back"],"i":["Doigts entrelacés, pouces vers le bas, arrondis les épaules en poussant les mains devant toi."],"k":2},{"id":"Upright_Barbell_Row","n":"Rowing menton barre","ne":"Upright Barbell Row","e":"barbell","c":"strength","l":"beginner","m":["shoulders"],"s":["traps"],"i":["Prends une barre en pronation, mains un peu plus serrées que les épaules, barre contre les cuisses, bras tendus, coudes légèrement fléchis, dos droit.","En expirant, monte la barre près du corps avec les épaules, coudes vers le haut et l'extérieur, jusqu'au menton. Les coudes mènent et restent plus hauts que les avant-bras. Pause en haut.","Redescends lentement en inspirant."],"k":2},{"id":"Upright_Cable_Row","n":"Rowing menton à la poulie","ne":"Upright Cable Row","e":"cable","c":"strength","l":"intermediate","m":["traps"],"s":["shoulders"],"i":["Prends la barre d'une poulie basse en pronation, mains un peu plus serrées que les épaules, barre contre les cuisses, coudes légèrement fléchis, dos droit.","Monte la barre près du corps jusqu'au menton avec les épaules, en expirant ; les coudes restent plus hauts que les avant-bras. Pause en haut.","Redescends lentement en inspirant."],"k":2},{"id":"Upright_Row_-_With_Bands","n":"Rowing menton aux élastiques","ne":"Upright Row - With Bands","e":"bands","c":"strength","l":"beginner","m":["traps"],"s":["shoulders"],"i":["Debout sur un élastique, tension dès bras tendus. Poignées en pronation contre les cuisses, mains un peu plus serrées que les épaules, coudes légèrement fléchis, dos droit.","Monte les poignées près du corps jusqu'au menton avec les épaules, en expirant ; les coudes restent plus hauts que les avant-bras. Pause en haut.","Redescends lentement en inspirant."],"k":2},{"id":"Upward_Stretch","n":"Étirement vers le haut","ne":"Upward Stretch","e":"other","c":"stretching","l":"beginner","m":["shoulders"],"s":["chest","lats"],"i":["Tends les deux mains au-dessus de la tête, paumes jointes.","Pousse lentement les mains vers le haut et l'arrière, dos droit."],"k":2},{"id":"V-Bar_Pulldown","n":"Tirage vertical barre en V","ne":"V-Bar Pulldown","e":"cable","c":"strength","l":"intermediate","m":["lats"],"s":["biceps","middle back","shoulders"],"i":["Assieds-toi au poste de tirage avec une poignée en V.","Cale les genoux sous les boudins.","Prends la poignée paumes face à face, poitrine sortie, buste penché en arrière d'environ 30° : c'est la position de départ.","Tire la poignée vers le bas avec le dos en serrant les omoplates, jusqu'à ce que la poitrine la frôle, en expirant. Buste fixe.","Après une seconde, remonte lentement en inspirant."],"k":2},{"id":"V-Bar_Pullup","n":"Traction barre en V","ne":"V-Bar Pullup","e":"body only","c":"strength","l":"beginner","m":["lats"],"s":["biceps","middle back","shoulders"],"i":["Pose le milieu d'une poignée en V sur le milieu de la barre de traction, poignées vers le bas.","Attrape une poignée de chaque côté et suspends-toi, poitrine sortie, légèrement penché en arrière : c'est la position de départ.","Tire-toi vers le haut avec le dos, tête légèrement en arrière, jusqu'à ce que la poitrine frôle la poignée, en expirant.","Après une seconde, redescends lentement en inspirant."],"k":2},{"id":"Vertical_Swing","n":"Swing vertical","ne":"Vertical Swing","e":"dumbbell","c":"plyometrics","l":"beginner","m":["hamstrings"],"s":["glutes","quadriceps","shoulders"],"i":["Haltère tenu à deux mains, bras tendus, pendant entre les jambes. Dos droit, tête haute.","Balance l'haltère entre les jambes en pliant les hanches et légèrement les genoux.","Inverse puissamment en tendant hanches, genoux et chevilles pour te propulser vers le haut en balançant l'haltère au-dessus de la tête.","Amortis la réception avec les jambes et ramène l'haltère contre le buste avant la répétition suivante."],"k":2},{"id":"Walking_Treadmill","n":"Marche sur tapis","ne":"Walking, Treadmill","e":"machine","c":"cardio","l":"beginner","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Monte sur le tapis et choisis un programme ou le mode manuel. Tu peux entrer âge et poids pour estimer les calories et régler l'inclinaison pour l'intensité.","Marche à allure soutenue, pas en flânant. Garde une bonne posture et ne tiens les poignées que si nécessaire."],"k":2},{"id":"Weighted_Ball_Hyperextension","n":"Hyperextension avec ballon lesté","ne":"Weighted Ball Hyperextension","e":"exercise ball","c":"strength","l":"intermediate","m":["lower back"],"s":["glutes","hamstrings","middle back"],"i":["Allongé sur un swiss ball, buste contre le ballon et parallèle au sol, avant des pieds au sol pour l'équilibre. Disque tenu sous le menton ou derrière la nuque : c'est la position de départ.","Monte lentement le buste en cambrant le bas du dos, en expirant.","Tiens une seconde puis redescends en inspirant."],"k":2},{"id":"Weighted_Ball_Side_Bend","n":"Flexion latérale avec ballon lesté","ne":"Weighted Ball Side Bend","e":"exercise ball","c":"strength","l":"intermediate","m":["abdominals"],"s":[],"i":["Allongé sur le côté gauche sur un swiss ball (taille, hanche et épaule contre le ballon).","Pieds au sol, jambes croisées. Tiens un disque de la main droite contre le côté droit de la tête.","Bras gauche en travers du buste, paume sur les obliques : c'est la position de départ.","Monte le côté du buste en fléchissant latéralement la taille, en expirant.","Tiens une seconde puis redescends lentement en inspirant.","Change de côté."],"k":2},{"id":"Weighted_Bench_Dip","n":"Dips sur banc lestés","ne":"Weighted Bench Dip","e":"other","c":"strength","l":"intermediate","m":["triceps"],"s":["chest","shoulders"],"i":["Place un banc derrière toi et un autre devant. Mains sur le bord du banc arrière, près du corps, largeur d'épaules, bras tendus.","Jambes tendues posées sur l'autre banc, parallèles au sol, buste vertical ; ton partenaire pose un poids sur tes cuisses.","Descends lentement en pliant les coudes jusqu'à un angle un peu inférieur à 90°, en inspirant, coudes serrés.","Remonte avec les triceps en expirant."],"k":2},{"id":"Weighted_Crunches","n":"Crunchs lestés","ne":"Weighted Crunches","e":"medicine ball","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Allongé sur le dos, pieds au sol (ou sur un banc, genoux à 90°).","Tiens un poids contre la poitrine ou bras tendus au-dessus du buste : c'est la position de départ.","Expire et décolle lentement les épaules d'environ 10 cm, bas du dos au sol.","En haut, contracte les abdos un instant.","Redescends lentement en inspirant."],"k":2},{"id":"Weighted_Jump_Squat","n":"Squat sauté lesté","ne":"Weighted Jump Squat","e":"barbell","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings","lower back"],"i":["Barre légère sur l'arrière des épaules (ou gilet lesté, sac de sable…), assez légère pour ne pas te ralentir.","Pieds juste plus larges que les épaules, tête et poitrine hautes : c'est la position de départ.","Fléchis partiellement puis saute explosivement en tendant hanches, genoux et chevilles, bonne posture.","Amortis la réception avec les jambes."],"k":2},{"id":"Weighted_Pull_Ups","n":"Tractions lestées","ne":"Weighted Pull Ups","e":"other","c":"strength","l":"intermediate","m":["lats"],"s":["biceps","middle back"],"i":["Accroche un poids à une ceinture de lest. Prends la barre paumes vers l'avant, prise largeur d'épaules, bras tendus.","Recule le buste d'environ 30°, bas du dos cambré, poitrine sortie : c'est la position de départ.","Expire et tire-toi jusqu'à ce que la tête passe au-dessus des mains, en serrant les omoplates vers l'arrière et le bas.","Après un instant, redescends lentement en inspirant jusqu'à bras tendus."],"k":2},{"id":"Weighted_Sissy_Squat","n":"Sissy squat lesté","ne":"Weighted Sissy Squat","e":"barbell","c":"strength","l":"expert","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Debout, pieds largeur d'épaules, sur la pointe des pieds ; une main tient un montant de rack, l'autre un disque contre la poitrine : c'est la position de départ.","En te tenant, plie les genoux et descends lentement le buste vers l'arrière en avançant bassin et genoux, jusqu'à presque 90° aux genoux, en inspirant. Tiens une seconde.","Remonte avec les cuisses en expirant."],"k":2},{"id":"Weighted_Sit-Ups_-_With_Bands","n":"Sit-ups lestés aux élastiques","ne":"Weighted Sit-Ups - With Bands","e":"other","c":"strength","l":"intermediate","m":["abdominals"],"s":[],"i":["Fixe des élastiques à la base d'un banc décliné, poignées accessibles une fois allongé.","Cale tes jambes dans le banc, attrape les poignées et place-les près des clavicules, en prise neutre ; les bras ne bougent plus : c'est la position de départ.","Monte le buste jusqu'à la verticale en expirant. Tiens une seconde puis redescends en inspirant."],"k":2},{"id":"Weighted_Squat","n":"Squat lesté","ne":"Weighted Squat","e":"other","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Place deux bancs plats écartés de la largeur des épaules et monte dessus avec une ceinture lestée autour de la taille, pointes de pieds ouvertes.","Debout, charge pendante entre les jambes, bras tendus le long du corps : c'est la position de départ.","Descends en pliant les genoux, tête haute, jusqu'à un angle un peu inférieur à 90°, en inspirant. Genoux dans l'axe des pieds.","Remonte en poussant surtout sur l'avant des pieds, en expirant."],"k":2},{"id":"Wide-Grip_Barbell_Bench_Press","n":"Développé couché prise large","ne":"Wide-Grip Barbell Bench Press","e":"barbell","c":"strength","l":"intermediate","m":["chest"],"s":["shoulders","triceps"],"i":["Allongé sur un banc plat, pieds au sol. Prise large en pronation (environ 8 cm plus large que les épaules de chaque côté), sors la barre et tiens-la bras tendus : c'est la position de départ.","En inspirant, descends lentement jusqu'au milieu de la poitrine.","Après une seconde, pousse avec les pectoraux en expirant et serre en haut. Descente deux fois plus lente que la montée."],"k":2},{"id":"Wide-Grip_Decline_Barbell_Bench_Press","n":"Développé décliné prise large","ne":"Wide-Grip Decline Barbell Bench Press","e":"barbell","c":"strength","l":"intermediate","m":["chest"],"s":["shoulders","triceps"],"i":["Allongé sur un banc décliné, pieds bien calés. Prise large en pronation, sors la barre et tiens-la bras tendus : c'est la position de départ.","En inspirant, descends lentement jusqu'au bas de la poitrine.","Après une seconde, pousse avec les pectoraux en expirant et serre en haut. Descente deux fois plus lente que la montée."],"k":2},{"id":"Wide-Grip_Decline_Barbell_Pullover","n":"Pull-over décliné barre prise large","ne":"Wide-Grip Decline Barbell Pullover","e":"barbell","c":"strength","l":"intermediate","m":["chest"],"s":["shoulders","triceps"],"i":["Allongé sur un banc décliné, jambes calées. Attrape la barre derrière la tête en pronation, plus large que les épaules, et monte-la avec les bras.","Bras tendus et verticaux : c'est la position de départ.","Descends la barre en arc vers l'arrière comme pour la poser au sol, mais arrête-toi quand les bras sont parallèles au sol ; bras toujours tendus, en inspirant.","Remonte en expirant, en gardant le contrôle.","À la fin, redescends la barre au niveau de la tête et lâche-la doucement."],"k":2},{"id":"Wide-Grip_Lat_Pulldown","n":"Tirage vertical prise large","ne":"Wide-Grip Lat Pulldown","e":"cable","c":"strength","l":"beginner","m":["lats"],"s":["biceps","middle back","shoulders"],"i":["Assieds-toi au poste de tirage avec une barre large, genoux calés sous les boudins.","Prends la barre paumes vers l'avant, mains plus larges que les épaules.","Bras tendus, recule le buste d'environ 30°, poitrine sortie, bas du dos cambré : c'est la position de départ.","En expirant, tire la barre jusqu'au haut de la poitrine en abaissant épaules et bras. Serre le dos ; le buste ne bouge pas, les avant-bras ne font que tenir.","Après une seconde, omoplates serrées, remonte lentement en inspirant jusqu'à bras tendus."],"k":2},{"id":"Wide-Grip_Pulldown_Behind_The_Neck","n":"Tirage nuque prise large","ne":"Wide-Grip Pulldown Behind The Neck","e":"cable","c":"strength","l":"intermediate","m":["lats"],"s":["biceps","middle back","shoulders"],"i":["Assieds-toi au poste de tirage avec une barre large, genoux calés sous les boudins.","Prends la barre paumes vers l'avant, prise large.","Bras tendus, penche buste et tête vers l'avant pour que la barre soit alignée avec ta nuque : c'est la position de départ.","En expirant, tire la barre jusqu'à la nuque en abaissant épaules et bras. Serre le dos.","Après une seconde, remonte lentement en inspirant jusqu'à bras tendus."],"k":2},{"id":"Wide-Grip_Rear_Pull-Up","n":"Traction nuque prise large","ne":"Wide-Grip Rear Pull-Up","e":"body only","c":"strength","l":"intermediate","m":["lats"],"s":["biceps","middle back","shoulders"],"i":["Attrape la barre paumes vers l'avant, prise large.","Bras tendus, penche buste et tête vers l'avant pour aligner la barre avec ta nuque : c'est la position de départ.","Tire-toi jusqu'à ce que la barre arrive près de la nuque, en abaissant épaules et bras, tête légèrement penchée en avant, en expirant. Serre le dos.","Après une seconde, redescends lentement en inspirant jusqu'à bras tendus."],"k":2},{"id":"Wide-Grip_Standing_Barbell_Curl","n":"Curl barre debout prise large","ne":"Wide-Grip Standing Barbell Curl","e":"barbell","c":"strength","l":"beginner","m":["biceps"],"s":[],"i":["Debout, buste droit, barre tenue en prise large, paumes vers l'avant, coudes près du corps.","Bras fixes, monte la barre en contractant les biceps, en expirant. Seuls les avant-bras bougent.","Continue jusqu'à hauteur d'épaules et serre fort une seconde.","Redescends lentement en inspirant."],"k":2},{"id":"Wide_Stance_Barbell_Squat","n":"Squat barre pieds écartés","ne":"Wide Stance Barbell Squat","e":"barbell","c":"strength","l":"intermediate","m":["quadriceps"],"s":["calves","glutes","hamstrings","lower back"],"i":["Idéalement dans une cage. Pose la barre sur le haut du dos (sous la nuque).","Décroche-la en poussant avec les jambes.","Recule, pieds plus larges que les épaules, pointes légèrement ouvertes, tête haute, dos droit.","Descends lentement jusqu'à un angle un peu inférieur à 90° aux genoux, en inspirant. Genoux dans l'axe des pieds.","Remonte en expirant en poussant sur les talons."],"k":2},{"id":"Wide_Stance_Stiff_Legs","n":"Jambes tendues pieds écartés (étirement)","ne":"Wide Stance Stiff Legs","e":"barbell","c":"olympic weightlifting","l":"intermediate","m":["hamstrings"],"s":["adductors","glutes","lower back"],"i":["Barre chargée au sol, pieds écartés. Penche-toi depuis les hanches pour la saisir, hanches le plus en arrière possible, jambes presque tendues, dos droit, tête et poitrine hautes : c'est la position de départ.","Pousse les hanches vers l'avant, bras pendants, jusqu'à être debout, puis redescends lentement. Pas besoin de reposer la barre au sol entre les répétitions."],"k":2},{"id":"Wind_Sprints","n":"Sprints courts","ne":"Wind Sprints","e":"body only","c":"strength","l":"beginner","m":["abdominals"],"s":[],"i":["Suspendu à la barre en pronation, bras et jambes tendus : c'est la position de départ.","Monte vivement un genou le plus haut possible, sans balancer.","Redescends-le aussitôt en montant l'autre genou.","Continue en alternant."],"k":2},{"id":"Windmills","n":"Moulins","ne":"Windmills","e":"other","c":"stretching","l":"intermediate","m":["abductors"],"s":["glutes","hamstrings","lower back"],"i":["Allongé sur le dos, bras écartés sur les côtés, jambes tendues : c'est la position de départ.","Lève une jambe et croise-la vivement par-dessus le corps pour toucher le sol près de la main opposée.","Reviens et fais de même avec l'autre jambe. Alterne 10 à 20 fois."],"k":2},{"id":"Worlds_Greatest_Stretch","n":"Le meilleur étirement du monde","ne":"World's Greatest Stretch","e":"other","c":"stretching","l":"intermediate","m":["hamstrings"],"s":["calves","glutes","quadriceps"],"i":["Étirement en trois temps. Fais une grande fente, pied avant à plat, appui sur les orteils derrière. Descends jusqu'à ce que le genou arrière frôle le sol, buste droit, et tiens 10 à 20 s.","Pose ensuite au sol l'avant-bras du côté de la jambe avant, coude près du pied, l'autre main au sol pour t'aider.","Après 10 à 20 s, mains de chaque côté du pied avant, décolle les orteils avant et tends la jambe avant (recule le pied arrière si besoin). Tiens 10 à 20 s puis fais tout de l'autre côté."],"k":2},{"id":"Wrist_Circles","n":"Cercles de poignets","ne":"Wrist Circles","e":"body only","c":"stretching","l":"beginner","m":["forearms"],"s":[],"i":["Debout, pieds largeur d'épaules, bras tendus sur les côtés à hauteur d'épaules (en « T »), paumes vers le bas : c'est la position de départ.","Corps immobile, fais des cercles avec les poignets vers l'avant, comme si tes mains dessinaient des ronds. Respire normalement."],"k":2},{"id":"Wrist_Roller","n":"Rouleau à poignets","ne":"Wrist Roller","e":"other","c":"strength","l":"beginner","m":["forearms"],"s":["shoulders"],"i":["Debout, pieds largeur d'épaules, tiens un rouleau à poignets en pronation.","Monte les bras tendus devant toi, parallèles au sol, corde déroulée. Seuls les avant-bras bougent : c'est la position de départ.","Tourne un poignet après l'autre pour enrouler la corde et monter la charge jusqu'au rouleau.","Puis redescends lentement en déroulant dans l'autre sens."],"k":2},{"id":"Wrist_Rotations_with_Straight_Bar","n":"Rotations des poignets avec barre","ne":"Wrist Rotations with Straight Bar","e":"barbell","c":"strength","l":"beginner","m":["forearms"],"s":[],"i":["Barre tenue à deux mains, paumes vers le bas, mains largeur d'épaules : c'est la position de départ.","En alternant les mains, tends les poignets comme pour enrouler un journal ; continue jusqu'à l'échec.","Puis fais le mouvement inverse en fléchissant les poignets, jusqu'à l'échec."],"k":2},{"id":"Yoke_Walk","n":"Marche avec joug","ne":"Yoke Walk","e":"other","c":"strongman","l":"intermediate","m":["quadriceps"],"s":["abdominals","abductors","adductors","calves","glutes","hamstrings","lower back"],"i":["Le joug se fait avec un appareil dédié (parfois un frigo ou un objet lourd).","Place-le sur l'arrière des épaules, regard devant, dos cambré, et soulève-le en poussant sur les talons.","Marche le plus vite possible à petits pas rapides, en tenant les montants pour le stabiliser, sur 20 à 30 m."],"k":2},{"id":"Zercher_Squats","n":"Squat Zercher","ne":"Zercher Squats","e":"barbell","c":"strength","l":"expert","m":["quadriceps"],"s":["calves","glutes","hamstrings"],"i":["Idéalement dans une cage, barre réglée entre la taille et la poitrine. Mains jointes, place la barre au creux des coudes.","Soulève la barre, posée sur les avant-bras, comme si tu croisais les bras autour.","Recule, pieds largeur d'épaules, pointes légèrement ouvertes, tête haute, dos droit.","Descends en pliant les genoux jusqu'à un angle un peu inférieur à 90°, en inspirant. Genoux dans l'axe des pieds.","Remonte en poussant surtout sur l'avant des pieds, en expirant."],"k":2},{"id":"Zottman_Curl","n":"Curl Zottman","ne":"Zottman Curl","e":"dumbbell","c":"strength","l":"intermediate","m":["biceps"],"s":["forearms"],"i":["Debout, buste droit, un haltère dans chaque main bras tendus, coudes près du corps.","Paumes face à face : c'est la position de départ.","Bras fixes, monte les haltères en tournant les poignets paumes vers le haut, en expirant, jusqu'à hauteur d'épaules.","Serre une seconde.","En haut, tourne les poignets paumes vers le bas.","Redescends lentement dans cette prise.","Près des cuisses, reviens en prise neutre."],"k":2},{"id":"Zottman_Preacher_Curl","n":"Curl pupitre Zottman","ne":"Zottman Preacher Curl","e":"dumbbell","c":"strength","l":"intermediate","m":["biceps"],"s":["forearms"],"i":["Un haltère dans chaque main, bras posés sur un pupitre ou un banc incliné, haltères à hauteur d'épaules, coudes pliés, paumes vers le bas : c'est la position de départ.","En inspirant, descends lentement, paumes vers le bas, jusqu'à bras tendus.","En bas, tourne les poignets paumes vers le haut.","En expirant, remonte avec les biceps jusqu'à hauteur d'épaules, petit doigt plus haut que le pouce.","Serre une seconde puis tourne les poignets paumes vers le bas."],"k":2}];
